final class ScreenshotAppStateTests: XCTestCase {
    func testClipboardPendingAttachmentFeedbackUsesWarningAndLocalizedCount() {
        XCTAssertNil(ClipboardSettingsPane.pendingAttachmentCleanupFeedback(count: 0))
        let feedback = ClipboardSettingsPane.pendingAttachmentCleanupFeedback(count: 2)
        XCTAssertEqual(feedback?.kind, .warning)
        XCTAssertNotEqual(feedback?.title, "clipboard.sidecarCleanup.pending.title")
        XCTAssertNotEqual(feedback?.detail, "clipboard.sidecarCleanup.pending.detail")
        XCTAssertTrue(feedback?.title.contains("2") == true)
        XCTAssertTrue(feedback?.detail.contains("2") == true)
    }

    func testClipboardClearPublishesCommittedTruthWhenSidecarCleanupIsPending() async throws {
        let root = FileManager.default.temporaryDirectory.appendingPathComponent("ClipboardOutboxStore.\(UUID().uuidString)", isDirectory: true)
        let database = try AppDatabase.open(environment: StorageEnvironment(rootDirectory: root))
        defer { database.close(); try? FileManager.default.removeItem(at: root) }
        let blobStore = BlobStore(directory: database.environment.blobDirectory, sidecarThresholdBytes: 1)
        let repository = ClipboardRepository(
            database: database,
            blobStore: blobStore,
            sidecarDeletionFailureInjector: { _ in
                throw NSError(domain: "ClipboardSidecarCleanupFixture", code: 1)
            }
        )
        let record = ClipboardRecorderRecord(id: "store-outbox", createdAt: Date(), changeCount: 1, kind: .image, formatSummary: ClipboardRecorderFormatSummary(itemCount: 1, types: ["public.png"]), sourceApp: nil, signatureSHA256: String(repeating: "a", count: 64), signatureSHA256_12: String(repeating: "a", count: 12), fixtureOwned: false, restorable: true, summary: "image")
        _ = try repository.insert(record: record, payload: ClipboardRecorderPayload(recordID: record.id, kind: .image, pngData: Data(repeating: 1, count: 16)))
        let store = ClipboardStore(repository: repository)
        let completed = expectation(description: "clear committed")
        store.requestClearUnfavorited { result in
            if case let .success(deleted, _) = result { XCTAssertEqual(deleted, 1) } else { XCTFail("expected committed clear") }
            completed.fulfill()
        }
        await fulfillment(of: [completed], timeout: 1)
        XCTAssertFalse(store.repositoryUnavailable)
        XCTAssertEqual(store.pendingAttachmentCleanupCount, 1)
    }

