    func testScreenshotFocusRequestsWaitForLifecycleAndRejectStaleGenerations() {
        let view = NSView()
        var isEligible = false
        var focusedRequestCount = 0
        let coordinator = ScreenshotFocusRequestCoordinator(
            isEligible: { _ in isEligible },
            performFocus: { _ in
                focusedRequestCount += 1
                return true
            }
        )

        coordinator.requestFocus(1)
        coordinator.attach(view)
        XCTAssertNil(coordinator.appliedRequestID)
        XCTAssertEqual(focusedRequestCount, 0)

        coordinator.requestFocus(2)
        isEligible = true
        XCTAssertTrue(coordinator.applyPendingFocus())
        XCTAssertEqual(coordinator.appliedRequestID, 2)
        XCTAssertEqual(focusedRequestCount, 1)

        coordinator.requestFocus(1)
        XCTAssertFalse(coordinator.applyPendingFocus())
        XCTAssertEqual(coordinator.appliedRequestID, 2)
        XCTAssertEqual(focusedRequestCount, 1)
    }

    func testScreenshotFocusRequestUsesRealFirstResponderWhenViewJoinsWindow() {
        let panel = NSPanel(
            contentRect: CGRect(x: 40, y: 40, width: 240, height: 160),
            styleMask: [.titled],
            backing: .buffered,
            defer: false
        )
        let content = NSView(frame: panel.contentView?.bounds ?? .zero)
        let target = NSButton(
            frame: CGRect(x: 20, y: 20, width: 80, height: 24)
        )
        content.addSubview(target)
        panel.contentView = content
        panel.animationBehavior = .none
        let coordinator = ScreenshotFocusRequestCoordinator()
        defer {
            coordinator.detach()
            closeAppKitFixtureWindow(panel)
            drainAppKitAnimationTransactions()
        }

        coordinator.requestFocus(1)
        XCTAssertNil(coordinator.appliedRequestID)

        panel.makeKeyAndOrderFront(nil)
        coordinator.attach(target)

        XCTAssertEqual(coordinator.appliedRequestID, 1)
        XCTAssertTrue(panel.firstResponder === target)
    }

    func testScreenshotFocusRequestRevalidatesAfterCurrentEventWithoutWallClockDelay() async {
        let view = NSView()
        var focusApplications = 0
        let coordinator = ScreenshotFocusRequestCoordinator(
            isEligible: { _ in true },
            performFocus: { _ in
                focusApplications += 1
                return true
            }
        )
        coordinator.attach(view)

        coordinator.requestFocusAfterCurrentEvent(1)
        XCTAssertEqual(focusApplications, 1)

        let revalidated = expectation(description: "next-run-loop focus validation")
        DispatchQueue.main.async {
            XCTAssertEqual(focusApplications, 2)
            revalidated.fulfill()
        }
        await fulfillment(of: [revalidated], timeout: 1)
        XCTAssertEqual(coordinator.appliedRequestID, 1)
    }

    func testFloatingPanelWindowRolesApplyStableWindowContracts() {
        let clipboard = NSPanel(
            contentRect: .zero,
            styleMask: [.titled, .resizable, .fullSizeContentView, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        BlocksFloatingPanelWindowRole.transientNonactivatingUtility.apply(to: clipboard)
        XCTAssertFalse(clipboard.isOpaque)
        XCTAssertEqual(clipboard.backgroundColor, .clear)
        XCTAssertFalse(clipboard.isMovable)
        XCTAssertFalse(clipboard.isMovableByWindowBackground)
        XCTAssertEqual(clipboard.level, .statusBar)
        XCTAssertEqual(clipboard.animationBehavior, .none)
        XCTAssertTrue(clipboard.collectionBehavior.contains(.moveToActiveSpace))
        XCTAssertTrue(clipboard.collectionBehavior.contains(.fullScreenAuxiliary))
        XCTAssertTrue(
            clipboard.standardWindowButton(.closeButton) == nil
                || clipboard.standardWindowButton(.closeButton)?.isHidden == true
        )

        let translation = NSPanel(
            contentRect: .zero,
            styleMask: [.titled, .closable, .resizable, .fullSizeContentView, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        BlocksFloatingPanelWindowRole.nonactivatingSession.apply(to: translation)
        XCTAssertFalse(translation.isOpaque)
        XCTAssertTrue(translation.becomesKeyOnlyIfNeeded)
        XCTAssertEqual(translation.animationBehavior, .none)
        XCTAssertTrue(translation.standardWindowButton(.zoomButton)?.isHidden == true)

        let tooltip = NSPanel(
            contentRect: .zero,
            styleMask: [.borderless, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        BlocksFloatingPanelWindowRole.tooltip.apply(to: tooltip)
        XCTAssertFalse(tooltip.isOpaque)
        XCTAssertTrue(tooltip.ignoresMouseEvents)
        XCTAssertTrue(tooltip.hasShadow)
        XCTAssertTrue(tooltip.collectionBehavior.contains(.transient))
    }

    func testFloatingPanelPresentationCoordinatorOwnsStableFirstAndLastFrames() {
        var animationCalls: [(BlocksMotionRole, BlocksMotionPhase)] = []
        let coordinator = BlocksFloatingPanelPresentationCoordinator {
            window,
            frame,
            alphaValue,
            role,
            phase,
            completion in
            animationCalls.append((role, phase))
            window.setFrame(frame, display: false)
            window.alphaValue = alphaValue
            completion()
        }
        let frame = CGRect(x: 80, y: 90, width: 420, height: 260)
        let panel = NSPanel(
            contentRect: frame,
            styleMask: [.titled, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        panel.animationBehavior = .none
        defer {
            closeAppKitFixtureWindow(panel)
            drainAppKitAnimationTransactions()
        }

        coordinator.present(window: panel, frame: frame, makeKey: false)

        XCTAssertEqual(coordinator.phase, .visible)
        XCTAssertTrue(panel.isVisible)
        XCTAssertEqual(panel.frame, frame)
        XCTAssertEqual(panel.alphaValue, 1)
        XCTAssertEqual(animationCalls.first?.0, .panel)
        XCTAssertEqual(animationCalls.first?.1, .insertion)

        var didCompleteDismissal = false
        XCTAssertTrue(
            coordinator.dismiss(window: panel) {
                didCompleteDismissal = true
            }
        )
        XCTAssertTrue(didCompleteDismissal)
        XCTAssertEqual(coordinator.phase, .hidden)
        XCTAssertTrue(panel.ignoresMouseEvents)
        XCTAssertEqual(panel.alphaValue, 0)
        XCTAssertEqual(animationCalls.last?.0, .confirmation)
        XCTAssertEqual(animationCalls.last?.1, .removal)
    }

    func testFloatingPanelPresentationCoordinatorRejectsStaleCompletion() {
        var completions: [@MainActor () -> Void] = []
        let coordinator = BlocksFloatingPanelPresentationCoordinator {
            _,
            _,
            _,
            _,
            _,
            completion in
            completions.append(completion)
        }
        let panel = NSPanel(
            contentRect: CGRect(x: 20, y: 20, width: 320, height: 180),
            styleMask: [.titled, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        panel.animationBehavior = .none
        defer {
            closeAppKitFixtureWindow(panel)
            drainAppKitAnimationTransactions()
        }

        coordinator.present(window: panel, frame: panel.frame, makeKey: false)
        coordinator.present(window: panel, frame: panel.frame, makeKey: false)

        XCTAssertEqual(completions.count, 2)
        completions[0]()
        XCTAssertEqual(coordinator.phase, .presenting)
        completions[1]()
        XCTAssertEqual(coordinator.phase, .visible)
    }

    func testFloatingPanelImmediateCloseLifecyclePressure() {
        for _ in 0..<500 {
            autoreleasepool {
                let panel = makeLifecyclePressurePanel()
                let coordinator = BlocksFloatingPanelPresentationCoordinator()

                coordinator.present(
                    window: panel,
                    frame: panel.frame,
                    makeKey: false
                )
                coordinator.closeImmediately(window: panel) {
                    panel.close()
                }

                drainAppKitAnimationTransactions()
                XCTAssertFalse(panel.isVisible)
            }
        }
    }

    func testFloatingPanelImmediateDismissAndCloseLifecyclePressure() {
        for _ in 0..<500 {
            autoreleasepool {
                let panel = makeLifecyclePressurePanel()
                let coordinator = BlocksFloatingPanelPresentationCoordinator()

                coordinator.present(
                    window: panel,
                    frame: panel.frame,
                    makeKey: false
                )
                XCTAssertTrue(coordinator.dismiss(window: panel) {})
                coordinator.closeImmediately(window: panel) {
                    panel.close()
                }

                drainAppKitAnimationTransactions()
                XCTAssertFalse(panel.isVisible)
            }
        }
    }

    private func makeLifecyclePressurePanel() -> NSPanel {
        let panel = NSPanel(
            contentRect: CGRect(x: 40, y: 40, width: 240, height: 160),
            styleMask: [.titled, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        BlocksFloatingPanelWindowRole.transientNonactivatingUtility.apply(to: panel)
        return panel
    }

    private func drainAppKitAnimationTransactions() {
        CATransaction.flush()
        RunLoop.main.run(mode: .default, before: Date())
        CATransaction.flush()
    }

    private func closeAppKitFixtureWindow(_ window: NSWindow) {
        window.orderOut(nil)
        window.close()
    }

    func testClipboardNotificationHUDAttachesAboveVisibleParentOutsideParentFrame() throws {
        let visibleFrame = try notificationTestVisibleFrame()
        let parent = makeVisibleNotificationParent(
            frame: CGRect(
                x: visibleFrame.midX - 160,
                y: visibleFrame.minY + 220,
                width: 320,
                height: 180
            )
        )
        let state = BlocksNotificationPresentationState()
        let presenter = BlocksAnchoredNotificationPanelPresenter(state: state)
        defer { closeNotificationTestWindows(parent: parent, presenter: presenter) }

        let parentFrame = parent.frame
        state.present(makeNotificationTestDescriptor())
        presenter.attach(to: parent)
        drainAppKitAnimationTransactions()

        let hud = try XCTUnwrap(presenter.panelForTesting)
        XCTAssertTrue(hud.styleMask.contains(.nonactivatingPanel))
        XCTAssertTrue(hud.parent === parent)
        XCTAssertTrue(parent.childWindows?.contains(where: { $0 === hud }) == true)
        XCTAssertTrue(hud.isVisible)
        XCTAssertFalse(hud.frame.intersects(parentFrame))
        XCTAssertGreaterThanOrEqual(
            hud.frame.minY,
            parentFrame.maxY + BlocksNotificationLayout.anchoredGap
        )
        XCTAssertEqual(parent.frame, parentFrame)
    }

    func testClipboardNotificationHUDFallsBackBelowVisibleParentWhenAboveIsUnavailable() throws {
        let visibleFrame = try notificationTestVisibleFrame()
