    func testClipboardNotificationHUDAvoidsFullHeightSideParents() throws {
        let visibleFrame = try notificationTestVisibleFrame()
        let notificationSize = CGSize(width: 260, height: 104)
        let sideWidth = min(360, visibleFrame.width / 3)
        let anchors = [
            CGRect(
                x: visibleFrame.minX,
                y: visibleFrame.minY,
                width: sideWidth,
                height: visibleFrame.height
            ),
            CGRect(
                x: visibleFrame.maxX - sideWidth,
                y: visibleFrame.minY,
                width: sideWidth,
                height: visibleFrame.height
            ),
        ]

        for anchor in anchors {
            let frame = try XCTUnwrap(BlocksNotificationLayout.anchoredFrame(
                size: notificationSize,
                anchorFrame: anchor,
                visibleFrame: visibleFrame
            ))
            XCTAssertFalse(frame.intersects(anchor))
            XCTAssertTrue(visibleFrame.contains(frame))
        }
    }

    func testClipboardNotificationHUDDoesNotCreateChildWhenNoSafeExternalPositionExists() throws {
        let visibleFrame = try notificationTestVisibleFrame()
        let parent = makeVisibleNotificationParent(frame: visibleFrame)
        let state = BlocksNotificationPresentationState()
        let presenter = BlocksAnchoredNotificationPanelPresenter(state: state)
        defer { closeNotificationTestWindows(parent: parent, presenter: presenter) }

        state.present(makeNotificationTestDescriptor())
        presenter.attach(to: parent)
        drainAppKitAnimationTransactions()

        XCTAssertNil(presenter.panelForTesting)
