        XCTAssertNotNil(state.current)
    }

    func testClipboardNotificationHUDDetachReattachAndShutdownClearWindowLifecycle() throws {
        let visibleFrame = try notificationTestVisibleFrame()
        let parent = makeVisibleNotificationParent(
            frame: CGRect(
                x: visibleFrame.midX - 160,
                y: visibleFrame.minY + 220,
                width: 320,
                height: 180
            )
        )
        let state = BlocksNotificationPresentationState()
        let presenter = BlocksAnchoredNotificationPanelPresenter(state: state)
        defer { closeNotificationTestWindows(parent: parent, presenter: presenter) }

        state.present(makeNotificationTestDescriptor())
        presenter.attach(to: parent)
        drainAppKitAnimationTransactions()
        let firstHUD = try XCTUnwrap(presenter.panelForTesting)

        presenter.detach()
        drainAppKitAnimationTransactions()
        XCTAssertFalse(firstHUD.isVisible)
        XCTAssertFalse(parent.childWindows?.contains(where: { $0 === firstHUD }) == true)
        XCTAssertNotNil(state.current, "Detaching must preserve the notification state for reattachment.")

        presenter.attach(to: parent)
        drainAppKitAnimationTransactions()
        let replacementHUD = try XCTUnwrap(presenter.panelForTesting)
        XCTAssertTrue(replacementHUD !== firstHUD)
        XCTAssertTrue(replacementHUD.parent === parent)
        XCTAssertTrue(replacementHUD.isVisible)

        presenter.shutdown()
        drainAppKitAnimationTransactions()
        XCTAssertNil(presenter.panelForTesting)
        XCTAssertNil(state.current)
        XCTAssertFalse(replacementHUD.isVisible)
        XCTAssertFalse(parent.childWindows?.contains(where: { $0 === replacementHUD }) == true)
    }

    func testClipboardPlainTextCopyInvalidLeaseReportsFailureWithoutRecencyOrSuccessNotification()
        async throws
    {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "ClipboardPlainTextInvalidLease.\(UUID().uuidString)",
                isDirectory: true
            )
        let database = try AppDatabase.open(
            environment: StorageEnvironment(rootDirectory: root)
        )
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        let recordID = "plain-text-invalid-lease"
        try insertClipboardCleanupFixture(
            repository,
            id: recordID,
            timestamp: 7_100
        )
        let store = ClipboardStore(repository: repository)
        XCTAssertTrue(store.loadRepositoryState(limit: 10))
        try await waitForClipboardRecords(store, expectedCount: 1)
        let originalLastCopiedAt = store.records.first?.lastCopiedAt
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: store,
            privacyStore: PrivacyStore(repository: nil),
            featureAvailabilityStore: FeatureAvailabilityStore(
                defaults: testDefaults()
            ),
            autoPasteCoordinator: ClipboardAutoPasteCoordinator(
                broker: InvalidLeaseClipboardBroker()
            )
        )
        var statuses: [AppStatus] = []
        coordinator.configure(
            statusRecorder: { statuses.append($0) },
            sectionSelector: { _ in },
            closeTranslationPanel: {},
            translateRecord: { _ in },
            refreshPermissionState: {},
            dispatchPluginEvent: { .allowed($0) },
            stagePluginTextResource: { _, _, _, _ in nil },
            removePluginResources: { _ in },
            accessibilityGranted: { true },
            presentAccessibilityAssist: { _ in }
        )
        coordinator.notificationCoordinator.setHostVisible(true)

        coordinator.copyRecordAsPlainText(recordID: recordID)
        for _ in 0..<100 where statuses.isEmpty {
            await Task.yield()
        }

        XCTAssertEqual(statuses.map(\.kind), [.failed])
        XCTAssertEqual(store.records.first?.lastCopiedAt, originalLastCopiedAt)
        XCTAssertEqual(
            try repository.loadRecord(recordID: recordID)?.lastCopiedAt,
            originalLastCopiedAt
        )
        XCTAssertEqual(
            coordinator.notificationCoordinator.presentationState.current?
                .descriptor.deduplicationKey,
            "clipboard.copy-plain-text.failed"
        )
        XCTAssertNotEqual(
            coordinator.notificationCoordinator.presentationState.current?
                .descriptor.deduplicationKey,
            "clipboard.copy-plain-text.succeeded"
        )
    }

    func testClipboardPlainTextCopyDisableDuringPayloadReadSuppressesAllEffects()
        async throws
    {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "ClipboardPlainTextCopyDisableDuringRead.\(UUID().uuidString)",
                isDirectory: true
            )
        let database = try AppDatabase.open(
            environment: StorageEnvironment(rootDirectory: root)
        )
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        let recordID = "plain-text-disable-during-read"
        try insertClipboardCleanupFixture(
            repository,
            id: recordID,
            timestamp: 7_105
        )
        let store = ClipboardStore(repository: repository)
        XCTAssertTrue(store.loadRepositoryState(limit: 10))
        try await waitForClipboardRecords(store, expectedCount: 1)
        let originalLastCopiedAt = try repository.loadRecord(recordID: recordID)?.lastCopiedAt
        let availability = FeatureAvailabilityStore(defaults: testDefaults())
        let pasteboard = ScriptedClipboardPasteboard(
            items: [],
            changeCount: 30,
            writeOutcomes: [true]
        )
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: store,
            privacyStore: PrivacyStore(repository: nil),
            featureAvailabilityStore: availability,
            autoPasteCoordinator: ClipboardAutoPasteCoordinator(
                pasteboard: pasteboard,
                changeSuppressor: ClipboardPasteboardChangeSuppressor()
            )
        )
        let payloadGate = ClipboardLiveCaptureStageGate()
        coordinator.plainTextCopyPayloadReader = { _ in
            await payloadGate.waitForRelease(of: "plain-text-copy-payload")
            return store.readPayload(
                recordID: recordID,
                purpose: .copyPlainText
            )
        }
        var statuses: [AppStatus] = []
        var events: [BlocksPluginEventEnvelope] = []
        coordinator.configure(
            statusRecorder: { statuses.append($0) },
            sectionSelector: { _ in },
            closeTranslationPanel: {},
            translateRecord: { _ in },
            refreshPermissionState: {},
            dispatchPluginEvent: { envelope in
                events.append(envelope)
                return .allowed(envelope)
            },
            stagePluginTextResource: { _, _, _, _ in nil },
            removePluginResources: { _ in },
            accessibilityGranted: { true },
            presentAccessibilityAssist: { _ in }
        )
        coordinator.notificationCoordinator.setHostVisible(true)

        coordinator.copyRecordAsPlainText(recordID: recordID)
        for _ in 0..<100 {
            if await payloadGate.hasStarted("plain-text-copy-payload") {
                break
            }
            await Task.yield()
        }
        let payloadReadStarted = await payloadGate.hasStarted(
            "plain-text-copy-payload"
        )
        XCTAssertTrue(payloadReadStarted)

        availability.setClipboardEnabled(false)
        coordinator.disableRuntime()
        statuses.removeAll()
        await payloadGate.release("plain-text-copy-payload")
        for _ in 0..<100 {
            await Task.yield()
        }

        XCTAssertEqual(pasteboard.writeCallCount, 0)
        XCTAssertEqual(store.records.first?.lastCopiedAt, originalLastCopiedAt)
        XCTAssertEqual(
            try repository.loadRecord(recordID: recordID)?.lastCopiedAt,
            originalLastCopiedAt
        )
        XCTAssertTrue(events.isEmpty)
        XCTAssertTrue(statuses.isEmpty)
        XCTAssertNil(coordinator.notificationCoordinator.presentationState.current)
    }

    func testClipboardPlainTextCopyDeletedDuringPreparedWriteDoesNotCommitOrPublishSuccess()
        async throws
    {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "ClipboardPlainTextCopyDeleteDuringPrepare.\(UUID().uuidString)",
                isDirectory: true
            )
        let database = try AppDatabase.open(
            environment: StorageEnvironment(rootDirectory: root)
        )
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        let recordID = "plain-text-delete-during-prepare"
        try insertClipboardCleanupFixture(
            repository,
            id: recordID,
            timestamp: 7_110
        )
        let recencyMutationCount = ClipboardCleanupInvocationCounter()
        let store = ClipboardStore(
            repository: repository,
            recordMutationPipelineHooks: ClipboardRecordMutationPipelineHooks(
                beforeMutation: { kind in
                    if kind == .markCopied {
                        _ = recencyMutationCount.increment()
                    }
                }
            )
        )
        XCTAssertTrue(store.loadRepositoryState(limit: 10))
        try await waitForClipboardRecords(store, expectedCount: 1)
        let broker = ControlledPlainTextCopyBroker(blockPrepare: true)
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: store,
            privacyStore: PrivacyStore(repository: nil),
            featureAvailabilityStore: FeatureAvailabilityStore(
                defaults: testDefaults()
            ),
            autoPasteCoordinator: ClipboardAutoPasteCoordinator(broker: broker)
        )
        let succeeded = expectation(description: "plain-text copy must not succeed")
        succeeded.isInverted = true
        let recordUpdated = expectation(description: "plain-text copy must not publish recency")
        recordUpdated.isInverted = true
        var statuses: [AppStatus] = []
        var events: [BlocksPluginEventEnvelope] = []
        coordinator.configure(
            statusRecorder: { status in
                statuses.append(status)
                if status.kind == .ready {
                    succeeded.fulfill()
                }
            },
            sectionSelector: { _ in },
            closeTranslationPanel: {},
            translateRecord: { _ in },
            refreshPermissionState: {},
            dispatchPluginEvent: { envelope in
