    func testClipboardPlainTextCopyAndDeletionSerializeAcrossPhysicalWrite()
        async throws
    {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "ClipboardPlainTextCopyDeleteAfterWrite.\(UUID().uuidString)",
                isDirectory: true
            )
        let database = try AppDatabase.open(
            environment: StorageEnvironment(rootDirectory: root)
        )
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        let recordID = "plain-text-delete-after-write"
        try insertClipboardCleanupFixture(
            repository,
            id: recordID,
            timestamp: 7_115
        )
        let recencyMutationCount = ClipboardCleanupInvocationCounter()
        let deletionMutationCount = ClipboardCleanupInvocationCounter()
        let deletionGateAttempt = expectation(
            description: "deletion attempts to acquire the record commit gate"
        )
        let store = ClipboardStore(
            repository: repository,
            recordMutationPipelineHooks: ClipboardRecordMutationPipelineHooks(
                beforeCommitGateAcquire: { kind in
                    if kind == .delete {
                        deletionGateAttempt.fulfill()
                    }
                },
                beforeMutation: { kind in
                    if kind == .markCopied {
                        _ = recencyMutationCount.increment()
                    } else if kind == .delete {
                        _ = deletionMutationCount.increment()
                    }
                }
            )
        )
        XCTAssertTrue(store.loadRepositoryState(limit: 10))
        try await waitForClipboardRecords(store, expectedCount: 1)
        let broker = ControlledPlainTextCopyBroker(blockAfterPhysicalWrite: true)
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: store,
            privacyStore: PrivacyStore(repository: nil),
            featureAvailabilityStore: FeatureAvailabilityStore(
                defaults: testDefaults()
            ),
            autoPasteCoordinator: ClipboardAutoPasteCoordinator(broker: broker)
        )
        var statuses: [AppStatus] = []
        var events: [BlocksPluginEventEnvelope] = []
        coordinator.configure(
            statusRecorder: { status in
                statuses.append(status)
            },
            sectionSelector: { _ in },
            closeTranslationPanel: {},
            translateRecord: { _ in },
            refreshPermissionState: {},
            dispatchPluginEvent: { envelope in
                events.append(envelope)
                return .allowed(envelope)
            },
            stagePluginTextResource: { _, _, _, _ in nil },
            removePluginResources: { _ in },
            accessibilityGranted: { true },
            presentAccessibilityAssist: { _ in }
        )
        coordinator.notificationCoordinator.setHostVisible(true)

        coordinator.copyRecordAsPlainText(recordID: recordID)
        try await broker.waitUntilPhysicalWrite()
        let deletionTask = Task { @MainActor in
            await store.delete(recordID: recordID)
        }
        await fulfillment(of: [deletionGateAttempt], timeout: 1)
        XCTAssertEqual(
            deletionMutationCount.currentValue,
            0,
            "A deletion must not enter its repository transaction while the physical write owns the commit gate."
        )
        await broker.releaseCommit()
        try await broker.waitUntilCommitReturned()
        let deleted = await deletionTask.value
        XCTAssertTrue(deleted)
        for _ in 0..<20 {
            await Task.yield()
        }

        let metrics = await broker.metrics()
        XCTAssertEqual(metrics.physicalWrites, 1)
        XCTAssertEqual(metrics.commits, 1)
        XCTAssertEqual(deletionMutationCount.currentValue, 1)
        XCTAssertLessThanOrEqual(recencyMutationCount.currentValue, 1)
        XCTAssertNil(try repository.loadRecord(recordID: recordID))
        XCTAssertFalse(statuses.contains { $0.kind == .failed })
        XCTAssertLessThanOrEqual(
            events.filter { $0.name == .clipboardRecordUpdated }.count,
            1
        )
    }

