    func testExplicitTextCopyRechecksPolicyAfterCleanupWaitBeforePersisting()
        async throws
    {
        enum Revocation {
            case paused
            case disabled
            case privacyUnavailable
        }

        for revocation in [
            Revocation.paused,
            .disabled,
            .privacyUnavailable,
        ] {
            let root = FileManager.default.temporaryDirectory
                .appendingPathComponent(
                    "ExplicitTextCopyCleanupPolicy.\(UUID().uuidString)",
                    isDirectory: true
                )
            let database = try AppDatabase.open(
                environment: StorageEnvironment(rootDirectory: root)
            )
            let privacyDatabase = try AppDatabase.open(
                environment: StorageEnvironment(
                    rootDirectory: root.appendingPathComponent("privacy", isDirectory: true)
                )
            )
            defer {
                database.close()
                privacyDatabase.close()
                try? FileManager.default.removeItem(at: root)
            }
            let cleanupStarted = expectation(
                description: "cleanup blocks \(String(describing: revocation))"
            )
            let releaseCleanup = DispatchSemaphore(value: 0)
            let store = ClipboardStore(
                repository: ClipboardRepository(database: database),
                cleanupPolicyDebounce: .zero,
                cleanupMutationPipelineHooks: ClipboardCleanupMutationPipelineHooks(
                    beforeMutation: { _ in
                        cleanupStarted.fulfill()
                        releaseCleanup.wait()
                    }
                )
            )
            let privacyStore = PrivacyStore(
                repository: PrivacyPolicyRepository(database: privacyDatabase)
            )
            let availability = FeatureAvailabilityStore(defaults: testDefaults())
            let pasteboard = ScriptedClipboardPasteboard(
                items: [],
                changeCount: 40,
                writeOutcomes: [true]
            )
            let coordinator = ClipboardFeatureCoordinator(
                clipboardStore: store,
                privacyStore: privacyStore,
                featureAvailabilityStore: availability,
                autoPasteCoordinator: ClipboardAutoPasteCoordinator(
                    pasteboard: pasteboard,
                    changeSuppressor: ClipboardPasteboardChangeSuppressor()
                )
            )
            var events: [BlocksPluginEventEnvelope] = []
            store.configurePluginEventDispatcher { envelope in
                events.append(envelope)
                return .allowed(envelope)
            }
            for _ in 0..<100 where !privacyStore.canCaptureClipboard {
                try await Task.sleep(for: .milliseconds(10))
            }
            XCTAssertTrue(privacyStore.canCaptureClipboard)
            XCTAssertTrue(store.requestPolicyApplication(
                cleanupMode: .count,
                retentionPolicy: .days30,
                maxItems: 500,
                preserveFavorite: false
            ) { _, _ in })
            await fulfillment(of: [cleanupStarted], timeout: 1)

            let copy = Task { @MainActor in
                await coordinator.copyExplicitText(
                    "cleanup policy fixture",
                    source: .translationResult
                )
            }
            for _ in 0..<100 where pasteboard.writeCallCount == 0 {
                await Task.yield()
            }
            XCTAssertEqual(pasteboard.writeCallCount, 1)

            switch revocation {
            case .paused:
                store.recorderPaused = true
            case .disabled:
                availability.setClipboardEnabled(false)
                coordinator.disableRuntime()
            case .privacyUnavailable:
                privacyDatabase.close()
                privacyStore.reloadSnapshot()
                XCTAssertFalse(privacyStore.canCaptureClipboard)
            }
            releaseCleanup.signal()

            let outcome = await copy.value
            XCTAssertEqual(outcome, .copiedWithoutHistory)
            XCTAssertTrue(store.records.isEmpty)
            XCTAssertTrue(
                try ClipboardRepository(database: database).loadRecent(limit: 10).isEmpty
            )
            XCTAssertTrue(events.isEmpty)
        }
    }

    func testExplicitTextCopyPrivacyReloadBeforeFinalAdmissionSkipsHistoryEffects()
        async throws
    {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "ExplicitTextCopyPrivacyAdmissionRace.\(UUID().uuidString)",
                isDirectory: true
            )
        let database = try AppDatabase.open(
            environment: StorageEnvironment(rootDirectory: root)
        )
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }

        let admissionReached = expectation(
            description: "explicit copy reaches final privacy admission"
        )
        let releaseAdmission = DispatchSemaphore(value: 0)
        let repository = ClipboardRepository(database: database)
        let clipboardStore = ClipboardStore(
            repository: repository,
            capturePersistencePipelineHooks: ClipboardCapturePersistencePipelineHooks(
                beforePrivacyAdmission: {
                    admissionReached.fulfill()
                    releaseAdmission.wait()
                }
            )
        )
        let privacyStore = PrivacyStore(
            repository: PrivacyPolicyRepository(database: database)
        )
        let pasteboard = ScriptedClipboardPasteboard(
            items: [],
            changeCount: 80,
            writeOutcomes: [true]
        )
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: clipboardStore,
            privacyStore: privacyStore,
            featureAvailabilityStore: FeatureAvailabilityStore(defaults: testDefaults()),
            autoPasteCoordinator: ClipboardAutoPasteCoordinator(
                pasteboard: pasteboard,
                changeSuppressor: ClipboardPasteboardChangeSuppressor()
            )
        )
        var statuses: [AppStatus] = []
        var events: [BlocksPluginEventEnvelope] = []
        coordinator.configure(
            statusRecorder: { statuses.append($0) },
            sectionSelector: { _ in },
            closeTranslationPanel: {},
            translateRecord: { _ in },
            refreshPermissionState: {},
            dispatchPluginEvent: { envelope in
                events.append(envelope)
                return .allowed(envelope)
            },
            stagePluginTextResource: { _, _, _, _ in nil },
            removePluginResources: { _ in },
            accessibilityGranted: { true },
            presentAccessibilityAssist: { _ in }
        )
        coordinator.notificationCoordinator.setHostVisible(true)
        for _ in 0..<100 where !privacyStore.canCaptureClipboard {
            try await Task.sleep(for: .milliseconds(10))
        }
        XCTAssertTrue(privacyStore.canCaptureClipboard)

        let copy = Task { @MainActor in
            await coordinator.copyExplicitText(
                "privacy admission revocation fixture",
                source: .translationResult
            )
        }
        await fulfillment(of: [admissionReached], timeout: 1)
        XCTAssertEqual(pasteboard.writeCallCount, 1)

        let authorizationGeneration = privacyStore.privacyCaptureAuthorizationGeneration
        let reloaded = expectation(
            description: "privacy reload completes with a new authorization generation"
        )
        var availabilityObservation: AnyCancellable?
        availabilityObservation = privacyStore.$capturePolicyAvailability.sink { availability in
            if availability == .ready,
               privacyStore.privacyCaptureAuthorizationGeneration > authorizationGeneration {
                reloaded.fulfill()
            }
        }
        privacyStore.reloadSnapshot()
        XCTAssertFalse(privacyStore.canCaptureClipboard)
        await fulfillment(of: [reloaded], timeout: 1)
        availabilityObservation?.cancel()
        availabilityObservation = nil
        XCTAssertTrue(privacyStore.canCaptureClipboard)

        releaseAdmission.signal()
        let outcome = await copy.value

        XCTAssertEqual(outcome, .copiedWithoutHistory)
        XCTAssertTrue(clipboardStore.records.isEmpty)
        XCTAssertTrue(try repository.loadRecent(limit: 10).isEmpty)
        XCTAssertTrue(events.allSatisfy { $0.name != .clipboardRecordUpdated })
        XCTAssertTrue(statuses.isEmpty)
        XCTAssertNil(coordinator.notificationCoordinator.presentationState.current)
    }

