            repository: PrivacyPolicyRepository(database: database)
        )
        let pasteboard = ScriptedClipboardPasteboard(
            items: [],
            changeCount: 90,
            writeOutcomes: [true]
        )
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: clipboardStore,
            privacyStore: privacyStore,
            featureAvailabilityStore: FeatureAvailabilityStore(defaults: testDefaults()),
            autoPasteCoordinator: ClipboardAutoPasteCoordinator(
                pasteboard: pasteboard,
                changeSuppressor: ClipboardPasteboardChangeSuppressor()
            )
        )
        var statuses: [AppStatus] = []
        var events: [BlocksPluginEventEnvelope] = []
        coordinator.configure(
            statusRecorder: { statuses.append($0) },
            sectionSelector: { _ in },
            closeTranslationPanel: {},
            translateRecord: { _ in },
            refreshPermissionState: {},
            dispatchPluginEvent: { envelope in
                events.append(envelope)
                return .allowed(envelope)
            },
            stagePluginTextResource: { _, _, _, _ in nil },
            removePluginResources: { _ in },
            accessibilityGranted: { true },
            presentAccessibilityAssist: { _ in }
        )
        coordinator.notificationCoordinator.setHostVisible(true)
        for _ in 0..<100 where !privacyStore.canCaptureClipboard {
            try await Task.sleep(for: .milliseconds(10))
        }
        XCTAssertTrue(privacyStore.canCaptureClipboard)

        let text = "privacy continuation revocation fixture"
        let copy = Task { @MainActor in
            await coordinator.copyExplicitText(text, source: .translationResult)
        }
        await fulfillment(of: [committed], timeout: 1)
        XCTAssertEqual(pasteboard.writeCallCount, 1)
        let committedRecord = try XCTUnwrap(repository.loadRecent(limit: 10).first)
        let committedLastCopiedAt = committedRecord.lastCopiedAt
        XCTAssertEqual(
            try repository.readPayload(recordID: committedRecord.id)?.text,
            text
        )

        let authorizationGeneration = privacyStore.privacyCaptureAuthorizationGeneration
        let reloaded = expectation(
            description: "privacy reload invalidates the committed copy continuation"
        )
        var availabilityObservation: AnyCancellable?
        availabilityObservation = privacyStore.$capturePolicyAvailability.sink { availability in
            if availability == .ready,
               privacyStore.privacyCaptureAuthorizationGeneration > authorizationGeneration {
                reloaded.fulfill()
            }
        }
        privacyStore.reloadSnapshot()
        XCTAssertFalse(privacyStore.canCaptureClipboard)
        await fulfillment(of: [reloaded], timeout: 1)
        availabilityObservation?.cancel()
        availabilityObservation = nil
        XCTAssertTrue(privacyStore.canCaptureClipboard)

        releaseContinuation.signal()
        let outcome = await copy.value
        let durableRecord = try XCTUnwrap(
            repository.loadRecord(recordID: committedRecord.id)
        )

        XCTAssertEqual(outcome, .copiedWithoutHistory)
        XCTAssertEqual(durableRecord.lastCopiedAt, committedLastCopiedAt)
        XCTAssertEqual(
            try repository.readPayload(recordID: committedRecord.id)?.text,
            text
        )
        XCTAssertTrue(clipboardStore.records.isEmpty)
        XCTAssertTrue(events.allSatisfy { $0.name != .clipboardRecordUpdated })
        XCTAssertTrue(statuses.isEmpty)
        XCTAssertNil(coordinator.notificationCoordinator.presentationState.current)
    }

    func testClipboardPanelTagActionsDispatchOnlyCommittedExactMutations()
        async throws
    {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "ClipboardPanelTagActions.\(UUID().uuidString)",
                isDirectory: true
            )
        let database = try AppDatabase.open(
            environment: StorageEnvironment(rootDirectory: root)
        )
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        let recordID = "panel-tag-record"
        try insertClipboardCleanupFixture(
            repository,
            id: recordID,
            timestamp: 7_110
        )
        let store = ClipboardStore(repository: repository)
        XCTAssertTrue(store.loadRepositoryState(limit: 10))
        try await waitForClipboardRecords(store, expectedCount: 1)
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: store,
            privacyStore: PrivacyStore(repository: nil),
            featureAvailabilityStore: FeatureAvailabilityStore(
                defaults: testDefaults()
            )
        )
        var events: [BlocksPluginEventEnvelope] = []
        coordinator.dispatchPluginEvent = { envelope in
            events.append(envelope)
            return .allowed(envelope)
        }
        let existingTag = await store.tagStore.createFilterTag(
            displayName: "Panel Tag"
        )
        let existingTagID = try XCTUnwrap(existingTag)
        let actions = coordinator.makeClipboardPanelActions()

        await actions.toggleTag(recordID, existingTagID)
        await actions.toggleTag(recordID, existingTagID)
        await actions.createTagAndAttach(recordID, "Created Tag")
        await actions.toggleTag(recordID, "missing-tag")

        XCTAssertEqual(events.map { $0.name }, [
            .clipboardTagChanged,
            .clipboardTagChanged,
            .clipboardTagChanged,
        ])
        XCTAssertEqual(events.map { $0.payload["operation"] }, [
            .string("attached"),
            .string("detached"),
            .string("created_and_attached"),
        ])
        XCTAssertEqual(events[0].payload["record_id"], .string(recordID))
        XCTAssertEqual(events[0].payload["tag_id"], .string(existingTagID))
        XCTAssertEqual(events[1].payload["record_id"], .string(recordID))
        XCTAssertEqual(events[1].payload["tag_id"], .string(existingTagID))
        let createdTagID: String
        guard case let .string(value)? = events[2].payload["tag_id"] else {
            return XCTFail("Created-and-attached event must include its tag ID.")
        }
        createdTagID = value
        XCTAssertEqual(events[2].payload["record_id"], .string(recordID))
        XCTAssertTrue(store.tagStore.isTagged(recordID: recordID, tagID: createdTagID))
    }

    func testIndependentNotificationHUDKeepsStandardCloseButtonClickable()
        throws
    {
        let screen = try XCTUnwrap(NSScreen.main)
        let presenter = BlocksNotificationPanelPresenter()
        defer { presenter.shutdown() }

        presenter.present(
            BlocksNotificationDescriptor(
                level: .warning,
                title: "Dismissible notification",
                dismissPolicy: .manual
            ),
            on: screen,
            avoiding: []
        )
        let panel = try XCTUnwrap(presenter.panelForTesting)
        XCTAssertFalse(panel.ignoresMouseEvents)
        XCTAssertTrue(panel.styleMask.contains(.nonactivatingPanel))
        XCTAssertFalse(panel.canBecomeKey)
        XCTAssertNil(panel.parent)

        presenter.present(
            BlocksNotificationDescriptor(
                level: .warning,
                title: "Actionable notification",
                action: BlocksNotificationAction(title: "Retry") {}
            ),
            on: screen,
            avoiding: []
        )
        XCTAssertTrue(presenter.panelForTesting === panel)
        XCTAssertFalse(panel.ignoresMouseEvents)
        XCTAssertFalse(panel.canBecomeKey)
        XCTAssertNil(panel.parent)
        presenter.dismiss()
        XCTAssertFalse(panel.isVisible)
    }

    func testIndependentNotificationHUDUsesAcceptedCardAndMeasuredHeight() throws {
        let screen = try XCTUnwrap(NSScreen.main)
        let presenter = BlocksNotificationPanelPresenter()
        defer { presenter.shutdown() }
        presenter.present(
            BlocksNotificationDescriptor(level: .error, title: "截图超时", detail: "可以关闭此提示后重试。"),
            on: screen,
            avoiding: []
        )
        let panel = try XCTUnwrap(presenter.panelForTesting)
        let failureHeight = panel.frame.height
        XCTAssertGreaterThan(failureHeight, 30)
        XCTAssertLessThan(failureHeight, 150, "Short notifications must not reserve a fixed 150pt panel")
        XCTAssertFalse(panel.ignoresMouseEvents)
        XCTAssertFalse(panel.canBecomeKey)
        XCTAssertFalse(panel.canBecomeMain)

        let compact = BlocksNotificationDescriptor(
            level: .success, title: "Copied", presentationStyle: .compactConfirmation
        )
        presenter.present(compact, on: screen, avoiding: [])
        XCTAssertFalse(panel.ignoresMouseEvents, "A rejected lower-priority card must not disable the visible error's close button")
        XCTAssertEqual(panel.frame.height, failureHeight, accuracy: 1)
        presenter.dismiss()
        XCTAssertFalse(panel.isVisible)

        presenter.present(compact, on: screen, avoiding: [])
        XCTAssertTrue(panel.ignoresMouseEvents)
        XCTAssertLessThan(panel.frame.height, failureHeight)
        XCTAssertFalse(panel.canBecomeKey)
    }

    private func notificationTestVisibleFrame() throws -> CGRect {
        guard let visibleFrame = NSScreen.main?.visibleFrame,
              visibleFrame.width >= 360,
              visibleFrame.height >= 420 else {
            throw XCTSkip("Anchored notification AppKit lifecycle tests require a usable main screen.")
        }
        return visibleFrame
    }

    private func makeVisibleNotificationParent(frame: CGRect) -> NSPanel {
        let panel = NSPanel(
            contentRect: frame,
            styleMask: [.titled, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        BlocksFloatingPanelWindowRole.transientNonactivatingUtility.apply(to: panel)
        panel.orderFrontRegardless()
        drainAppKitAnimationTransactions()
        return panel
    }

    private func makeNotificationTestDescriptor() -> BlocksNotificationDescriptor {
        BlocksNotificationDescriptor(
            level: .warning,
            title: "Clipboard notification test",
            dismissPolicy: .manual
        )
    }

    private func closeNotificationTestWindows(
        parent: NSPanel,
        presenter: BlocksAnchoredNotificationPanelPresenter
    ) {
        presenter.shutdown()
        parent.childWindows?.forEach { child in
            parent.removeChildWindow(child)
            child.close()
        }
        parent.close()
        drainAppKitAnimationTransactions()
    }

    func testRegularWindowVisibilitySessionRestoresOnlyCapturedRegularWindows() {
        let regular = NSWindow(
            contentRect: CGRect(x: 10, y: 10, width: 240, height: 180),
            styleMask: [.titled],
            backing: .buffered,
            defer: false
        )
        let transient = NSPanel(
            contentRect: CGRect(x: 20, y: 20, width: 120, height: 80),
            styleMask: [.borderless, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        transient.level = .popUpMenu
        let owner = NSPanel(
            contentRect: CGRect(x: 40, y: 40, width: 300, height: 200),
            styleMask: [.titled, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        regular.animationBehavior = .none
        transient.animationBehavior = .none
        owner.animationBehavior = .none
        regular.orderFront(nil)
        transient.orderFront(nil)
        owner.orderFront(nil)
        defer {
            regular.orderOut(nil)
            transient.orderOut(nil)
            owner.orderOut(nil)
            drainAppKitAnimationTransactions()
        }
        let session = BlocksRegularWindowVisibilitySession(
            windowsProvider: { [regular, transient, owner] },
            applicationIsActive: { false }
        )

        session.hideRegularWindows(excluding: owner)

        XCTAssertFalse(regular.isVisible)
        XCTAssertTrue(transient.isVisible)
        XCTAssertTrue(owner.isVisible)

        session.restore()

        XCTAssertTrue(regular.isVisible)
        XCTAssertTrue(transient.isVisible)
        XCTAssertTrue(owner.isVisible)
    }

