    func testPermissionStoreSupersededAccessibilityAssistRefreshPublishesBeforeRetainedCompletion() async throws {
        let initial = permissionRefreshTestSnapshot(
            granted: false,
            capturedAt: Date(timeIntervalSinceReferenceDate: 1)
        )
        let granted = permissionRefreshTestSnapshot(
            granted: true,
            capturedAt: Date(timeIntervalSinceReferenceDate: 2)
        )
        let denied = permissionRefreshTestSnapshot(
            granted: false,
            capturedAt: Date(timeIntervalSinceReferenceDate: 3)
        )
        let provider = ControlledPermissionSnapshotProvider(initialSnapshot: initial)
        let accessRequester = RecordingPermissionAccessRequester()
        let assistPresenter = ManualPermissionAssistPresenter()
        let systemActions = RecordingPermissionSystemActions()
        let store = PermissionStore(
            snapshotProvider: provider,
            accessRequester: accessRequester,
            assistPresenter: assistPresenter,
            systemActions: systemActions
        )
        defer { provider.releaseAll(with: granted) }

        try await provider.waitUntilStarted(ordinal: 0)
        let completion = expectation(description: "accessibility assist completion")
        var observedSnapshots: [PermissionStateSnapshot] = []

        store.requestAccessibilityPermissionAssist {
            observedSnapshots.append(store.permissionSnapshot)
            completion.fulfill()
        }
        assistPresenter.finish(kind: .accessibility)
        try await provider.waitUntilStarted(ordinal: 1)

        store.requestInputMonitoringPermissionAssist()
        assistPresenter.finish(kind: .inputMonitoring)
        try await provider.waitUntilStarted(ordinal: 2)
        try provider.finish(ordinal: 2, with: granted)

        await fulfillment(of: [completion], timeout: 1)
        XCTAssertEqual(accessRequester.requestedKinds, [.accessibility, .inputMonitoring])
        XCTAssertEqual(observedSnapshots.count, 1)
        XCTAssertTrue(observedSnapshots[0].accessibilityGranted)
        XCTAssertEqual(observedSnapshots[0].capturedAt, granted.capturedAt)
        XCTAssertEqual(store.permissionSnapshot, granted)

        try provider.finish(ordinal: 1, with: denied)
        try await provider.waitUntilReturned(ordinal: 1)
        await Task.yield()

        XCTAssertEqual(store.permissionSnapshot, granted)
        XCTAssertEqual(observedSnapshots.count, 1)
        XCTAssertEqual(observedSnapshots[0].capturedAt, granted.capturedAt)
    }

    func testPermissionStorePublishedSnapshotReentrancyDefersCompletionToReplacementGeneration()
        async throws
    {
        let initial = permissionRefreshTestSnapshot(
            granted: false,
            capturedAt: Date(timeIntervalSinceReferenceDate: 4)
        )
        let superseded = permissionRefreshTestSnapshot(
            granted: false,
            capturedAt: Date(timeIntervalSinceReferenceDate: 5)
        )
        let current = permissionRefreshTestSnapshot(
            granted: true,
            capturedAt: Date(timeIntervalSinceReferenceDate: 6)
        )
        let provider = ControlledPermissionSnapshotProvider(initialSnapshot: initial)
        let assistPresenter = ManualPermissionAssistPresenter()
        let store = PermissionStore(
            snapshotProvider: provider,
            accessRequester: RecordingPermissionAccessRequester(),
            assistPresenter: assistPresenter,
            systemActions: RecordingPermissionSystemActions()
        )
        defer { provider.releaseAll(with: current) }

        try await provider.waitUntilStarted(ordinal: 0)
        let completion = expectation(description: "replacement generation publishes before completion")
        var completionSnapshots: [PermissionStateSnapshot] = []
        store.requestAccessibilityPermissionAssist {
            completionSnapshots.append(store.permissionSnapshot)
            completion.fulfill()
        }
        assistPresenter.finish(kind: .accessibility)
        try await provider.waitUntilStarted(ordinal: 1)

        var didStartReplacement = false
        var observation: AnyCancellable?
        observation = store.$permissionSnapshot.dropFirst().sink { _ in
            guard !didStartReplacement else { return }
            didStartReplacement = true
            store.refreshPermissionState()
        }
        defer { observation?.cancel() }

        try provider.finish(ordinal: 1, with: superseded)
        try await provider.waitUntilStarted(ordinal: 2)
        await Task.yield()

        XCTAssertTrue(didStartReplacement)
        XCTAssertTrue(completionSnapshots.isEmpty)
        XCTAssertEqual(store.permissionSnapshot, superseded)

        try provider.finish(ordinal: 2, with: current)
        await fulfillment(of: [completion], timeout: 1)

        XCTAssertEqual(completionSnapshots.count, 1)
        XCTAssertEqual(completionSnapshots[0], current)
        XCTAssertEqual(store.permissionSnapshot, current)
    }

