    func testShortcutFixtureRegistrationNeverInvokesCarbonSystemBackend() {
        let command = ShortcutCommand.clipboardHistory
        var registrationCount = 0
        var unregistrationCount = 0
        let controller = ShortcutController.fixture(
            registrar: { _, _, _, _ in
                registrationCount += 1
                return (status: noErr, hasReference: true)
            },
            unregistrar: { _ in
                unregistrationCount += 1
                return noErr
            }
        )
        let bindings = Dictionary(
            uniqueKeysWithValues: ShortcutCommand.allCases.map { candidate in
                var binding = candidate.defaultBinding
                binding.enabled = candidate == command
                return (candidate, binding)
            }
        )

        let results = controller.registerShortcuts(
            bindings: bindings,
            actions: [command: {}]
        )
        XCTAssertEqual(registrationCount, 1)
        XCTAssertTrue(results.first { $0.command == command }?.registered ?? false)

        controller.unregisterAll()

        XCTAssertEqual(unregistrationCount, 1)
        XCTAssertEqual(
            controller.systemRegistrationCallCountsForFixtures,
            .zero
        )
    }

