    func testShortcutBindingRecordingRejectsUnsupportedPhysicalKeysAndMissingModifiers() {
        let unsupportedKeyCodes: [UInt32] = [
            UInt32(kVK_F1),
            UInt32(kVK_LeftArrow),
            UInt32(kVK_Return),
            UInt32(kVK_Space)
        ]

        for keyCode in unsupportedKeyCodes {
            XCTAssertNil(
                ShortcutBinding.makeForFixtures(
                    command: .screenshotSmart,
                    keyCode: keyCode,
                    modifierFlags: [.command],
                    charactersIgnoringModifiers: "A",
                    enabled: true
                )
            )
        }

        XCTAssertNil(
            ShortcutBinding.makeForFixtures(
                command: .screenshotSmart,
                keyCode: UInt32(kVK_ANSI_A),
                modifierFlags: [],
                charactersIgnoringModifiers: "A",
                enabled: true
            )
        )

        XCTAssertNil(
            ShortcutBinding.makeForFixtures(
                command: .screenshotSmart,
                keyCode: UInt32(kVK_ANSI_A),
                modifierFlags: [.capsLock],
                charactersIgnoringModifiers: "A",
                enabled: true
            )
        )

        let normalizedBinding = ShortcutBinding.makeForFixtures(
            command: .screenshotSmart,
            keyCode: UInt32(kVK_ANSI_A),
            modifierFlags: [.command, .capsLock],
            charactersIgnoringModifiers: "A",
            enabled: true
        )
        XCTAssertEqual(normalizedBinding?.modifierFlags, [.command])

        let legacyKeypadBinding = ShortcutBinding.makeForFixtures(
            command: .screenshotSmart,
            keyCode: UInt32(kVK_ANSI_Keypad0),
            modifierFlags: [.command],
            charactersIgnoringModifiers: "0",
            enabled: true
        )
        XCTAssertEqual(legacyKeypadBinding?.keyLabel, "Keypad 0")
        XCTAssertEqual(legacyKeypadBinding?.displayValue, "Command + Keypad 0")
    }

    func testShortcutBindingStoreCanonicalizesPersistedLabelAndRejectsInvalidKeyCode() {
        let suite = "ShortcutBindingStoreTests.\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: suite)!
        defaults.removePersistentDomain(forName: suite)
        let command = ShortcutCommand.screenshotSmart
        defer { defaults.removePersistentDomain(forName: suite) }

        ShortcutBindingStore.save(
            ShortcutBinding(
                command: command,
                keyCode: UInt32(kVK_ANSI_A),
                keyLabel: "Ж",
                modifierFlagsRawValue: UInt(NSEvent.ModifierFlags.command.rawValue),
                enabled: true
            ),
            userDefaults: defaults
        )
        XCTAssertEqual(ShortcutBindingStore.customBinding(for: command, userDefaults: defaults)?.keyLabel, "A")
        XCTAssertEqual(ShortcutBindingStore.binding(for: command, userDefaults: defaults).displayValue, "Command + A")

        let key = "shortcut.binding.\(command.rawValue)"
        defaults.set("not-json", forKey: key)
        XCTAssertEqual(ShortcutBindingStore.binding(for: command, userDefaults: defaults), command.defaultBinding)

        let invalidBinding = ShortcutBinding(
            command: command,
            keyCode: UInt32(kVK_F1),
            keyLabel: "A",
            modifierFlagsRawValue: UInt(NSEvent.ModifierFlags.command.rawValue),
            enabled: true
        )
        let invalidJSON = try! String(data: JSONEncoder().encode(invalidBinding), encoding: .utf8)
        defaults.set(invalidJSON, forKey: key)
        XCTAssertEqual(ShortcutBindingStore.binding(for: command, userDefaults: defaults), command.defaultBinding)

        let emptyModifierBinding = ShortcutBinding(
            command: command,
            keyCode: UInt32(kVK_ANSI_A),
            keyLabel: "A",
            modifierFlagsRawValue: 0,
            enabled: true
        )
        let emptyModifierJSON = try! String(data: JSONEncoder().encode(emptyModifierBinding), encoding: .utf8)
        defaults.set(emptyModifierJSON, forKey: key)
        XCTAssertEqual(ShortcutBindingStore.binding(for: command, userDefaults: defaults), command.defaultBinding)

        defaults.removeObject(forKey: key)
        ShortcutBindingStore.save(invalidBinding, userDefaults: defaults)
        XCTAssertNil(defaults.string(forKey: key))
        ShortcutBindingStore.save(emptyModifierBinding, userDefaults: defaults)
        XCTAssertNil(defaults.string(forKey: key))

        let mixedModifierBinding = ShortcutBinding(
            command: command,
            keyCode: UInt32(kVK_ANSI_A),
            keyLabel: "A",
            modifierFlagsRawValue: UInt(NSEvent.ModifierFlags([.command, .capsLock]).rawValue),
            enabled: true
        )
        ShortcutBindingStore.save(mixedModifierBinding, userDefaults: defaults)
        XCTAssertEqual(
            ShortcutBindingStore.customBinding(for: command, userDefaults: defaults)?.modifierFlags,
            [.command]
        )
    }

