    func testShortcutRegistrationUsesPhysicalKeyCodeAndDetectsDuplicateDespiteLegacyLabels() {
        let firstCommand = ShortcutCommand.screenshotSmart
        let duplicateCommand = ShortcutCommand.clipboardHistory
        let modifierFlags = NSEvent.ModifierFlags([.command, .capsLock])
