    func testShortcutRegistrationFailsClosedUntilPendingUnregistrationSucceeds() async {
        let command = ShortcutCommand.clipboardHistory
        var registrarCallCount = 0
        var unregistrationShouldFail = false
        var unregisteredHotKeyIDs: [UInt32] = []
        var oldRouteToken: UInt32?
        var actionCount = 0
        let controller = ShortcutController.fixture(
            registrar: { _, _, hotKeyID, _ in
                registrarCallCount += 1
                oldRouteToken = oldRouteToken ?? hotKeyID.id
                return (status: noErr, hasReference: true)
            },
            unregistrar: { hotKeyID in
                unregisteredHotKeyIDs.append(hotKeyID.id)
                return unregistrationShouldFail ? OSStatus(-50) : noErr
            }
        )
        let bindings = shortcutBindings(enabledCommands: [command])
        defer { controller.unregisterAll() }

        _ = controller.registerShortcuts(
            bindings: bindings,
            actions: [command: { actionCount += 1 }]
        )
        guard let oldRouteToken else {
            XCTFail("The fixture requires an initial Carbon route.")
            return
        }

        unregistrationShouldFail = true
        let blockedResults = controller.registerShortcuts(
            bindings: bindings,
            actions: [command: { actionCount += 1 }]
        )

        XCTAssertEqual(registrarCallCount, 1, "Cleanup failure must block all replacement registration.")
        XCTAssertEqual(controller.pendingUnregistrationCountForFixtures, 1)
        XCTAssertEqual(controller.activeRouteCountForFixtures, 0)
        let blockedResult = blockedResults.first { $0.command == command }
        XCTAssertFalse(blockedResult?.registered ?? true)
        XCTAssertEqual(blockedResult?.osStatus, OSStatus(-50))
        XCTAssertEqual(blockedResult?.failureReason, .unregistrationFailed)
        XCTAssertEqual(
            blockedResult?.localizedStatus,
            L10n.string("settings.shortcutReregisterFailedTitle")
        )
        XCTAssertFalse(
            controller.handlesRoutedEventForFixtures(
                signature: ShortcutController.routeSignatureForFixtures,
                routeToken: oldRouteToken
            )
        )

        controller.simulateRoutedEventForFixtures(routeToken: oldRouteToken, pressed: true)
        await Task.yield()
        XCTAssertEqual(actionCount, 0, "A failed unregistration must not leave its stale action routable.")

        unregistrationShouldFail = false
        let recoveredResults = controller.registerShortcuts(
            bindings: bindings,
            actions: [command: { actionCount += 1 }]
        )

        XCTAssertEqual(registrarCallCount, 2)
        XCTAssertEqual(unregisteredHotKeyIDs, [oldRouteToken, oldRouteToken])
        XCTAssertEqual(controller.pendingUnregistrationCountForFixtures, 0)
        XCTAssertEqual(controller.activeRouteCountForFixtures, 1)
        XCTAssertTrue(recoveredResults.first { $0.command == command }?.registered ?? false)
    }

    func testShortcutRegistrationBlocksAllCommandsWhenOnlyOneUnregistrationFails() {
        let commands: Set<ShortcutCommand> = [.screenshotSmart, .clipboardHistory]
        var registrarCallCount = 0
        var registeredRouteTokens: [UInt32] = []
        var unregisteredHotKeyIDs: [UInt32] = []
        var failingHotKeyID: UInt32?
        var hasFailedOnce = false
        let controller = ShortcutController.fixture(
            registrar: { _, _, hotKeyID, _ in
                registrarCallCount += 1
                registeredRouteTokens.append(hotKeyID.id)
                return (status: noErr, hasReference: true)
            },
            unregistrar: { hotKeyID in
                unregisteredHotKeyIDs.append(hotKeyID.id)
                if hotKeyID.id == failingHotKeyID && !hasFailedOnce {
                    hasFailedOnce = true
                    return OSStatus(-50)
                }
                return noErr
            }
        )
        let bindings = shortcutBindings(enabledCommands: commands)
        defer { controller.unregisterAll() }

        _ = controller.registerShortcuts(
            bindings: bindings,
            actions: Dictionary(uniqueKeysWithValues: commands.map { ($0, {}) })
        )
        XCTAssertEqual(registrarCallCount, 2)
        guard registeredRouteTokens.count == 2 else {
            XCTFail("The fixture requires route tokens for both enabled commands.")
            return
        }
        failingHotKeyID = registeredRouteTokens[0]

        let blockedResults = controller.registerShortcuts(
            bindings: bindings,
            actions: Dictionary(uniqueKeysWithValues: commands.map { ($0, {}) })
        )

        XCTAssertEqual(registrarCallCount, 2)
        XCTAssertEqual(controller.pendingUnregistrationCountForFixtures, 1)
        XCTAssertEqual(controller.activeRouteCountForFixtures, 0)
        for command in commands {
            XCTAssertEqual(
                blockedResults.first { $0.command == command }?.failureReason,
                .unregistrationFailed
            )
        }

        _ = controller.registerShortcuts(
            bindings: bindings,
            actions: Dictionary(uniqueKeysWithValues: commands.map { ($0, {}) })
        )

        XCTAssertEqual(registrarCallCount, 4)
        XCTAssertEqual(
            unregisteredHotKeyIDs,
            [registeredRouteTokens[0], registeredRouteTokens[1], registeredRouteTokens[0]]
        )
        XCTAssertEqual(controller.pendingUnregistrationCountForFixtures, 0)
        XCTAssertEqual(controller.activeRouteCountForFixtures, 2)
    }

    func testShortcutRegistrationReportsOwnUnregistrationStatusInStableCommandOrder() {
        let commands: Set<ShortcutCommand> = [.screenshotSmart, .clipboardHistory]
        var registeredRouteTokens: [UInt32] = []
