    func testShortcutOrphanedUnregistrationRecoversBeforeNextControllerRegisters() async {
        ShortcutController.resetOrphanedUnregistrationsForFixtures()
        defer { ShortcutController.resetOrphanedUnregistrationsForFixtures() }

        let command = ShortcutCommand.clipboardHistory
        let bindings = shortcutBindings(enabledCommands: [command])
        var cleanupShouldFail = true
        var registrarCallCount = 0
        var unregisteredRouteTokens: [UInt32] = []
        var oldRouteToken: UInt32?
        var oldActionCount = 0
        weak var releasedController: ShortcutController?

        do {
            var firstController: ShortcutController? = ShortcutController.fixture(
                registrar: { _, _, hotKeyID, _ in
                    registrarCallCount += 1
                    oldRouteToken = hotKeyID.id
                    return (status: noErr, hasReference: true)
                },
                unregistrar: { hotKeyID in
                    unregisteredRouteTokens.append(hotKeyID.id)
                    return cleanupShouldFail ? OSStatus(-50) : noErr
                }
            )
            releasedController = firstController
            _ = firstController?.registerShortcuts(
                bindings: bindings,
                actions: [command: { oldActionCount += 1 }]
            )
            firstController = nil
        }

        XCTAssertNil(releasedController)
        guard let oldRouteToken else {
            XCTFail("The first controller must reserve a route token.")
            return
        }
        XCTAssertEqual(ShortcutController.orphanedUnregistrationCountForFixtures, 1)

        let secondController = ShortcutController.fixture(
            registrar: { _, _, _, _ in
                registrarCallCount += 1
                return (status: noErr, hasReference: true)
            },
            unregistrar: { hotKeyID in
                unregisteredRouteTokens.append(hotKeyID.id)
                return cleanupShouldFail ? OSStatus(-50) : noErr
            }
        )
        defer { secondController.unregisterAll() }

        let blockedResults = secondController.registerShortcuts(
            bindings: bindings,
            actions: [command: {}]
        )
        XCTAssertEqual(registrarCallCount, 1)
        XCTAssertEqual(ShortcutController.orphanedUnregistrationCountForFixtures, 1)
        XCTAssertEqual(blockedResults.first { $0.command == command }?.osStatus, OSStatus(-50))
        XCTAssertFalse(
            secondController.handlesRoutedEventForFixtures(
                signature: ShortcutController.routeSignatureForFixtures,
                routeToken: oldRouteToken
            )
        )
        secondController.simulateRoutedEventForFixtures(routeToken: oldRouteToken, pressed: true)
        await Task.yield()
        XCTAssertEqual(oldActionCount, 0)

        cleanupShouldFail = false
        let recoveredResults = secondController.registerShortcuts(
            bindings: bindings,
            actions: [command: {}]
        )
        XCTAssertEqual(registrarCallCount, 2)
        XCTAssertEqual(ShortcutController.orphanedUnregistrationCountForFixtures, 0)
        XCTAssertTrue(recoveredResults.first { $0.command == command }?.registered ?? false)
        XCTAssertEqual(unregisteredRouteTokens, [oldRouteToken, oldRouteToken, oldRouteToken])
    }

    func testShortcutOrphanFailureClearsCurrentControllerBeforeBlockingRefresh() async {
        ShortcutController.resetOrphanedUnregistrationsForFixtures()
        defer { ShortcutController.resetOrphanedUnregistrationsForFixtures() }

        let command = ShortcutCommand.clipboardHistory
        let bindings = shortcutBindings(enabledCommands: [command])
        var orphanCleanupShouldFail = true
        var registrarCallCount = 0
        var currentActionCount = 0
        var currentRouteToken: UInt32?
        let secondController = ShortcutController.fixture(
            registrar: { _, _, hotKeyID, _ in
                registrarCallCount += 1
                currentRouteToken = hotKeyID.id
                return (status: noErr, hasReference: true)
            },
            unregistrar: { _ in noErr }
        )
        defer { secondController.unregisterAll() }

        _ = secondController.registerShortcuts(
            bindings: bindings,
            actions: [command: { currentActionCount += 1 }]
        )
        guard let currentRouteToken else {
            XCTFail("The second controller must initially own an active route.")
            return
        }
        XCTAssertEqual(registrarCallCount, 1)
        XCTAssertTrue(
            secondController.handlesRoutedEventForFixtures(
                signature: ShortcutController.routeSignatureForFixtures,
                routeToken: currentRouteToken
            )
        )

        weak var releasedFirstController: ShortcutController?
        do {
            var firstController: ShortcutController? = ShortcutController.fixture(
                registrar: { _, _, _, _ in
                    registrarCallCount += 1
                    return (status: noErr, hasReference: true)
                },
                unregistrar: { _ in
                    orphanCleanupShouldFail ? OSStatus(-50) : noErr
                }
            )
            releasedFirstController = firstController
            _ = firstController?.registerShortcuts(
                bindings: bindings,
                actions: [command: {}]
            )
            firstController = nil
        }

        XCTAssertNil(releasedFirstController)
        XCTAssertEqual(registrarCallCount, 2)
        XCTAssertEqual(ShortcutController.orphanedUnregistrationCountForFixtures, 1)

        let blockedResults = secondController.registerShortcuts(
            bindings: bindings,
            actions: [command: { currentActionCount += 1 }]
        )
        XCTAssertEqual(registrarCallCount, 2, "An orphan failure must block new registration.")
        XCTAssertEqual(secondController.pendingUnregistrationCountForFixtures, 0)
        XCTAssertEqual(secondController.activeRouteCountForFixtures, 0)
        XCTAssertFalse(
            secondController.handlesRoutedEventForFixtures(
                signature: ShortcutController.routeSignatureForFixtures,
                routeToken: currentRouteToken
            )
        )
        secondController.simulateRoutedEventForFixtures(routeToken: currentRouteToken, pressed: true)
        await Task.yield()
        XCTAssertEqual(currentActionCount, 0)
        XCTAssertEqual(blockedResults.first { $0.command == command }?.failureReason, .unregistrationFailed)
        XCTAssertEqual(ShortcutController.orphanedUnregistrationCountForFixtures, 1)

        orphanCleanupShouldFail = false
        let recoveredResults = secondController.registerShortcuts(
            bindings: bindings,
            actions: [command: {}]
        )
        XCTAssertEqual(registrarCallCount, 3)
        XCTAssertEqual(ShortcutController.orphanedUnregistrationCountForFixtures, 0)
        XCTAssertTrue(recoveredResults.first { $0.command == command }?.registered ?? false)
    }

    private func shortcutBindings(
        enabledCommands: Set<ShortcutCommand>
    ) -> [ShortcutCommand: ShortcutBinding] {
        Dictionary(uniqueKeysWithValues: ShortcutCommand.allCases.map { command in
            var binding = command.defaultBinding
            binding.enabled = enabledCommands.contains(command)
            return (command, binding)
        })
    }

