    private func assertShortcutRegistrationFailureRemovesReservedRoute(
        registrarStatus: OSStatus
    ) async {
        let command = ShortcutCommand.clipboardHistory
        var capturedRouteToken: UInt32?
        var actionCount = 0
        var deliveryCount = 0
        let controller = ShortcutController.fixture { _, _, hotKeyID, _ in
            capturedRouteToken = hotKeyID.id
            return (status: registrarStatus, hasReference: false)
        }
        controller.setEventDeliveryObserver { _, _ in
            deliveryCount += 1
        }
        defer { controller.unregisterAll() }

        let bindings = Dictionary(
            uniqueKeysWithValues: ShortcutCommand.allCases.map { candidate in
                var binding = candidate.defaultBinding
                binding.enabled = candidate == command
                return (candidate, binding)
            }
        )
        let results = controller.registerShortcuts(
            bindings: bindings,
            actions: [command: { actionCount += 1 }]
        )

        guard let routeToken = capturedRouteToken else {
            XCTFail("The registration state machine must invoke the injected registrar.")
            return
        }
        let result = results.first { $0.command == command }
        if registrarStatus == noErr {
            XCTAssertEqual(result?.osStatus, noErr)
            XCTAssertEqual(result?.failureReason, .missingReference)
            XCTAssertEqual(
                result?.localizedStatus,
                L10n.string("settings.shortcutReregisterFailedTitle")
            )
            XCTAssertFalse(result?.localizedStatus.contains("OSStatus 0") ?? true)
        } else {
            XCTAssertEqual(result?.osStatus, registrarStatus)
            XCTAssertNil(result?.failureReason)
            XCTAssertEqual(
                result?.localizedStatus,
                L10n.format("settings.shortcutConflict", String(registrarStatus))
            )
        }
        XCTAssertFalse(result?.registered ?? true)
        XCTAssertNil(controller.routeTokenForFixtures(for: command))
        XCTAssertEqual(controller.activeRouteCountForFixtures, 0)
        XCTAssertFalse(
            controller.handlesRoutedEventForFixtures(
                signature: ShortcutController.routeSignatureForFixtures,
                routeToken: routeToken
            ),
            "A failed Carbon registration must remove its reserved route."
        )

        controller.simulateRoutedEventForFixtures(routeToken: routeToken, pressed: true)
        await Task.yield()

        XCTAssertEqual(actionCount, 0)
        XCTAssertEqual(deliveryCount, 0)
        XCTAssertTrue(controller.pressedHotKeyIDsForFixtures.isEmpty)
        XCTAssertEqual(
            controller.systemRegistrationCallCountsForFixtures,
            .zero
        )
    }

