    func testShortcutRouterIgnoresLateEventsForRemovedRoute() async {
        var actionCount = 0
        var deliveryCount = 0
        let controller = ShortcutController.fixture()
        let actions: [ShortcutCommand: () -> Void] = Dictionary(
            uniqueKeysWithValues: ShortcutCommand.allCases.map { command in
                let action: () -> Void = command == .clipboardHistory
                    ? { actionCount += 1 }
                    : {}
                return (command, action)
            }
        )
        controller.setEventDeliveryObserver { _, _ in
            deliveryCount += 1
        }
        defer { controller.unregisterAll() }

        _ = controller.replaceRoutesForFixtures(
            commands: ShortcutCommand.allCases,
            actions: actions
        )
        guard let oldRouteToken = controller.routeTokenForFixtures(for: .clipboardHistory) else {
            XCTFail("The fixture requires a clipboard-history route.")
            return
        }

        _ = controller.replaceRoutesForFixtures(
            commands: ShortcutCommand.allCases,
            actions: actions
        )
        guard let currentRouteToken = controller.routeTokenForFixtures(for: .clipboardHistory) else {
            XCTFail("The replacement fixture registration must keep a current route.")
            return
        }
        XCTAssertNotEqual(currentRouteToken, oldRouteToken)

        controller.simulateRoutedEventForFixtures(routeToken: currentRouteToken, pressed: true)
        for _ in 0..<20 where actionCount == 0 { await Task.yield() }
        let pressedStateBeforeLateEvents = controller.pressedHotKeyIDsForFixtures
        XCTAssertEqual(actionCount, 1)
        XCTAssertEqual(deliveryCount, 1)
        XCTAssertTrue(pressedStateBeforeLateEvents.contains(ShortcutCommand.clipboardHistory.hotKeyID))

        controller.simulateRoutedEventForFixtures(routeToken: oldRouteToken, pressed: true)
        controller.simulateRoutedEventForFixtures(routeToken: oldRouteToken, pressed: false)
        for _ in 0..<20 { await Task.yield() }

        XCTAssertEqual(actionCount, 1)
        XCTAssertEqual(deliveryCount, 1)
        XCTAssertEqual(controller.pressedHotKeyIDsForFixtures, pressedStateBeforeLateEvents)
        XCTAssertEqual(
            controller.systemRegistrationCallCountsForFixtures,
            .zero
        )
    }

    func testShortcutRouterDoesNotClaimUnknownCarbonHotKeySignatures() {
        let controller = ShortcutController.fixture()
        defer { controller.unregisterAll() }
        let routes = controller.replaceRoutesForFixtures(
