    func testPasteTransactionRejectsStaleGenerationAndTracksExplicitPhases() {
        let firstToken = UUID()
        let secondToken = UUID()
        var state = ClipboardPasteTransactionState()
        let firstGeneration = state.begin(token: firstToken)

        XCTAssertEqual(state.phase, .copying)
        XCTAssertTrue(state.transition(generation: firstGeneration, token: firstToken, to: .copied))
        XCTAssertEqual(state.phase, .copied)
        XCTAssertTrue(state.transition(generation: firstGeneration, token: firstToken, to: .targetVerifying))
        XCTAssertEqual(state.phase, .targetVerifying)

        let secondGeneration = state.begin(token: secondToken)
        XCTAssertFalse(state.isCurrent(generation: firstGeneration, token: firstToken))
        XCTAssertFalse(state.transition(generation: firstGeneration, token: firstToken, to: .completed))
        XCTAssertTrue(state.isCurrent(generation: secondGeneration, token: secondToken))
        XCTAssertEqual(state.phase, .copying)
        XCTAssertTrue(state.canWrite(expectedChangeCount: 43, currentChangeCount: 43))
        XCTAssertFalse(state.canWrite(expectedChangeCount: 43, currentChangeCount: 44))

        state.invalidate()
        XCTAssertFalse(state.isCurrent(generation: secondGeneration, token: secondToken))
        XCTAssertEqual(state.phase, .idle)
    }

    func testOneHundredPasteSessionsNeverAcceptAnOlderCompletion() {
        var state = ClipboardPasteTransactionState()
        var previous: (generation: Int, token: UUID)?

        for _ in 0..<100 {
            let token = UUID()
            let generation = state.begin(token: token)
            if let previous {
                XCTAssertFalse(
                    state.transition(
                        generation: previous.generation,
                        token: previous.token,
                        to: .completed
                    )
                )
            }
            XCTAssertTrue(state.transition(generation: generation, token: token, to: .copied))
            XCTAssertTrue(state.transition(generation: generation, token: token, to: .targetVerifying))
            XCTAssertTrue(state.transition(generation: generation, token: token, to: .dispatching))
            XCTAssertTrue(state.transition(generation: generation, token: token, to: .completed))
            previous = (generation, token)
        }
    }

