    func testPinnedScreenshotUsesIntrinsicScaleUntilItNeedsToFit() {
        let visible = CGRect(x: 0, y: 0, width: 1440, height: 900)
        let small = PinnedScreenshotDisplayState(
            sourceSize: CGSize(width: 640, height: 480),
            visibleFrame: visible
        )
        let large = PinnedScreenshotDisplayState(
            sourceSize: CGSize(width: 3840, height: 2160),
            visibleFrame: visible
        )

        XCTAssertEqual(small.zoom, 1)
        XCTAssertEqual(small.percentage, 100)
        XCTAssertLessThan(large.zoom, 1)
        XCTAssertLessThanOrEqual(large.displaySize.width, visible.width - 48 + 0.5)
        XCTAssertLessThanOrEqual(large.displaySize.height, visible.height - 72 + 0.5)

        let long = PinnedScreenshotDisplayState(
            sourceSize: CGSize(width: 800, height: 16_384),
            visibleFrame: visible
        )
        XCTAssertLessThan(long.zoom, 0.25)
        XCTAssertLessThanOrEqual(long.displaySize.height, visible.height - 72 + 0.5)
    }

    func testSelectionPointerInvalidationStaysOnAffectedDisplaysUntilStateChanges() {
        let left = ScreenshotSelectionDisplay(
            id: 1,
            frame: CGRect(x: -1_000, y: 0, width: 1_000, height: 800),
            title: "Left",
            backingScale: 2
        )
        let right = ScreenshotSelectionDisplay(
            id: 2,
            frame: CGRect(x: 0, y: 0, width: 1_000, height: 800),
            title: "Right",
            backingScale: 2
        )

        XCTAssertEqual(
            ScreenshotSelectionInvalidationPolicy.displayIDsForPointerMove(
                previousPointer: CGPoint(x: 100, y: 100),
                currentPointer: CGPoint(x: 200, y: 200),
                stateChanged: false,
                displays: [left, right]
            ),
            [2]
        )
        XCTAssertEqual(
            ScreenshotSelectionInvalidationPolicy.displayIDsForPointerMove(
                previousPointer: CGPoint(x: -20, y: 100),
                currentPointer: CGPoint(x: 20, y: 100),
                stateChanged: false,
                displays: [left, right]
            ),
            [1, 2]
        )
        XCTAssertNil(
            ScreenshotSelectionInvalidationPolicy.displayIDsForPointerMove(
                previousPointer: CGPoint(x: 100, y: 100),
                currentPointer: CGPoint(x: 200, y: 200),
                stateChanged: true,
                displays: [left, right]
            )
        )
    }

