    func testClipboardPanelUsesNonactivatingStyleAndClosesImmediatelyAfterCopy() {
        let presenter = ClipboardHistoryPanelPresenter()
        defer {
            presenter.forceCloseForRuntimeDisable()
            drainAppKitAnimationTransactions()
        }
        let store = ClipboardStore(repository: nil)
        let invocation = ClipboardPanelInvocationContext(
            id: UUID(),
            source: .floatingPanel,
            openedAt: Date(),
            targetContext: nil
        )
        let actions = ClipboardPanelActions(
            pasteQuickRecord: { _ in },
            pasteRecord: { _ in },
            translateRecord: { _ in },
            copyRecordAsPlainText: { _ in },
            deleteHistoryItem: { _ in true },
            toggleFavorite: { _ in },
            setTagFilter: { _ in }
        )
        var closedPasteSessionID: UUID?
        _ = presenter.present(
            clipboardStore: store,
            notificationState: BlocksNotificationPresentationState(),
            actions: actions,
            position: .bottom,
            invocationContext: invocation,
            openMainWindow: {},
            openSettings: {},
            onClosed: { closedPasteSessionID = $0 }
        )
        XCTAssertTrue(presenter.isVisible)
        XCTAssertTrue(presenter.usesNonactivatingPanel)
        XCTAssertEqual(presenter.invocationID, invocation.id)

        let pasteSessionID = UUID()
        XCTAssertFalse(
            presenter.releasePanelForPaste(
                sessionID: pasteSessionID,
                expectedInvocationID: UUID()
            ),
            "A stale invocation must not close the current panel."
        )
        XCTAssertTrue(presenter.isVisible)
        XCTAssertTrue(
            presenter.releasePanelForPaste(
                sessionID: pasteSessionID,
                expectedInvocationID: invocation.id
            )
        )
        XCTAssertFalse(presenter.isVisible)
        XCTAssertNil(presenter.invocationID)
        XCTAssertEqual(closedPasteSessionID, pasteSessionID)
    }

