    func testPanelCloseClearsInvocationBoundAccessibilityRetry() {
        let presenter = ClipboardHistoryPanelPresenter()
        defer {
            presenter.forceCloseForRuntimeDisable()
            drainAppKitAnimationTransactions()
        }
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: ClipboardStore(repository: nil),
            privacyStore: PrivacyStore(repository: nil),
            featureAvailabilityStore: FeatureAvailabilityStore(defaults: testDefaults()),
            clipboardHistoryPanelPresenter: presenter
        )
        coordinator.showFloatingPanel(openMainWindow: {}, openSettings: {})
        guard let invocationID = presenter.invocationID else {
            return XCTFail("The visible panel must retain its invocation ID.")
        }
        let retry = coordinator.makePendingPasteRequest(
            recordID: "accessibility-retry",
            targetContext: nil,
            panelInvocationID: invocationID,
            promptForAccessibility: false
        )
        coordinator.pendingPasteRequest = retry

        presenter.close()

        XCTAssertNil(coordinator.pendingPasteRequest)
        XCTAssertNil(coordinator.pasteTransactionState.activeToken)
        XCTAssertEqual(coordinator.pasteTransactionState.phase, .idle)
    }

    func testVisiblePinnedClipboardPanelReentryPreservesPinAndInvocation() {
        let (presenter, completions) = makeClipboardPanelPresenterForReentryTesting()
        defer {
            presenter.forceCloseForRuntimeDisable()
            drainAppKitAnimationTransactions()
        }
        let store = ClipboardStore(repository: nil)
        let firstInvocation = makeClipboardPanelInvocation()

        guard case .shown = presenter.present(
            clipboardStore: store,
            notificationState: BlocksNotificationPresentationState(),
            actions: makeClipboardPanelActions(),
            position: .bottom,
            invocationContext: firstInvocation,
            openMainWindow: {},
            openSettings: {},
            onClosed: { _ in }
        ) else {
            return XCTFail("The initial panel presentation must be shown.")
        }
        XCTAssertEqual(completions.completions.count, 1)
        guard completions.completions.count == 1 else {
            return XCTFail("Initial presentation must enqueue exactly one completion.")
        }
        completions.completions[0]()
        presenter.pinStateForTesting.setPinned(true)

        guard case .shown = presenter.present(
            clipboardStore: store,
            notificationState: BlocksNotificationPresentationState(),
            actions: makeClipboardPanelActions(),
            position: .right,
            invocationContext: makeClipboardPanelInvocation(),
            openMainWindow: {},
            openSettings: {},
            onClosed: { _ in }
        ) else {
            return XCTFail("A visible pinned panel must be refocused.")
        }

        XCTAssertTrue(presenter.pinStateForTesting.isPinned)
        XCTAssertEqual(presenter.invocationID, firstInvocation.id)
        presenter.close()
        XCTAssertTrue(presenter.isVisible, "Pinned reentry must retain the no-dismiss contract.")
        XCTAssertEqual(completions.completions.count, 1)
        presenter.pinStateForTesting.setPinned(false)
        presenter.close()
        XCTAssertEqual(completions.completions.count, 2)
        guard completions.completions.count == 2 else {
            return XCTFail("Closing the unpinned panel must enqueue exactly two completions total.")
        }
        completions.completions[1]()
        XCTAssertFalse(presenter.isVisible)
    }

    func testClipboardRuntimeDisableForceClosesPinnedPanelAndCleansSession() {
        let (presenter, completions) = makeClipboardPanelPresenterForReentryTesting()
        defer {
            presenter.forceCloseForRuntimeDisable()
            drainAppKitAnimationTransactions()
        }
        let defaults = testDefaults()
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: ClipboardStore(repository: nil),
            privacyStore: PrivacyStore(repository: nil),
            featureAvailabilityStore: FeatureAvailabilityStore(defaults: defaults),
            clipboardHistoryPanelPresenter: presenter
        )
        var closeCount = 0

        guard case .shown = presenter.present(
            clipboardStore: coordinator.clipboardStore,
            notificationState: BlocksNotificationPresentationState(),
            actions: makeClipboardPanelActions(),
            position: .bottom,
            invocationContext: makeClipboardPanelInvocation(),
            openMainWindow: {},
            openSettings: {},
            onClosed: { _ in closeCount += 1 }
        ) else {
            return XCTFail("The clipboard panel must be visible before runtime disable.")
        }
        guard completions.completions.count == 1 else {
            return XCTFail("Initial presentation must enqueue exactly one completion.")
        }
        completions.completions[0]()
        presenter.pinStateForTesting.setPinned(true)

        coordinator.disableRuntime()

        XCTAssertEqual(
            completions.completions.count,
            1,
            "Runtime disable uses the immediate lifecycle and must not enqueue another animated completion."
        )
        XCTAssertFalse(presenter.isVisible)
        XCTAssertFalse(presenter.pinStateForTesting.isPinned)
        XCTAssertNil(presenter.invocationID)
        XCTAssertEqual(presenter.focusCoordinatorForTesting.target, .inactive)
        XCTAssertEqual(closeCount, 1)

        coordinator.disableRuntime()
        XCTAssertEqual(closeCount, 1, "Repeated runtime disable must remain idempotent.")
    }

    func testClipboardPanelReentryBeforeInsertionCompletionRestoresDismissMonitoring() async {
        var completions: [@MainActor () -> Void] = []
        let dismissalRequested = expectation(description: "dismiss monitor requests close")
        let presentationCoordinator = BlocksFloatingPanelPresentationCoordinator {
            _, _, _, _, phase, completion in
            if phase == .removal {
                dismissalRequested.fulfill()
            }
            completions.append(completion)
        }
        let presenter = ClipboardHistoryPanelPresenter(
            presentationCoordinator: presentationCoordinator
        )
        defer {
            presenter.forceCloseForRuntimeDisable()
            drainAppKitAnimationTransactions()
        }
        let store = ClipboardStore(repository: nil)

        guard case .shown = presenter.present(
            clipboardStore: store,
            notificationState: BlocksNotificationPresentationState(),
            actions: makeClipboardPanelActions(),
            position: .bottom,
            invocationContext: makeClipboardPanelInvocation(),
            openMainWindow: {},
            openSettings: {},
            onClosed: { _ in }
        ) else {
            return XCTFail("The initial clipboard panel presentation must be shown.")
        }
        XCTAssertEqual(completions.count, 1)
        guard completions.count == 1 else {
            return XCTFail("Initial presentation must enqueue exactly one completion.")
        }

        guard case .shown = presenter.present(
            clipboardStore: store,
            notificationState: BlocksNotificationPresentationState(),
            actions: makeClipboardPanelActions(),
            position: .bottom,
            invocationContext: makeClipboardPanelInvocation(),
            openMainWindow: {},
            openSettings: {},
            onClosed: { _ in }
        ) else {
            return XCTFail("Clipboard panel reentry must remain shown while insertion is pending.")
        }
        XCTAssertEqual(
            completions.count,
            1,
            "Reentry must cancel the stale insertion completion rather than run it."
        )

        NotificationCenter.default.post(
            name: NSApplication.didResignActiveNotification,
            object: NSApp
        )
        await fulfillment(of: [dismissalRequested], timeout: 1)
        XCTAssertEqual(presentationCoordinator.phase, .dismissing)

        guard completions.count == 2 else {
            return XCTFail("Dismissal must enqueue exactly two completions total.")
        }
        completions[1]()
        XCTAssertFalse(presenter.isVisible)

        var pinnedCompletions: [@MainActor () -> Void] = []
        let pinnedPresenter = ClipboardHistoryPanelPresenter(
            presentationCoordinator: BlocksFloatingPanelPresentationCoordinator {
                _, _, _, _, _, completion in
                pinnedCompletions.append(completion)
            }
        )
        defer {
            pinnedPresenter.forceCloseForRuntimeDisable()
            drainAppKitAnimationTransactions()
        }
        guard case .shown = pinnedPresenter.present(
            clipboardStore: store,
            notificationState: BlocksNotificationPresentationState(),
            actions: makeClipboardPanelActions(),
            position: .bottom,
            invocationContext: makeClipboardPanelInvocation(),
            openMainWindow: {},
            openSettings: {},
            onClosed: { _ in }
        ) else {
            return XCTFail("The initial pinned clipboard panel presentation must be shown.")
        }
        pinnedPresenter.pinStateForTesting.setPinned(true)
        guard case .shown = pinnedPresenter.present(
            clipboardStore: store,
            notificationState: BlocksNotificationPresentationState(),
            actions: makeClipboardPanelActions(),
            position: .bottom,
            invocationContext: makeClipboardPanelInvocation(),
            openMainWindow: {},
            openSettings: {},
            onClosed: { _ in }
        ) else {
            return XCTFail("Pinned clipboard panel reentry must remain shown.")
        }

        NotificationCenter.default.post(
            name: NSApplication.didResignActiveNotification,
            object: NSApp
        )
        await Task.yield()
        XCTAssertEqual(pinnedCompletions.count, 1)
        XCTAssertTrue(pinnedPresenter.isVisible)

        pinnedPresenter.pinStateForTesting.setPinned(false)
        pinnedPresenter.close()
        XCTAssertEqual(pinnedCompletions.count, 2)
        guard pinnedCompletions.count == 2 else {
            return XCTFail("Closing the unpinned panel must enqueue exactly two completions total.")
        }
        pinnedCompletions[1]()
        XCTAssertFalse(pinnedPresenter.isVisible)
    }

