    func testClipboardPanelStaleDismissalCompletionCannotCloseReplacementInvocation() {
        var completions: [@MainActor () -> Void] = []
        let presentationCoordinator = BlocksFloatingPanelPresentationCoordinator {
            _, _, _, _, _, completion in
            completions.append(completion)
        }
        let presenter = ClipboardHistoryPanelPresenter(
            presentationCoordinator: presentationCoordinator
        )
        defer {
            presenter.forceCloseForRuntimeDisable()
            drainAppKitAnimationTransactions()
        }
        let actions = ClipboardPanelActions(
            pasteQuickRecord: { _ in },
            pasteRecord: { _ in },
            translateRecord: { _ in },
            copyRecordAsPlainText: { _ in },
            deleteHistoryItem: { _ in true },
            toggleFavorite: { _ in },
            setTagFilter: { _ in }
        )
        let invocationA = ClipboardPanelInvocationContext(
            id: UUID(), source: .floatingPanel, openedAt: Date(), targetContext: nil
        )
        let invocationB = ClipboardPanelInvocationContext(
            id: UUID(), source: .floatingPanel, openedAt: Date(), targetContext: nil
        )
        var closedA = 0
        var closedB = 0

        _ = presenter.present(
            clipboardStore: ClipboardStore(repository: nil),
            notificationState: BlocksNotificationPresentationState(),
            actions: actions,
            position: .bottom,
            invocationContext: invocationA,
            openMainWindow: {},
            openSettings: {},
            onClosed: { _ in closedA += 1 }
        )
        XCTAssertEqual(completions.count, 1)
        guard completions.count == 1 else {
            return XCTFail("Initial presentation must enqueue exactly one completion.")
        }
        completions[0]()
        presenter.close()
        XCTAssertEqual(completions.count, 2)

        guard case .shown = presenter.present(
            clipboardStore: ClipboardStore(repository: nil),
            notificationState: BlocksNotificationPresentationState(),
            actions: actions,
            position: .bottom,
            invocationContext: invocationB,
            openMainWindow: {},
            openSettings: {},
            onClosed: { _ in closedB += 1 }
        ) else {
            return XCTFail("The replacement clipboard invocation must be shown.")
        }
        XCTAssertEqual(completions.count, 3)
        guard completions.count == 3 else {
            return XCTFail("Replacement presentation must enqueue exactly three completions total.")
        }
        completions[1]()
        completions[2]()

        XCTAssertTrue(presenter.isVisible)
        XCTAssertEqual(presenter.invocationID, invocationB.id)
        XCTAssertEqual(closedA, 0)
        XCTAssertEqual(closedB, 0)
        presenter.close()
        XCTAssertEqual(completions.count, 4)
        guard completions.count == 4 else {
            return XCTFail("Final close must enqueue exactly four completions total.")
        }
        completions[3]()
        XCTAssertFalse(presenter.isVisible)
        XCTAssertNil(presenter.invocationID)
        XCTAssertEqual(closedA, 0)
        XCTAssertEqual(closedB, 1)
    }

    func testClipboardPanelRecentCloseSuppressionLeavesNoStateAndAllowsNextOpen() {
        var shouldSuppress = false
        var animationCompletions: [@MainActor () -> Void] = []
        let presenter = ClipboardHistoryPanelPresenter(
            presentationCoordinator: BlocksFloatingPanelPresentationCoordinator {
                _, _, _, _, _, completion in
                animationCompletions.append(completion)
            },
            shouldSuppressRecentOpen: { shouldSuppress }
        )
        defer {
            presenter.forceCloseForRuntimeDisable()
            drainAppKitAnimationTransactions()
        }
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: ClipboardStore(repository: nil),
            privacyStore: PrivacyStore(repository: nil),
            featureAvailabilityStore: FeatureAvailabilityStore(defaults: testDefaults()),
            clipboardHistoryPanelPresenter: presenter
        )
        coordinator.showFloatingPanel(openMainWindow: {}, openSettings: {})
        XCTAssertEqual(animationCompletions.count, 1)
        guard animationCompletions.count == 1 else {
            return XCTFail("Initial presentation must enqueue exactly one completion.")
        }
        animationCompletions[0]()
        XCTAssertTrue(presenter.isVisible)
        XCTAssertEqual(
            coordinator.notificationCoordinator.presentationState.current?
                .descriptor.deduplicationKey,
            "clipboard.repository.unavailable",
            "A normal open must still report an unavailable repository."
        )
        presenter.close()
        XCTAssertEqual(animationCompletions.count, 2)
        guard animationCompletions.count == 2 else {
            return XCTFail("Initial close must enqueue exactly two completions total.")
        }
        animationCompletions[1]()
        XCTAssertFalse(presenter.isVisible)
        coordinator.notificationCoordinator.presentationState.dismiss()

        shouldSuppress = true
        coordinator.showFloatingPanel(openMainWindow: {}, openSettings: {})

        XCTAssertEqual(
            animationCompletions.count,
            2,
            "A suppressed open must not start another panel presentation."
        )
        XCTAssertFalse(presenter.isVisible)
        XCTAssertNil(presenter.invocationID)
        XCTAssertFalse(presenter.isApplicationObservationActive)
        coordinator.notificationCoordinator.favoriteChanged(
            recordID: "suppressed-open",
            isFavorite: true
        )
        XCTAssertNil(
            coordinator.notificationCoordinator.presentationState.current,
            "A suppressed open must leave the notification host hidden."
        )

        shouldSuppress = false
        coordinator.showFloatingPanel(openMainWindow: {}, openSettings: {})

        XCTAssertEqual(animationCompletions.count, 3)
        guard animationCompletions.count == 3 else {
            return XCTFail("Replacement presentation must enqueue exactly three completions total.")
        }
        animationCompletions[2]()
        XCTAssertTrue(presenter.isVisible)
        XCTAssertNotNil(presenter.invocationID)
        XCTAssertTrue(presenter.isApplicationObservationActive)
        coordinator.notificationCoordinator.favoriteChanged(
            recordID: "normal-open",
            isFavorite: true
        )
        XCTAssertNotNil(coordinator.notificationCoordinator.presentationState.current)

        presenter.close()
        XCTAssertEqual(animationCompletions.count, 4)
        guard animationCompletions.count == 4 else {
            return XCTFail("Final close must enqueue exactly four completions total.")
        }
        animationCompletions[3]()
        XCTAssertFalse(presenter.isVisible)
    }

    func testClipboardPasteTargetEligibilityRequiresAnOnscreenLayerZeroWindow() {
        let processIdentifier: pid_t = 4123
        let tinyBounds: [String: NSNumber] = ["X": 0, "Y": 0, "Width": 20, "Height": 20]
        let validBounds: [String: NSNumber] = ["X": 50, "Y": 60, "Width": 640, "Height": 480]
        let windows: [[String: Any]] = [
            [
                kCGWindowOwnerPID as String: processIdentifier,
                kCGWindowLayer as String: 3,
                kCGWindowAlpha as String: 1,
                kCGWindowBounds as String: validBounds
            ],
            [
                kCGWindowOwnerPID as String: processIdentifier,
                kCGWindowLayer as String: 0,
                kCGWindowAlpha as String: 1,
                kCGWindowBounds as String: tinyBounds
            ],
            [
                kCGWindowOwnerPID as String: processIdentifier,
                kCGWindowLayer as String: 0,
                kCGWindowAlpha as String: 1,
                kCGWindowBounds as String: validBounds
            ]
        ]

        XCTAssertTrue(
            ClipboardPasteTargetEligibility.hasVisibleApplicationWindow(
                processIdentifier: processIdentifier,
                windowInfo: windows
            )
        )
        XCTAssertFalse(
            ClipboardPasteTargetEligibility.hasVisibleApplicationWindow(
                processIdentifier: 9999,
                windowInfo: windows
            )
        )
    }

