    func testPendingPasteRequestDefersBaselineToBrokerAndRetryUsesItsOwnWrite() {
        var pasteboardChangeCount = 51
        let defaults = testDefaults()
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: ClipboardStore(repository: nil),
            privacyStore: PrivacyStore(repository: nil),
            featureAvailabilityStore: FeatureAvailabilityStore(defaults: defaults),
            pasteboardChangeCount: { pasteboardChangeCount }
        )

        let request = coordinator.makePendingPasteRequest(
            recordID: "clipboard-record",
            targetContext: nil,
            promptForAccessibility: true
        )
        pasteboardChangeCount = 52
        let retryLease = ClipboardPasteboardWriteLease(changeCount: pasteboardChangeCount)
        let retry = request
            .waitingForAccessibilityRetry(
                lease: retryLease,
                historySyncPending: true
            )
            .retryingAfterAccessibilityGrant()

        XCTAssertNil(
            request.expectedPasteboardChangeCount,
            "A sampled observer value must not become the write CAS baseline."
        )
        XCTAssertNil(request.preparedWriteLease)
        XCTAssertEqual(retry.expectedPasteboardChangeCount, 52)
        XCTAssertEqual(retry.preparedWriteLease, retryLease)
        XCTAssertTrue(retry.historySyncPending)
        XCTAssertFalse(retry.promptForAccessibility)
        XCTAssertEqual(retry.token, request.token)
    }

    func testAccessibilityRetryRetriesFailedRecencyWithoutRewritingPasteboard()
        async throws
    {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "ClipboardAccessibilityRecencyRetry.\(UUID().uuidString)",
                isDirectory: true
            )
        let database = try AppDatabase.open(
            environment: StorageEnvironment(rootDirectory: root)
        )
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        let originalCopiedAt = Date(timeIntervalSince1970: 1_000)
        let recordID = "accessibility-recency-retry"
        let signature = String(repeating: "e", count: 64)
        let record = ClipboardRecorderRecord(
            id: recordID,
            createdAt: originalCopiedAt,
            changeCount: 60,
            kind: .text,
            formatSummary: .init(
                itemCount: 1,
                types: ["public.utf8-plain-text"],
                textLength: 7,
                byteCount: 7
            ),
            sourceApp: nil,
            signatureSHA256: signature,
            signatureSHA256_12: String(signature.prefix(12)),
            fixtureOwned: true,
            restorable: true,
            lastCopiedAt: originalCopiedAt,
            summary: "fixture"
        )
        _ = try repository.insert(
            record: record,
            payload: .init(recordID: recordID, kind: .text, text: "fixture")
        )
        let mutationCount = ClipboardCleanupInvocationCounter()
        let store = ClipboardStore(
            repository: repository,
            recordMutationPipelineHooks: ClipboardRecordMutationPipelineHooks(
                shouldFailMutation: { kind in
                    kind == .markCopied && mutationCount.increment() == 1
                }
            )
        )
        XCTAssertTrue(store.loadRepositoryState(limit: 10))
        try await waitForClipboardRecords(store, expectedCount: 1)

        let pasteboard = ScriptedClipboardPasteboard(
            items: [],
            changeCount: 60,
            writeOutcomes: [true]
        )
        let application = NSRunningApplication.current
        let focus = makeEditablePasteFocusContext(application: application)
        var accessibilityGranted = false
        var pasteShortcutCount = 0
        var retryAction: (() -> Void)?
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: store,
            privacyStore: PrivacyStore(repository: nil),
            featureAvailabilityStore: FeatureAvailabilityStore(
                defaults: testDefaults()
            ),
            autoPasteCoordinator: ClipboardAutoPasteCoordinator(
                pasteboard: pasteboard,
                changeSuppressor: ClipboardPasteboardChangeSuppressor(),
                frontmostApplication: { application },
                focusSnapshot: { _ in focus },
                eventPostingAccess: { _ in accessibilityGranted },
                pasteShortcutFactory: makePasteShortcutForTesting,
                pasteShortcutPoster: { _ in pasteShortcutCount += 1 }
            )
        )
        coordinator.configure(
            statusRecorder: { _ in },
            sectionSelector: { _ in },
            closeTranslationPanel: {},
            translateRecord: { _ in },
            refreshPermissionState: {},
            dispatchPluginEvent: { .allowed($0) },
            stagePluginTextResource: { _, _, _, _ in nil },
            removePluginResources: { _ in },
            accessibilityGranted: { accessibilityGranted },
            presentAccessibilityAssist: { retryAction = $0 }
        )

        coordinator.startPaste(coordinator.makePendingPasteRequest(
            recordID: recordID,
            targetContext: focus,
            promptForAccessibility: true
        ))
        let initialPasteTask = try XCTUnwrap(coordinator.pasteTask)
        await initialPasteTask.value
        XCTAssertEqual(pasteboard.writeCallCount, 1)
        XCTAssertEqual(mutationCount.currentValue, 1)
        XCTAssertEqual(
            try repository.loadRecord(recordID: recordID)?.lastCopiedAt,
            originalCopiedAt
        )
        XCTAssertNotNil(retryAction)

        accessibilityGranted = true
        coordinator.retryPendingPasteIfPossible() // Explicit retry, not a permission refresh.
        for _ in 0..<200 where pasteShortcutCount == 0 {
            try await Task.sleep(for: .milliseconds(5))
        }

        XCTAssertEqual(pasteboard.writeCallCount, 1)
        XCTAssertEqual(mutationCount.currentValue, 2)
        XCTAssertNotEqual(
            try repository.loadRecord(recordID: recordID)?.lastCopiedAt,
            originalCopiedAt
        )
        XCTAssertEqual(pasteShortcutCount, 1)
    }

    func testVisiblePanelAccessibilityRetryReusesCommittedWriteAfterPanelCloses()
        async throws
    {
