            let signature = String(repeating: String(index + 1), count: 64)
            _ = try repository.insert(
                record: ClipboardRecorderRecord(
                    id: id,
                    createdAt: Date(timeIntervalSince1970: TimeInterval(1_000 + index)),
                    changeCount: index + 1,
                    kind: .text,
                    formatSummary: ClipboardRecorderFormatSummary(
                        itemCount: 1,
                        types: ["public.utf8-plain-text"],
                        byteCount: text.utf8.count
                    ),
                    sourceApp: nil,
                    signatureSHA256: signature,
                    signatureSHA256_12: String(signature.prefix(12)),
                    fixtureOwned: true,
                    restorable: true,
                    summary: text
                ),
                payload: ClipboardRecorderPayload(recordID: id, kind: .text, text: text)
            )
        }
        let store = ClipboardStore(repository: repository)
        XCTAssertTrue(store.loadRepositoryState(limit: 1))
        XCTAssertTrue(
            store.records.isEmpty,
            "Repository reload must return to MainActor before SQLite and preview reads finish."
        )
        try await waitForClipboardRecords(store, expectedCount: 1)
        XCTAssertFalse(store.records.contains(where: { $0.id == "search-record-0" }))

        store.refreshSearchResult(query: "search-only-needle", limit: 10)
        try await waitForClipboardSearch(store, query: "search-only-needle")
        XCTAssertEqual(store.currentSearchResult.records.map(\.id), ["search-record-0"])
        XCTAssertEqual(store.resolveRecord(recordID: "search-record-0")?.id, "search-record-0")
        let actionPayload = await store.readPayloadForAction(
            recordID: "search-record-0",
            purpose: .paste
        )
        XCTAssertEqual(actionPayload.payload?.text, "search-only-needle")
        let favoriteState = await store.toggleFavorite(recordID: "search-record-0")
        XCTAssertEqual(favoriteState, true)
        XCTAssertTrue(store.tagStore.isFavorite(recordID: "search-record-0"))

        let update = await store.commitCopyEvent(
            recordID: "search-record-0",
            source: .panelPaste,
            at: Date(timeIntervalSince1970: 2_000)
        )
        XCTAssertTrue(update.recordFound)
        XCTAssertTrue(update.persisted)
        XCTAssertEqual(store.records.first?.id, "search-record-0")
        XCTAssertEqual(try repository.loadRecent(limit: 1).first?.id, "search-record-0")
        let deleted = await store.delete(recordID: "search-record-0")
        XCTAssertTrue(deleted)
        XCTAssertNil(try repository.loadRecord(recordID: "search-record-0"))
        let duplicateDelete = await store.delete(recordID: "search-record-0")
        XCTAssertFalse(duplicateDelete)
    }

    func testClipboardStorePublishesCommittedRecordEventsOnceWithCallerCausation() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ClipboardUnifiedRecordEvents.\(UUID().uuidString)", isDirectory: true)
        let database = try AppDatabase.open(environment: StorageEnvironment(rootDirectory: root))
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        for (index, id) in ["event-favorite", "event-update", "event-delete"].enumerated() {
            try insertClipboardCleanupFixture(
                repository,
                id: id,
                timestamp: TimeInterval(2_100 + index)
            )
        }
        let store = ClipboardStore(repository: repository)
        var events: [BlocksPluginEventEnvelope] = []
        store.configurePluginEventDispatcher { envelope in
            events.append(envelope)
            return .allowed(envelope)
        }
        XCTAssertTrue(store.loadRepositoryState(limit: 10))
        try await waitForClipboardRecords(store, expectedCount: 3)

        let favoriteCausation = UUID()
        let favoriteResult = await store.toggleFavorite(
            recordID: "event-favorite",
            causationID: favoriteCausation
        )
        XCTAssertEqual(favoriteResult, true)
        let updateCausation = UUID()
        let update = try await store.updateRecordFromPlugin(
            recordID: "event-update",
            customTitle: "Updated title",
            text: nil,
            expectedContentRevision: 1,
            causationID: updateCausation
        )
        let recencyCausation = UUID()
        let recency = await store.commitCopyEvent(
            recordID: "event-update",
            source: .panelPaste,
            at: Date(timeIntervalSince1970: 3_000),
            causationID: recencyCausation
        )
        XCTAssertTrue(recency.persisted)
        let deleteCausation = UUID()
        let deleteResult = await store.delete(
            recordID: "event-delete",
            causationID: deleteCausation
        )
        XCTAssertTrue(deleteResult)

        XCTAssertEqual(events.count, 4)
        XCTAssertEqual(events[0].name, .clipboardRecordUpdated)
        XCTAssertEqual(events[0].causationID, favoriteCausation)
        XCTAssertEqual(events[0].payload["operation"], .string("favorite_changed"))
        XCTAssertEqual(events[0].payload["is_favorite"], .bool(true))
        XCTAssertEqual(events[1].name, .clipboardRecordUpdated)
        XCTAssertEqual(events[1].causationID, updateCausation)
        XCTAssertEqual(events[1].revision, update.newContentRevision)
        XCTAssertEqual(events[1].payload["operation"], .string("content_updated"))
        XCTAssertEqual(
            events[1].payload["content_revision"],
            .int(Int(update.newContentRevision))
        )
        XCTAssertEqual(events[2].name, .clipboardRecordUpdated)
        XCTAssertEqual(events[2].causationID, recencyCausation)
        XCTAssertEqual(events[2].payload["operation"], .string("recency_promoted"))
        XCTAssertEqual(events[3].name, .clipboardRecordDeleted)
        XCTAssertEqual(events[3].causationID, deleteCausation)
        XCTAssertEqual(events[3].payload["record_id"], .string("event-delete"))
    }

