        let snapshot = ClipboardLiveCaptureSnapshot(
            record: ClipboardRecorderRecord(
                id: "ephemeral-event",
                createdAt: Date(timeIntervalSince1970: 2_300),
                changeCount: 2_300,
                kind: .text,
                formatSummary: .init(
