        _ = try tags.toggleFavorite(recordID: "search-boundary-1")
        XCTAssertEqual(try repository.search("cleanup", limit: 6_000).count, 5_002)

        // Characterize the retired limit-before-filter path with the same
        // repository: its first 5,000 candidates contain neither favorite.
        let cappedCandidates = try repository.search("cleanup", limit: 5_000)
        let cappedTags = try tags.loadRecordTags(recordIDs: cappedCandidates.map(\.id))
        XCTAssertTrue(ClipboardSearchCoordinator.applyFilters(
