        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        let recordID = "image-preview-background-read"
        let pngData = try XCTUnwrap(
            NSBitmapImageRep(
                cgImage: solidImage(width: 2_048, height: 2_048, color: .systemRed)
            )
            .representation(using: .png, properties: [:])
        )
        let signature = String(repeating: "d", count: 64)
        _ = try repository.insert(
            record: ClipboardRecorderRecord(
                id: recordID,
                createdAt: Date(timeIntervalSince1970: 3_000),
                changeCount: 1,
                kind: .image,
                formatSummary: ClipboardRecorderFormatSummary(
                    itemCount: 1,
                    types: ["public.png"],
                    byteCount: pngData.count
                ),
                sourceApp: nil,
                signatureSHA256: signature,
                signatureSHA256_12: String(signature.prefix(12)),
                fixtureOwned: true,
                restorable: true,
                summary: "synthetic image"
            ),
            payload: ClipboardRecorderPayload(
                recordID: recordID,
                kind: .image,
                pngData: pngData
            )
        )

        let store = ClipboardStore(repository: repository)
        XCTAssertTrue(store.loadRepositoryState(limit: 10))
        try await waitForClipboardRecords(store, containing: recordID)
        let record = try XCTUnwrap(store.records.first(where: { $0.id == recordID }))

        // SwiftUI body evaluation may request every visible row preview. The
        // first request must return immediately instead of synchronously
        // rebuilding and Base64-decoding the full persisted image payload.
        XCTAssertNil(store.preview(for: record).image)

        for _ in 0..<200 {
            if let preview = store.preview(for: record).image {
                XCTAssertLessThanOrEqual(preview.size.width, 720)
                XCTAssertLessThanOrEqual(preview.size.height, 720)
                return
            }
            try await Task.sleep(for: .milliseconds(10))
        }
        XCTFail("The background thumbnail read did not publish a preview.")
    }

