    func testPanelCloseDuringPreparedPasteCancelsWithoutWriteOrLateEffects()
        async throws
    {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ClipboardPanelClosePrepared.\(UUID().uuidString)")
        let database = try AppDatabase.open(
            environment: StorageEnvironment(rootDirectory: root)
        )
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let recordID = "panel-close-prepared"
        let repository = ClipboardRepository(database: database)
        try insertClipboardCleanupFixture(repository, id: recordID, timestamp: 8_010)
        let store = ClipboardStore(repository: repository)
        XCTAssertTrue(store.loadRepositoryState(limit: 10))
        try await waitForClipboardRecords(store, expectedCount: 1)
        let broker = ControlledScreenshotClipboardBroker(pausesPreparedReturn: true)
        let presenter = ClipboardHistoryPanelPresenter()
        let target = makeEditablePasteFocusContext(
            application: .current,
            identity: "panel-close-prepared-target"
        )
        var postedShortcutCount = 0
        var statuses: [AppStatus] = []
        var events: [BlocksPluginEventName] = []
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: store,
            privacyStore: PrivacyStore(repository: nil),
            featureAvailabilityStore: FeatureAvailabilityStore(defaults: testDefaults()),
            autoPasteCoordinator: ClipboardAutoPasteCoordinator(
                broker: broker,
                frontmostApplication: { .current },
                focusSnapshot: { _ in target },
                eventPostingAccess: { _ in true },
                pasteShortcutFactory: makePasteShortcutForTesting,
                pasteShortcutPoster: { _ in postedShortcutCount += 1 }
            ),
            clipboardHistoryPanelPresenter: presenter
        )
        coordinator.configure(
            statusRecorder: { statuses.append($0) },
            sectionSelector: { _ in },
            closeTranslationPanel: {},
            translateRecord: { _ in },
            refreshPermissionState: {},
            dispatchPluginEvent: { envelope in
                events.append(envelope.name)
                return .allowed(envelope)
            },
            stagePluginTextResource: { _, _, _, _ in nil },
            removePluginResources: { _ in },
            accessibilityGranted: { true },
            presentAccessibilityAssist: { _ in }
        )
        defer {
            presenter.forceCloseForRuntimeDisable()
            drainAppKitAnimationTransactions()
        }
        coordinator.showFloatingPanel(openMainWindow: {}, openSettings: {})
        XCTAssertTrue(presenter.isVisible)
        XCTAssertTrue(coordinator.pasteRecord(recordID: recordID))
        try await broker.waitUntilPrepared()
        let pasteTask = try XCTUnwrap(coordinator.pasteTask)
        let closed = expectation(description: "panel close completes before prepared write resumes")
        coordinator.closeFloatingPanel(afterClose: { closed.fulfill() })
        let effectsAtClose = (statuses.count, events.count)
        await broker.releasePreparedReturn()
        await pasteTask.value
        await fulfillment(of: [closed], timeout: 1)

        let commitCount = await broker.commitCount()
        let cancelCount = await broker.cancelCount()
        XCTAssertEqual(commitCount, 0)
        XCTAssertEqual(cancelCount, 1)
        XCTAssertEqual(postedShortcutCount, 0)
        XCTAssertEqual(statuses.count, effectsAtClose.0)
        XCTAssertEqual(events.count, effectsAtClose.1)
    }

