    func testClipboardDetailSaveContinuesOnlyTheLatestNavigationRequestedWhileSaving() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ClipboardDetailLatestIntent.\(UUID().uuidString)", isDirectory: true)
        let database = try AppDatabase.open(environment: StorageEnvironment(rootDirectory: root))
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        for (id, text, signature) in [("detail-intent-a", "original", "a"), ("detail-intent-c", "target", "c")] {
            let digest = String(repeating: signature, count: 64)
            _ = try repository.insert(
                record: ClipboardRecorderRecord(
                    id: id,
                    createdAt: Date(),
                    changeCount: id == "detail-intent-a" ? 1 : 2,
                    kind: .text,
                    formatSummary: .init(itemCount: 1, types: ["public.utf8-plain-text"], byteCount: text.utf8.count),
                    sourceApp: nil,
                    signatureSHA256: digest,
                    signatureSHA256_12: String(digest.prefix(12)),
                    fixtureOwned: true,
                    restorable: true,
                    summary: text
                ),
                payload: .init(recordID: id, kind: .text, text: text)
            )
        }
        let saveHarness = SuspendedClipboardDetailSaveHarness()
        let store = ClipboardDetailStore(
            repository: repository,
            pipelineHooks: .init(beforeSave: { _ in await saveHarness.suspendFirstSave() })
        )
        var actionCount = 0
        store.requestOpen(recordID: "detail-intent-a")
        try await waitForClipboardDetail(store) {
            $0.readModel?.recordID == "detail-intent-a" && !$0.isBusy
        }
        store.beginEditing()
        try await waitForClipboardDetail(store) { $0.status == .editClean }
        store.updateDraft("saved")
        store.requestAction { actionCount += 1 }
        store.saveAndContinue()
        try await saveHarness.waitUntilSuspended()

        store.requestOpen(recordID: "detail-intent-c")
        store.updateDraft("saved plus newer draft")
        await saveHarness.resume()

        try await waitForClipboardDetail(store) {
            $0.readModel?.recordID == "detail-intent-a" && !$0.isBusy
        }
        XCTAssertTrue(store.isDirty)
        XCTAssertTrue(store.dirtyNavigation)
        XCTAssertEqual(store.pendingNavigationAction, .open(recordID: "detail-intent-c"))
        XCTAssertEqual(actionCount, 0)

        store.saveAndContinue()
        try await waitForClipboardDetail(store) {
            $0.readModel?.recordID == "detail-intent-c" && !$0.isBusy
        }
        XCTAssertEqual(actionCount, 0)
    }

