    func testClipboardDetailMetadataAndDefaultModelDoNotReadUnrelatedImagePayload() throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ClipboardDetailMetadataNoPayload.\(UUID().uuidString)", isDirectory: true)
        let database = try AppDatabase.open(environment: StorageEnvironment(rootDirectory: root))
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let blobStore = BlobStore(
            directory: database.environment.blobDirectory,
            sidecarThresholdBytes: 1
        )
        let repository = ClipboardRepository(database: database, blobStore: blobStore)
        let recordID = "detail-metadata-no-image-payload"
        let png = Data(repeating: 0x5A, count: 256)
        let signature = String(repeating: "7", count: 64)
        _ = try repository.insert(
            record: ClipboardRecorderRecord(
                id: recordID,
                createdAt: Date(timeIntervalSince1970: 4_070),
                changeCount: 3,
                kind: .image,
                formatSummary: .init(
                    itemCount: 1,
                    types: ["public.png"],
                    byteCount: png.count
                ),
                sourceApp: ClipboardRecorderSourceApp(
                    bundleIdentifier: "com.example.preview",
                    localizedName: "Preview Fixture"
                ),
                signatureSHA256: signature,
                signatureSHA256_12: String(signature.prefix(12)),
                fixtureOwned: true,
                restorable: true,
                summary: "Fixture image"
            ),
            payload: .init(recordID: recordID, kind: .image, pngData: png)
        )
        if let enumerator = FileManager.default.enumerator(
            at: database.environment.blobDirectory,
            includingPropertiesForKeys: [.isRegularFileKey]
        ) {
            for case let url as URL in enumerator {
                let values = try url.resourceValues(forKeys: [.isRegularFileKey])
                if values.isRegularFile == true {
                    try FileManager.default.removeItem(at: url)
                }
            }
        }

        XCTAssertThrowsError(try repository.readPayload(recordID: recordID))
        XCTAssertNoThrow(try repository.loadDetailReadModel(recordID: recordID))
