                recordID: recordID,
                itemID: "source",
                purpose: "detailFullValueRead"
            ),
            "Preview Fixture"
        )
    }

    func testClipboardDetailLateFullValueDoesNotLeakAfterSwitchOrDismiss() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ClipboardDetailLateFullValue.\(UUID().uuidString)", isDirectory: true)
        let database = try AppDatabase.open(environment: StorageEnvironment(rootDirectory: root))
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        for (index, recordID) in ["detail-late-a", "detail-late-b"].enumerated() {
            let fullURL = "https://example.com/\(recordID)/" + String(repeating: "segment/", count: 40)
            let signatureCharacter: Character = index == 0 ? "4" : "5"
            let signature = String(repeating: signatureCharacter, count: 64)
            _ = try repository.insert(
                record: ClipboardRecorderRecord(
                    id: recordID,
                    createdAt: Date(timeIntervalSince1970: TimeInterval(4_080 + index)),
                    changeCount: index + 1,
                    kind: .url,
                    formatSummary: .init(
                        itemCount: 1,
                        types: ["public.url"],
                        textLength: fullURL.count,
                        byteCount: fullURL.utf8.count,
                        urlCount: 1
                    ),
                    sourceApp: nil,
                    signatureSHA256: signature,
                    signatureSHA256_12: String(signature.prefix(12)),
                    fixtureOwned: true,
                    restorable: true,
                    summary: String(fullURL.prefix(320))
                ),
                payload: .init(recordID: recordID, kind: .url, text: fullURL, urlString: fullURL)
            )
        }

        let delayedRead: @Sendable (String) async -> Void = { _ in
            await withCheckedContinuation { continuation in
                DispatchQueue.global().asyncAfter(deadline: .now() + 0.15) {
                    continuation.resume()
                }
            }
        }
        let detailStore = ClipboardDetailStore(
            repository: repository,
            pipelineHooks: ClipboardDetailPipelineHooks(
                beforeMetadataRead: delayedRead,
                beforeFullValueRead: delayedRead
            )
        )

        detailStore.open(recordID: "detail-late-a")
        try await waitForClipboardDetail(detailStore) {
            $0.readModel?.recordID == "detail-late-a" && !$0.isBusy
        }
        detailStore.revealFullBodyValue()
        detailStore.requestOpen(recordID: "detail-late-b")
        try await waitForClipboardDetail(detailStore) {
            $0.readModel?.recordID == "detail-late-b" && !$0.isBusy
        }
        try await Task.sleep(for: .milliseconds(220))
        XCTAssertNil(detailStore.revealedFullBodyText)
        XCTAssertFalse(detailStore.isLoadingAuxiliary)

        let urlItem = try XCTUnwrap(
            detailStore.readModel?.metadata.items.first(where: { $0.id == "url" })
        )
        detailStore.revealFullValue(item: urlItem)
        detailStore.dismissFullValuePresentation()
        try await Task.sleep(for: .milliseconds(220))
        XCTAssertNil(detailStore.expandedFullValueText)
        XCTAssertNil(detailStore.expandedFullValueItemID)
        XCTAssertFalse(detailStore.isLoadingAuxiliary)
    }

    func testClipboardDetailSaveInvalidatesOnlyEditedRecordPayloadCache() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ClipboardDetailTargetedCache.\(UUID().uuidString)", isDirectory: true)
        let database = try AppDatabase.open(environment: StorageEnvironment(rootDirectory: root))
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        let payloads = [
            "detail-edited": ClipboardRecorderPayload(
                recordID: "detail-edited",
                kind: .text,
                text: "edited original"
            ),
            "detail-untouched": ClipboardRecorderPayload(
                recordID: "detail-untouched",
                kind: .text,
                text: "untouched original"
            ),
        ]
        for (index, entry) in payloads.sorted(by: { $0.key < $1.key }).enumerated() {
            let signature = String(repeating: index == 0 ? "d" : "e", count: 64)
            _ = try repository.insert(
                record: ClipboardRecorderRecord(
                    id: entry.key,
                    createdAt: Date(timeIntervalSince1970: TimeInterval(4_200 + index)),
                    changeCount: index + 1,
                    kind: .text,
                    formatSummary: .init(
                        itemCount: 1,
                        types: ["public.utf8-plain-text"],
                        byteCount: entry.value.text?.utf8.count ?? 0
                    ),
                    sourceApp: nil,
                    signatureSHA256: signature,
                    signatureSHA256_12: String(signature.prefix(12)),
                    fixtureOwned: true,
                    restorable: true,
                    summary: entry.value.text ?? ""
                ),
                payload: entry.value
            )
        }

        let store = ClipboardStore(repository: repository)
        store.replacePayloadCacheForFixtures(payloads)
        store.detailStore.open(recordID: "detail-edited")
        try await waitForClipboardDetail(store.detailStore) {
            $0.readModel?.recordID == "detail-edited" && !$0.isBusy
        }
        store.detailStore.beginEditing()
        try await waitForClipboardDetail(store.detailStore) {
            $0.status == .editClean
        }
        store.detailStore.updateDraft("edited replacement")
        store.detailStore.save()
        try await waitForClipboardDetail(store.detailStore) {
            ($0.status == .saveSuccess || $0.status == .savedIndexPending) && !$0.isBusy
        }

        let cache = store.payloadCacheSnapshotForFixtures()
        XCTAssertNil(cache["detail-edited"])
        XCTAssertEqual(cache["detail-untouched"]?.text, "untouched original")
    }

