    func testClipboardDirtyDetailKeepsCurrentNavigationUntilDiscardResolves() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ClipboardDirtyNavigation.\(UUID().uuidString)", isDirectory: true)
        let database = try AppDatabase.open(environment: StorageEnvironment(rootDirectory: root))
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        for index in 0..<2 {
            let recordID = "dirty-navigation-\(index)"
            let text = "detail \(index)"
            let signature = String(repeating: index == 0 ? "7" : "8", count: 64)
            _ = try repository.insert(
                record: ClipboardRecorderRecord(
                    id: recordID,
                    createdAt: Date(timeIntervalSince1970: TimeInterval(4_300 + index)),
                    changeCount: index + 1,
                    kind: .text,
                    formatSummary: .init(
                        itemCount: 1,
                        types: ["public.utf8-plain-text"],
                        byteCount: text.utf8.count
                    ),
                    sourceApp: nil,
                    signatureSHA256: signature,
                    signatureSHA256_12: String(signature.prefix(12)),
                    fixtureOwned: true,
                    restorable: true,
                    summary: text
                ),
                payload: .init(recordID: recordID, kind: .text, text: text)
            )
        }

        let store = ClipboardDetailStore(repository: repository)
        store.requestOpen(recordID: "dirty-navigation-0")
        try await waitForClipboardDetail(store) {
            $0.readModel?.recordID == "dirty-navigation-0" && !$0.isBusy
        }
        store.beginEditing()
        try await waitForClipboardDetail(store) { $0.status == .editClean }
        store.updateDraft("unsaved replacement")

        store.requestOpen(recordID: "dirty-navigation-1")

        XCTAssertTrue(store.dirtyNavigation)
        XCTAssertEqual(store.navigationResolution.recordID, "dirty-navigation-0")
        XCTAssertEqual(store.readModel?.recordID, "dirty-navigation-0")

        store.discardChangesAndContinue()
        XCTAssertEqual(store.navigationResolution.recordID, "dirty-navigation-1")
        try await waitForClipboardDetail(store) {
            $0.readModel?.recordID == "dirty-navigation-1" && !$0.isBusy
        }
        XCTAssertEqual(
            try repository.readPayload(recordID: "dirty-navigation-0")?.text,
            "detail 0"
        )
    }

    func testClipboardFocusCoordinatorOwnsDetailReturnTargetAndRejectsStaleGeneration() {
        let coordinator = ClipboardPanelFocusCoordinator()
        coordinator.beginSession(sessionID: UUID())
        XCTAssertEqual(coordinator.target, .search)

        let openedGeneration = coordinator.generation
        coordinator.focusRecord("detail-record")
        coordinator.presentDetail(recordID: "detail-record")
        coordinator.beginDetailEditing(recordID: "detail-record")

        XCTAssertEqual(coordinator.target, .detailEdit(recordID: "detail-record"))
        XCTAssertFalse(coordinator.accepts(generation: openedGeneration))

        coordinator.finishDetailEditing(recordID: "detail-record")
        XCTAssertEqual(coordinator.target, .records(recordID: "detail-record"))

        coordinator.presentDetail(recordID: "detail-record")
        coordinator.dismissDetail(recordID: "detail-record")
        XCTAssertEqual(coordinator.target, .records(recordID: "detail-record"))
    }

