    func testClipboardDetailRevealMotionPreservesStablePanelGeometry() {
        let target = CGRect(x: 420, y: 260, width: 380, height: 300)
        let source = CGRect(x: 40, y: 40, width: 180, height: 120)
        let start = ClipboardDetailMotionGeometry.revealFrame(
            targetFrame: target,
            sourceFrame: source
        )

        XCTAssertEqual(start.size, target.size)
        XCTAssertLessThanOrEqual(abs(start.minX - target.minX), 8)
        XCTAssertLessThanOrEqual(abs(start.minY - target.minY), 8)
