    func testClipboardRecordFocusAnchorRetriesRejectedFirstResponder() {
        let coordinator = ClipboardPanelFocusCoordinator()
        let parent = ClipboardAnchorRetryPanel()
        let anchor = ClipboardPanelRecordFocusAnchorView(focusCoordinator: coordinator)
        parent.contentView = anchor
        defer { coordinator.endSession(); parent.close() }
        XCTAssertTrue(parent.makeFirstResponder(nil))
        coordinator.beginSession(sessionID: UUID())
        coordinator.registerParentWindow(parent)
        coordinator.focusRecord("retry-record")
        let generation = coordinator.generation
        parent.observesAnchorRequests = true
        parent.rejectsNextAnchorRequest = true

        anchor.applyFocusRequest(generation: generation)
        XCTAssertEqual(parent.anchorRequestCount, 1)
        XCTAssertFalse(parent.firstResponder === anchor)

        anchor.applyFocusRequest(generation: generation)
        XCTAssertEqual(parent.anchorRequestCount, 2, "A rejected request must remain retryable at the same generation.")
        XCTAssertTrue(parent.firstResponder === anchor)

        anchor.applyFocusRequest(generation: generation)
        XCTAssertEqual(parent.anchorRequestCount, 2, "A successfully applied request must remain deduplicated.")
        coordinator.endSession()
        XCTAssertTrue(parent.makeFirstResponder(nil))
        anchor.applyFocusRequest(generation: generation)
        XCTAssertEqual(parent.anchorRequestCount, 2, "A closed session must not resurrect the rejected or completed request.")
    }

    func testClipboardRecordFocusAnchorCacheIsScopedToCoordinatorIdentity() {
        let original = ClipboardPanelFocusCoordinator()
        let replacement = ClipboardPanelFocusCoordinator()
        let parent = ClipboardAnchorRetryPanel()
        let anchor = ClipboardPanelRecordFocusAnchorView(focusCoordinator: original)
        parent.contentView = anchor
        defer { original.endSession(); replacement.endSession(); parent.close() }
        XCTAssertTrue(parent.makeFirstResponder(nil))
        for coordinator in [original, replacement] {
            coordinator.beginSession(sessionID: UUID())
            coordinator.registerParentWindow(parent)
            coordinator.focusRecord("same-generation-record")
        }
        XCTAssertEqual(original.generation, replacement.generation)
        parent.observesAnchorRequests = true
        anchor.applyFocusRequest(generation: original.generation)
        XCTAssertEqual(parent.anchorRequestCount, 1)
        XCTAssertTrue(parent.firstResponder === anchor)

        XCTAssertTrue(parent.makeFirstResponder(nil))
        anchor.focusCoordinator = replacement
        anchor.applyFocusRequest(generation: replacement.generation)
        XCTAssertEqual(parent.anchorRequestCount, 2, "An equal counter from another coordinator is not the same request.")
        XCTAssertTrue(parent.firstResponder === anchor)
    }

    func testClipboardRecordFocusAnchorReentrantGenerationDoesNotLoseNewAcknowledgement() {
        let coordinator = ClipboardPanelFocusCoordinator()
        let parent = ClipboardAnchorRetryPanel()
        let anchor = ClipboardPanelRecordFocusAnchorView(focusCoordinator: coordinator)
        parent.contentView = anchor
        defer { coordinator.endSession(); parent.close() }
        coordinator.beginSession(sessionID: UUID())
        coordinator.registerParentWindow(parent)
        coordinator.focusRecord("first-record")
        let generation = coordinator.generation
        parent.observesAnchorRequests = true
        parent.onNextAnchorRequest = {
            coordinator.focusRecord("newer-record")
            anchor.applyFocusRequest(generation: coordinator.generation)
        }

        anchor.applyFocusRequest(generation: generation)
        XCTAssertEqual(parent.anchorRequestCount, 2)
        anchor.applyFocusRequest(generation: coordinator.generation)
        XCTAssertEqual(parent.anchorRequestCount, 2, "An older successful return must not overwrite the newer acknowledgement.")
    }

    func testClipboardRecordFocusAnchorDeduplicatesSameGenerationInFlight() {
        let coordinator = ClipboardPanelFocusCoordinator()
        let parent = ClipboardAnchorRetryPanel()
        let anchor = ClipboardPanelRecordFocusAnchorView(focusCoordinator: coordinator)
        parent.contentView = anchor
        defer { coordinator.endSession(); parent.close() }
        coordinator.beginSession(sessionID: UUID())
        coordinator.registerParentWindow(parent)
        coordinator.focusRecord("reentrant-record")
        let generation = coordinator.generation
        parent.observesAnchorRequests = true
        parent.onNextAnchorRequest = { anchor.applyFocusRequest(generation: generation) }

        anchor.applyFocusRequest(generation: generation)
        XCTAssertEqual(parent.anchorRequestCount, 1)
        XCTAssertTrue(parent.firstResponder === anchor)
        anchor.applyFocusRequest(generation: generation)
        XCTAssertEqual(parent.anchorRequestCount, 1)
    }

    func testClipboardRecordFocusAnchorOwnerRoundTripAfterRejectionDoesNotReuseOldCache() {
        let original = ClipboardPanelFocusCoordinator()
        let replacement = ClipboardPanelFocusCoordinator()
        let parent = ClipboardAnchorRetryPanel()
        let anchor = ClipboardPanelRecordFocusAnchorView(focusCoordinator: original)
        parent.contentView = anchor
        defer { original.endSession(); replacement.endSession(); parent.close() }
        for coordinator in [original, replacement] {
            coordinator.beginSession(sessionID: UUID())
            coordinator.registerParentWindow(parent)
            coordinator.focusRecord("round-trip-record")
        }
        parent.observesAnchorRequests = true
        anchor.applyFocusRequest(generation: original.generation)
        XCTAssertEqual(parent.anchorRequestCount, 1)
        XCTAssertTrue(parent.makeFirstResponder(nil))
        anchor.focusCoordinator = replacement
        parent.rejectsNextAnchorRequest = true
        anchor.applyFocusRequest(generation: replacement.generation)
        XCTAssertEqual(parent.anchorRequestCount, 2)
        XCTAssertFalse(parent.firstResponder === anchor)

        anchor.focusCoordinator = original
        anchor.applyFocusRequest(generation: original.generation)
        XCTAssertEqual(parent.anchorRequestCount, 3)
        XCTAssertTrue(parent.firstResponder === anchor)
    }

    func testClipboardFocusEndpointsUseRealAppKitFirstRespondersAndFirstMouse() {
        let coordinator = ClipboardPanelFocusCoordinator()
        let parent = ClipboardTestKeyPanel(
            contentRect: CGRect(x: 0, y: 0, width: 320, height: 220),
            styleMask: [.borderless, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        parent.usesDeterministicKeyWindowState = true
        parent.animationBehavior = .none
        let anchor = ClipboardPanelRecordFocusAnchorView(focusCoordinator: coordinator)
        parent.contentView = anchor
        defer {
            if let detail = parent.childWindows?.first {
                parent.removeChildWindow(detail)
                detail.orderOut(nil)
                coordinator.unregisterDetailWindow(detail)
                detail.close()
            }
            coordinator.endSession()
            parent.orderOut(nil)
            parent.close()
        }

        coordinator.beginSession(sessionID: UUID())
        coordinator.registerParentWindow(parent)
        parent.orderFront(nil)
        parent.makeKey()
        coordinator.windowBecameKey(.parent, window: parent)
        coordinator.focusRecord("record-a")
        anchor.applyFocusRequest(generation: coordinator.generation)

        XCTAssertTrue(anchor.acceptsFirstResponder)
        XCTAssertTrue(parent.firstResponder === anchor)

        let detail = ClipboardTestKeyPanel(
            contentRect: CGRect(x: 0, y: 0, width: 240, height: 140),
            styleMask: [.borderless, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        detail.usesDeterministicKeyWindowState = true
        detail.animationBehavior = .none
        let detailEditor = NSTextView(frame: detail.contentView?.bounds ?? .zero)
        detail.contentView = detailEditor
        parent.addChildWindow(detail, ordered: .above)
        parent.resignKey()
        coordinator.registerDetailWindow(detail)
        detail.orderFront(nil)
        detail.makeKey()
        coordinator.windowBecameKey(.detail, window: detail)
        coordinator.beginDetailEditing(recordID: "record-a")
        XCTAssertTrue(detail.makeFirstResponder(detailEditor))
        XCTAssertTrue(detail.firstResponder === detailEditor)

        let generationBeforeReturningToParent = coordinator.generation
        let parentMakeKeyCountBeforeReturn = parent.makeKeyInvocationCount
        coordinator.finishDetailEditing(recordID: "record-a")
        XCTAssertEqual(coordinator.generation, generationBeforeReturningToParent + 1)
        XCTAssertEqual(parent.makeKeyInvocationCount, parentMakeKeyCountBeforeReturn + 1)
        anchor.applyFocusRequest(generation: coordinator.generation)
        XCTAssertTrue(parent.isKeyWindow)
        XCTAssertTrue(parent.firstResponder === anchor)

        let hostedContent = NSView(frame: CGRect(x: 0, y: 0, width: 80, height: 60))
        let detailContainer = ClipboardDetailPanelContainer(hostingView: hostedContent)
        XCTAssertTrue(detailContainer.acceptsFirstMouse(for: nil as NSEvent?))
    }

