    func testClipboardKeyboardRouterUsesFocusStateAndPanelOrientation() throws {
        let coordinator = ClipboardPanelFocusCoordinator()
        let router = ClipboardPanelKeyboardCommandRouter(focusCoordinator: coordinator)
        var commands: [ClipboardPanelKeyboardCommand] = []
        router.configure(position: .bottom) { commands.append($0) }
        let panel = ClipboardTestKeyPanel(
            contentRect: CGRect(x: 0, y: 0, width: 320, height: 160),
            styleMask: [.borderless, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        let content = NSView(frame: panel.contentView?.bounds ?? .zero)
        let searchField = NSTextField()
        searchField.placeholderString = L10n.string("clipboard.searchPlaceholder")
        let searchEditor = NSTextView(frame: .zero)
        searchEditor.isFieldEditor = true
        let recordAnchor = ClipboardPanelRecordFocusAnchorView(
            focusCoordinator: coordinator
        )
        content.addSubview(searchEditor)
        content.addSubview(recordAnchor)
        searchEditor.nextResponder = searchField
        panel.contentView = content
        defer { panel.close() }

        coordinator.beginSession(sessionID: UUID())
        coordinator.registerParentWindow(panel)
        XCTAssertTrue(panel.makeFirstResponder(searchEditor))

        XCTAssertTrue(router.route(try keyEvent(keyCode: UInt16(kVK_DownArrow))))
        XCTAssertEqual(commands.last, .navigate(delta: 1))

        coordinator.focusRecord("record-a")
        XCTAssertTrue(panel.makeFirstResponder(recordAnchor))
        XCTAssertTrue(router.route(try keyEvent(keyCode: UInt16(kVK_LeftArrow))))
        XCTAssertEqual(commands.last, .navigate(delta: -1))

        coordinator.beginDetailEditing(recordID: "record-a")
        XCTAssertTrue(router.route(try keyEvent(
            keyCode: UInt16(kVK_Return),
            modifiers: [.command],
            characters: "\r"
        )))
        XCTAssertEqual(commands.last, .saveDetail)
    }

    func testClipboardKeyboardRouterDefersFilterResponderButKeepsSearchAndRecordEndpoints()
        throws
    {
        let coordinator = ClipboardPanelFocusCoordinator()
        let router = ClipboardPanelKeyboardCommandRouter(focusCoordinator: coordinator)
        var commands: [ClipboardPanelKeyboardCommand] = []
        router.configure(position: .bottom) { commands.append($0) }

        let panel = ClipboardTestKeyPanel(
            contentRect: CGRect(x: 0, y: 0, width: 320, height: 160),
            styleMask: [.borderless, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        let content = NSView(frame: panel.contentView?.bounds ?? .zero)
        let filterControl = ClipboardTestFilterMenuControl(frame: .zero, pullsDown: false)
        filterControl.addItem(withTitle: "All")
        let searchField = NSTextField()
        searchField.placeholderString = L10n.string("clipboard.searchPlaceholder")
        let searchEditor = NSTextView(frame: .zero)
        searchEditor.isFieldEditor = true
        let recordAnchor = ClipboardPanelRecordFocusAnchorView(
            focusCoordinator: coordinator
        )
        content.addSubview(filterControl)
        content.addSubview(searchEditor)
        content.addSubview(recordAnchor)
        searchEditor.nextResponder = searchField
        panel.contentView = content
        defer { panel.close() }

        coordinator.beginSession(sessionID: UUID())
        coordinator.registerParentWindow(panel)
        XCTAssertTrue(panel.makeFirstResponder(filterControl))
        XCTAssertTrue(panel.firstResponder === filterControl)

        XCTAssertFalse(router.route(try keyEvent(keyCode: UInt16(kVK_DownArrow))))
        XCTAssertFalse(router.route(try keyEvent(
            keyCode: UInt16(kVK_Return),
            characters: "\r"
        )))
        XCTAssertTrue(commands.isEmpty, "Filter input must not navigate or paste a record.")

        XCTAssertTrue(panel.makeFirstResponder(searchEditor))
        XCTAssertTrue(router.route(try keyEvent(keyCode: UInt16(kVK_UpArrow))))
        XCTAssertTrue(router.route(try keyEvent(keyCode: UInt16(kVK_DownArrow))))
        XCTAssertTrue(router.route(try keyEvent(
            keyCode: UInt16(kVK_Return),
            characters: "\r"
        )))
        XCTAssertEqual(
            commands,
            [.navigate(delta: -1), .navigate(delta: 1), .pasteSelected]
        )

        coordinator.focusRecord("record-a")
        XCTAssertTrue(panel.makeFirstResponder(recordAnchor))
        XCTAssertTrue(router.route(try keyEvent(keyCode: UInt16(kVK_LeftArrow))))
        XCTAssertEqual(commands.last, .navigate(delta: -1))
    }

