    func testScreenshotCanvasInvalidationOnlyAcceptsChangedSnapshot() {
        let image = NSImage(size: NSSize(width: 40, height: 30))
        let original = screenshotCanvasSnapshot(image: image, zoomScale: 1)
        let changed = screenshotCanvasSnapshot(image: image, zoomScale: 2)
        let toolOnlyChange = screenshotCanvasSnapshot(
            image: image,
            zoomScale: 1,
            selectedTool: .text
        )
        let interactionOnlyChange = screenshotCanvasSnapshot(
            image: image,
            zoomScale: 1,
            isInteractionEnabled: false
        )

        XCTAssertFalse(ScreenshotCanvasInvalidationPolicy.shouldRedraw(
            previous: original,
            next: original
        ))
        XCTAssertTrue(ScreenshotCanvasInvalidationPolicy.shouldRedraw(
            previous: original,
            next: changed
        ))
        XCTAssertFalse(ScreenshotCanvasInvalidationPolicy.shouldRedraw(
            previous: original,
            next: toolOnlyChange
        ))
        XCTAssertFalse(ScreenshotCanvasInvalidationPolicy.shouldRedraw(
            previous: original,
            next: interactionOnlyChange
        ))

        let element = ScreenshotElement(
            kind: .rectangle,
            geometry: .rect(.init(x: 4, y: 5, width: 10, height: 8))
        )
        let elementChange = screenshotCanvasSnapshot(
            image: image,
            zoomScale: 1,
            sceneElements: [element]
        )
        XCTAssertEqual(
            ScreenshotCanvasInvalidationPolicy.invalidation(
                previous: original,
                next: elementChange
            ),
            .sourceRect(CGRect(x: 4, y: 5, width: 10, height: 8))
        )
        var movedElement = element
        movedElement.geometry = .rect(.init(x: 20, y: 12, width: 10, height: 8))
        let movedElementChange = screenshotCanvasSnapshot(
            image: image,
            zoomScale: 1,
            sceneElements: [movedElement]
        )
        XCTAssertEqual(
            ScreenshotCanvasInvalidationPolicy.invalidation(
                previous: elementChange,
                next: movedElementChange
            ),
            .sourceRect(CGRect(x: 4, y: 5, width: 26, height: 15))
        )
        XCTAssertEqual(
            ScreenshotCanvasInvalidationPolicy.invalidation(
                previous: original,
                next: changed
            ),
            .full
        )
    }

