    func testClipboardRecencyPromotionIsStrictlyMonotonicAtSameClockInstant() async throws {
        let store = ClipboardStore(repository: nil)
        let baseDate = Date(timeIntervalSince1970: 5_000)
        store.records = ["a", "b"].enumerated().map { index, id in
            ClipboardRecorderRecord(
                id: id,
                createdAt: baseDate.addingTimeInterval(TimeInterval(index)),
                changeCount: index,
                kind: .text,
                formatSummary: ClipboardRecorderFormatSummary(
                    itemCount: 1,
                    types: ["public.utf8-plain-text"],
                    byteCount: 1
                ),
                sourceApp: nil,
                signatureSHA256_12: id,
                fixtureOwned: true,
                restorable: true,
                summary: id
            )
        }

        let first = await store.commitCopyEvent(recordID: "a", source: .panelPaste, at: baseDate)
        let second = await store.commitCopyEvent(recordID: "b", source: .panelPaste, at: baseDate)

        XCTAssertNotNil(first.promotedAt)
        XCTAssertNotNil(second.promotedAt)
        XCTAssertGreaterThan(try XCTUnwrap(second.promotedAt), try XCTUnwrap(first.promotedAt))
        XCTAssertEqual(store.records.map(\.id), ["b", "a"])
    }

    func testClipboardPasteHookReceivesCompleteContentAndAppliesTextMutation()
        async throws
    {
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: ClipboardStore(repository: nil),
            privacyStore: PrivacyStore(repository: nil),
            featureAvailabilityStore:
                FeatureAvailabilityStore(defaults: testDefaults())
        )
        let stagedResources = ClipboardPluginTextResourceRecorder()
        coordinator.stagePluginTextResource = { text, kind, mediaType, _ in
            stagedResources.record(Data(text.utf8))
            return BlocksPluginResourceReference(
                id: "resource",
                kind: kind,
                mediaType: mediaType,
                byteCount: Int64(text.utf8.count),
                sha256: "fixture"
            )
        }
        let record = ClipboardRecorderRecord(
            id: "plugin-paste",
            createdAt: Date(timeIntervalSince1970: 1_000),
            changeCount: 4,
            kind: .richText,
            formatSummary: ClipboardRecorderFormatSummary(
                itemCount: 1,
                types: ["public.rtf", "public.utf8-plain-text"],
                byteCount: 8
            ),
            sourceApp: nil,
            signatureSHA256_12: "signature",
            fixtureOwned: true,
            restorable: true,
            summary: "original"
        )
        let original = ClipboardRecorderPayload(
            recordID: record.id,
            kind: .richText,
            text: "original",
            rtfData: Data("{\\rtf1 original}".utf8)
        )

        let input = await coordinator.pluginClipboardContentEventInput(
            record: record,
            payload: original
        )
        XCTAssertEqual(input.payload["text"], .string("original"))
        XCTAssertEqual(input.payload["content_resource_id"], .string("resource"))
        XCTAssertEqual(stagedResources.latestData, Data("original".utf8))

        var mutatedPayload = input.payload
        mutatedPayload["text"] = .string("transformed")
        let transformed = try XCTUnwrap(
            coordinator.applyingPluginPasteMutations(
                from: BlocksPluginEventEnvelope(
                    name: .clipboardWillWritePasteboard,
                    payload: mutatedPayload,
                    resources: input.resources
                ),
                to: original
            )
        )
        XCTAssertEqual(transformed.kind, .text)
        XCTAssertEqual(transformed.text, "transformed")
        XCTAssertNil(transformed.rtfData)

        let fileURL = "file:///tmp/plugin-source.txt"
        let originalFileURL = ClipboardRecorderPayload(
            recordID: "file-url-record",
            kind: .fileURL,
            text: "/tmp/plugin-source.txt",
            urlString: fileURL
        )
        let preservedFileURL = try XCTUnwrap(
            coordinator.applyingPluginPasteMutations(
                from: BlocksPluginEventEnvelope(
                    name: .clipboardWillWritePasteboard,
                    payload: ["text": .string("transformed")]
                ),
                to: originalFileURL
            )
        )
        XCTAssertEqual(preservedFileURL.kind, .fileURL)
        XCTAssertEqual(preservedFileURL.text, "/tmp/plugin-source.txt")
        XCTAssertEqual(preservedFileURL.urlString, fileURL)

        let imageData = Data([0x89, 0x50, 0x4E, 0x47])
        let originalImage = ClipboardRecorderPayload(
            recordID: "image-record",
            kind: .image,
            pngData: imageData
        )
        let preservedImage = try XCTUnwrap(
            coordinator.applyingPluginPasteMutations(
                from: BlocksPluginEventEnvelope(
                    name: .clipboardWillWritePasteboard,
                    payload: ["text": .string("")]
                ),
                to: originalImage
            )
        )
        XCTAssertEqual(preservedImage.kind, .image)
        XCTAssertEqual(preservedImage.pngData, imageData)
        XCTAssertNil(preservedImage.text)

        let largeText = String(repeating: "x", count: 4 * 1_024 * 1_024)
        let largeInput = await coordinator.pluginClipboardContentEventInput(
            record: record,
            payload: ClipboardRecorderPayload(
                recordID: record.id,
                kind: .text,
                text: largeText
            )
        )
        XCTAssertNil(largeInput.payload["text"])
        XCTAssertNil(largeInput.payload["plain_text"])
        XCTAssertEqual(
            largeInput.payload["content_resource_id"],
            .string("resource")
        )
        XCTAssertEqual(largeInput.resources.first?.byteCount, Int64(largeText.utf8.count))
        XCTAssertEqual(stagedResources.latestData, Data(largeText.utf8))
    }

    func testRestrictedClipboardCaptureDoesNotStageOrDispatchContentBeforePersistence() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "RestrictedClipboardCapturePreflight.\(UUID().uuidString)",
                isDirectory: true
            )
        let database = try AppDatabase.open(
            environment: StorageEnvironment(rootDirectory: root)
        )
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let privacyRepository = PrivacyPolicyRepository(database: database)
        let restrictedBundleID = "com.blocks.tests.restricted-clipboard-source"
        try privacyRepository.applyPolicy(
            subject: PrivacyPolicySubject(
                subjectRef: "bundle:\(restrictedBundleID)",
                type: .bundleID,
                identifier: restrictedBundleID
            ),
            policy: .restricted
        )
        let privacyStore = PrivacyStore(repository: privacyRepository)
        let privacyReady = expectation(description: "privacy policy snapshot loads")
        var privacyAvailabilityObservation: AnyCancellable?
        privacyAvailabilityObservation = privacyStore.$capturePolicyAvailability.sink {
            if $0 == .ready {
                privacyReady.fulfill()
            }
        }
        await fulfillment(of: [privacyReady], timeout: 1)
        privacyAvailabilityObservation?.cancel()
        privacyAvailabilityObservation = nil

        let repository = ClipboardRepository(database: database)
        let store = ClipboardStore(repository: repository)
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: store,
            privacyStore: privacyStore,
            featureAvailabilityStore: FeatureAvailabilityStore(defaults: testDefaults())
        )
        let stagedResourceCount = ClipboardCleanupInvocationCounter()
        var willPersistCount = 0
        var didPersistCount = 0
        let allowedPersisted = expectation(description: "allowed capture persists")
        coordinator.configure(
            statusRecorder: { _ in },
            sectionSelector: { _ in },
            closeTranslationPanel: {},
            translateRecord: { _ in },
            refreshPermissionState: {},
            dispatchPluginEvent: { envelope in
                switch envelope.name {
                case .clipboardWillPersistCapture:
                    willPersistCount += 1
                    var payload = envelope.payload
                    payload["summary"] = .string("plugin-mutated summary")
                    return .allowed(BlocksPluginEventEnvelope(
                        name: envelope.name,
                        sessionID: envelope.sessionID,
                        causationID: envelope.causationID,
                        source: envelope.source,
                        authorization: envelope.authorization,
                        payload: payload,
                        resources: envelope.resources
                    ))
                case .clipboardDidPersistCapture:
                    didPersistCount += 1
                    allowedPersisted.fulfill()
                default:
                    break
                }
                return .allowed(envelope)
            },
            stagePluginTextResource: { _, _, _, _ in
                _ = stagedResourceCount.increment()
                return BlocksPluginResourceReference(
                    id: "allowed-content-resource",
                    kind: .text,
                    mediaType: "text/plain; charset=utf-8",
                    byteCount: 16,
                    sha256: "fixture"
                )
            },
            removePluginResources: { _ in },
            accessibilityGranted: { true },
            presentAccessibilityAssist: { _ in }
        )

        func snapshot(
            id: String,
            text: String,
            sourceApp: ClipboardRecorderSourceApp?
        ) -> ClipboardLiveCaptureSnapshot {
            let signature = String(repeating: id == "restricted" ? "r" : "a", count: 64)
            return ClipboardLiveCaptureSnapshot(
                record: ClipboardRecorderRecord(
                    id: id,
                    createdAt: Date(),
                    changeCount: id == "restricted" ? 6_100 : 6_101,
                    kind: .text,
                    formatSummary: .init(
                        itemCount: 1,
                        types: ["public.utf8-plain-text"],
                        textLength: text.count,
                        byteCount: text.utf8.count
                    ),
                    sourceApp: sourceApp,
                    signatureSHA256: signature,
                    signatureSHA256_12: String(signature.prefix(12)),
                    fixtureOwned: true,
                    restorable: true,
                    summary: text
                ),
                payload: .init(recordID: id, kind: .text, text: text)
            )
        }

        let restricted = snapshot(
            id: "restricted",
            text: "restricted sentinel must not leave capture",
            sourceApp: ClipboardRecorderSourceApp(
                bundleIdentifier: restrictedBundleID,
                localizedName: "Restricted Sentinel"
            )
        )
        coordinator.ingestLiveCapture(restricted)

        XCTAssertEqual(stagedResourceCount.currentValue, 0)
        XCTAssertEqual(willPersistCount, 0)
        XCTAssertEqual(didPersistCount, 0)
        XCTAssertNil(try repository.loadRecord(recordID: restricted.record.id))
        XCTAssertNil(try repository.readPayload(recordID: restricted.record.id))

        let allowed = snapshot(
            id: "allowed",
            text: "allowed sentinel",
            sourceApp: ClipboardRecorderSourceApp(
                bundleIdentifier: "com.blocks.tests.allowed-clipboard-source",
                localizedName: "Allowed Sentinel"
            )
        )
        coordinator.ingestLiveCapture(allowed)
        await fulfillment(of: [allowedPersisted], timeout: 1)

        XCTAssertEqual(stagedResourceCount.currentValue, 1)
        XCTAssertEqual(willPersistCount, 1)
        XCTAssertEqual(didPersistCount, 1)
        XCTAssertEqual(
            try repository.loadRecord(recordID: allowed.record.id)?.summary,
            "plugin-mutated summary"
        )
        XCTAssertEqual(
            try repository.readPayload(recordID: allowed.record.id)?.text,
            "allowed sentinel"
        )
    }

    func testLiveClipboardCaptureSetPolicyRevocationDuringStagingFailsClosed() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "LiveClipboardCapturePrivacyRevocation.\(UUID().uuidString)",
                isDirectory: true
            )
        let database = try AppDatabase.open(
            environment: StorageEnvironment(rootDirectory: root)
        )
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }

        let privacyRepository = PrivacyPolicyRepository(database: database)
        let privacyStore = PrivacyStore(repository: privacyRepository)
        let privacyReady = expectation(description: "privacy policy snapshot loads")
        var privacyAvailabilityObservation: AnyCancellable?
        privacyAvailabilityObservation = privacyStore.$capturePolicyAvailability.sink {
            if $0 == .ready {
                privacyReady.fulfill()
            }
        }
        await fulfillment(of: [privacyReady], timeout: 1)
        privacyAvailabilityObservation?.cancel()
        privacyAvailabilityObservation = nil

        let repository = ClipboardRepository(database: database)
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: ClipboardStore(repository: repository),
            privacyStore: privacyStore,
            featureAvailabilityStore: FeatureAvailabilityStore(defaults: testDefaults())
        )
        let stageGate = ClipboardLiveCaptureStageGate()
        let stageEntered = expectation(description: "resource staging begins")
        let resourceCleaned = expectation(description: "staged resource is cleaned")
        var willPersistCount = 0
        var didPersistCount = 0
        let sourceBundleID = "com.blocks.tests.revoked-live-capture-source"
        let recordID = "revoked-during-resource-staging"
        coordinator.configure(
            statusRecorder: { _ in },
            sectionSelector: { _ in },
            closeTranslationPanel: {},
            translateRecord: { _ in },
            refreshPermissionState: {},
            dispatchPluginEvent: { envelope in
                switch envelope.name {
                case .clipboardWillPersistCapture:
                    willPersistCount += 1
                case .clipboardDidPersistCapture:
                    didPersistCount += 1
                default:
                    break
                }
                return .allowed(envelope)
            },
            stagePluginTextResource: { text, _, _, _ in
                XCTAssertEqual(text, "must not persist after privacy revocation")
                await stageGate.recordStart(recordID)
                stageEntered.fulfill()
                await stageGate.waitForRelease(of: recordID)
                return BlocksPluginResourceReference(
                    id: "revoked-content-resource",
                    kind: .text,
                    mediaType: "text/plain; charset=utf-8",
                    byteCount: Int64(text.utf8.count),
                    sha256: "fixture"
                )
            },
            removePluginResources: { resourceIDs in
                if resourceIDs == ["revoked-content-resource"] {
                    resourceCleaned.fulfill()
                }
            },
            accessibilityGranted: { true },
            presentAccessibilityAssist: { _ in }
        )

        let sourceApp = ClipboardRecorderSourceApp(
            bundleIdentifier: sourceBundleID,
            localizedName: "Revoked Live Capture Source"
        )
        let text = "must not persist after privacy revocation"
        let signature = String(repeating: "v", count: 64)
        coordinator.ingestLiveCapture(
            ClipboardLiveCaptureSnapshot(
                record: ClipboardRecorderRecord(
                    id: recordID,
                    createdAt: Date(),
                    changeCount: 6_102,
                    kind: .text,
                    formatSummary: .init(
                        itemCount: 1,
                        types: ["public.utf8-plain-text"],
                        textLength: text.count,
                        byteCount: text.utf8.count
                    ),
                    sourceApp: sourceApp,
                    signatureSHA256: signature,
                    signatureSHA256_12: String(signature.prefix(12)),
                    fixtureOwned: true,
                    restorable: true,
                    summary: text
                ),
                payload: .init(recordID: recordID, kind: .text, text: text)
            )
        )
        await fulfillment(of: [stageEntered], timeout: 1)

        let authorizationGeneration = privacyStore.privacyCaptureAuthorizationGeneration
        let deniedSnapshot = expectation(description: "restricted snapshot is published")
        var policyObservation: AnyCancellable?
        policyObservation = privacyStore.$policySnapshot.sink { snapshot in
            if snapshot.match(sourceApp: sourceApp).decision == .deny,
               privacyStore.privacyCaptureAuthorizationGeneration > authorizationGeneration {
                deniedSnapshot.fulfill()
            }
        }
        let policyApp = PrivacyAppInstance(
            id: "revoked-live-capture-policy-app",
            displayName: "Revoked Live Capture Source",
            bundleIdentifier: sourceBundleID,
            subjectRef: "bundle:\(sourceBundleID)",
            pathHash: "fixture-path-hash",
            pathSummary: "/Applications/Revoked Live Capture Source.app",
            sourceDirectory: .applications
        )
        privacyStore.setPolicy(for: policyApp, policy: .restricted)
        XCTAssertEqual(privacyStore.mutationState, .saving)
        XCTAssertFalse(privacyStore.canCaptureClipboard)
        XCTAssertGreaterThan(
            privacyStore.privacyCaptureAuthorizationGeneration,
            authorizationGeneration
        )
        await fulfillment(of: [deniedSnapshot], timeout: 1)
        policyObservation?.cancel()
        policyObservation = nil
        XCTAssertTrue(privacyStore.canCaptureClipboard)

        await stageGate.release(recordID)
        await fulfillment(of: [resourceCleaned], timeout: 1)

        XCTAssertEqual(willPersistCount, 0)
        XCTAssertEqual(didPersistCount, 0)
        XCTAssertNil(try repository.loadRecord(recordID: recordID))
        XCTAssertNil(try repository.readPayload(recordID: recordID))
    }

