    func testPrivacyCaptureAdmissionGateAdmittedInsertWinsAndRevokeWaits()
        async throws
    {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "PrivacyCaptureAdmissionCriticalSection.\(UUID().uuidString)",
                isDirectory: true
            )
        let database = try AppDatabase.open(
            environment: StorageEnvironment(rootDirectory: root)
        )
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }

        let generation = 41
        let gate = PrivacyCaptureAdmissionGate()
        gate.invalidate(generation: generation)
        gate.open(generation: generation)
        let token = try XCTUnwrap(gate.token(generation: generation))

        let insertAdmitted = expectation(
            description: "admitted insert reaches before-insert hook"
        )
        let insertGate = OneShotDispatchSemaphoreGate()
        defer { insertGate.release() }
        let repository = ClipboardRepository(database: database)
        let store = ClipboardStore(
            repository: repository,
            capturePersistencePipelineHooks: ClipboardCapturePersistencePipelineHooks(
                beforeInsert: {
                    insertAdmitted.fulfill()
                    insertGate.wait()
                }
            )
        )
        let recordID = "privacy-admitted-insert"
        let text = "admitted insert must durably win"
        let snapshot = ClipboardLiveCaptureSnapshot(
            record: ClipboardRecorderRecord(
                id: recordID,
                createdAt: Date(),
                changeCount: 6_110,
                kind: .text,
                formatSummary: .init(
                    itemCount: 1,
                    types: ["public.utf8-plain-text"],
                    textLength: text.count,
                    byteCount: text.utf8.count
                ),
                sourceApp: nil,
                signatureSHA256: String(repeating: "c", count: 64),
                signatureSHA256_12: String(repeating: "c", count: 12),
                fixtureOwned: true,
                restorable: true,
                summary: text
            ),
            payload: .init(recordID: recordID, kind: .text, text: text)
        )

        let captureTask = Task { @MainActor in
            await store.ingestLiveCaptureAsync(
                snapshot,
                capturePolicy: ClipboardCapturePolicy(
                    paused: false,
                    privacyPolicyAvailable: true,
                    privacySnapshot: PrivacyPolicySnapshot()
                ),
                cleanupMode: .count,
                retentionPolicy: .days30,
                maxItems: 500,
                preserveFavorite: false,
                privacyCaptureAdmissionToken: token
            )
        }
        await fulfillment(of: [insertAdmitted], timeout: 1)

        let revokeStarted = DispatchSemaphore(value: 0)
        let revokeReturned = DispatchSemaphore(value: 0)
        DispatchQueue.global(qos: .userInitiated).async {
            revokeStarted.signal()
            gate.invalidate(generation: generation + 1)
            revokeReturned.signal()
        }
        XCTAssertEqual(revokeStarted.wait(timeout: .now() + 1), .success)
        XCTAssertEqual(
            revokeReturned.wait(timeout: .now() + .milliseconds(100)),
            .timedOut,
            "Revocation must not return while the admitted insert owns the gate."
        )
        XCTAssertNil(try repository.loadRecord(recordID: recordID))
        XCTAssertNil(try repository.readPayload(recordID: recordID))

        insertGate.release()

        let captureResult = await captureTask.value
        XCTAssertTrue(captureResult.succeeded)
        XCTAssertTrue(captureResult.durablyCommitted)
        XCTAssertFalse(captureResult.invalidated)
        XCTAssertEqual(revokeReturned.wait(timeout: .now() + 1), .success)
        XCTAssertNotNil(try repository.loadRecord(recordID: recordID))
        XCTAssertEqual(try repository.readPayload(recordID: recordID)?.text, text)
        XCTAssertNil(token.withAuthorizedAdmission { true })
    }

    func testInMemoryPrivacyOrGenerationRevocationSkipsLiveAndExplicitCaptureMutation()
        async throws
    {
        func snapshot(
            id: String,
            text: String,
            changeCount: Int
        ) -> ClipboardLiveCaptureSnapshot {
            let signature = String(format: "%064d", changeCount)
