            stagePluginTextResource: { text, _, _, _ in
                BlocksPluginResourceReference(
                    id: "committed-content-resource",
                    kind: .text,
                    mediaType: "text/plain; charset=utf-8",
                    byteCount: Int64(text.utf8.count),
                    sha256: "fixture"
                )
            },
            removePluginResources: { resourceIDs in
                if resourceIDs == ["committed-content-resource"] {
                    resourceCleaned.fulfill()
                }
            },
            accessibilityGranted: { true },
            presentAccessibilityAssist: { _ in }
        )

        let recordID = "privacy-reload-after-commit"
        let text = "commit remains, publication is revoked"
        let signature = String(repeating: "p", count: 64)
        let defaults = UserDefaults.standard
        let cleanupModeKey = "clipboard.policy.cleanupMode"
        let maxItemsKey = "clipboard.policy.maxItems"
        let preserveFavoriteKey = "clipboard.policy.preserveFavorite"
        let originalCleanupMode = defaults.object(forKey: cleanupModeKey)
        let originalMaxItems = defaults.object(forKey: maxItemsKey)
        let originalPreserveFavorite = defaults.object(forKey: preserveFavoriteKey)
        defer {
            for (key, value) in [
                (cleanupModeKey, originalCleanupMode),
                (maxItemsKey, originalMaxItems),
                (preserveFavoriteKey, originalPreserveFavorite),
            ] {
                if let value {
                    defaults.set(value, forKey: key)
                } else {
                    defaults.removeObject(forKey: key)
                }
            }
        }
        defaults.set(ClipboardCleanupMode.count.rawValue, forKey: cleanupModeKey)
        defaults.set(1, forKey: maxItemsKey)
        defaults.set(false, forKey: preserveFavoriteKey)

        coordinator.ingestLiveCapture(
            ClipboardLiveCaptureSnapshot(
                record: ClipboardRecorderRecord(
                    id: recordID,
                    createdAt: Date(),
                    changeCount: 6_103,
                    kind: .text,
                    formatSummary: .init(
                        itemCount: 1,
                        types: ["public.utf8-plain-text"],
                        textLength: text.count,
                        byteCount: text.utf8.count
                    ),
                    sourceApp: nil,
                    signatureSHA256: signature,
                    signatureSHA256_12: String(signature.prefix(12)),
                    fixtureOwned: true,
                    restorable: true,
                    summary: text
                ),
                payload: .init(recordID: recordID, kind: .text, text: text)
            )
        )
        await fulfillment(of: [committed], timeout: 1)
        XCTAssertNotNil(try repository.loadRecord(recordID: recordID))

        let authorizationGeneration = privacyStore.privacyCaptureAuthorizationGeneration
        privacyStore.reloadSnapshot()
        XCTAssertFalse(privacyStore.canCaptureClipboard)
        XCTAssertGreaterThan(
            privacyStore.privacyCaptureAuthorizationGeneration,
            authorizationGeneration
        )

        releaseContinuation.signal()
        await fulfillment(of: [resourceCleaned], timeout: 1)

        XCTAssertEqual(willPersistCount, 1)
        XCTAssertEqual(didPersistCount, 0)
        XCTAssertEqual(failedCount, 0)
        XCTAssertEqual(deletedCount, 0)
        XCTAssertEqual(store.records.map(\.id), publishedRecordIDsBeforeCapture)
        XCTAssertEqual(store.searchRevision, searchRevisionBeforeCapture)
        XCTAssertFalse(store.currentSearchResult.records.contains { $0.id == recordID })
        XCTAssertNotNil(try repository.loadRecord(recordID: recordID))
        XCTAssertEqual(try repository.readPayload(recordID: recordID)?.text, text)
        XCTAssertNil(try repository.loadRecord(recordID: "privacy-reload-pruned-record"))
    }

