    func testTranslationCopyWritesPasteboardAndPromotesOneCanonicalHistoryRecord()
        async throws
    {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "TranslationClipboardCopy.\(UUID().uuidString)",
                isDirectory: true
            )
        let database = try AppDatabase.open(
            environment: StorageEnvironment(rootDirectory: root)
        )
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let clipboardStore = ClipboardStore(
            repository: ClipboardRepository(database: database)
        )
        let privacyStore = PrivacyStore(
            repository: PrivacyPolicyRepository(database: database)
        )
        let defaults = testDefaults()
        let pasteboard = ScriptedClipboardPasteboard(
            items: [],
            changeCount: 40,
            writeOutcomes: [true, true]
        )
        let autoPasteCoordinator = ClipboardAutoPasteCoordinator(
            pasteboard: pasteboard,
            changeSuppressor: ClipboardPasteboardChangeSuppressor()
        )
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: clipboardStore,
            privacyStore: privacyStore,
            featureAvailabilityStore:
                FeatureAvailabilityStore(defaults: defaults),
            autoPasteCoordinator: autoPasteCoordinator
        )
        for _ in 0..<100 where !privacyStore.canCaptureClipboard {
            try await Task.sleep(for: .milliseconds(10))
        }
        XCTAssertTrue(privacyStore.canCaptureClipboard)

        let first = await coordinator.copyExplicitText(
            "translated fixture",
            source: .translationResult
        )
        let firstRecord = try XCTUnwrap(clipboardStore.records.first)
        let firstTimestamp = firstRecord.lastCopiedAt
        let second = await coordinator.copyExplicitText(
            "translated fixture",
            source: .translationResult
        )

        XCTAssertEqual(first, .copiedAndRecorded)
        XCTAssertEqual(second, .copiedAndRecorded)
        XCTAssertEqual(clipboardStore.records.count, 1)
        XCTAssertEqual(
            clipboardStore.records.first?.summary,
            "translated fixture"
        )
        XCTAssertGreaterThan(
            try XCTUnwrap(clipboardStore.records.first?.lastCopiedAt),
            firstTimestamp
        )
        XCTAssertEqual(pasteboard.writeCallCount, 2)
        let stringRepresentation = try XCTUnwrap(
            pasteboard.items.first?
                .representations[.string]
        )
        guard case let .string(value) = stringRepresentation else {
            return XCTFail("Translation copy must write plain text.")
        }
        XCTAssertEqual(value, "translated fixture")
    }

    func testTranslationCopyRespectsClipboardHistoryAvailabilityWithoutBlockingSystemCopy()
        async throws
    {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "TranslationClipboardAvailability.\(UUID().uuidString)",
                isDirectory: true
            )
        let database = try AppDatabase.open(
            environment: StorageEnvironment(rootDirectory: root)
        )
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let clipboardStore = ClipboardStore(
            repository: ClipboardRepository(database: database)
        )
        let privacyStore = PrivacyStore(
            repository: PrivacyPolicyRepository(database: database)
        )
        let defaults = testDefaults()
        let featureStore = FeatureAvailabilityStore(defaults: defaults)
        let pasteboard = ScriptedClipboardPasteboard(
            items: [],
            changeCount: 60,
            writeOutcomes: [true, true, true]
        )
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: clipboardStore,
            privacyStore: privacyStore,
            featureAvailabilityStore: featureStore,
            autoPasteCoordinator: ClipboardAutoPasteCoordinator(
                pasteboard: pasteboard,
                changeSuppressor: ClipboardPasteboardChangeSuppressor()
            )
        )
        for _ in 0..<100 where !privacyStore.canCaptureClipboard {
            try await Task.sleep(for: .milliseconds(10))
        }
        XCTAssertTrue(privacyStore.canCaptureClipboard)

        featureStore.setClipboardEnabled(false)
        let disabled = await coordinator.copyExplicitText(
            "disabled history fixture",
            source: .translationResult
        )

        featureStore.setClipboardEnabled(true)
        clipboardStore.recorderPaused = true
        let paused = await coordinator.copyExplicitText(
            "paused history fixture",
            source: .translationResult
        )

        clipboardStore.recorderPaused = false
        let recorded = await coordinator.copyExplicitText(
            "recorded history fixture",
            source: .translationResult
        )

        XCTAssertEqual(disabled, .copiedWithoutHistory)
        XCTAssertEqual(paused, .copiedWithoutHistory)
        XCTAssertEqual(recorded, .copiedAndRecorded)
        XCTAssertEqual(pasteboard.writeCallCount, 3)
        XCTAssertEqual(clipboardStore.records.map(\.summary), ["recorded history fixture"])
        XCTAssertEqual(
            try ClipboardRepository(database: database).loadRecent(limit: 10)
                .map(\.summary),
            ["recorded history fixture"]
        )
    }

    func testClipboardPolicySummaryUsesFavoriteSemanticsInsteadOfPermissionStatus() {
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: ClipboardStore(repository: nil),
            privacyStore: PrivacyStore(repository: nil),
            featureAvailabilityStore: FeatureAvailabilityStore(defaults: testDefaults())
        )

        let preserved = coordinator.policySummary(
            cleanupMode: .count,
            retentionPolicy: .days30,
            maxItems: 500,
            preserveFavorite: true
        )
        let notPreserved = coordinator.policySummary(
            cleanupMode: .count,
            retentionPolicy: .days30,
            maxItems: 500,
            preserveFavorite: false
        )

        XCTAssertTrue(preserved.contains(L10n.string("clipboard.policy.favorite.preserved")))
        XCTAssertTrue(notPreserved.contains(L10n.string("clipboard.policy.favorite.notPreserved")))
        XCTAssertFalse(preserved.contains(L10n.string("settings.granted")))
        XCTAssertFalse(notPreserved.contains(L10n.string("settings.missing")))
    }

