    func testClipboardPolicyPreviewCancelAndBusyRejectionLeaveRepositoryUnchanged() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ClipboardPolicyCancel.\(UUID().uuidString)", isDirectory: true)
        let database = try AppDatabase.open(environment: StorageEnvironment(rootDirectory: root))
        defer { database.close(); try? FileManager.default.removeItem(at: root) }
        let repository = ClipboardRepository(database: database)
        try insertClipboardCleanupFixture(repository, id: "old", timestamp: 10)
        try insertClipboardCleanupFixture(repository, id: "new", timestamp: 20)
        let store = ClipboardStore(repository: repository)
        let previewed = expectation(description: "destructive policy previewed")

        XCTAssertTrue(store.requestPolicyPreview(
            cleanupMode: .count,
            retentionPolicy: .days30,
            maxItems: 1,
            preserveFavorite: false
        ) { result in
            guard case let .preview(deleteCount, _) = result else {
                return XCTFail("Expected a destructive preview, got \(result)")
            }
            XCTAssertEqual(deleteCount, 1)
            previewed.fulfill()
        })
        await fulfillment(of: [previewed], timeout: 1)
        XCTAssertEqual(store.cleanupMutationState, .awaitingConfirmation)

        let secondPreviewRejected = expectation(description: "second preview rejected")
        XCTAssertFalse(store.requestPolicyPreview(
            cleanupMode: .count,
            retentionPolicy: .days30,
            maxItems: 2,
            preserveFavorite: false
        ) { result in
            XCTAssertEqual(result, .rejectedWhileBusy)
            secondPreviewRejected.fulfill()
        })
        let clearRejected = expectation(description: "clear rejected")
        store.requestClearUnfavorited { result in
            XCTAssertEqual(result, .rejectedWhileBusy)
            clearRejected.fulfill()
        }
        await fulfillment(of: [secondPreviewRejected, clearRejected], timeout: 1)

        store.cancelPolicyPreview()
        XCTAssertEqual(store.cleanupMutationState, .committed)
        XCTAssertEqual(Set(try repository.loadRecent(limit: 10).map(\.id)), ["old", "new"])
    }

    func testClipboardPolicyFavoriteChangeWithSameDeleteCountRequiresReconfirmation() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ClipboardPolicyFavoriteStale.\(UUID().uuidString)", isDirectory: true)
        let database = try AppDatabase.open(environment: StorageEnvironment(rootDirectory: root))
        defer { database.close(); try? FileManager.default.removeItem(at: root) }
        let repository = ClipboardRepository(database: database)
        try insertClipboardCleanupFixture(repository, id: "old", timestamp: 10)
        try insertClipboardCleanupFixture(repository, id: "new", timestamp: 20)
        let store = ClipboardStore(repository: repository)
        var previewToken: ClipboardPolicyConfirmationToken?
        let previewed = expectation(description: "favorite-aware policy previewed")

        XCTAssertTrue(store.requestPolicyPreview(
            cleanupMode: .count,
            retentionPolicy: .days30,
            maxItems: 1,
            preserveFavorite: true
        ) { result in
            guard case let .preview(deleteCount, token) = result else {
                return XCTFail("Expected preview, got \(result)")
            }
            XCTAssertEqual(deleteCount, 1)
            previewToken = token
            previewed.fulfill()
        })
        await fulfillment(of: [previewed], timeout: 1)

        _ = try ClipboardTagRepository(repository: repository).toggleFavorite(recordID: "old")
        var replacementToken: ClipboardPolicyConfirmationToken?
        let stale = expectation(description: "same-count changed ID set is stale")
        store.confirmPolicyApplication(token: try XCTUnwrap(previewToken)) { result in
            guard case let .stale(deleteCount, token) = result else {
                return XCTFail("Expected stale plan, got \(result)")
            }
            XCTAssertEqual(deleteCount, 1)
            replacementToken = token
            stale.fulfill()
        }
        await fulfillment(of: [stale], timeout: 1)
        XCTAssertEqual(Set(try repository.loadRecent(limit: 10).map(\.id)), ["old", "new"])

        let committed = expectation(description: "replacement plan commits")
        store.confirmPolicyApplication(token: try XCTUnwrap(replacementToken)) { result in
            guard case .committed = result else {
                return XCTFail("Expected committed plan, got \(result)")
            }
            committed.fulfill()
        }
        await fulfillment(of: [committed], timeout: 1)
        XCTAssertEqual(try repository.loadRecent(limit: 10).map(\.id), ["old"])
    }

