    func testClipboardPolicyEmptyPreviewBecomesStaleBeforeAutomaticCommit() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ClipboardPolicyEmptyBecomesStale.\(UUID().uuidString)", isDirectory: true)
        let database = try AppDatabase.open(environment: StorageEnvironment(rootDirectory: root))
        defer { database.close(); try? FileManager.default.removeItem(at: root) }
        let repository = ClipboardRepository(database: database)
        try insertClipboardCleanupFixture(
            repository,
            id: "recent",
            timestamp: Date().timeIntervalSince1970
        )
        let mutationStarted = expectation(description: "automatic confirmed mutation started")
        let releaseMutation = DispatchSemaphore(value: 0)
        let store = ClipboardStore(
            repository: repository,
            cleanupMutationPipelineHooks: ClipboardCleanupMutationPipelineHooks(
                beforeMutation: { kind in
                    guard kind == .applyPolicy else { return }
                    mutationStarted.fulfill()
                    _ = releaseMutation.wait(timeout: .now() + 1)
                }
            )
        )
        let stale = expectation(description: "empty plan becomes stale")

        XCTAssertTrue(store.requestPolicyPreview(
            cleanupMode: .time,
            retentionPolicy: .days7,
            maxItems: 500,
            preserveFavorite: false
        ) { result in
            guard case let .stale(deleteCount, _) = result else {
                return XCTFail("Expected stale plan, got \(result)")
            }
            XCTAssertEqual(deleteCount, 1)
            stale.fulfill()
        })
        await fulfillment(of: [mutationStarted], timeout: 1)
        XCTAssertEqual(store.cleanupMutationState, .applying)

        let clearRejected = expectation(description: "clear rejected during automatic commit")
        store.requestClearUnfavorited { result in
            XCTAssertEqual(result, .rejectedWhileBusy)
            clearRejected.fulfill()
        }
        try insertClipboardCleanupFixture(repository, id: "expired", timestamp: 0)
        releaseMutation.signal()
        await fulfillment(of: [clearRejected, stale], timeout: 2)

        XCTAssertEqual(store.cleanupMutationState, .awaitingConfirmation)
        XCTAssertEqual(Set(try repository.loadRecent(limit: 10).map(\.id)), ["recent", "expired"])
        store.cancelPolicyPreview()
    }

    func testClipboardCleanupCoordinatorPublishesFailureWithoutPersistingRejectedPolicy() async throws {
        let keys = [
            "clipboard.policy.cleanupMode",
            "clipboard.policy.retention",
            "clipboard.policy.maxItems",
            "clipboard.policy.preserveFavorite",
        ]
        let defaults = UserDefaults.standard
        let originalValues = keys.reduce(into: [String: Any]()) { values, key in
            values[key] = defaults.object(forKey: key)
        }
        defer {
            for key in keys {
                if let value = originalValues[key] {
                    defaults.set(value, forKey: key)
                } else {
                    defaults.removeObject(forKey: key)
                }
            }
        }
        defaults.set(ClipboardCleanupMode.count.rawValue, forKey: keys[0])
        defaults.set(ClipboardRetentionPolicy.days30.rawValue, forKey: keys[1])
        defaults.set(500, forKey: keys[2])
        defaults.set(true, forKey: keys[3])

        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ClipboardCleanupCoordinator.\(UUID().uuidString)", isDirectory: true)
        let database = try AppDatabase.open(environment: StorageEnvironment(rootDirectory: root))
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let store = ClipboardStore(
            repository: ClipboardRepository(database: database),
            cleanupPolicyDebounce: .zero,
            cleanupMutationPipelineHooks: ClipboardCleanupMutationPipelineHooks(
                shouldFailMutation: { $0 == .applyPolicy }
            )
        )
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: store,
            privacyStore: PrivacyStore(repository: nil),
            featureAvailabilityStore: FeatureAvailabilityStore(defaults: testDefaults())
        )
        let completed = expectation(description: "coordinator reports rejected cleanup policy")

        XCTAssertTrue(coordinator.previewCleanupPolicy(
            cleanupMode: .time,
            retentionPolicy: .days7,
            maxItems: 1,
            preserveFavorite: false
        ) { result in
            XCTAssertEqual(result, .failed)
            completed.fulfill()
        })
        await fulfillment(of: [completed], timeout: 1)

        XCTAssertEqual(defaults.string(forKey: keys[0]), ClipboardCleanupMode.count.rawValue)
        XCTAssertEqual(defaults.string(forKey: keys[1]), ClipboardRetentionPolicy.days30.rawValue)
        XCTAssertEqual(defaults.integer(forKey: keys[2]), 500)
        XCTAssertTrue(defaults.bool(forKey: keys[3]))
    }

