        )
        XCTAssertTrue(events.allSatisfy { event in
            event.name == .clipboardRecordDeleted
                && event.payload["operation"] == .string("retention_policy")
        })
        XCTAssertEqual(Set(events.map(\.causationID)).count, 1)
        events.removeAll()

        let clearCompleted = expectation(description: "clear deletion event published")
