        try insertClipboardCleanupFixture(repository, id: "cleanup-active-1", timestamp: 5_013)
        let mutationStarted = expectation(description: "destructive cleanup started")
        let firstPublished = expectation(description: "started cleanup publishes its real result")
        let rejectedPublished = expectation(description: "rejected cleanup must not publish")
        rejectedPublished.isInverted = true
        let releaseMutation = DispatchSemaphore(value: 0)
        let store = ClipboardStore(
            repository: repository,
            cleanupPolicyDebounce: .zero,
            cleanupMutationPipelineHooks: ClipboardCleanupMutationPipelineHooks(
