    func testClipboardCaptureWaitsForCommittedCleanupPolicyAndSharedMutationQueue() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ClipboardCleanupCaptureOrder.\(UUID().uuidString)", isDirectory: true)
        let database = try AppDatabase.open(environment: StorageEnvironment(rootDirectory: root))
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        try insertClipboardCleanupFixture(repository, id: "capture-order-0", timestamp: 5_050)
        try insertClipboardCleanupFixture(repository, id: "capture-order-1", timestamp: 5_051)
        let policyStarted = expectation(description: "policy mutation started")
        let policyCompleted = expectation(description: "policy mutation completed")
        let releasePolicy = DispatchSemaphore(value: 0)
        let store = ClipboardStore(
            repository: repository,
            cleanupPolicyDebounce: .zero,
            cleanupMutationPipelineHooks: ClipboardCleanupMutationPipelineHooks(
                beforeMutation: { kind in
                    guard kind == .applyPolicy else { return }
                    policyStarted.fulfill()
                    releasePolicy.wait()
                }
            )
        )
        XCTAssertTrue(store.requestPolicyApplication(
            cleanupMode: .count,
            retentionPolicy: .days30,
            maxItems: 500,
            preserveFavorite: false
        ) { result, _ in
            XCTAssertEqual(result, .success(redactedCount: 0))
            policyCompleted.fulfill()
        })
        await fulfillment(of: [policyStarted], timeout: 1)

        let text = "capture after policy"
        let signature = String(repeating: "a", count: 64)
        let snapshot = ClipboardLiveCaptureSnapshot(
            record: ClipboardRecorderRecord(
                id: "capture-after-policy",
                createdAt: Date(timeIntervalSince1970: 5_052),
                changeCount: 5_052,
                kind: .text,
                formatSummary: .init(
                    itemCount: 1,
                    types: ["public.utf8-plain-text"],
                    textLength: text.count,
                    byteCount: text.utf8.count
                ),
                sourceApp: nil,
                signatureSHA256: signature,
                signatureSHA256_12: String(signature.prefix(12)),
                fixtureOwned: true,
                restorable: true,
                summary: text
            ),
            payload: .init(
                recordID: "capture-after-policy",
                kind: .text,
                text: text
            )
        )
        let captureTask = Task { @MainActor in
            return await store.ingestLiveCaptureAsync(
                snapshot,
                capturePolicy: ClipboardCapturePolicy(
                    paused: false,
                    privacyPolicyAvailable: true,
                    privacySnapshot: PrivacyPolicySnapshot()
                ),
                cleanupMode: .count,
                retentionPolicy: .days30,
                // Intentionally stale. The shared mutation queue must apply
                // the policy that committed ahead of this capture.
                maxItems: 1,
                preserveFavorite: false
            )
        }
        try await Task.sleep(for: .milliseconds(30))
        XCTAssertNil(try repository.loadRecord(recordID: "capture-after-policy"))

        releasePolicy.signal()
        await fulfillment(of: [policyCompleted], timeout: 2)
        let captureResult = await captureTask.value

        XCTAssertTrue(captureResult.succeeded)
        XCTAssertEqual(try repository.loadRecent(limit: 10).count, 3)
    }

    func testClipboardTagAndRecencyMutationsWaitForSharedBackgroundQueue() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ClipboardSharedMutationQueue.\(UUID().uuidString)", isDirectory: true)
        let database = try AppDatabase.open(environment: StorageEnvironment(rootDirectory: root))
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        try insertClipboardCleanupFixture(repository, id: "shared-mutation-record", timestamp: 5_059)
        let policyStarted = expectation(description: "policy occupies shared mutation queue")
        let policyCompleted = expectation(description: "policy releases shared mutation queue")
        let releasePolicy = DispatchSemaphore(value: 0)
        let executionProbe = ClipboardMutationExecutionProbe()
        let store = ClipboardStore(
            repository: repository,
            cleanupPolicyDebounce: .zero,
            cleanupMutationPipelineHooks: ClipboardCleanupMutationPipelineHooks(
                beforeMutation: { _ in
                    policyStarted.fulfill()
                    releasePolicy.wait()
                }
            ),
            recordMutationPipelineHooks: ClipboardRecordMutationPipelineHooks(
                beforeMutation: { kind in
                    executionProbe.record(kind: kind, onMainThread: Thread.isMainThread)
                }
            )
        )

        XCTAssertTrue(store.requestPolicyApplication(
            cleanupMode: .count,
            retentionPolicy: .days30,
            maxItems: 500,
            preserveFavorite: false
        ) { result, _ in
            XCTAssertEqual(result, .success(redactedCount: 0))
            policyCompleted.fulfill()
        })
        await fulfillment(of: [policyStarted], timeout: 1)

        let tagTask = Task { @MainActor in
            let result = await store.tagStore.createTag(displayName: "Shared Queue")
            executionProbe.markTagCompleted()
            return result
        }
        await Task.yield()
        let recencyTask = Task { @MainActor in
            await store.commitCopyEvent(
                recordID: "shared-mutation-record",
                source: .panelPaste,
                at: Date(timeIntervalSince1970: 6_000)
            )
        }

        try await Task.sleep(for: .milliseconds(40))
        XCTAssertFalse(executionProbe.tagCompleted)
        XCTAssertTrue(executionProbe.recordExecutions.isEmpty)

        releasePolicy.signal()
        await fulfillment(of: [policyCompleted], timeout: 2)
        let tagCreated = await tagTask.value
        XCTAssertTrue(tagCreated)
        let recency = await recencyTask.value
        XCTAssertTrue(recency.persisted)
        XCTAssertEqual(executionProbe.recordExecutions.map(\.kind), [.markCopied])
        XCTAssertEqual(executionProbe.recordExecutions.map(\.onMainThread), [false])
        XCTAssertTrue(store.tagStore.tags.contains { $0.displayName == "Shared Queue" })
    }

