        let releasePolicy = DispatchSemaphore(value: 0)
        let store = ClipboardStore(
            repository: repository,
            cleanupPolicyDebounce: .zero,
            cleanupMutationPipelineHooks: ClipboardCleanupMutationPipelineHooks(
                beforeMutation: { _ in
                    policyStarted.fulfill()
                    releasePolicy.wait()
                }
            )
        )
        XCTAssertTrue(store.loadRepositoryState(limit: 10))
        try await waitForClipboardRecords(store, expectedCount: 2)
        store.detailStore.open(recordID: "queued-detail-record")
        try await waitForClipboardDetail(store.detailStore) {
            $0.readModel?.recordID == "queued-detail-record" && !$0.isBusy
        }
        store.detailStore.beginEditing()
        try await waitForClipboardDetail(store.detailStore) {
            $0.status == .editClean
        }
        store.detailStore.updateDraft("detail queued replacement")

        XCTAssertTrue(store.requestPolicyApplication(
            cleanupMode: .count,
            retentionPolicy: .days30,
            maxItems: 500,
            preserveFavorite: false
        ) { result, _ in
            XCTAssertEqual(result, .success(redactedCount: 0))
            policyCompleted.fulfill()
        })
        await fulfillment(of: [policyStarted], timeout: 1)

        store.detailStore.save()
        let pluginUpdateTask = Task { @MainActor in
            try await store.updateRecordFromPlugin(
                recordID: "queued-plugin-record",
                customTitle: "Plugin queued title",
                text: nil,
                expectedContentRevision: 1
            )
        }
        try await Task.sleep(for: .milliseconds(40))
        XCTAssertEqual(store.detailStore.status, .saving)
        XCTAssertEqual(
            try repository.readDetailEditablePayload(
                recordID: "queued-detail-record",
                purpose: ClipboardPayloadReadPurpose.detailEditRead.rawValue
            )?.text,
            "cleanup fixture queued-detail-record"
        )
        XCTAssertFalse(
            try repository.loadDetailReadModel(recordID: "queued-plugin-record")
                .titleIsCustom
        )

        releasePolicy.signal()
        await fulfillment(of: [policyCompleted], timeout: 2)
        _ = try await pluginUpdateTask.value
        try await waitForClipboardDetail(store.detailStore) {
            ($0.status == .saveSuccess || $0.status == .savedIndexPending) && !$0.isBusy
        }
        XCTAssertEqual(
            try repository.readDetailEditablePayload(
                recordID: "queued-detail-record",
                purpose: ClipboardPayloadReadPurpose.detailEditRead.rawValue
            )?.text,
            "detail queued replacement"
        )
        XCTAssertEqual(
            try repository.loadDetailReadModel(recordID: "queued-plugin-record").title,
            "Plugin queued title"
        )
    }

