    func testClipboardCaptureWaitsForReplacementCleanupPolicyBeforeIngesting()
        async throws
    {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "ClipboardCleanupReplacementRace.\(UUID().uuidString)",
                isDirectory: true
            )
        let database = try AppDatabase.open(
            environment: StorageEnvironment(rootDirectory: root)
        )
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        try insertClipboardCleanupFixture(repository, id: "replacement-old-0", timestamp: 5_060)
        try insertClipboardCleanupFixture(repository, id: "replacement-old-1", timestamp: 5_061)
        let store = ClipboardStore(
            repository: repository,
            cleanupPolicyDebounce: .milliseconds(250)
        )
        XCTAssertTrue(store.loadRepositoryState(limit: 10))
        try await waitForClipboardRecords(store, expectedCount: 2)

        XCTAssertTrue(store.requestPolicyApplication(
            cleanupMode: .count,
            retentionPolicy: .days30,
            maxItems: 1,
            preserveFavorite: false
        ) { _, _ in
            XCTFail("The replaced policy must not publish or mutate records.")
        })
        XCTAssertEqual(store.cleanupMutationState, .policyPending)

        let text = "capture after replacement"
        let signature = String(repeating: "b", count: 64)
        let snapshot = ClipboardLiveCaptureSnapshot(
            record: ClipboardRecorderRecord(
                id: "replacement-capture",
                createdAt: Date(timeIntervalSince1970: 5_062),
                changeCount: 5_062,
                kind: .text,
                formatSummary: .init(
                    itemCount: 1,
                    types: ["public.utf8-plain-text"],
                    textLength: text.count,
                    byteCount: text.utf8.count
                ),
                sourceApp: nil,
                signatureSHA256: signature,
                signatureSHA256_12: String(signature.prefix(12)),
                fixtureOwned: true,
                restorable: true,
                summary: text
            ),
            payload: .init(recordID: "replacement-capture", kind: .text, text: text)
        )
        let captureTask = Task { @MainActor in
            await store.waitForCleanupMutationToSettle()
            return await store.ingestLiveCaptureAsync(
                snapshot,
                capturePolicy: ClipboardCapturePolicy(
                    paused: false,
                    privacyPolicyAvailable: true,
                    privacySnapshot: PrivacyPolicySnapshot()
                ),
                cleanupMode: .count,
                retentionPolicy: .days30,
                maxItems: 1,
                preserveFavorite: false
            )
        }
        await Task.yield()

        let replacementCompleted = expectation(
            description: "replacement cleanup policy completed"
        )
        XCTAssertTrue(store.requestPolicyApplication(
            cleanupMode: .count,
            retentionPolicy: .days30,
            maxItems: 500,
            preserveFavorite: false
        ) { result, _ in
            XCTAssertEqual(result, .success(redactedCount: 0))
            replacementCompleted.fulfill()
        })

        await fulfillment(of: [replacementCompleted], timeout: 2)
        let captureResult = await captureTask.value
        XCTAssertTrue(captureResult.succeeded)
        XCTAssertEqual(try repository.loadRecent(limit: 10).count, 3)
    }

    func testClipboardDisableInvalidatesQueuedCaptureBeforeInsert() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "ClipboardCaptureDisableRace.\(UUID().uuidString)",
                isDirectory: true
            )
        let database = try AppDatabase.open(
            environment: StorageEnvironment(rootDirectory: root)
        )
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        let captureQueued = expectation(description: "capture reaches before-insert gate")
        let currentCaptureQueued = expectation(
            description: "current capture reaches before-insert gate after invalidated capture"
        )
        let insertGate = OneShotDispatchSemaphoreGate()
        defer { insertGate.release() }
        let insertCount = ClipboardCleanupInvocationCounter()
        let store = ClipboardStore(
            repository: repository,
            capturePersistencePipelineHooks: ClipboardCapturePersistencePipelineHooks(
                beforeInsert: {
                    switch insertCount.increment() {
                    case 1:
                        captureQueued.fulfill()
                        insertGate.wait()
                    case 2:
                        currentCaptureQueued.fulfill()
                    default:
                        break
                    }
                }
            )
        )
        let privacyStore = PrivacyStore(
            repository: PrivacyPolicyRepository(database: database)
        )
        let availability = FeatureAvailabilityStore(defaults: testDefaults())
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: store,
            privacyStore: privacyStore,
            featureAvailabilityStore: availability
        )
        for _ in 0..<100 where !privacyStore.canCaptureClipboard {
            try await Task.sleep(for: .milliseconds(10))
        }
        XCTAssertTrue(privacyStore.canCaptureClipboard)

        func snapshot(
            id: String,
            text: String,
            changeCount: Int
        ) -> ClipboardLiveCaptureSnapshot {
            let signature = String(format: "%064d", changeCount)
            return ClipboardLiveCaptureSnapshot(
                record: ClipboardRecorderRecord(
                    id: id,
                    // Keep this race fixture inside the active retention
                    // window; a 1970 timestamp tests cleanup, not ownership.
                    createdAt: Date(),
                    changeCount: changeCount,
                    kind: .text,
                    formatSummary: .init(
                        itemCount: 1,
                        types: ["public.utf8-plain-text"],
                        textLength: text.count,
                        byteCount: text.utf8.count
                    ),
                    sourceApp: nil,
                    signatureSHA256: signature,
                    signatureSHA256_12: String(signature.prefix(12)),
                    fixtureOwned: true,
                    restorable: true,
                    summary: text
                ),
                payload: .init(recordID: id, kind: .text, text: text)
            )
        }

        let invalidatedID = "disable-race-invalidated"
        coordinator.ingestLiveCapture(
            snapshot(id: invalidatedID, text: "must not persist", changeCount: 5_070)
        )
        await fulfillment(of: [captureQueued], timeout: 1)

        availability.setClipboardEnabled(false)
        coordinator.disableRuntime()

        XCTAssertNil(try repository.loadRecord(recordID: invalidatedID))
        XCTAssertNil(try repository.readPayload(recordID: invalidatedID))

        // `beforeInsert` now runs inside the final privacy-admission critical
        // section. Release the invalidated transaction before asking the main
        // actor to obtain a token for its replacement; otherwise the fixture,
        // unlike production, holds the privacy lock while waiting on itself.
        insertGate.release()
        availability.setClipboardEnabled(true)
        let persistedID = "disable-race-current"
        coordinator.ingestLiveCapture(
            snapshot(id: persistedID, text: "must persist", changeCount: 5_071)
        )
        await fulfillment(of: [currentCaptureQueued], timeout: 1)

        XCTAssertNil(try repository.loadRecord(recordID: invalidatedID))
        XCTAssertNil(try repository.readPayload(recordID: invalidatedID))
        try await waitForClipboardRecords(store, containing: persistedID)

        XCTAssertNotNil(try repository.loadRecord(recordID: persistedID))
        XCTAssertEqual(try repository.readPayload(recordID: persistedID)?.text, "must persist")
    }

    func testClipboardDisableAfterCommittedCapturePublishesCommittedTruth() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "ClipboardCommittedCaptureDisableRace.\(UUID().uuidString)",
                isDirectory: true
            )
        let database = try AppDatabase.open(
            environment: StorageEnvironment(rootDirectory: root)
        )
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        let committed = expectation(description: "capture commits before continuation")
        let didPersist = expectation(description: "committed capture publishes once")
        let releaseContinuation = DispatchSemaphore(value: 0)
        let store = ClipboardStore(
            repository: repository,
            capturePersistencePipelineHooks: ClipboardCapturePersistencePipelineHooks(
                afterCommitBeforeContinuation: {
                    committed.fulfill()
                    releaseContinuation.wait()
                }
            )
        )
        let privacyStore = PrivacyStore(
            repository: PrivacyPolicyRepository(database: database)
        )
        let availability = FeatureAvailabilityStore(defaults: testDefaults())
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: store,
            privacyStore: privacyStore,
            featureAvailabilityStore: availability
        )
        var didPersistCount = 0
        var failedCount = 0
        coordinator.configure(
            statusRecorder: { _ in },
            sectionSelector: { _ in },
            closeTranslationPanel: {},
            translateRecord: { _ in },
            refreshPermissionState: {},
            dispatchPluginEvent: { envelope in
                switch envelope.name {
                case .clipboardDidPersistCapture:
                    didPersistCount += 1
                    didPersist.fulfill()
                case .clipboardCaptureFailed:
                    failedCount += 1
                default:
                    break
                }
                return .allowed(envelope)
            },
            stagePluginTextResource: { _, _, _, _ in nil },
            removePluginResources: { _ in },
            accessibilityGranted: { true },
            presentAccessibilityAssist: { _ in }
        )
        for _ in 0..<100 where !privacyStore.canCaptureClipboard {
            try await Task.sleep(for: .milliseconds(10))
        }
        XCTAssertTrue(privacyStore.canCaptureClipboard)

        let recordID = "committed-disable-race"
        let text = "committed capture survives cancellation"
        let signature = String(repeating: "c", count: 64)
        coordinator.ingestLiveCapture(
            ClipboardLiveCaptureSnapshot(
                record: ClipboardRecorderRecord(
                    id: recordID,
                    createdAt: Date(),
                    changeCount: 5_075,
                    kind: .text,
                    formatSummary: .init(
                        itemCount: 1,
                        types: ["public.utf8-plain-text"],
                        textLength: text.count,
                        byteCount: text.utf8.count
                    ),
                    sourceApp: nil,
                    signatureSHA256: signature,
                    signatureSHA256_12: String(signature.prefix(12)),
                    fixtureOwned: true,
                    restorable: true,
                    summary: text
                ),
                payload: .init(recordID: recordID, kind: .text, text: text)
            )
        )
        await fulfillment(of: [committed], timeout: 1)
        XCTAssertNotNil(try repository.loadRecord(recordID: recordID))

        availability.setClipboardEnabled(false)
        coordinator.disableRuntime()
        releaseContinuation.signal()

        await fulfillment(of: [didPersist], timeout: 1)
        XCTAssertEqual(didPersistCount, 1)
        XCTAssertEqual(failedCount, 0)
        try await waitForClipboardRecords(store, containing: recordID)
        XCTAssertEqual(
            store.records.first(where: { $0.id == recordID })?.summary,
            text
        )

        let reopenedStore = ClipboardStore(repository: repository)
        XCTAssertTrue(reopenedStore.loadRepositoryState(limit: 10))
        try await waitForClipboardRecords(reopenedStore, containing: recordID)
        XCTAssertEqual(
            reopenedStore.records.first(where: { $0.id == recordID })?.summary,
            text
        )
    }

    func testCancelledLiveCaptureCannotClearNewTaskOwnership() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "ClipboardCaptureTaskOwnership.\(UUID().uuidString)",
                isDirectory: true
            )
        let database = try AppDatabase.open(
            environment: StorageEnvironment(rootDirectory: root)
        )
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        let bReachedPersistence = expectation(description: "B reaches persistence")
        let releaseBPersistence = DispatchSemaphore(value: 0)
        let persistenceCount = ClipboardCleanupInvocationCounter()
        let store = ClipboardStore(
            repository: repository,
            capturePersistencePipelineHooks: ClipboardCapturePersistencePipelineHooks(
                beforeInsert: {
                    guard persistenceCount.increment() == 1 else { return }
                    bReachedPersistence.fulfill()
                    releaseBPersistence.wait()
                }
            )
        )
        let privacyStore = PrivacyStore(
            repository: PrivacyPolicyRepository(database: database)
        )
        let availability = FeatureAvailabilityStore(defaults: testDefaults())
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: store,
            privacyStore: privacyStore,
            featureAvailabilityStore: availability
        )
        let stageGate = ClipboardLiveCaptureStageGate()
        coordinator.configure(
            statusRecorder: { _ in },
            sectionSelector: { _ in },
            closeTranslationPanel: {},
            translateRecord: { _ in },
            refreshPermissionState: {},
            dispatchPluginEvent: { .allowed($0) },
            stagePluginTextResource: { text, _, _, _ in
                if text == "owner-A" || text == "owner-B" {
                    await stageGate.waitForRelease(of: text)
                } else {
                    await stageGate.recordStart(text)
                }
                return nil
            },
            removePluginResources: { _ in },
            accessibilityGranted: { true },
            presentAccessibilityAssist: { _ in }
        )
        for _ in 0..<100 where !privacyStore.canCaptureClipboard {
            try await Task.sleep(for: .milliseconds(10))
        }
        XCTAssertTrue(privacyStore.canCaptureClipboard)

        func snapshot(_ label: String, changeCount: Int) -> ClipboardLiveCaptureSnapshot {
            let signature = String(format: "%064d", changeCount)
            return ClipboardLiveCaptureSnapshot(
                record: ClipboardRecorderRecord(
                    id: label,
                    createdAt: Date(),
                    changeCount: changeCount,
                    kind: .text,
                    formatSummary: .init(
                        itemCount: 1,
                        types: ["public.utf8-plain-text"],
                        textLength: label.count,
                        byteCount: label.utf8.count
                    ),
                    sourceApp: nil,
                    signatureSHA256: signature,
                    signatureSHA256_12: String(signature.prefix(12)),
                    fixtureOwned: true,
                    restorable: true,
                    summary: label
                ),
                payload: .init(recordID: label, kind: .text, text: label)
            )
        }

        func waitForStage(_ label: String) async throws {
            for _ in 0..<100 where !(await stageGate.hasStarted(label)) {
                try await Task.sleep(for: .milliseconds(10))
            }
            let hasStarted = await stageGate.hasStarted(label)
            XCTAssertTrue(hasStarted)
        }

        func waitForPersistence(_ recordID: String) async throws {
            for _ in 0..<100 {
                if try repository.loadRecord(recordID: recordID) != nil {
                    return
                }
                try await Task.sleep(for: .milliseconds(10))
            }
            XCTFail("Timed out waiting for \(recordID) to persist")
        }

        coordinator.ingestLiveCapture(snapshot("owner-A", changeCount: 5_080))
        try await waitForStage("owner-A")

        availability.setClipboardEnabled(false)
        coordinator.disableRuntime()
        availability.setClipboardEnabled(true)

        coordinator.ingestLiveCapture(snapshot("owner-B", changeCount: 5_081))
        try await waitForStage("owner-B")
        await stageGate.release("owner-A")
        coordinator.ingestLiveCapture(snapshot("owner-C", changeCount: 5_082))
        try await Task.sleep(for: .milliseconds(30))

        let cStartedBeforeBPersistence = await stageGate.hasStarted("owner-C")
        XCTAssertFalse(
            cStartedBeforeBPersistence,
            "C must remain coalesced while B owns the live-capture task slot."
        )
        XCTAssertNil(try repository.loadRecord(recordID: "owner-C"))

        await stageGate.release("owner-B")
        await fulfillment(of: [bReachedPersistence], timeout: 1)
        let cStartedDuringBPersistence = await stageGate.hasStarted("owner-C")
        XCTAssertFalse(cStartedDuringBPersistence)
        XCTAssertNil(try repository.loadRecord(recordID: "owner-C"))

        releaseBPersistence.signal()
        try await waitForPersistence("owner-B")
        try await waitForStage("owner-C")
        try await waitForPersistence("owner-C")

        XCTAssertNil(try repository.loadRecord(recordID: "owner-A"))
        XCTAssertNotNil(try repository.loadRecord(recordID: "owner-B"))
        XCTAssertNotNil(try repository.loadRecord(recordID: "owner-C"))
    }

