    func testExternalCopyWinsOneHundredInterleavedPasteTransactions() async throws {
        for iteration in 0..<100 {
            let token = UUID()
            var state = ClipboardPasteTransactionState()
            let generation = state.begin(token: token)
            let pasteboard = ScriptedClipboardPasteboard(
                items: [],
                changeCount: 1_000 + iteration * 2,
                writeOutcomes: [true, true]
            )
            let writer = ClipboardPasteboardWriter(
                pasteboard: pasteboard,
                changeSuppressor: ClipboardPasteboardChangeSuppressor()
            )
            let writeLease = try await writer.write(payload: ClipboardRecorderPayload(
                recordID: "transaction-\(iteration)",
                kind: .text,
                text: "fixture"
            ))
            XCTAssertTrue(pasteboard.writeItems([
                ClipboardPasteboardWriteItem(representations: [.string: .string("external-fixture")])
            ]))
            let externalCopyChangeCount = pasteboard.changeCount

            XCTAssertNotEqual(writeLease.changeCount, externalCopyChangeCount)
            XCTAssertTrue(state.isCurrent(generation: generation, token: token))
            state.invalidate()
            XCTAssertFalse(state.isCurrent(generation: generation, token: token))
        }
    }

