    func testActionBrokerEmbeddedServiceValidatorRequiresPlistAndExecutable() throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ActionBrokerEmbeddedServiceValidatorTests.\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        let launchAgents = root.appendingPathComponent("Contents/Library/LaunchAgents", isDirectory: true)
        let executables = root.appendingPathComponent("Contents/MacOS", isDirectory: true)
        try FileManager.default.createDirectory(at: launchAgents, withIntermediateDirectories: true)
        try FileManager.default.createDirectory(at: executables, withIntermediateDirectories: true)
        let plist: [String: Any] = [
            "Label": BlocksActionBrokerXPC.launchAgentLabel,
            "BundleProgram": "Contents/MacOS/BlocksActionBroker",
            "MachServices": [BlocksActionBrokerXPC.machServiceName: true],
        ]
        let plistData = try PropertyListSerialization.data(
            fromPropertyList: plist,
            format: .xml,
            options: 0
        )
        try plistData.write(
            to: launchAgents.appendingPathComponent(BlocksActionBrokerXPC.launchAgentPlistName)
        )
        let executable = executables.appendingPathComponent("BlocksActionBroker")
        try Data("fixture".utf8).write(to: executable)
        try FileManager.default.setAttributes([.posixPermissions: 0o700], ofItemAtPath: executable.path)

        XCTAssertTrue(ActionBrokerEmbeddedServiceValidator(bundleURL: root).isAvailable())
        try FileManager.default.removeItem(at: executable)
        XCTAssertFalse(ActionBrokerEmbeddedServiceValidator(bundleURL: root).isAvailable())
    }

