    func testActionBrokerHostLifecycleRejectsStaleCallbacksAndStopsListener() {
        let lifecycle = ActionBrokerHostConnectionLifecycle()
        let firstConnection = lifecycle.beginConnection()
        let firstGeneration = firstConnection.generation
        XCTAssertTrue(firstConnection.shouldResumeListener)
        XCTAssertTrue(lifecycle.isListenerResumed)
        XCTAssertTrue(lifecycle.claimCompletion(for: firstGeneration))

        let secondConnection = lifecycle.beginConnection()
        let secondGeneration = secondConnection.generation
        XCTAssertFalse(secondConnection.shouldResumeListener)
        XCTAssertTrue(lifecycle.isListenerResumed)
        XCTAssertFalse(lifecycle.isCurrent(firstGeneration))
        XCTAssertFalse(lifecycle.claimCompletion(for: firstGeneration))
        XCTAssertTrue(lifecycle.claimCompletion(for: secondGeneration))

        XCTAssertTrue(lifecycle.stop())
        XCTAssertFalse(lifecycle.isListenerResumed)
        XCTAssertFalse(lifecycle.isCurrent(secondGeneration))
        XCTAssertFalse(lifecycle.stop())
    }

