    func testCLIUpdateRejectsSameDigestReplacementAtInstallCommitBoundary() async throws {
        let root = try makeCLITemporaryDirectory()
        defer { try? FileManager.default.removeItem(at: root) }
        let source = root.appendingPathComponent("source")
        let destination = root.appendingPathComponent("blocks")
        try Data("v1".utf8).write(to: source)

        let initialController = makeCLIController(source: source)
        await initialController.install(
            sourceURL: source,
            destinationURL: destination
        )
        let previousRecord = try XCTUnwrap(
            defaults.data(
                forKey: BlocksCLIInstallationController.recordKey
            )
        )
        let initialIdentity = try XCTUnwrap(
            BlocksCLIFileIdentity.resourceIdentifier(of: destination)
        )

        try Data("v2".utf8).write(to: source)
        let commitGate = CLIInstallCommitGate()
        let controller = makeCLIController(
            source: source,
            beforeInstallCommit: { commitGate.waitBeforeCommit() }
        )
        let installTask = Task { @MainActor in
            await controller.install(
                sourceURL: source,
                destinationURL: destination
            )
        }
        await commitGate.waitUntilBlocked()

        let replacement = root.appendingPathComponent("replacement")
        try Data("v1".utf8).write(to: replacement)
        try FileManager.default.removeItem(at: destination)
        try FileManager.default.moveItem(at: replacement, to: destination)
        XCTAssertNotEqual(
            initialIdentity,
            BlocksCLIFileIdentity.resourceIdentifier(of: destination)
        )

        commitGate.resume()
        await installTask.value

        XCTAssertEqual(controller.state, .destinationConflict)
        XCTAssertEqual(try Data(contentsOf: destination), Data("v1".utf8))
        XCTAssertEqual(
            defaults.data(forKey: BlocksCLIInstallationController.recordKey),
            previousRecord
        )
    }

