    func testCLIUpdateUsesStableDirectoryScopeAndPostSwapFileBookmark() async throws {
        let root = try makeCLITemporaryDirectory()
        defer { try? FileManager.default.removeItem(at: root) }
        let source = root.appendingPathComponent("source")
        let destination = root.appendingPathComponent("blocks")
        try Data("v1".utf8).write(to: source)
        let followingBookmarks = CLIIdentityFollowingBookmarkAccess()
        let controller = makeCLIController(
            source: source,
            bookmarkAccess: followingBookmarks.access
        )
        await controller.install(
            sourceURL: source,
            destinationURL: destination
        )
        XCTAssertEqual(controller.state, .installedCurrent)

        try Data("v2".utf8).write(to: source)
        await controller.install(
            sourceURL: source,
            destinationURL: destination
        )
        XCTAssertEqual(controller.state, .installedCurrent)
        let recordData = try XCTUnwrap(
            defaults.data(forKey: BlocksCLIInstallationController.recordKey)
        )
        let record = try JSONDecoder().decode(
            BlocksCLIInstallationRecord.self,
            from: recordData
        )
        XCTAssertNotNil(record.directorySecurityScopedBookmark)
        let resolvedFileBookmark = try XCTUnwrap(
            followingBookmarks.access.resolve(record.securityScopedBookmark)
        )
        XCTAssertEqual(
            BlocksCLIFileIdentity.resourceIdentifier(of: resolvedFileBookmark),
            record.installedFileIdentity
        )
        XCTAssertEqual(resolvedFileBookmark.standardizedFileURL, destination)
        let displacedRecoveryURL = try XCTUnwrap(controller.recoveryURL)
        XCTAssertEqual(
            try Data(contentsOf: displacedRecoveryURL),
            Data("v1".utf8)
        )
        XCTAssertNil(defaults.data(
            forKey: BlocksCLIInstallationController.operationJournalKey
        ))
        XCTAssertNil(defaults.data(
            forKey: BlocksCLIInstallationController.recoveryBookmarkKey
        ))

        let recreated = makeCLIController(
            source: source,
            bookmarkAccess: followingBookmarks.access
        )
        recreated.refresh()
        await waitForCLIState(recreated, .installedCurrent)
        let refreshedRecordData = try XCTUnwrap(
            defaults.data(forKey: BlocksCLIInstallationController.recordKey)
        )
        let refreshedRecord = try JSONDecoder().decode(
            BlocksCLIInstallationRecord.self,
            from: refreshedRecordData
        )
        let preservedArtifacts = try XCTUnwrap(
            refreshedRecord.preservedCleanupArtifacts
        )
        XCTAssertEqual(preservedArtifacts.count, 1)
        XCTAssertEqual(
            preservedArtifacts.first?.expectedSHA256,
            BlocksCLIFileDigest.sha256(of: displacedRecoveryURL)
        )

        try Data("v3".utf8).write(to: source)
        await recreated.install(
            sourceURL: source,
            destinationURL: destination
        )
        XCTAssertEqual(recreated.state, .installedCurrent)
        let secondUpdateRecordData = try XCTUnwrap(
            defaults.data(forKey: BlocksCLIInstallationController.recordKey)
        )
        let secondUpdateRecord = try JSONDecoder().decode(
            BlocksCLIInstallationRecord.self,
            from: secondUpdateRecordData
        )
        let allPreservedArtifacts = try XCTUnwrap(
            secondUpdateRecord.preservedCleanupArtifacts
        )
        XCTAssertEqual(allPreservedArtifacts.count, 2)
        XCTAssertEqual(
            allPreservedArtifacts.map(\.expectedSHA256),
            [
                BlocksCLIFileDigest.sha256(of: displacedRecoveryURL),
                BlocksCLIFileDigest.sha256(of: try XCTUnwrap(recreated.recoveryURL))
            ]
        )
        recreated.uninstall()
        await waitForCLIState(recreated, .recoveryRequired)
        XCTAssertFalse(FileManager.default.fileExists(atPath: destination.path))
        let recoveryURL = try XCTUnwrap(recreated.recoveryURL)
        XCTAssertEqual(try Data(contentsOf: recoveryURL), Data("v3".utf8))
        XCTAssertNotNil(defaults.data(forKey: BlocksCLIInstallationController.recordKey))
        XCTAssertNotNil(defaults.data(forKey: BlocksCLIInstallationController.operationJournalKey))
    }

