    func testCLIRecordSaveRollbackPreservesRecoveryWhenDestinationChangesAfterSwap() async throws {
        let root = try makeCLITemporaryDirectory()
        defer { try? FileManager.default.removeItem(at: root) }
        let source = root.appendingPathComponent("source")
        let destination = root.appendingPathComponent("blocks")
        try Data("v1".utf8).write(to: source)
        let initialController = makeCLIController(source: source)
        await initialController.install(
            sourceURL: source,
            destinationURL: destination
        )
        let previousRecord = try XCTUnwrap(
            defaults.data(forKey: BlocksCLIInstallationController.recordKey)
        )

        try Data("v2".utf8).write(to: source)
        let restoreGate = CLIInstallCommitGate()
        let replacement = root.appendingPathComponent("replacement")
        try Data("later-file".utf8).write(to: replacement)
        let controller = makeCLIController(
            source: source,
            recordSaver: { _ in false },
            beforeRestoreCommit: { restoreGate.waitBeforeCommit() },
            afterRestoreSwap: { recoveryDestination in
                try? FileManager.default.removeItem(at: recoveryDestination)
                try? FileManager.default.moveItem(at: replacement, to: recoveryDestination)
            }
        )
        let task = Task { @MainActor in
            await controller.install(
                sourceURL: source,
                destinationURL: destination
            )
        }
        await restoreGate.waitUntilBlocked()

        restoreGate.resume()
        await task.value

        XCTAssertEqual(controller.state, .recoveryRequired)
        XCTAssertEqual(try Data(contentsOf: destination), Data("later-file".utf8))
        let recoveryURL = try XCTUnwrap(controller.recoveryURL)
        XCTAssertEqual(
            try Data(contentsOf: recoveryURL),
            Data("v2".utf8)
        )
        XCTAssertEqual(
            defaults.data(forKey: BlocksCLIInstallationController.recordKey),
            previousRecord
        )
    }

