        try Data("v2".utf8).write(to: displacedNew)
        let oldIdentity = try XCTUnwrap(
            BlocksCLIFileIdentity.resourceIdentifier(of: destination)
        )
        let oldDigest = try XCTUnwrap(BlocksCLIFileDigest.sha256(of: destination))
        let newIdentity = try XCTUnwrap(
            BlocksCLIFileIdentity.resourceIdentifier(of: displacedNew)
        )
        let newDigest = try XCTUnwrap(BlocksCLIFileDigest.sha256(of: displacedNew))
        let oldRecord = BlocksCLIInstallationRecord(
            securityScopedBookmark: Data(destination.path.utf8),
            directorySecurityScopedBookmark: Data(root.path.utf8),
            installedSHA256: oldDigest,
            installedFileIdentity: oldIdentity,
            appVersion: "test",
            displayPath: destination.path
        )
        let oldRecordData = try JSONEncoder().encode(oldRecord)
        defaults.set(
            oldRecordData,
            forKey: BlocksCLIInstallationController.recordKey
        )
        let targetRecord = BlocksCLIInstallationRecord(
            securityScopedBookmark: Data(destination.path.utf8),
            directorySecurityScopedBookmark: Data(root.path.utf8),
            installedSHA256: newDigest,
            installedFileIdentity: newIdentity,
            appVersion: "test",
            displayPath: destination.path
        )
        let journal = BlocksCLIOperationJournal(
            kind: .install,
            destinationBookmark: Data(destination.path.utf8),
            destinationDirectoryBookmark: Data(root.path.utf8),
            recoveryBookmark: nil,
            recoveryPath: displacedNew.path,
            displayPath: destination.path,
            expectedOldIdentity: oldIdentity,
            expectedOldDigest: oldDigest,
            expectedNewIdentity: newIdentity,
            expectedNewDigest: newDigest,
            targetRecord: try JSONEncoder().encode(targetRecord),
            previousRecord: oldRecordData
        )
        let journalData = try JSONEncoder().encode(journal)
        defaults.set(
            journalData,
            forKey: BlocksCLIInstallationController.operationJournalKey
        )

        let recreated = makeCLIController(source: source)
        recreated.refresh()
        await waitForCLIState(recreated, .recoveryRequired)

        XCTAssertEqual(
            BlocksCLIFileIdentity.resourceIdentifier(of: destination),
            oldIdentity
        )
        XCTAssertEqual(try Data(contentsOf: displacedNew), Data("v2".utf8))
        XCTAssertEqual(recreated.recoveryURL, displacedNew)
        XCTAssertEqual(
            defaults.data(forKey: BlocksCLIInstallationController.recordKey),
            oldRecordData
        )
        XCTAssertEqual(
            defaults.data(
                forKey: BlocksCLIInstallationController.operationJournalKey
            ),
            journalData
        )
    }

    func testCLIDurableRecordAndJournalStoresPersistAndMigrateOwnerOnlyFiles() throws {
        let root = try makeCLITemporaryDirectory()
        defer { try? FileManager.default.removeItem(at: root) }
        let suiteName = "BlocksCLIStoreTests.\(UUID().uuidString)"
        let isolatedDefaults = try XCTUnwrap(UserDefaults(suiteName: suiteName))
        defer { isolatedDefaults.removePersistentDomain(forName: suiteName) }
        let stateDirectory = root
            .appendingPathComponent("Blocks", isDirectory: true)
            .appendingPathComponent("State", isDirectory: true)
        let recordURL = stateDirectory.appendingPathComponent("record.json")
        let journalURL = stateDirectory.appendingPathComponent("journal.json")
        let recordStore = BlocksCLIInstallationRecordStore.durable(
            fileURL: recordURL,
            defaults: isolatedDefaults,
            key: "legacy.record"
        )
        let journalStore = BlocksCLIOperationJournalStore.durable(
            fileURL: journalURL,
            defaults: isolatedDefaults,
            key: "legacy.journal"
        )
        let recordData = Data("record".utf8)
        let legacyJournalData = Data("journal".utf8)

        XCTAssertTrue(recordStore.save(recordData))
        XCTAssertEqual(recordStore.load(), recordData)
        isolatedDefaults.set(legacyJournalData, forKey: "legacy.journal")
        XCTAssertEqual(journalStore.load(), .readable(legacyJournalData))
        XCTAssertNil(isolatedDefaults.data(forKey: "legacy.journal"))

        for url in [recordURL, journalURL] {
            let attributes = try FileManager.default.attributesOfItem(
                atPath: url.path
            )
            let permissions = try XCTUnwrap(
                attributes[.posixPermissions] as? NSNumber
            ).intValue
            XCTAssertEqual(permissions & 0o777, 0o600)
        }

        XCTAssertTrue(recordStore.clear())
        XCTAssertTrue(journalStore.clear())
        XCTAssertFalse(FileManager.default.fileExists(atPath: recordURL.path))
        XCTAssertFalse(FileManager.default.fileExists(atPath: journalURL.path))
    }

    func testCLIDurableRecordFailedStagingSyncPreservesPreviousRecord() throws {
        let root = try makeCLITemporaryDirectory()
        defer { try? FileManager.default.removeItem(at: root) }
        let suiteName = "BlocksCLIRecordFailureTests.\(UUID().uuidString)"
        let isolatedDefaults = try XCTUnwrap(UserDefaults(suiteName: suiteName))
