        let recordURL = root.appendingPathComponent("record.json")
        let initialStore = BlocksCLIInstallationRecordStore.durable(
            fileURL: recordURL,
            defaults: isolatedDefaults,
            key: "legacy.record"
        )
        let previousRecord = Data("previous-record".utf8)
        XCTAssertTrue(initialStore.save(previousRecord))

        let failingStore = BlocksCLIInstallationRecordStore.durable(
            fileURL: recordURL,
            defaults: isolatedDefaults,
            key: "legacy.record",
