    func testCLIMutationLeaseAndPendingJournalBlockCompetingController() async throws {
        let root = try makeCLITemporaryDirectory()
        defer { try? FileManager.default.removeItem(at: root) }
        let source = root.appendingPathComponent("source")
        let destination = root.appendingPathComponent("blocks")
        let lockURL = root.appendingPathComponent("operation.lock")
        try Data("v1".utf8).write(to: source)

        let firstLease = try XCTUnwrap(
            BlocksCLIInstallationOperationLease.acquire(at: lockURL)
        )
        XCTAssertNil(
            BlocksCLIInstallationOperationLease.acquire(at: lockURL),
            "A second controller must not enter the CLI mutation transaction."
        )
        firstLease.release()
        let replacementLease = try XCTUnwrap(
            BlocksCLIInstallationOperationLease.acquire(at: lockURL)
        )
        replacementLease.release()

        let pendingJournal = try JSONEncoder().encode(
            BlocksCLIOperationJournal(
                kind: .install,
                destinationBookmark: Data(destination.path.utf8),
                destinationDirectoryBookmark: Data(root.path.utf8),
                recoveryBookmark: nil,
                recoveryPath: nil,
                displayPath: destination.path,
                expectedOldIdentity: nil,
                expectedOldDigest: nil,
                expectedNewIdentity: Data(repeating: 1, count: 24),
                expectedNewDigest: "pending",
                targetRecord: nil
            )
        )
        defaults.set(
            pendingJournal,
            forKey: BlocksCLIInstallationController.operationJournalKey
        )
        let competing = makeCLIController(source: source)

        await competing.install(
            sourceURL: source,
            destinationURL: destination
        )

        XCTAssertEqual(competing.state, .recoveryRequired)
        XCTAssertEqual(
            defaults.data(
                forKey: BlocksCLIInstallationController.operationJournalKey
            ),
            pendingJournal
        )
        XCTAssertFalse(FileManager.default.fileExists(atPath: destination.path))
    }

    func testCLIJournalRecoveryRejectsConcurrentInstallRefreshAndUninstall() async throws {
        let root = try makeCLITemporaryDirectory()
        defer { try? FileManager.default.removeItem(at: root) }
        let source = root.appendingPathComponent("source")
        let destination = root.appendingPathComponent("blocks")
        let quarantine = root.appendingPathComponent(".blocks-uninstall-pending")
        try Data("v1".utf8).write(to: source)
        try Data("v1".utf8).write(to: quarantine)
        let identity = try XCTUnwrap(
            BlocksCLIFileIdentity.resourceIdentifier(of: quarantine)
        )
        let digest = try XCTUnwrap(BlocksCLIFileDigest.sha256(of: quarantine))
        let record = BlocksCLIInstallationRecord(
            securityScopedBookmark: Data(destination.path.utf8),
            directorySecurityScopedBookmark: Data(root.path.utf8),
            installedSHA256: digest,
            installedFileIdentity: identity,
            appVersion: "test",
            displayPath: destination.path
        )
        let recordData = try JSONEncoder().encode(record)
        defaults.set(
            recordData,
            forKey: BlocksCLIInstallationController.recordKey
        )
        let journalData = try JSONEncoder().encode(BlocksCLIOperationJournal(
            kind: .uninstall,
            destinationBookmark: Data(destination.path.utf8),
            destinationDirectoryBookmark: Data(root.path.utf8),
            recoveryBookmark: nil,
            recoveryPath: quarantine.path,
            displayPath: destination.path,
            expectedOldIdentity: identity,
            expectedOldDigest: digest,
            expectedNewIdentity: nil,
            expectedNewDigest: nil,
            targetRecord: recordData
        ))
        defaults.set(
            journalData,
            forKey: BlocksCLIInstallationController.operationJournalKey
        )
        let gate = CLIJournalRecoveryGate()
        let controller = makeCLIController(
            source: source,
            beforeJournalRecovery: { await gate.waitBeforeRecovery() }
        )

        controller.refresh()
        await gate.waitUntilBlocked()
        XCTAssertTrue(controller.isRecovering)
        XCTAssertTrue(controller.isBusy)
        XCTAssertFalse(controller.canInstall)
        XCTAssertFalse(controller.canUninstall)

        await controller.install(
            sourceURL: source,
            destinationURL: destination
        )
        controller.refresh()
        controller.uninstall()
        XCTAssertEqual(
            defaults.data(
                forKey: BlocksCLIInstallationController.operationJournalKey
            ),
            journalData
        )
        XCTAssertTrue(FileManager.default.fileExists(atPath: quarantine.path))

        await gate.resume()
        await waitForCLIState(controller, .recoveryRequired)
        XCTAssertFalse(controller.isRecovering)
        XCTAssertEqual(try Data(contentsOf: quarantine), Data("v1".utf8))
        XCTAssertEqual(controller.recoveryURL, quarantine)
        XCTAssertEqual(defaults.data(forKey: BlocksCLIInstallationController.recordKey), recordData)
        XCTAssertEqual(defaults.data(forKey: BlocksCLIInstallationController.operationJournalKey), journalData)
    }

