        XCTAssertNotNil(defaults.data(forKey: BlocksCLIInstallationController.operationJournalKey))
    }

    func testCLIOperationLeaseAcquireAndReleaseRunOffMainActor() async throws {
        let root = try makeCLITemporaryDirectory()
        defer { try? FileManager.default.removeItem(at: root) }
        let source = root.appendingPathComponent("source")
        let destination = root.appendingPathComponent("blocks")
        let lockURL = root.appendingPathComponent("operation.lock")
        try Data("v1".utf8).write(to: source)
        let probe = CLILeaseThreadProbe()
        let baseProvider = BlocksCLIOperationLeaseProvider.file(lockURL)
        let provider = BlocksCLIOperationLeaseProvider(
            acquire: {
                probe.recordAcquire()
                return baseProvider.acquire()
            },
            didRelease: {
                probe.recordRelease()
            }
        )
        let controller = makeCLIController(
            source: source,
            operationLeaseProvider: provider
        )

        await controller.install(
            sourceURL: source,
            destinationURL: destination
        )

        XCTAssertEqual(controller.state, .installedCurrent)
        XCTAssertEqual(probe.acquireCount, 1)
        XCTAssertEqual(probe.releaseCount, 1)
        XCTAssertFalse(probe.acquireWasCalledOnMainThread)
        XCTAssertFalse(probe.releaseWasCalledOnMainThread)
    }

    func testCLIUninstallPreventsRefreshAndInstallFromReplacingItsLateRefreshCompletion() async throws {
        let root = try makeCLITemporaryDirectory()
        defer { try? FileManager.default.removeItem(at: root) }
        let source = root.appendingPathComponent("source")
        let destination = root.appendingPathComponent("blocks")
        try Data("v1".utf8).write(to: source)

        let initialController = makeCLIController(source: source)
        await initialController.install(sourceURL: source, destinationURL: destination)
        XCTAssertNotNil(defaults.data(forKey: BlocksCLIInstallationController.recordKey))
        defaults.set(Data("legacy-bookmark".utf8), forKey: BlocksCLIInstallationController.bookmarkKey)

        let refreshProbe = CLIRefreshDigestProbe(blockedURL: source)
        let uninstallCommitGate = CLIUninstallCommitGate()
        let controller = makeCLIController(
            source: source,
            digest: refreshProbe.digest,
            beforeUninstallCommit: { await uninstallCommitGate.waitBeforeCommit() }
        )
        controller.refresh()
        await refreshProbe.waitUntilBlocked()

        controller.uninstall()
        refreshProbe.resume()
        await uninstallCommitGate.waitUntilBlocked()
        XCTAssertEqual(controller.state, .uninstalling)

        controller.refresh()
        await controller.install(sourceURL: source, destinationURL: destination)
        XCTAssertEqual(controller.state, .uninstalling)
        XCTAssertTrue(FileManager.default.fileExists(atPath: destination.path))
        XCTAssertNotNil(defaults.data(forKey: BlocksCLIInstallationController.recordKey))
        XCTAssertNotNil(defaults.data(forKey: BlocksCLIInstallationController.bookmarkKey))

        await uninstallCommitGate.resume()
        await waitForCLIState(controller, .recoveryRequired)

        XCTAssertFalse(FileManager.default.fileExists(atPath: destination.path))
        let recoveryURL = try XCTUnwrap(controller.recoveryURL)
        XCTAssertEqual(try Data(contentsOf: recoveryURL), Data("v1".utf8))
        XCTAssertNotNil(defaults.data(forKey: BlocksCLIInstallationController.recordKey))
        XCTAssertNotNil(defaults.data(forKey: BlocksCLIInstallationController.bookmarkKey))
        XCTAssertNotNil(defaults.data(forKey: BlocksCLIInstallationController.operationJournalKey))
    }

    func testCLIUninstallRejectsSameDigestReplacementAtCommitBoundary() async throws {
        let root = try makeCLITemporaryDirectory()
        defer { try? FileManager.default.removeItem(at: root) }
        let source = root.appendingPathComponent("source")
        let destination = root.appendingPathComponent("blocks")
        try Data("managed-command".utf8).write(to: source)
        let initialController = makeCLIController(source: source)
        await initialController.install(
            sourceURL: source,
            destinationURL: destination
        )
        let initialIdentity = try XCTUnwrap(
            BlocksCLIFileIdentity.resourceIdentifier(of: destination)
        )
        let uninstallCommitGate = CLIUninstallCommitGate()
        let controller = makeCLIController(
            source: source,
            beforeUninstallCommit: {
                await uninstallCommitGate.waitBeforeCommit()
            }
        )

        controller.uninstall()
        await uninstallCommitGate.waitUntilBlocked()

        let replacement = root.appendingPathComponent("replacement")
        try Data("managed-command".utf8).write(to: replacement)
        try FileManager.default.removeItem(at: destination)
        try FileManager.default.moveItem(at: replacement, to: destination)
        let replacementIdentity = try XCTUnwrap(
            BlocksCLIFileIdentity.resourceIdentifier(of: destination)
        )
        XCTAssertNotEqual(initialIdentity, replacementIdentity)

        await uninstallCommitGate.resume()
        await waitForCLIState(controller, .changed)

        XCTAssertTrue(FileManager.default.fileExists(atPath: destination.path))
        XCTAssertEqual(
            try Data(contentsOf: destination),
            Data("managed-command".utf8)
        )
        XCTAssertNotNil(
            defaults.data(forKey: BlocksCLIInstallationController.recordKey)
        )
    }

    func testCLIUninstallRestoresReplacementMadeAfterFinalValidation() async throws {
        let root = try makeCLITemporaryDirectory()
        defer { try? FileManager.default.removeItem(at: root) }
        let source = root.appendingPathComponent("source")
        let destination = root.appendingPathComponent("blocks")
        let replacement = root.appendingPathComponent("replacement")
        try Data("managed-command".utf8).write(to: source)
        try Data("later-file".utf8).write(to: replacement)
        let initialController = makeCLIController(source: source)
        await initialController.install(sourceURL: source, destinationURL: destination)

        let controller = makeCLIController(
            source: source,
            beforeUninstallRename: {
                try? FileManager.default.removeItem(at: destination)
                try? FileManager.default.moveItem(at: replacement, to: destination)
            }
        )
        controller.uninstall()
        await waitForCLIState(controller, .changed)

        XCTAssertEqual(try Data(contentsOf: destination), Data("later-file".utf8))
        XCTAssertNotNil(defaults.data(forKey: BlocksCLIInstallationController.recordKey))
    }

    private func makeCLIController(
        source: URL,
        bookmarkAccess: BlocksCLIInstallationBookmarkAccess? = nil,
        digest: @escaping (URL) -> String? = BlocksCLIFileDigest.sha256,
        recordEncoder: @escaping (BlocksCLIInstallationRecord) throws -> Data = { try JSONEncoder().encode($0) },
        recordSaver: (@Sendable (Data) -> Bool)? = nil,
        installationRecordStore: BlocksCLIInstallationRecordStore? = nil,
        operationJournalStore: BlocksCLIOperationJournalStore? = nil,
        journalSaver: (@Sendable (Data) -> Bool)? = nil,
        beforeJournalRecovery: @escaping @Sendable () async -> Void = {},
        beforeInstallCommit: @escaping @Sendable () -> Void = {},
        beforeRestoreCommit: @escaping @Sendable () -> Void = {},
        afterRestoreSwap: @escaping @Sendable (URL) -> Void = { _ in },
        beforeUninstallCommit: @escaping @Sendable () async -> Void = {},
        beforeUninstallRename: @escaping @Sendable () -> Void = {},
        operationLeaseProvider: BlocksCLIOperationLeaseProvider? = nil
    ) -> BlocksCLIInstallationController {
        let defaultBookmarks = BlocksCLIInstallationBookmarkAccess(
            make: { Data($0.path.utf8) },
            resolve: { data in
                String(data: data, encoding: .utf8).map(URL.init(fileURLWithPath:))
            },
            start: { _ in true },
            stop: { _ in }
        )
        return BlocksCLIInstallationController(
            defaults: defaults,
            digest: digest,
            bookmarkAccess: bookmarkAccess ?? defaultBookmarks,
            sourceURLProvider: { source },
            recordEncoder: recordEncoder,
            installationRecordStore: installationRecordStore ?? .defaults(
                defaults,
                key: BlocksCLIInstallationController.recordKey,
                saveOverride: recordSaver
            ),
            operationJournalStore: operationJournalStore ?? .defaults(
                defaults,
                key: BlocksCLIInstallationController.operationJournalKey,
                saveOverride: journalSaver
            ),
            operationLeaseProvider: operationLeaseProvider ?? .file(
                source.deletingLastPathComponent()
                    .appendingPathComponent(".agent-cli-operation.lock")
            ),
            beforeJournalRecovery: beforeJournalRecovery,
            beforeInstallCommit: beforeInstallCommit,
            beforeRestoreCommit: beforeRestoreCommit,
            afterRestoreSwap: afterRestoreSwap,
            beforeUninstallCommit: beforeUninstallCommit,
            beforeUninstallRename: beforeUninstallRename
        )
    }

    private func makeCLITemporaryDirectory() throws -> URL {
        let root = FileManager.default.temporaryDirectory.appendingPathComponent(
            "BlocksCLIInstallationTests.\(UUID().uuidString)",
            isDirectory: true
        )
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        return root
    }

    private func waitForCLIState(
        _ controller: BlocksCLIInstallationController,
        _ expected: BlocksCLIInstallationState,
        timeout: Duration = .seconds(2)
    ) async {
        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: timeout)
        while clock.now < deadline {
            if controller.state == expected { return }
            try? await Task.sleep(for: .milliseconds(5))
        }
        XCTFail(
            "Timed out waiting for CLI state: \(expected); "
                + "current state: \(controller.state)"
        )
    }

    private func waitForCLIOperationJournalToClear() async {
        for _ in 0..<200 {
            if defaults.data(forKey: BlocksCLIInstallationController.operationJournalKey) == nil {
                return
            }
            try? await Task.sleep(for: .milliseconds(5))
        }
        XCTFail("Timed out waiting for CLI operation journal to clear")
    }

