    func testCancellingMagnifierStylePreviewRestoresCommittedPixelsBeforeNextSession() async throws {
        let store = try makeMagnifierStore(sourceSize: 500)
        _ = store.beginGesture(at: CGPoint(x: 250, y: 250), modifiers: [])
        store.endGesture(at: CGPoint(x: 250, y: 250), modifiers: [])
        try await waitForEditorRender(store)
        try await Task.sleep(for: .milliseconds(80))
        let originalSnapshot = store.document.snapshot
        let originalAppearance = try XCTUnwrap(store.selectedElement?.appearance)

        store.beginStyleEditing()
        var firstPreview = store.activeStyle
        firstPreview.effectIntensity = 5
        store.updateSelectedStyle(firstPreview)
        XCTAssertEqual(store.selectedElement?.appearance.effectIntensity, 5)
        try await waitForEditorRender(store)

        store.cancelStyleEditing()
        try await waitForEditorRender(store)
        XCTAssertEqual(store.document.snapshot, originalSnapshot)
        XCTAssertEqual(store.selectedElement?.appearance, originalAppearance)

        // Start another effect edit immediately after cancellation. A stale
        // completion from the first session must not become this session's base.
        store.beginStyleEditing()
        var secondPreview = store.activeStyle
        secondPreview.effectIntensity = 3
        store.updateSelectedStyle(secondPreview)
        XCTAssertEqual(store.selectedElement?.appearance.effectIntensity, 3)
        store.cancelStyleEditing()
        try await waitForEditorRender(store)

        let expected = try ScreenshotRenderer().render(
            sourceContext: store.document.sourceContext,
            snapshot: store.document.snapshot
        )
        let actual = try XCTUnwrap(store.renderedImage.cgImage(
            forProposedRect: nil,
            context: nil,
            hints: nil
        ))
        let encoder = ScreenshotImageEncoder()
        XCTAssertEqual(try encoder.pngData(actual), try encoder.pngData(expected))
        XCTAssertNil(store.interactionBaseImage)
    }

    func testRapidMagnifierStyleUpdatesCoalesceToFirstAndLatestPreviewFrames() async throws {
        let store = try makeMagnifierStore(sourceSize: 500)
        _ = store.beginGesture(at: CGPoint(x: 250, y: 250), modifiers: [])
        store.endGesture(at: CGPoint(x: 250, y: 250), modifiers: [])
        try await waitForEditorRender(store)
        try await Task.sleep(for: .milliseconds(80))
        store.beginStyleEditing()
        let submissions = store.renderSubmissionCount

        for zoom in [2.2, 2.8, 3.4, 4.1, 5.0] {
            var preview = store.activeStyle
            preview.effectIntensity = zoom
            store.updateSelectedStyle(preview)
        }

        XCTAssertEqual(store.renderSubmissionCount, submissions + 1)
        try await waitForEditorRender(store)
        XCTAssertEqual(store.renderSubmissionCount, submissions + 2)
        XCTAssertEqual(store.selectedElement?.appearance.effectIntensity, 5)
        store.cancelStyleEditing()
        try await waitForEditorRender(store)
    }

