    func testEditorChromeTracksTheCropInsideTheReservedCanvasArea() {
        let frames = ScreenshotEditorCropChromeLayout.resolve(
            availableSize: CGSize(width: 1_200, height: 800),
            sourceRect: .init(x: 0, y: 0, width: 1_200, height: 800),
            cropRect: .init(x: 200, y: 200, width: 600, height: 300),
            zoomScale: 1,
            panOffset: .zero,
            statusWidth: 180,
            toolbarWidth: 620
        )

        XCTAssertEqual(frames.canvas, CGRect(x: 0, y: 0, width: 1_200, height: 800))
        XCTAssertEqual(frames.crop, CGRect(x: 200, y: 200, width: 600, height: 300))
        XCTAssertEqual(frames.status.maxY + ScreenshotEditorChromeMetrics.cropGap, frames.crop.minY)
        XCTAssertEqual(frames.toolbar.minY, frames.crop.maxY + ScreenshotEditorChromeMetrics.cropGap)
        XCTAssertEqual(frames.status.width, 180)
        XCTAssertEqual(frames.toolbar.width, 620)
        XCTAssertEqual(frames.status.midX, frames.toolbar.midX)
        XCTAssertEqual(frames.status.midX, frames.crop.midX)
    }

