            toolbarWidth: 620
        )

        XCTAssertEqual(frames.canvas.minY, ScreenshotEditorChromeMetrics.canvasTopInset)
        XCTAssertEqual(
            frames.canvas.maxY,
            800 - ScreenshotEditorChromeMetrics.canvasBottomInset
        )
        XCTAssertEqual(
            frames.status.maxY + ScreenshotEditorChromeMetrics.cropGap,
            frames.crop.minY
        )
        XCTAssertEqual(
            frames.toolbar.minY,
            frames.crop.maxY + ScreenshotEditorChromeMetrics.cropGap
        )
        XCTAssertFalse(frames.status.intersects(frames.crop))
        XCTAssertFalse(frames.toolbar.intersects(frames.crop))
    }

