    func testScrollingHUDKeepsCommandsInStableSemanticSlots() {
        let ready = ScrollingScreenshotHUDPresentation(state: .init(phase: .ready))
        let capturing = ScrollingScreenshotHUDPresentation(state: .init(phase: .capturing))
        let paused = ScrollingScreenshotHUDPresentation(state: .init(phase: .paused))

        XCTAssertEqual(ready.command(in: .primary), .start)
        XCTAssertEqual(capturing.command(in: .primary), .pause)
        XCTAssertEqual(paused.command(in: .primary), .resume)
        XCTAssertEqual(ready.command(in: .secondary), .reselect)
        XCTAssertEqual(capturing.command(in: .secondary), .restart)
        XCTAssertNil(ready.command(in: .finish))
        XCTAssertEqual(capturing.command(in: .finish), .finish)
        XCTAssertEqual(ready.command(in: .cancel), .cancel)
        XCTAssertEqual(capturing.command(in: .cancel), .cancel)
    }

    func testScrollingHUDFocusPolicyPreservesCancelAcrossNonFocusStateChanges() {
        let capturing = scrollingHUDFocusConfiguration(
            state: .init(phase: .capturing, accumulatedHeight: 1_200)
        )
        let tallerCapture = scrollingHUDFocusConfiguration(
            state: .init(phase: .capturing, accumulatedHeight: 2_400)
        )
        let warningCapture = scrollingHUDFocusConfiguration(
            state: .init(
                phase: .capturing,
                accumulatedHeight: 2_400,
                warning: "Capture height is large"
            )
        )

        XCTAssertEqual(capturing, tallerCapture)
        XCTAssertEqual(capturing, warningCapture)
        XCTAssertNil(
            ScrollingScreenshotHUDFocusPolicy.focusAfterConfigurationChange(
                currentFocus: nil,
                configuration: tallerCapture
            )
        )
        XCTAssertEqual(
            ScrollingScreenshotHUDFocusPolicy.focusAfterConfigurationChange(
                currentFocus: .cancel,
                configuration: tallerCapture
            ),
            .cancel
        )
        XCTAssertEqual(
            ScrollingScreenshotHUDFocusPolicy.focusAfterConfigurationChange(
                currentFocus: .cancel,
                configuration: warningCapture
            ),
            .cancel
        )
    }

    func testScrollingHUDFocusPolicyPreservesStillEnabledCommandAcrossPhaseChange() {
        let capturing = scrollingHUDFocusConfiguration(state: .init(phase: .capturing))
        let recovering = scrollingHUDFocusConfiguration(state: .init(phase: .recovering))

        XCTAssertNotEqual(capturing, recovering)
        XCTAssertEqual(
            ScrollingScreenshotHUDFocusPolicy.focusAfterConfigurationChange(
                currentFocus: .cancel,
                configuration: recovering
            ),
            .cancel
        )
    }

    func testScrollingHUDFocusPolicyMovesDisabledFocusToFirstEnabledCommand() {
        let recovering = scrollingHUDFocusConfiguration(state: .init(phase: .recovering))

        XCTAssertEqual(
            ScrollingScreenshotHUDFocusPolicy.focusAfterConfigurationChange(
                currentFocus: .finish,
                configuration: recovering
            ),
            .restart
        )
    }

    func testScrollingHUDFocusPolicyUsesAccentForInitialFocusAndNilWhenAllDisabled() {
        let capturing = scrollingHUDFocusConfiguration(state: .init(phase: .capturing))
        let allDisabled = ScrollingScreenshotHUDFocusPolicy.Configuration(
            presentation: ScrollingScreenshotHUDPresentation(state: .init(phase: .capturing)),
            disabledCommands: Set(ScreenshotScrollingCommand.allCases)
        )

        XCTAssertEqual(ScrollingScreenshotHUDFocusPolicy.initialFocus(for: capturing), .finish)
        XCTAssertNil(ScrollingScreenshotHUDFocusPolicy.initialFocus(for: allDisabled))
        XCTAssertNil(
            ScrollingScreenshotHUDFocusPolicy.focusAfterConfigurationChange(
                currentFocus: .finish,
                configuration: allDisabled
            )
        )
    }

    private func scrollingHUDFocusConfiguration(
        state: ScrollingScreenshotHUDState
    ) -> ScrollingScreenshotHUDFocusPolicy.Configuration {
        let presentation = ScrollingScreenshotHUDPresentation(state: state)
        return ScrollingScreenshotHUDFocusPolicy.Configuration(
            presentation: presentation,
            disabledCommands: presentation.disabledCommands
        )
    }

    func testEditorCanvasUsesAUniformSemanticBackdropInsteadOfAFullCanvasCheckerboard() throws {
        for appearanceName in [NSAppearance.Name.aqua, .darkAqua] {
            let view = ScreenshotEditorCanvasView(frame: CGRect(x: 0, y: 0, width: 72, height: 48))
            view.appearance = NSAppearance(named: appearanceName)
            guard let bitmap = view.bitmapImageRepForCachingDisplay(in: view.bounds) else {
                return XCTFail("Expected a bitmap representation")
            }
            view.cacheDisplay(in: view.bounds, to: bitmap)
            let first = try XCTUnwrap(bitmap.colorAt(x: 6, y: 6)?.usingColorSpace(.deviceRGB))
            let second = try XCTUnwrap(bitmap.colorAt(x: 30, y: 18)?.usingColorSpace(.deviceRGB))
            XCTAssertEqual(first.redComponent, second.redComponent, accuracy: 0.001)
            XCTAssertEqual(first.greenComponent, second.greenComponent, accuracy: 0.001)
            XCTAssertEqual(first.blueComponent, second.blueComponent, accuracy: 0.001)
            XCTAssertEqual(first.alphaComponent, 1, accuracy: 0.001)
        }
    }

