    func testManualOCRPanelFlipsAcrossFourVisibleQuadrantsAndClamps() {
        let visibleBounds = CGRect(x: 0, y: 0, width: 800, height: 600)
        let panelSize = ScreenshotDesignTokens.ocrPanelSize
        let anchors = [
            CGRect(x: 20, y: 20, width: 40, height: 40),
            CGRect(x: 740, y: 20, width: 40, height: 40),
            CGRect(x: 20, y: 540, width: 40, height: 40),
            CGRect(x: 740, y: 540, width: 40, height: 40),
        ]
        let frames = anchors.map {
            ScreenshotFloatingPanelLayout.frame(
                anchorFrame: $0,
                panelSize: panelSize,
                visibleBounds: visibleBounds
            )
        }
        let safeBounds = visibleBounds.insetBy(
            dx: BlocksVisualTokens.Spacing.md,
            dy: BlocksVisualTokens.Spacing.md
        )

        XCTAssertTrue(frames.allSatisfy(safeBounds.contains))
        XCTAssertGreaterThan(frames[0].minY, anchors[0].maxY)
        XCTAssertGreaterThan(frames[1].minY, anchors[1].maxY)
        XCTAssertLessThan(frames[2].maxY, anchors[2].minY)
        XCTAssertLessThan(frames[3].maxY, anchors[3].minY)
        XCTAssertEqual(frames[0].minX, anchors[0].minX, accuracy: 0.001)
        XCTAssertEqual(frames[1].maxX, anchors[1].maxX, accuracy: 0.001)
    }

