    }

    func testPreferencesPersistSharedOrderAndAlwaysVisibleToolZones() {
        let store = ScreenshotPreferencesStore(userDefaults: defaults)
        XCTAssertEqual(store.preferences.toolOrder.first, .select)
        XCTAssertFalse(store.preferences.toolOrder.contains(.aspectRatio))

        _ = store.moveTool(.text, to: .quick, before: .arrow)
        _ = store.moveTool(.ellipse, to: .hidden, before: nil)
        _ = store.moveTool(.highlight, to: .expanded, before: nil)

        let restored = ScreenshotPreferencesStore(userDefaults: defaults)
        XCTAssertLessThan(
            restored.preferences.toolOrder.firstIndex(of: .text)!,
            restored.preferences.toolOrder.firstIndex(of: .arrow)!
        )
        XCTAssertFalse(restored.preferences.visibleExtendedToolbarItemIDs.contains(.ellipse))
        XCTAssertEqual(restored.preferences.toolOrder.first, .select)
        XCTAssertFalse(restored.preferences.toolOrder.contains(.aspectRatio))
        XCTAssertLessThan(
            restored.preferences.visibleQuickToolbarItemIDs.firstIndex(of: .text)!,
            restored.preferences.visibleQuickToolbarItemIDs.firstIndex(of: .arrow)!
        )
        XCTAssertTrue(restored.preferences.visibleExtendedToolbarItemIDs.contains(.highlight))
    }

