    func testEditorHostPanelLetsFocusedControlConsumeEscapeLocally() throws {
        final class LocalEscapeView: NSView, ScreenshotEditorLocalEscapeHandling {
            var localEscapeCount = 0

            override var acceptsFirstResponder: Bool { true }

            func handleEditorEscape() -> Bool {
                localEscapeCount += 1
                return true
            }
        }

        let panel = ScreenshotEditorHostPanel(
            contentRect: CGRect(x: 0, y: 0, width: 640, height: 480)
        )
        let control = LocalEscapeView()
        panel.contentView = control
        panel.makeFirstResponder(control)
        var globalEscapeCount = 0
        panel.onEscape = { globalEscapeCount += 1 }

        panel.sendEvent(try keyEvent(keyCode: 53))

        XCTAssertEqual(control.localEscapeCount, 1)
        XCTAssertEqual(globalEscapeCount, 0)
    }

