    func testEditorCanvasReportsTheFirstCompleteDrawOnlyOnce() async throws {
        let canvas = ScreenshotEditorCanvasView(
            frame: CGRect(x: 0, y: 0, width: 160, height: 120)
        )
        canvas.image = NSImage(
            cgImage: solidImage(width: 160, height: 120, color: .white),
            size: NSSize(width: 160, height: 120)
        )
        canvas.visibleSourceRect = .init(x: 0, y: 0, width: 160, height: 120)
        canvas.cropRect = canvas.visibleSourceRect
        let firstFrame = expectation(description: "first canvas frame")
        var callbackCount = 0
        let bitmap = try XCTUnwrap(
            canvas.bitmapImageRepForCachingDisplay(in: canvas.bounds)
        )

        canvas.onFirstFrameRendered = nil
        canvas.cacheDisplay(in: canvas.bounds, to: bitmap)
        canvas.onFirstFrameRendered = {
            callbackCount += 1
            firstFrame.fulfill()
        }
        canvas.cacheDisplay(in: canvas.bounds, to: bitmap)
        canvas.cacheDisplay(in: canvas.bounds, to: bitmap)
        await fulfillment(of: [firstFrame], timeout: 1)

        XCTAssertEqual(callbackCount, 1)
    }

