    func testReplacingVisibleEditorDoesNotRestoreSupersededApplicationContext() async throws {
        let preferences = ScreenshotPreferencesStore(userDefaults: defaults)
        let presenter = ScreenshotEditorPresenter(preferencesStore: preferences)
        var restorationCount = 0
        let store = ScreenshotStore(
            captureService: CaptureServiceStub(capture: makeCapture()),
            editorPresenter: presenter,
            preferencesStore: preferences,
            applicationContextSuspender: {
                ScreenshotApplicationContextRestorer { restorationCount += 1 }
            },
            permissionRefresher: {},
            permissionSnapshotProvider: { self.grantedPermissionSnapshot() }
        )

        let firstStart = await store.startSmartScreenshot()
        XCTAssertEqual(firstStart, .completed)
        XCTAssertEqual(restorationCount, 0)

        let secondStart = await store.startSmartScreenshot()
        XCTAssertEqual(secondStart, .completed)
        for _ in 0..<4 { await Task.yield() }
        XCTAssertEqual(restorationCount, 0)

        presenter.cancelCurrentSession()
        for _ in 0..<20 where restorationCount == 0 { await Task.yield() }
        XCTAssertEqual(restorationCount, 1)
    }

    func testScreenshotPluginMutationsRequireUserInitiatedOrigin() async throws {
        let preferences = ScreenshotPreferencesStore(userDefaults: defaults)
        var savePanelPresentationCount = 0
        let saveWriter = ScreenshotSaveWriterProbe()
        let presenter = ScreenshotEditorPresenter(
            preferencesStore: preferences,
            outputCoordinatorFactory: {
                preferencesStore,
                presentationWindow,
                serializationGate in
                ScreenshotEditorOutputCoordinator(
                    preferencesStore: preferencesStore,
                    fileWriter: { data, url in try saveWriter.write(data, to: url) },
                    presentationWindow: presentationWindow,
                    serializationGate: serializationGate,
                    savePanelPresenter: { _, _ in
                        savePanelPresentationCount += 1
                        return .cancel
                    }
                )
            }
        )
        let pasteboard = FinalizedArtifactPasteboardWriterSpy()
        let archive = FinalizedArtifactArchiveWriterSpy()
        let store = ScreenshotStore(
            captureService: CaptureServiceStub(capture: makeCapture()),
            editorPresenter: presenter,
            preferencesStore: preferences,
            pasteboardWriter: pasteboard,
            archiveWriter: archive,
            permissionRefresher: {},
            permissionSnapshotProvider: { self.grantedPermissionSnapshot() }
        )

        let startResult = await store.startSmartScreenshot()
        XCTAssertEqual(startResult, .completed)
        let editor = try XCTUnwrap(presenter.editorStoreForTesting)
        try await waitForEditorRender(editor)
        let originalElementCount = editor.document.presentedSnapshot.elements.count

        for origin in [
            BlocksPluginHostInvocationOrigin.background,
            BlocksPluginHostInvocationOrigin.scheduled,
        ] {
            do {
                _ = try await store.performPluginHostAction(
                    "screenshot.annotation.add_text",
                    origin: origin,
                    input: ["text": .string("blocked")]
                )
                XCTFail("A non-user-initiated plugin mutation must be rejected")
            } catch let error as BlocksPluginRuntimeError {
                guard case let .invalidHostOperation(operation) = error else {
                    return XCTFail("Unexpected plugin error: \(error)")
                }
                XCTAssertEqual(
                    operation,
                    "screenshot.annotation.add_text.requires_user_initiated"
                )
            }
            XCTAssertEqual(
                editor.document.presentedSnapshot.elements.count,
                originalElementCount
            )

            for actionID in [
                "screenshot.output.copy",
                "screenshot.output.save",
                "screenshot.output.pin",
                "screenshot.output.complete",
            ] {
                do {
                    _ = try await store.performPluginHostAction(
                        actionID,
                        origin: origin,
                        input: [:]
                    )
                    XCTFail(
                        "A non-user-initiated plugin output must be rejected: \(actionID)"
                    )
                } catch let error as BlocksPluginRuntimeError {
                    guard case let .invalidHostOperation(operation) = error else {
                        return XCTFail("Unexpected plugin error: \(error)")
                    }
                    XCTAssertEqual(
                        operation,
                        "\(actionID).requires_user_initiated"
                    )
                }
                XCTAssertTrue(presenter.editorStoreForTesting === editor)
                XCTAssertNil(pasteboard.artifact)
                XCTAssertNil(archive.artifact)
                XCTAssertFalse(editor.isOutputPending)
            }
            XCTAssertEqual(savePanelPresentationCount, 0)
            XCTAssertEqual(saveWriter.writeCount, 0)
        }

        _ = try await store.performPluginHostAction(
            "screenshot.annotation.add_text",
            origin: .explicitUser,
            input: ["text": .string("allowed")]
        )
        XCTAssertEqual(
            editor.document.presentedSnapshot.elements.count,
            originalElementCount + 1
        )

        _ = try await store.performPluginHostAction(
            "screenshot.document.snapshot",
            origin: .background,
            input: [:]
        )
        presenter.cancelCurrentSession()
    }

