    func testScreenshotPluginCopyWaitsForWriterAndSerializesFinalOutput() async throws {
        let preferences = ScreenshotPreferencesStore(userDefaults: defaults)
        let gate = ScreenshotOutputSerialGate()
        let writer = SuspendedScreenshotPasteboardWriter()
        let outputCoordinator = ScreenshotEditorOutputCoordinator(
            preferencesStore: preferences,
            pasteboardWriter: writer,
            serializationGate: gate
        )
        let editor = try ScreenshotEditorStore(
            capture: makeCapture(),
            preferencesStore: preferences,
            onComplete: { _ in },
            onRetake: {},
            onClose: {},
            outputCoordinator: outputCoordinator
        )
        try await waitForEditorRender(editor)

        var copyResult: ScreenshotEditorOutputExecutionResult?
        let copyTask = Task { @MainActor in
            let result = await editor.copyCurrentAwaitingCompletion()
            copyResult = result
            return result
        }
        await writer.waitUntilStarted()
        XCTAssertNil(copyResult)

        let archive = ScreenshotArchiveWriterSpy()
        let finalOutput = ScreenshotFinalOutputCoordinator(
            preferencesStore: preferences,
            pasteboardWriter: ScreenshotPasteboardWriterSpy(),
            archiveWriter: archive,
            serializationGate: gate
        )
        let capture = makeCapture()
        let finalTask = Task { @MainActor in
            await finalOutput.finalize(
                capture: capture,
                image: capture.image,
                writesPasteboard: false
            )
        }
        for _ in 0..<20 { await Task.yield() }
        XCTAssertEqual(archive.writeCount, 0)

        writer.resume(with: .success(ClipboardPasteboardWriteLease(changeCount: 1)))
        let completedCopyResult = await copyTask.value
        XCTAssertEqual(completedCopyResult, .succeeded)
        let finalResult = await finalTask.value

        XCTAssertEqual(copyResult, .succeeded)
        XCTAssertEqual(finalResult.archive, .succeeded)
        XCTAssertEqual(archive.writeCount, 1)
    }

