    func testFinalOutputRevocationAfterCommittedPasteboardSkipsArchiveAsNotRequested() async throws {
        let preferences = ScreenshotPreferencesStore(userDefaults: defaults)
        let pasteboardCommitted = expectation(description: "pasteboard durable commit")
        let writer = GatedFinalizedArtifactPasteboardWriter(
            onDurableCommit: { pasteboardCommitted.fulfill() }
        )
        defer { writer.resume() }
        let archive = ScreenshotArchiveWriterSpy()
        let coordinator = ScreenshotFinalOutputCoordinator(
            preferencesStore: preferences,
            pasteboardWriter: writer,
            archiveWriter: archive
        )
        let capture = makeCapture()
        var isCurrent = true
        var eventNames: [BlocksPluginEventName] = []
        coordinator.configurePluginPlatform(
            dispatchPluginEvent: { envelope in
                eventNames.append(envelope.name)
                return .allowed(envelope)
            },
            registerResource: { _, _, _, _ in nil },
            removeResources: { _ in }
        )
        let finalization = Task { @MainActor in
            await coordinator.finalize(
                capture: capture,
                image: capture.image,
                writesPasteboard: true,
                isCurrent: { isCurrent }
            )
        }
        await fulfillment(of: [pasteboardCommitted], timeout: 1)
        isCurrent = false
        writer.resume()
        let result = try await waitForTask(
            finalization,
            description: "pasteboard-revocation finalization returned"
        )

        XCTAssertFalse(result.isCancelled)
        XCTAssertEqual(result.pasteboard, .succeeded)
        XCTAssertEqual(result.archive, .notRequested)
        XCTAssertEqual(writer.writeCount, 1)
        XCTAssertEqual(archive.writeCount, 0)
        XCTAssertEqual(eventNames, [.screenshotWillFinalizeOutput])
    }

