    func testScreenshotPluginSaveLateOKAfterShutdownDoesNotWriteFile() async throws {
        let preferences = ScreenshotPreferencesStore(userDefaults: defaults)
        let host = ScreenshotEditorPresenter.makeHostPanel(
            frame: CGRect(x: 0, y: 0, width: 320, height: 240)
        )
        host.animationBehavior = .none
        defer {
            host.orderOut(nil)
            host.close()
        }
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ScreenshotSaveCancellation-\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        let destination = root.appendingPathComponent("existing.png")
        let originalData = Data("original".utf8)
        try originalData.write(to: destination)

        let panelStarted = expectation(description: "save panel started")
        var panelContinuation: CheckedContinuation<ScreenshotEditorOutputCoordinator.SavePanelResult, Never>?
        let writer = ScreenshotSaveWriterProbe()
        let outputCoordinator = ScreenshotEditorOutputCoordinator(
            preferencesStore: preferences,
            fileWriter: { data, url in try writer.write(data, to: url) },
            presentationWindow: { host },
            savePanelPresenter: { _, _ in
                panelStarted.fulfill()
                return await withCheckedContinuation { panelContinuation = $0 }
            }
        )
        let editor = try ScreenshotEditorStore(
            capture: makeCapture(),
            preferencesStore: preferences,
            onComplete: { _ in },
            onRetake: {},
            onClose: {},
            outputCoordinator: outputCoordinator
        )
        try await waitForEditorRender(editor)

        let saveTask = Task { @MainActor in
            await editor.saveCurrentAwaitingCompletion()
        }
        await fulfillment(of: [panelStarted], timeout: 2)

        editor.shutdown()
        let result = await saveTask.value
        XCTAssertEqual(result, .cancelled)

        panelContinuation?.resume(returning: .ok(destination))
        for _ in 0..<100 {
            await Task.yield()
        }

        XCTAssertEqual(writer.writeCount, 0)
        XCTAssertEqual(try Data(contentsOf: destination), originalData)
    }

