    func testScreenshotPluginCompleteReturnsCommittedTruthAfterRuntimeRevocation()
        async throws
    {
        var enabled = true
        let preferences = ScreenshotPreferencesStore(userDefaults: defaults)
        let presenter = ScreenshotEditorPresenter(preferencesStore: preferences)
        let archiveCommitted = expectation(description: "host archive durable commit")
        let archive = GatedFinalizedArtifactArchiveWriter(
            pauseAfterDurableCommit: true,
            onReachedPause: { archiveCommitted.fulfill() }
        )
        let pasteboard = FinalizedArtifactPasteboardWriterSpy()
        let store = ScreenshotStore(
            captureService: CaptureServiceStub(capture: makeCapture()),
            editorPresenter: presenter,
            preferencesStore: preferences,
            pasteboardWriter: pasteboard,
            archiveWriter: archive,
            featureEnabled: { enabled },
            permissionRefresher: {},
            permissionSnapshotProvider: { self.grantedPermissionSnapshot() }
        )
        var terminalEvents: [BlocksPluginEventName] = []
        var lateStatuses: [AppStatus] = []
        store.configureCoordinator(
            statusRecorder: { lateStatuses.append($0) },
            retakeHandler: { _ in },
            dispatchPluginEvent: { envelope in
                terminalEvents.append(envelope.name)
                return .allowed(envelope)
            }
        )
        defer {
            archive.resume()
            presenter.cancelCurrentSession()
        }

        let startResult = await store.startSmartScreenshot()
        XCTAssertEqual(startResult, .completed)
        let editor = try XCTUnwrap(presenter.editorStoreForTesting)
        try await waitForEditorRender(editor)
        terminalEvents.removeAll()
        lateStatuses.removeAll()

        let hostAction = Task { @MainActor in
            try await store.performPluginHostAction(
                "screenshot.output.complete",
                origin: .explicitUser,
                input: [:]
            )
        }
        defer { hostAction.cancel() }
        await fulfillment(of: [archiveCommitted], timeout: 1)
        enabled = false
        store.disableRuntime()
        archive.resume()
        let hostResult = try await waitForTask(
            hostAction,
            description: "revoked host completion returned"
        )

        XCTAssertEqual(hostResult, .bool(true))
        XCTAssertEqual(pasteboard.artifact?.captureID, "fixture")
        XCTAssertEqual(archive.archiveCount, 1)
        XCTAssertEqual(terminalEvents, [.screenshotWillFinalizeOutput])
        XCTAssertTrue(lateStatuses.isEmpty)
    }

