            statusRecorder: { _ in },
            retakeHandler: { _ in },
            dispatchPluginEvent: { envelope in
                terminalEvents.append(envelope.name)
                return .allowed(envelope)
            }
        )
        defer {
            captureService.resumeFinish()
            presenter.cancelCurrentSession()
        }

        let startResult = await screenshotStore.startSmartScreenshot()
