        )
        XCTAssertFalse(cancelResult.cancelled)
        captureService.resumeFinish()
        let cleanupSettled = expectation(description: "cancelled scrolling completion settled")
        Task { @MainActor in
            let clock = ContinuousClock()
            let deadline = clock.now.advanced(by: .seconds(1))
            while (presenter.editorPanelForTesting != nil
                || presenter.reportedFinalOutputResultCountForTesting != 0)
                && clock.now < deadline
            {
                try? await Task.sleep(for: .milliseconds(5))
            }
            cleanupSettled.fulfill()
        }
