        XCTAssertNil(presenter.editorPanelForTesting)
        XCTAssertNil(pasteboard.artifact)
        XCTAssertNil(archive.artifact)
        XCTAssertFalse(terminalEvents.contains(.screenshotOutputFinished))
        XCTAssertFalse(terminalEvents.contains(.screenshotOutputFailed))
        XCTAssertEqual(presenter.reportedFinalOutputResultCountForTesting, 0)
    }

