    func testGUIOldSaveTaskCannotPresentSaveSheetOnReplacementEditor() async throws {
        let preferences = ScreenshotPreferencesStore(userDefaults: defaults)
        let processor = SuspendedScreenshotOutputImageProcessorProbe(suspends: true)
        var presentationWindows: [NSWindow] = []
        let presenter = ScreenshotEditorPresenter(
