            outputCoordinatorFactory: {
                preferencesStore,
                presentationWindow,
                serializationGate in
                ScreenshotEditorOutputCoordinator(
                    preferencesStore: preferencesStore,
                    presentationWindow: presentationWindow,
                    serializationGate: serializationGate,
                    savePanelPresenter: { _, window in
                        presentationWindows.append(window)
                        return .cancel
                    }
                )
            },
            outputImageProcessor: { image, _, _, _ in
                processor.process(image)
            }
        )
        var firstOutcomes: [ScreenshotEditorOutcome] = []
        var replacementOutcomes: [ScreenshotEditorOutcome] = []

