        XCTAssertEqual(presenter.activeSessionIDForTesting, replacementSessionID)
        XCTAssertEqual(firstRetakeCount, 0)
        XCTAssertTrue(firstOutcomes.isEmpty)
        XCTAssertTrue(replacementOutcomes.isEmpty)
    }

