        do {
            _ = try await store.performPluginHostAction(
                "screenshot.output.complete",
                origin: .explicitUser,
                input: [:]
            )
            XCTFail("A failed archive sink must not be reported as success")
        } catch let error as BlocksPluginRuntimeError {
