    }

    func testCancellingScreenshotPluginCompleteBeforeSinksReturnsCancelled() async throws {
        let preferences = ScreenshotPreferencesStore(userDefaults: defaults)
        let presenter = ScreenshotEditorPresenter(preferencesStore: preferences)
        let pasteboard = FinalizedArtifactPasteboardWriterSpy()
        let archive = FinalizedArtifactArchiveWriterSpy()
        let store = ScreenshotStore(
            captureService: CaptureServiceStub(capture: makeCapture()),
            editorPresenter: presenter,
            preferencesStore: preferences,
            pasteboardWriter: pasteboard,
            archiveWriter: archive,
            permissionRefresher: {},
            permissionSnapshotProvider: { self.grantedPermissionSnapshot() }
        )
        var willFinalizeStarted = false
        var willFinalizeContinuation: CheckedContinuation<Void, Never>?
        var terminalEvents: [BlocksPluginEventName] = []
        store.configureCoordinator(
            statusRecorder: { _ in },
            retakeHandler: { _ in },
            dispatchPluginEvent: { envelope in
                if envelope.name == .screenshotWillFinalizeOutput {
                    willFinalizeStarted = true
                    await withCheckedContinuation { willFinalizeContinuation = $0 }
                }
                if envelope.name == .screenshotOutputFinished
                    || envelope.name == .screenshotOutputFailed {
                    terminalEvents.append(envelope.name)
                }
                return .allowed(envelope)
            }
        )
        defer {
            willFinalizeContinuation?.resume()
            presenter.cancelCurrentSession()
        }
        let startResult = await store.startSmartScreenshot()
        XCTAssertEqual(startResult, .completed)
        let editor = try XCTUnwrap(presenter.editorStoreForTesting)
        try await waitForEditorRender(editor)

        let task = Task { @MainActor in
            try await store.performPluginHostAction(
                "screenshot.output.complete",
                origin: .explicitUser,
                input: [:]
            )
        }
        while !willFinalizeStarted { await Task.yield() }
        store.cancelCurrentAction()
        willFinalizeContinuation?.resume()
        willFinalizeContinuation = nil

        do {
            _ = try await task.value
            XCTFail("A cancelled pre-sink finalization must not report success")
        } catch let error as BlocksPluginRuntimeError {
            guard case let .invalidHostOperation(operation) = error else {
                return XCTFail("Unexpected plugin error: \(error)")
            }
            XCTAssertEqual(operation, "screenshot.output.complete.output_cancelled")
        }
        XCTAssertNil(pasteboard.artifact)
        XCTAssertNil(archive.artifact)
        XCTAssertEqual(terminalEvents, [.screenshotOutputFailed])
    }

    func testCancellingScreenshotPluginCompleteTaskBeforeSinksCancelsUnderlyingFinalization()
        async throws
    {
        let preferences = ScreenshotPreferencesStore(userDefaults: defaults)
        let presenter = ScreenshotEditorPresenter(preferencesStore: preferences)
        let pasteboard = FinalizedArtifactPasteboardWriterSpy()
        let archive = FinalizedArtifactArchiveWriterSpy()
        let store = ScreenshotStore(
            captureService: CaptureServiceStub(capture: makeCapture()),
            editorPresenter: presenter,
            preferencesStore: preferences,
            pasteboardWriter: pasteboard,
            archiveWriter: archive,
            permissionRefresher: {},
            permissionSnapshotProvider: { self.grantedPermissionSnapshot() }
        )
        let willFinalizeStarted = expectation(
            description: "plugin finalization reaches the pre-sink hook"
        )
        var willFinalizeContinuation: CheckedContinuation<Void, Never>?
        var terminalEvents: [BlocksPluginEventName] = []
        store.configureCoordinator(
            statusRecorder: { _ in },
            retakeHandler: { _ in },
            dispatchPluginEvent: { envelope in
                if envelope.name == .screenshotWillFinalizeOutput {
                    willFinalizeStarted.fulfill()
                    await withCheckedContinuation { willFinalizeContinuation = $0 }
                }
                if envelope.name == .screenshotOutputFinished
                    || envelope.name == .screenshotOutputFailed {
                    terminalEvents.append(envelope.name)
                }
                return .allowed(envelope)
            }
        )
        defer {
            willFinalizeContinuation?.resume()
            presenter.cancelCurrentSession()
        }
        let startResult = await store.startSmartScreenshot()
        XCTAssertEqual(startResult, .completed)
        let editor = try XCTUnwrap(presenter.editorStoreForTesting)
        try await waitForEditorRender(editor)

        let task = Task { @MainActor in
            try await store.performPluginHostAction(
                "screenshot.output.complete",
                origin: .explicitUser,
                input: [:]
            )
        }
        defer { task.cancel() }
        await fulfillment(of: [willFinalizeStarted], timeout: 1)
        task.cancel()
        willFinalizeContinuation?.resume()
        willFinalizeContinuation = nil

        do {
            _ = try await task.value
            XCTFail("Cancelling the host request before commit must cancel its sink task")
        } catch let error as BlocksPluginRuntimeError {
            guard case let .invalidHostOperation(operation) = error else {
                return XCTFail("Unexpected plugin error: \(error)")
            }
            XCTAssertEqual(operation, "screenshot.output.complete.output_cancelled")
        }
        XCTAssertNil(pasteboard.artifact)
        XCTAssertNil(archive.artifact)
        XCTAssertEqual(terminalEvents, [.screenshotOutputFailed])
    }

