        var decisionCompletion: ((NSApplication.ModalResponse) -> Void)?
        let confirmation = ScreenshotEditorCloseConfirmationCoordinator { _, _, completion in
            decisionCompletion = completion
        }
        let preferences = ScreenshotPreferencesStore(userDefaults: defaults)
        let presenter = ScreenshotEditorPresenter(
            preferencesStore: preferences,
            closeConfirmationCoordinator: confirmation
        )
        let pasteboard = FinalizedArtifactPasteboardWriterSpy()
        let archive = SuspendedFinalizedArtifactArchiveWriter()
        let store = ScreenshotStore(
            captureService: CaptureServiceStub(capture: makeCapture()),
            editorPresenter: presenter,
            preferencesStore: preferences,
            pasteboardWriter: pasteboard,
            archiveWriter: archive,
            permissionRefresher: {},
            permissionSnapshotProvider: { self.grantedPermissionSnapshot() }
        )
        var retakeCount = 0
        store.configureCoordinator(
            statusRecorder: { _ in },
            retakeHandler: { _ in retakeCount += 1 }
        )

        let result = await store.startSmartScreenshot()
        XCTAssertEqual(result, .completed)
        let editor = try XCTUnwrap(presenter.editorStoreForTesting)
        try await waitForEditorRender(editor)
        editor.selectTool(.rectangle)
        editor.beginGesture(at: CGPoint(x: 2, y: 2), modifiers: [])
        editor.updateGesture(to: CGPoint(x: 18, y: 18), points: [], modifiers: [])
        editor.endGesture(at: CGPoint(x: 18, y: 18), modifiers: [])
