    func testCloseConfirmationCoordinatorRejectsDuplicatePresentationUntilCompletion() {
        var presentationCount = 0
        var pendingCompletion: ((NSApplication.ModalResponse) -> Void)?
        let coordinator = ScreenshotEditorCloseConfirmationCoordinator { _, _, completion in
            presentationCount += 1
            pendingCompletion = completion
        }
        let panel = ScreenshotEditorHostPanel(contentRect: .init(x: 0, y: 0, width: 760, height: 520))
        var decisions: [ScreenshotEditorCloseDecision] = []

        XCTAssertTrue(coordinator.present(on: panel, completion: { decisions.append($0.decision) }))
        XCTAssertFalse(coordinator.present(on: panel, completion: { decisions.append($0.decision) }))
        XCTAssertEqual(presentationCount, 1)
        XCTAssertTrue(coordinator.isPresenting)

        pendingCompletion?(.alertThirdButtonReturn)

        XCTAssertEqual(decisions, [.cancel])
        XCTAssertFalse(coordinator.isPresenting)
        XCTAssertTrue(coordinator.present(on: panel, completion: { decisions.append($0.decision) }))
        XCTAssertEqual(presentationCount, 2)
    }

