        let presentation = ScreenshotToolbarPresentation.make(
            quickTools: [.arrow, .rectangle],
            extendedTools: [.ellipse, .counter, .step],
            selectedItem: store.activeToolbarItemID
        )

        XCTAssertEqual(store.activeToolbarItemID, .step)
        XCTAssertEqual(store.selectedTool, .step)
        XCTAssertEqual(store.inspectorTool, .step)
        XCTAssertEqual(presentation.activeOverflowTool, .step)
    }

