    func testMoreToolsPresentationOwnsOneDeterministicDismissalPath() {
        var state = ScreenshotMoreToolsPresentationState()

        state.handle(.trigger(hasOverflow: true, source: .mouse))
        XCTAssertTrue(state.isPresented)
        XCTAssertFalse(state.shouldAutofocus)

        state.handle(.trigger(hasOverflow: true, source: .mouse))
        XCTAssertFalse(state.isPresented)
        XCTAssertFalse(state.shouldAutofocus)

        state.handle(.trigger(hasOverflow: false, source: .mouse))
        XCTAssertFalse(state.isPresented)
        XCTAssertFalse(state.shouldAutofocus)

        state.handle(.trigger(hasOverflow: true, source: .keyboardOrAccessibility))
        XCTAssertTrue(state.isPresented)
        XCTAssertTrue(state.shouldAutofocus)
        state.handle(.toolbarAction)
        XCTAssertFalse(state.isPresented)
        XCTAssertFalse(state.shouldAutofocus)

        state.handle(.trigger(hasOverflow: true, source: .keyboardOrAccessibility))
        state.handle(.toolsChanged(hasOverflow: true))
        XCTAssertTrue(state.isPresented)
        XCTAssertTrue(state.shouldAutofocus)

        state.handle(.toolsChanged(hasOverflow: false))
        XCTAssertFalse(state.isPresented)
        XCTAssertFalse(state.shouldAutofocus)

        state.handle(.trigger(hasOverflow: true, source: .keyboardOrAccessibility))
        state.handle(.escape)
        XCTAssertFalse(state.isPresented)
        XCTAssertFalse(state.shouldAutofocus)

        state.handle(.trigger(hasOverflow: true, source: .keyboardOrAccessibility))
        state.handle(.disappear)
        XCTAssertFalse(state.isPresented)
        XCTAssertFalse(state.shouldAutofocus)
    }

    func testMoreToolsMouseActivationPreservesExistingFirstResponder() throws {
        let window = ScreenshotEditorHostPanel(
            contentRect: CGRect(x: 40, y: 40, width: 240, height: 160)
        )
        let content = NSView(frame: window.contentView?.bounds ?? .zero)
        let existingResponder = NSTextView(
            frame: CGRect(x: 20, y: 20, width: 120, height: 24)
        )
        let container = ScreenshotMoreToolsTriggerButton.FocusableButtonContainer(
            frame: CGRect(x: 160, y: 20, width: 28, height: 28)
        )
        content.addSubview(existingResponder)
        content.addSubview(container)
        window.contentView = content
        defer {
            window.makeFirstResponder(nil)
            window.contentView = nil
            window.close()
            drainAppKitAnimationTransactions()
        }

        XCTAssertTrue(window.makeFirstResponder(existingResponder))
        var activationSources: [ScreenshotMoreToolsActivationSource] = []
        let coordinator = ScreenshotMoreToolsTriggerButton.Coordinator {
            activationSources.append($0)
        }
        container.onMouseActivate = { coordinator.activateFromMouse() }

        let location = CGPoint(x: 174, y: 34)
        let mouseDown = try mouseEvent(
            type: .leftMouseDown,
            location: location,
            windowNumber: window.windowNumber
        )
        let mouseUp = try mouseEvent(
            type: .leftMouseUp,
            location: location,
            windowNumber: window.windowNumber
        )
        var trackingEvents = [mouseUp]
        container.nextTrackingEventForTesting = { _ in
            trackingEvents.isEmpty ? nil : trackingEvents.removeFirst()
        }
        container.mouseDown(with: mouseDown)

        XCTAssertTrue(window.firstResponder === existingResponder)
        XCTAssertEqual(activationSources, [.mouse])
    }

