    func testScreenshotCompactToolbarAndMoreToolsUseStableWidthBudgets() {
        XCTAssertEqual(ScreenshotSelectionToolbarPresentation.runtime.controlHeight, 28)
        XCTAssertEqual(ScreenshotSelectionToolbarPresentation.settingsCompact.controlHeight, 28)
        XCTAssertEqual(ScreenshotSelectionToolbarPresentation.runtime.groupSpacing, 8)
        XCTAssertEqual(ScreenshotSelectionToolbarPresentation.runtime.parameterControlSpacing, 12)
        XCTAssertEqual(ScreenshotConstraintToolbarMetrics.contentSpacing, 4)
        XCTAssertEqual(ScreenshotConstraintToolbarMetrics.valueWidth, 96)
        XCTAssertEqual(ScreenshotConstraintToolbarMetrics.keyHeight, 28)
        XCTAssertEqual(
            ScreenshotConstraintToolbarMetrics.unitWidth,
            ScreenshotConstraintToolbarMetrics.keyWidth
                + ScreenshotConstraintToolbarMetrics.contentSpacing
                + ScreenshotConstraintToolbarMetrics.valueWidth
        )
        let compactExpectedWidth = 4 * ScreenshotConstraintToolbarMetrics.unitWidth
            + 3 * ScreenshotConstraintToolbarMetrics.parameterControlSpacing
            + ScreenshotConstraintToolbarMetrics.islandHorizontalPadding
            + ScreenshotSelectionToolbarPresentation.settingsCompact.outerPadding * 2
        XCTAssertEqual(
            ScreenshotSelectionToolbarView.preferredSize(
                showsScrollingMode: false,
                presentation: .settingsCompact
            ).width,
            compactExpectedWidth
        )
        let runtimeExpectedWidth = compactExpectedWidth
            - ScreenshotSelectionToolbarPresentation.settingsCompact.outerPadding * 2
            + ScreenshotSelectionToolbarPresentation.runtime.dragHandleSize
            + ScreenshotConstraintToolbarMetrics.islandHorizontalPadding
            + ScreenshotSelectionToolbarPresentation.runtime.groupSpacing
            + ScreenshotSelectionToolbarPresentation.runtime.outerPadding * 2
        XCTAssertEqual(
            ScreenshotSelectionToolbarView.preferredSize(showsScrollingMode: false).width,
            runtimeExpectedWidth
        )
        XCTAssertEqual(
            ScreenshotSelectionToolbarView.preferredSize.width,
            runtimeExpectedWidth
                + ScreenshotSelectionToolbarPresentation.runtime.controlHeight
                + ScreenshotConstraintToolbarMetrics.islandHorizontalPadding
                + ScreenshotSelectionToolbarPresentation.runtime.groupSpacing
        )

        XCTAssertEqual(ScreenshotMoreToolsPanelMetrics.columnCount(toolCount: 1), 1)
        XCTAssertEqual(ScreenshotMoreToolsPanelMetrics.panelWidth(toolCount: 1), 176)
        XCTAssertEqual(ScreenshotMoreToolsPanelMetrics.columnCount(toolCount: 2), 2)
        XCTAssertEqual(ScreenshotMoreToolsPanelMetrics.panelWidth(toolCount: 2), 224)
        XCTAssertEqual(ScreenshotMoreToolsPanelMetrics.columnCount(toolCount: 8), 3)
        XCTAssertEqual(ScreenshotMoreToolsPanelMetrics.panelWidth(toolCount: 8), 320)

        let parameterFont = BlocksTypography.nsFont(size: 12, weight: .medium)
        let builtInWidth = ("1920×1080" as NSString).size(withAttributes: [.font: parameterFont]).width
        let maximumWidth = ("32768×3662" as NSString).size(withAttributes: [.font: parameterFont]).width
        XCTAssertLessThan(builtInWidth, maximumWidth)

        let compactToolbar = ScreenshotSelectionToolbarView(
            parameters: ScreenshotSelectionParameters(),
            allowsDragging: false,
            showsScrollingMode: false,
            presentation: .settingsCompact,
            onAction: { _ in }
        )
        let toolbarWindow = NSWindow(
            contentRect: NSRect(origin: .zero, size: compactToolbar.intrinsicContentSize),
            styleMask: [.borderless],
            backing: .buffered,
            defer: false
        )
        toolbarWindow.animationBehavior = .none
        toolbarWindow.contentView = compactToolbar
        compactToolbar.frame.size = compactToolbar.intrinsicContentSize
        toolbarWindow.orderFront(nil)
        defer {
            toolbarWindow.orderOut(nil)
            drainAppKitAnimationTransactions()
        }
        toolbarWindow.layoutIfNeeded()
        compactToolbar.layoutSubtreeIfNeeded()
        let constraintButton = compactToolbar.interactiveControls.first
        let buttonCenter = NSPoint(x: constraintButton?.bounds.midX ?? 0, y: constraintButton?.bounds.midY ?? 0)
        XCTAssertIdentical(constraintButton?.hitTest(buttonCenter), constraintButton)
        XCTAssertTrue(constraintButton?.subviews.allSatisfy { !$0.isAccessibilityElement() } ?? false)
        XCTAssertNil((constraintButton as? NSButton)?.image)

        func descendants(of view: NSView) -> [NSView] {
            view.subviews + view.subviews.flatMap(descendants)
        }
        let parameterLabelFields = descendants(of: compactToolbar)
            .compactMap { $0 as? NSTextField }
            .filter { $0.superview !== constraintButton }
        let parameterLabels = parameterLabelFields.map(\.stringValue)
        let expectedParameterLabels = Set([
            "screenshot.selection.constraint",
            "screenshot.selection.delay",
            "screenshot.selection.freeze",
            "screenshot.selection.watermark",
        ].map {
            L10n.format(
                "screenshot.selection.parameter.labelFormat",
                L10n.string($0)
            )
        })
        for expectedLabel in expectedParameterLabels {
            XCTAssertTrue(parameterLabels.contains(expectedLabel))
        }
        for label in parameterLabelFields where expectedParameterLabels.contains(label.stringValue) {
            XCTAssertFalse(label.isEditable)
            XCTAssertFalse(label.isSelectable)
            XCTAssertNil(label.action)
            XCTAssertEqual(label.frame.width, ScreenshotConstraintToolbarMetrics.keyWidth, accuracy: 0.5)
            XCTAssertEqual(label.frame.height, ScreenshotConstraintToolbarMetrics.keyHeight, accuracy: 0.5)
            if let drawingRect = label.cell?.drawingRect(forBounds: label.bounds) {
                XCTAssertEqual(drawingRect.midY, label.bounds.midY, accuracy: 0.5)
            } else {
                XCTFail("Parameter key label must provide a text cell.")
            }
            XCTAssertGreaterThan(
                label.layer?.backgroundColor.flatMap { NSColor(cgColor: $0) }?.alphaComponent ?? 0,
                0.1
            )
        }

        XCTAssertFalse(descendants(of: compactToolbar).contains { $0 is NSPopUpButton })
        XCTAssertEqual(compactToolbar.interactiveControls.prefix(4).map(\.frame.width), [96, 96, 96, 96])
        XCTAssertTrue(compactToolbar.interactiveControls.prefix(4).allSatisfy { $0 is NSButton })
        XCTAssertEqual(compactToolbar.interactiveControls[1].accessibilityRole(), .popUpButton)
        XCTAssertEqual(compactToolbar.interactiveControls[2].accessibilityRole(), .button)
        XCTAssertEqual(compactToolbar.interactiveControls[2].accessibilitySubrole(), .switch)
        XCTAssertEqual(compactToolbar.interactiveControls[3].accessibilityRole(), .popUpButton)

        let longValueToolbar = ScreenshotSelectionToolbarView(
            parameters: ScreenshotSelectionParameters(
                constraint: .fixedPixels(width: 32_768, height: 3_662)
            ),
            allowsDragging: false,
            showsScrollingMode: false,
            presentation: .settingsCompact,
            onAction: { _ in }
        )
        let fittedSize = longValueToolbar.intrinsicContentSize
        XCTAssertEqual(fittedSize.width, compactToolbar.intrinsicContentSize.width)
        longValueToolbar.frame.size = fittedSize
        longValueToolbar.layoutSubtreeIfNeeded()
        for control in longValueToolbar.interactiveControls {
            let controlFrame = longValueToolbar.convert(control.bounds, from: control)
            XCTAssertGreaterThanOrEqual(controlFrame.minX, 0)
            XCTAssertLessThanOrEqual(controlFrame.maxX, longValueToolbar.bounds.maxX + 0.5)
        }
        let longConstraintButton = try? XCTUnwrap(longValueToolbar.interactiveControls.first)
        let longValueLabel = longConstraintButton.flatMap { button in
            descendants(of: button)
                .compactMap { $0 as? NSTextField }
                .first { $0.stringValue == "32768×3662" }
        }
        if let longConstraintButton, let longValueLabel {
            let labelFrame = longConstraintButton.convert(longValueLabel.bounds, from: longValueLabel)
            XCTAssertGreaterThanOrEqual(labelFrame.minX, -0.5)
            XCTAssertLessThanOrEqual(labelFrame.maxX, longConstraintButton.bounds.maxX + 0.5)
            XCTAssertLessThan(
                longValueLabel.contentCompressionResistancePriority(for: .horizontal),
                .required
            )
            XCTAssertEqual(longConstraintButton.accessibilityValue() as? String, "32768×3662")
        } else {
            XCTFail("Expected the long constraint label to remain inside the fixed-width button")
        }

        let runtimeToolbar = ScreenshotSelectionToolbarView(
            parameters: ScreenshotSelectionParameters(),
            allowsDragging: true,
            showsScrollingMode: false,
            onAction: { _ in }
        )
        let runtimeWidth = runtimeToolbar.intrinsicContentSize.width
        XCTAssertEqual(runtimeWidth, runtimeExpectedWidth)
        runtimeToolbar.update(parameters: ScreenshotSelectionParameters(
            constraint: .fixedPixels(width: 32_768, height: 3_662)
        ))
        XCTAssertEqual(runtimeToolbar.intrinsicContentSize.width, runtimeWidth)

        let scrollingToolbar = ScreenshotSelectionToolbarView(
            parameters: ScreenshotSelectionParameters(
                constraint: .ratio(width: 16, height: 9)
            ),
            allowsDragging: true,
            showsScrollingMode: true,
            onAction: { _ in }
        )
        let scrollingWidth = scrollingToolbar.intrinsicContentSize.width
        XCTAssertEqual(scrollingWidth, ScreenshotSelectionToolbarView.preferredSize.width)
        scrollingToolbar.update(parameters: ScreenshotSelectionParameters(
            constraint: .fixedPixels(width: 32_768, height: 3_662)
        ))
        XCTAssertEqual(scrollingToolbar.intrinsicContentSize.width, scrollingWidth)
    }

    func testScreenshotChromeUsesGlobalMotionAndKeepsDirectManipulationImmediate() {
