    func testCurvatureAnchorPulseUsesNonSpatialGlobalFeedbackPolicy() {
        let standard = ScreenshotCurvatureAnchorPulsePolicy(reduceMotion: false)
        let reduced = ScreenshotCurvatureAnchorPulsePolicy(reduceMotion: true)

        XCTAssertEqual(standard.duration, BlocksMotionRole.hoverFocus.policy(reduceMotion: false).duration)
        XCTAssertFalse(standard.allowsSpatialMotion)
        XCTAssertEqual(standard.diameter(isHighlighted: true), 14)
        XCTAssertEqual(standard.diameter(isHighlighted: false), 14)

        XCTAssertEqual(reduced.duration, BlocksMotionRole.hoverFocus.policy(reduceMotion: true).duration)
        XCTAssertFalse(reduced.allowsSpatialMotion)
        XCTAssertEqual(reduced.diameter(isHighlighted: true), 14)
    }

    func testSelectionToolbarAspectPopoverReplacesItsInstanceAndRestoresTriggerFocus() async throws {
        let toolbar = ScreenshotSelectionToolbarView(
            parameters: ScreenshotSelectionParameters(),
            allowsDragging: false,
            showsScrollingMode: false,
            onAction: { _ in }
        )
        let window = NSWindow(
            contentRect: NSRect(origin: .zero, size: ScreenshotSelectionToolbarView.preferredSize),
            styleMask: [.titled],
            backing: .buffered,
            defer: false
        )
        window.animationBehavior = .none
        window.contentView = toolbar
        window.makeKeyAndOrderFront(nil)
        defer {
            toolbar.activeAspectRatioPopover?.animates = false
            toolbar.activeAspectRatioPopover?.close()
            drainAppKitAnimationTransactions()
            window.orderOut(nil)
            drainAppKitAnimationTransactions()
        }
        let trigger = try XCTUnwrap(toolbar.interactiveControls.first as? NSButton)

        trigger.performClick(nil)
        let first = try XCTUnwrap(toolbar.activeAspectRatioPopover)
        first.animates = false
        XCTAssertTrue(first.isShown)

        trigger.performClick(nil)
        let second = try XCTUnwrap(toolbar.activeAspectRatioPopover)
        XCTAssertFalse(first === second)
        XCTAssertTrue(second.isShown)

        second.animates = false
        let didClose = expectation(forNotification: NSPopover.didCloseNotification, object: second)
        second.close()
        await fulfillment(of: [didClose], timeout: 1)
        await Task.yield()

        XCTAssertNil(toolbar.activeAspectRatioPopover)
        XCTAssertTrue(window.firstResponder === trigger)
    }

    func testAspectControlModelSharesOrientationCustomDraftAndSavedPresetSemantics() throws {
        let model = ScreenshotAspectControlModel(
            selection: ScreenshotAspectSelection(
                orientation: .landscape,
                constraint: .ratio(width: 16, height: 9)
            ),
            customConstraints: []
        )

        XCTAssertEqual(model.setOrientation(.portrait).resolvedConstraint, .ratio(width: 9, height: 16))
        model.customMode = .fixedPixels
        model.fixedWidth = "640"
        model.fixedHeight = "480"
        let result = try XCTUnwrap(model.applyCustom(saves: true))

        XCTAssertEqual(result.selection.resolvedConstraint, .fixedPixels(width: 480, height: 640))
        XCTAssertEqual(model.savedConstraints.count, 1)
        XCTAssertEqual(model.savedConstraints.first?.constraint, .fixedPixels(width: 640, height: 480))

        let savedID = try XCTUnwrap(model.savedConstraints.first?.id)
        model.deleteSaved(savedID)
        XCTAssertTrue(model.savedConstraints.isEmpty)
    }

    func testAspectPresetSelectionSynchronizesCustomModeAndDraft() {
        let model = ScreenshotAspectControlModel(
            selection: ScreenshotAspectSelection(orientation: .landscape, constraint: .free),
            customConstraints: []
        )

        _ = model.select(.fixedPixels(width: 800, height: 600))
        XCTAssertEqual(model.customMode, .fixedPixels)
        XCTAssertEqual(model.fixedWidth, "800")
        XCTAssertEqual(model.fixedHeight, "600")

        _ = model.select(.ratio(width: 4, height: 3))
        XCTAssertEqual(model.customMode, .ratio)
        XCTAssertEqual(model.ratioWidth, "4")
        XCTAssertEqual(model.ratioHeight, "3")

        _ = model.select(.free)
