    func testOrientationGlyphFollowsConstraintWithoutChangingAbsoluteOrientationScale() {
        let landscape = ScreenshotOrientationGlyphLayout.shapeSize(
            for: .fixedPixels(width: 1_920, height: 1_080),
            orientation: .landscape
        )
        let portrait = ScreenshotOrientationGlyphLayout.shapeSize(
            for: .fixedPixels(width: 1_920, height: 1_080),
            orientation: .portrait
        )
        let fourByThree = ScreenshotOrientationGlyphLayout.shapeSize(
            for: .ratio(width: 4, height: 3),
            orientation: .landscape
        )

        XCTAssertEqual(landscape.width, portrait.height, accuracy: 0.001)
        XCTAssertEqual(landscape.height, portrait.width, accuracy: 0.001)
        XCTAssertEqual(landscape.width, ScreenshotOrientationGlyphLayout.maximumEdge, accuracy: 0.001)
        XCTAssertEqual(portrait.height, ScreenshotOrientationGlyphLayout.maximumEdge, accuracy: 0.001)
        XCTAssertNotEqual(landscape.height, fourByThree.height)
    }

