    func testAspectControlModelReturnsStableNeighborAfterDeletingSavedPreset() throws {
        let first = ScreenshotCustomConstraintPreset(
            id: UUID(uuidString: "00000000-0000-0000-0000-000000000001")!,
            constraint: .ratio(width: 3, height: 2)
        )
        let middle = ScreenshotCustomConstraintPreset(
            id: UUID(uuidString: "00000000-0000-0000-0000-000000000002")!,
            constraint: .ratio(width: 5, height: 4)
        )
        let last = ScreenshotCustomConstraintPreset(
            id: UUID(uuidString: "00000000-0000-0000-0000-000000000003")!,
            constraint: .fixedPixels(width: 1_200, height: 800)
        )
        let model = ScreenshotAspectControlModel(
            selection: ScreenshotAspectSelection(orientation: .landscape, constraint: .free),
            customConstraints: [first, middle, last]
        )

        XCTAssertEqual(model.deleteSaved(middle.id), last.id)
        XCTAssertEqual(model.savedConstraints.map(\.id), [first.id, last.id])
        XCTAssertEqual(model.deleteSaved(last.id), first.id)
        XCTAssertEqual(model.deleteSaved(first.id), nil)
        XCTAssertTrue(model.savedConstraints.isEmpty)
    }

