    func testContinuousStyleEditingSubmitsAndPersistsOnlyOnce() throws {
        let preferences = ScreenshotPreferencesStore(userDefaults: defaults)
        let store = try ScreenshotEditorStore(
            capture: makeCapture(),
            preferencesStore: preferences,
            onComplete: { _ in },
            onRetake: {},
            onClose: {}
        )
        store.selectTool(.rectangle)
        store.beginGesture(at: CGPoint(x: 2, y: 2), modifiers: [])
        store.updateGesture(to: CGPoint(x: 18, y: 18), points: [], modifiers: [])
        store.endGesture(at: CGPoint(x: 18, y: 18), modifiers: [])
        let renderSubmissions = store.renderSubmissionCount
        let persistCount = store.stylePersistenceCount

        store.beginStyleEditing()
        var style = store.activeStyle
        style.lineWidth = 5
        store.updateSelectedStyle(style)
        style.lineWidth = 8
        store.updateSelectedStyle(style)

        XCTAssertEqual(store.renderSubmissionCount, renderSubmissions)
        XCTAssertEqual(store.stylePersistenceCount, persistCount)

        store.endStyleEditing()

        XCTAssertEqual(store.renderSubmissionCount, renderSubmissions + 1)
