    func testMarkedTextResolverOverridesIMEForegroundButPreservesCompositionSegments() throws {
        let imeColor = NSColor.systemBlue
        let editorColor = NSColor.systemRed
        let source = NSMutableAttributedString(string: "pin yin")
        source.addAttributes([
            .foregroundColor: imeColor,
            .underlineStyle: NSUnderlineStyle.single.rawValue,
        ], range: NSRange(location: 0, length: 3))
        source.addAttributes([
            .foregroundColor: imeColor,
            .underlineStyle: NSUnderlineStyle.double.rawValue,
        ], range: NSRange(location: 3, length: 4))

        let resolved = ScreenshotInlineMarkedTextResolver.resolve(
            source,
            applying: [.foregroundColor: editorColor, .font: NSFont.systemFont(ofSize: 21)]
        )

        XCTAssertEqual(resolved.attribute(.foregroundColor, at: 0, effectiveRange: nil) as? NSColor, editorColor)
        XCTAssertEqual(resolved.attribute(.foregroundColor, at: 5, effectiveRange: nil) as? NSColor, editorColor)
        XCTAssertEqual(
            resolved.attribute(.underlineStyle, at: 0, effectiveRange: nil) as? Int,
            NSUnderlineStyle.single.rawValue
        )
        XCTAssertEqual(
            resolved.attribute(.underlineStyle, at: 5, effectiveRange: nil) as? Int,
            NSUnderlineStyle.double.rawValue
        )
    }

    func testInlineTextViewReappliesEditorColorAfterIMEUpdatesMarkedRange() throws {
        var appearance = ScreenshotElementAppearance.defaultValue(for: .text)
        appearance.strokeColor = ScreenshotColor(red: 0.9, green: 0.1, blue: 0.2, alpha: 0.8)
        appearance.opacity = 0.5
        let expected = ScreenshotInlineTextAttributes(
            appearance: appearance,
            sourceUnitsPerViewPoint: 1
        )
        let inputColor = NSColor.black
        let source = NSMutableAttributedString(string: "yan se")
        source.addAttributes([
            .foregroundColor: inputColor,
            .underlineStyle: NSUnderlineStyle.single.rawValue,
        ], range: NSRange(location: 0, length: 3))
        source.addAttributes([
            .foregroundColor: inputColor,
            .underlineStyle: NSUnderlineStyle.double.rawValue,
        ], range: NSRange(location: 3, length: 3))

        let editor = ScreenshotInlineTextView(frame: CGRect(x: 0, y: 0, width: 240, height: 60))
        editor.resolvedMarkedTextAttributes = expected.attributes
        editor.markedTextAttributes = expected.mergingMarkedTextAttributes(editor.markedTextAttributes)
        editor.typingAttributes = expected.attributes
        let owner = NSWindow(
            contentRect: CGRect(x: 0, y: 0, width: 320, height: 160),
            styleMask: [.titled],
            backing: .buffered,
            defer: false
        )
        owner.contentView?.addSubview(editor)
        owner.makeFirstResponder(editor)

        editor.setMarkedText(
            source,
            selectedRange: NSRange(location: source.length, length: 0),
            replacementRange: NSRange(location: NSNotFound, length: 0)
        )

        let markedRange = editor.markedRange()
        XCTAssertNotEqual(markedRange.location, NSNotFound)
        let firstColor = try XCTUnwrap(
            editor.textStorage?.attribute(.foregroundColor, at: markedRange.location, effectiveRange: nil) as? NSColor
        )
        let lastColor = try XCTUnwrap(
            editor.textStorage?.attribute(
                .foregroundColor,
                at: markedRange.location + markedRange.length - 1,
                effectiveRange: nil
            ) as? NSColor
        )
        XCTAssertEqual(firstColor, expected.foregroundColor)
        XCTAssertEqual(lastColor, expected.foregroundColor)
        XCTAssertEqual(
            editor.textStorage?.attribute(.underlineStyle, at: markedRange.location, effectiveRange: nil) as? Int,
            NSUnderlineStyle.single.rawValue
        )
        XCTAssertEqual(
            editor.textStorage?.attribute(
                .underlineStyle,
                at: markedRange.location + markedRange.length - 1,
                effectiveRange: nil
            ) as? Int,
            NSUnderlineStyle.double.rawValue
        )
        XCTAssertEqual(editor.insertionPointColor, expected.foregroundColor)
        XCTAssertEqual(editor.typingAttributes[.foregroundColor] as? NSColor, expected.foregroundColor)
    }

    func testInlineTextViewNotifiesAutoSizingAfterIMEStoresMarkedText() throws {
        var appearance = ScreenshotElementAppearance.defaultValue(for: .text)
        appearance.fontSize = 96
        appearance.strokeColor = ScreenshotColor(red: 0.96, green: 0.24, blue: 0.22, alpha: 1)
        let layout = ScreenshotTextLayout(appearance: appearance)
        let editor = ScreenshotInlineTextView(frame: CGRect(x: 0, y: 0, width: 4.5, height: 62))
        let resolved = ScreenshotInlineTextAttributes(
            appearance: appearance,
            sourceUnitsPerViewPoint: 2
        )
        editor.resolvedMarkedTextAttributes = resolved.attributes
        editor.markedTextAttributes = resolved.mergingMarkedTextAttributes(editor.markedTextAttributes)
        editor.drawsBackground = true
        editor.backgroundColor = .black
        let owner = NSWindow(
            contentRect: CGRect(x: 0, y: 0, width: 320, height: 120),
            styleMask: [.borderless],
            backing: .buffered,
            defer: false
        )
        owner.contentView?.addSubview(editor)
        owner.makeFirstResponder(editor)
        var observedString = ""
        var observedMarkedRange = NSRange(location: NSNotFound, length: 0)
        editor.onMarkedTextChange = {
            observedString = editor.string
            observedMarkedRange = editor.markedRange()
            let measured = layout.measure(
                editor.string,
                sizing: .auto,
                constrainedTo: ScreenshotTextLayout.defaultMaximumAutoWidth
            )
            editor.frame.size.width = CGFloat(measured.width / 2)
        }

        editor.setMarkedText(
            "yan'se",
            selectedRange: NSRange(location: 6, length: 0),
            replacementRange: NSRange(location: NSNotFound, length: 0)
        )

        XCTAssertEqual(observedString, "yan'se")
        XCTAssertEqual(observedMarkedRange, NSRange(location: 0, length: 6))
        XCTAssertGreaterThan(editor.frame.width, 4.5)

        editor.displayIfNeeded()
        let bitmap = try XCTUnwrap(editor.bitmapImageRepForCachingDisplay(in: editor.bounds))
        editor.cacheDisplay(in: editor.bounds, to: bitmap)
        var redGlyphPixelCount = 0
        for y in 0..<bitmap.pixelsHigh {
            for x in 0..<bitmap.pixelsWide {
                guard let color = bitmap.colorAt(x: x, y: y)?.usingColorSpace(.sRGB) else { continue }
                if color.redComponent > 0.55,
                   color.redComponent > color.greenComponent * 1.5,
                   color.redComponent > color.blueComponent * 1.5 {
                    redGlyphPixelCount += 1
                }
            }
        }
        XCTAssertGreaterThan(redGlyphPixelCount, 20)
    }

    func testNumericValueDescriptorParsesFormatsClampsAndSteps() {
        let percent = ScreenshotNumericValueDescriptor(
            range: 0...1,
            step: 0.05,
            fractionDigits: 0,
            unit: .percent
        )
        XCTAssertEqual(percent.parse("75%"), 0.75)
        XCTAssertEqual(percent.parse("130"), 1)
        XCTAssertEqual(percent.format(0.42), "42%")
        XCTAssertEqual(percent.stepped(0.95, direction: 1), 1)

        let multiplier = ScreenshotNumericValueDescriptor(
            range: 1.5...5,
            step: 0.1,
            fractionDigits: 1,
            unit: .multiplier
        )
        XCTAssertEqual(multiplier.parse("2.5x"), 2.5)
        XCTAssertEqual(multiplier.format(2.5), "2.5×")
        XCTAssertNil(multiplier.parse("invalid"))
    }

