    func testColorPanelStaysAboveOwnerPreviewsLiveAndCommitsOnceOnClose() throws {
        let owner = NSWindow(
            contentRect: CGRect(x: 0, y: 0, width: 320, height: 240),
            styleMask: [.titled],
            backing: .buffered,
            defer: false
        )
        owner.animationBehavior = .none
        let controller = ScreenshotColorPanelController()
        controller.ownerWindow = owner
        defer {
            controller.dismiss()
            owner.orderOut(nil)
            drainAppKitAnimationTransactions()
        }
        var previews: [ScreenshotColor] = []
        var completions: [(ScreenshotColor, Bool)] = []
        controller.present(
            color: ScreenshotColor(red: 0.1, green: 0.2, blue: 0.3, alpha: 1),
            onChange: { previews.append($0) },
            onClose: { completions.append(($0, $1)) }
        )

        let panel = NSColorPanel.shared
        XCTAssertTrue(owner.childWindows?.contains(panel) == true)
        XCTAssertFalse(panel.showsAlpha)
        panel.color = NSColor(srgbRed: 0.25, green: 0.5, blue: 0.75, alpha: 0.2)
        controller.colorChanged(panel)

        let preview = try XCTUnwrap(previews.last)
        XCTAssertEqual(preview.red, 0.25, accuracy: 0.001)
        XCTAssertEqual(preview.green, 0.5, accuracy: 0.001)
        XCTAssertEqual(preview.blue, 0.75, accuracy: 0.001)
        XCTAssertEqual(preview.alpha, 1)

        controller.dismiss()

        XCTAssertFalse(owner.childWindows?.contains(panel) == true)
        XCTAssertFalse(panel.isVisible)
        XCTAssertEqual(completions.count, 1)
        XCTAssertEqual(completions[0].0, preview)
        XCTAssertTrue(completions[0].1)
    }

    func testImmediateTooltipUsesAnUnclippedChildPanelAndClearsOnWindowResign() async throws {
        let owner = NSWindow(
            contentRect: CGRect(x: 120, y: 120, width: 320, height: 240),
            styleMask: [.titled],
            backing: .buffered,
            defer: false
        )
        owner.animationBehavior = .none
        let anchor = NSView(frame: CGRect(x: 280, y: 200, width: 32, height: 32))
        owner.contentView?.addSubview(anchor)
        let host = BlocksImmediateTooltipHostModel()
        host.ownerWindow = owner
        defer {
            host.hide()
            owner.orderOut(nil)
            drainAppKitAnimationTransactions()
        }

        host.show(label: "文字", anchor: anchor)

        let panel = try XCTUnwrap(owner.childWindows?.first)
        XCTAssertTrue(panel is NSPanel)
        XCTAssertTrue(panel.ignoresMouseEvents)
        XCTAssertGreaterThan(panel.frame.width, 0)
        XCTAssertGreaterThan(panel.frame.height, 0)

        NotificationCenter.default.post(name: NSWindow.didResignKeyNotification, object: owner)
        await Task.yield()

        XCTAssertFalse(owner.childWindows?.contains(panel) == true)
        XCTAssertFalse(panel.isVisible)
    }

