    func testCancellingReplacementWhilePixelProcessingResumesCallerAndDropsLateImage() async throws {
        let probe = SuspendedScreenshotOutputImageProcessorProbe(suspends: true)
        let closed = expectation(description: "editor closed")
        let replacementFinished = expectation(description: "replacement request finished")
        var replacementImage: NSImage?
        let store = try ScreenshotEditorStore(
            capture: makeCapture(),
            preferencesStore: ScreenshotPreferencesStore(userDefaults: defaults),
            onComplete: { _ in XCTFail("Cancelled replacement must not complete output") },
            onRetake: {},
            onClose: { closed.fulfill() },
            outputImageProcessor: { image, _, _, _ in
                probe.process(image)
            }
        )
        Task { @MainActor in
            replacementImage = await store.completeForReplacement()
            replacementFinished.fulfill()
        }
        await probe.waitUntilStarted()

        store.close()
        store.shutdown()
        await fulfillment(of: [closed, replacementFinished], timeout: 1)
        XCTAssertNil(replacementImage)
        XCTAssertFalse(store.isOutputPending)

        probe.resume()
        try await Task.sleep(for: .milliseconds(30))
        XCTAssertNil(replacementImage)
    }

