    func testSaveKeepsStableOutputStateAndRejectsCompetingOutput() async throws {
        let preferences = ScreenshotPreferencesStore(userDefaults: defaults)
        let host = NSWindow(
            contentRect: CGRect(x: 0, y: 0, width: 320, height: 240),
            styleMask: [],
            backing: .buffered,
            defer: false
        )
        let saveStarted = expectation(description: "save panel started")
        var saveContinuation: CheckedContinuation<
            ScreenshotEditorOutputCoordinator.SavePanelResult,
            Never
        >?
        let output = ScreenshotEditorOutputCoordinator(
            preferencesStore: preferences,
            presentationWindow: { host },
            savePanelPresenter: { _, _ in
                saveStarted.fulfill()
                return await withCheckedContinuation { saveContinuation = $0 }
            }
        )
        var pinCount = 0
        let store = try ScreenshotEditorStore(
            capture: makeCapture(),
            preferencesStore: preferences,
            onComplete: { _ in },
            onPinned: { _ in pinCount += 1 },
            onRetake: {},
            onClose: {},
            outputCoordinator: output
        )

        store.saveAs()
        await fulfillment(of: [saveStarted], timeout: 2)

        XCTAssertTrue(store.isOutputPending)
        XCTAssertEqual(store.currentOutputCommand, .save)
        store.pinCurrent()
        XCTAssertEqual(pinCount, 0)
        XCTAssertEqual(store.currentOutputCommand, .save)

        saveContinuation?.resume(returning: .cancel)
        for _ in 0..<100 where store.isOutputPending {
            await Task.yield()
        }
        XCTAssertFalse(store.isOutputPending)
        XCTAssertNil(store.currentOutputCommand)
    }

