    func testInlineTextCreationRevalidatesEditorFocusAfterMouseEventFinishes() async {
        let window = ScreenshotInlineTextFocusWindow(acceptedAfterAttempt: 2,
            contentRect: CGRect(x: 0, y: 0, width: 400, height: 300),
            styleMask: [.titled],
            backing: .buffered,
            defer: false
        )
        window.animationBehavior = .none
        defer {
            drainAppKitAnimationTransactions()
            window.orderOut(nil)
            drainAppKitAnimationTransactions()
        }
        let canvas = ScreenshotEditorCanvasView(frame: window.contentView?.bounds ?? .zero)
        canvas.image = NSImage(
            cgImage: solidImage(width: 400, height: 300, color: .white),
            size: NSSize(width: 400, height: 300)
        )
        canvas.visibleSourceRect = ScreenshotPixelRect(x: 0, y: 0, width: 400, height: 300)
        canvas.cropRect = canvas.visibleSourceRect
        let text = ScreenshotElement(
            kind: .text,
            geometry: .rect(ScreenshotPixelRect(x: 40, y: 50, width: 180, height: 48)),
            text: "Draft",
            appearance: .defaultValue(for: .text)
        )
        canvas.sceneElements = [text]
        window.contentView = canvas
        window.makeKeyAndOrderFront(nil)

        canvas.beginInlineTextEditing(for: text.id)
        XCTAssertEqual(window.textResponderAttemptCount, 1)
        XCTAssertFalse(canvas.isInlineTextEditorFirstResponder)
        let focusValidation = expectation(description: "next-run-loop focus validation")
        DispatchQueue.main.async { focusValidation.fulfill() }
        await fulfillment(of: [focusValidation], timeout: 1)

        XCTAssertEqual(window.textResponderAttemptCount, 2)
        XCTAssertTrue(canvas.isInlineTextEditorFirstResponder)
        canvas.commitInlineTextIfNeeded()
    }

