    func testStepClickCreatesNumberAndRequestsInlineNoteEditing() async throws {
        let store = try ScreenshotEditorStore(
            capture: makeExpandableCapture(),
            preferencesStore: ScreenshotPreferencesStore(userDefaults: defaults),
            onComplete: { _ in },
            onRetake: {},
            onClose: {}
        )
        store.selectTool(.step)
        let request = store.inlineTextEditRequestID

        store.beginGesture(at: CGPoint(x: 22, y: 20), modifiers: [])
        store.endGesture(at: CGPoint(x: 22, y: 20), modifiers: [])

        let step = try XCTUnwrap(store.document.snapshot.elements.last)
        XCTAssertEqual(step.kind, .step)
        XCTAssertEqual(step.stepNumber, 1)
        guard case let .step(_, note) = step.geometry else {
            return XCTFail("Expected step geometry")
        }
        XCTAssertNotNil(note, "A step must persist its resolved note region at creation time")
        for _ in 0..<100 where store.inlineTextEditRequestID == request {
            try await Task.sleep(for: .milliseconds(5))
        }
        XCTAssertEqual(store.inlineTextEditRequestID, request + 1)

        store.applyText("", in: .zero, replacing: step.id, sizing: .fixedWidth)
        XCTAssertEqual(store.document.snapshot.elements.last?.id, step.id)
        XCTAssertNil(store.document.snapshot.elements.last?.text)
    }

    func testStepCreationPlacesNoteInsideNonZeroCropAndSwitchesAwayFromBlockedEdge() throws {
        let crop = ScreenshotPixelRect(x: 100, y: 80, width: 300, height: 220)
        let store = try ScreenshotEditorStore(
            capture: makeExpandableCapture(
                sourceWidth: 600,
                sourceHeight: 400,
                initialCropRect: crop
            ),
            preferencesStore: ScreenshotPreferencesStore(userDefaults: defaults),
            onComplete: { _ in },
            onRetake: {},
            onClose: {}
        )
        store.selectTool(.step)
        let isContained: (ScreenshotPixelRect) -> Bool = { rect in
            rect.x >= crop.x
                && rect.y >= crop.y
                && rect.x + rect.width <= crop.x + crop.width
                && rect.y + rect.height <= crop.y + crop.height
        }

        store.beginGesture(at: CGPoint(x: 385, y: 160), modifiers: [])
        store.endGesture(at: CGPoint(x: 385, y: 160), modifiers: [])
        let rightEdgeStep = try XCTUnwrap(store.document.snapshot.elements.last)
        let rightParts = try stepParts(of: rightEdgeStep)
        XCTAssertLessThanOrEqual(rightParts.note.x + rightParts.note.width, Int(rightParts.badgeCenter.x))
        XCTAssertTrue(isContained(rightParts.note))

        store.endInlineTextEditing()
        store.beginGesture(at: CGPoint(x: 115, y: 220), modifiers: [])
        store.endGesture(at: CGPoint(x: 115, y: 220), modifiers: [])
        let leftEdgeStep = try XCTUnwrap(store.document.snapshot.elements.last)
        let leftParts = try stepParts(of: leftEdgeStep)
        XCTAssertGreaterThanOrEqual(leftParts.note.x, Int(leftParts.badgeCenter.x))
        XCTAssertTrue(isContained(leftParts.note))

        store.selectStepComponent(leftEdgeStep.id, component: .note)
        store.adjustAccessibilityTarget(.stepComponent(leftEdgeStep.id, .note), dx: 1_000, dy: 1_000)
        let constrained = try stepParts(of: XCTUnwrap(store.selectedElement))
        XCTAssertTrue(isContained(constrained.note))
    }

    func testCalloutClickCreatesPointTargetArrowAndPersistentEmptyNote() throws {
