    func testCalloutTargetAndNoteNudgesRecomputeNearestConnectorEnds() throws {
        let store = try makeCalloutStore()
        store.beginGesture(at: CGPoint(x: 80, y: 90), modifiers: [])
        store.updateGesture(
            to: CGPoint(x: 150, y: 140),
            points: [CGPoint(x: 80, y: 90), CGPoint(x: 150, y: 140)],
            modifiers: []
        )
        store.endGesture(at: CGPoint(x: 150, y: 140), modifiers: [])
        let id = try XCTUnwrap(store.selectedElementID)
        let original = try XCTUnwrap(store.selectedElement.flatMap(ScreenshotCalloutResolvedLayout.init))

        store.selectCalloutComponent(id, component: .target)
        store.nudgeSelection(dx: 12, dy: 7)
        let targetMoved = try XCTUnwrap(store.selectedElement.flatMap(ScreenshotCalloutResolvedLayout.init))
        XCTAssertNotEqual(targetMoved.target, original.target)
        XCTAssertEqual(targetMoved.noteRect, original.noteRect)
        XCTAssertNotEqual(targetMoved.connector.end, original.connector.end)

        store.selectCalloutComponent(id, component: .note)
        store.nudgeSelection(dx: -9, dy: 13)
        let noteMoved = try XCTUnwrap(store.selectedElement.flatMap(ScreenshotCalloutResolvedLayout.init))
        XCTAssertEqual(noteMoved.target, targetMoved.target)
