    }

    func testCalloutNoteResizePreservesWidthHeightAndTextColor() throws {
        let store = try makeCalloutStore()
        store.beginGesture(at: CGPoint(x: 100, y: 100), modifiers: [])
        store.endGesture(at: CGPoint(x: 100, y: 100), modifiers: [])
        let id = try XCTUnwrap(store.selectedElementID)
        let originalLayout = try XCTUnwrap(store.selectedElement.flatMap(ScreenshotCalloutResolvedLayout.init))

        var style = try XCTUnwrap(store.selectedElement).appearance
        style.calloutTextColor = .init(red: 0.9, green: 0.1, blue: 0.2, alpha: 1)
        store.updateSelectedStyle(style, commitsImmediately: true)
        store.applyText(
            "红色气泡文字",
            in: CGRect(
                x: originalLayout.noteRect.x,
                y: originalLayout.noteRect.y,
                width: originalLayout.noteRect.width,
                height: originalLayout.noteRect.height
            ),
            replacing: id,
            sizing: .fixedWidth
        )

        let beforeHeight = try XCTUnwrap(store.selectedElement.flatMap(ScreenshotCalloutResolvedLayout.init))
        store.adjustAccessibilityTarget(
            .calloutResizeHandle(id, .note, .south),
            dx: 0,
            dy: 36
        )
        let heightResized = try XCTUnwrap(store.selectedElement)
        let heightLayout = try XCTUnwrap(ScreenshotCalloutResolvedLayout(element: heightResized))
        XCTAssertEqual(heightResized.textBoxSizing, .fixedBox)
        XCTAssertEqual(heightLayout.noteRect.width, beforeHeight.noteRect.width)
        XCTAssertGreaterThan(heightLayout.noteRect.height, beforeHeight.noteRect.height)

        store.adjustAccessibilityTarget(
            .calloutResizeHandle(id, .note, .east),
            dx: 42,
            dy: 0
        )
        let widthResized = try XCTUnwrap(store.selectedElement)
        let widthLayout = try XCTUnwrap(ScreenshotCalloutResolvedLayout(element: widthResized))
        XCTAssertGreaterThan(widthLayout.noteRect.width, heightLayout.noteRect.width)
        XCTAssertEqual(widthLayout.noteRect.height, heightLayout.noteRect.height)
        XCTAssertEqual(widthResized.appearance.calloutTextColor, style.calloutTextColor)
        XCTAssertTrue(
            widthLayout.connector.start.x == Double(widthLayout.noteRect.x)
                || widthLayout.connector.start.x == Double(widthLayout.noteRect.x + widthLayout.noteRect.width)
                || widthLayout.connector.start.y == Double(widthLayout.noteRect.y)
                || widthLayout.connector.start.y == Double(widthLayout.noteRect.y + widthLayout.noteRect.height)
        )
    }

