    func testCompositeCalloutDraftBitmapContainsTextDuringDrag() throws {
        let canvas = ScreenshotEditorCanvasView(
            frame: CGRect(x: 0, y: 0, width: 480, height: 260)
        )
        canvas.image = NSImage(
            cgImage: solidImage(width: 480, height: 260, color: .white),
            size: NSSize(width: 480, height: 260)
        )
        canvas.visibleSourceRect = .init(x: 0, y: 0, width: 480, height: 260)
        canvas.cropRect = canvas.visibleSourceRect
        var element = ScreenshotElement(
            kind: .callout,
            geometry: .calloutComposite(
                target: .point(.init(x: 80, y: 120)),
                note: .init(x: 190, y: 70, width: 220, height: 90)
            ),
            text: "Text remains visible",
            textBoxSizing: .fixedWidth,
            appearance: .defaultValue(for: .callout)
        )

        func renderedBytes() throws -> Data {
            let bitmap = try XCTUnwrap(
                canvas.bitmapImageRepForCachingDisplay(in: canvas.bounds)
            )
            canvas.cacheDisplay(in: canvas.bounds, to: bitmap)
            let count = bitmap.bytesPerRow * bitmap.pixelsHigh
            return Data(
                bytes: try XCTUnwrap(bitmap.bitmapData),
                count: count
            )
        }

        canvas.draftElement = element
        let withText = try renderedBytes()
        element.text = nil
        canvas.draftElement = element
        let withoutText = try renderedBytes()

        XCTAssertNotEqual(withText, withoutText)
    }

