    func testMagnifierClickAlwaysCreatesDefaultDiameterRegardlessOfActiveStyle() throws {
        let store = try ScreenshotEditorStore(
            capture: makeExpandableCapture(
                sourceWidth: 400,
                sourceHeight: 400,
                initialCropRect: ScreenshotPixelRect(x: 0, y: 0, width: 400, height: 400)
            ),
            preferencesStore: ScreenshotPreferencesStore(userDefaults: defaults),
            onComplete: { _ in },
            onRetake: {},
            onClose: {}
        )
        store.selectTool(.magnifier)
        var nonDefaultStyle = store.activeStyle
        nonDefaultStyle.magnifierDiameter = 200
        store.updateSelectedStyle(nonDefaultStyle, commitsImmediately: true)

        store.beginGesture(at: CGPoint(x: 200, y: 200), modifiers: [])
        store.endGesture(at: CGPoint(x: 200, y: 200), modifiers: [])

        let magnifier = try XCTUnwrap(store.document.snapshot.elements.last)
        guard case let .magnifier(center) = magnifier.geometry else {
            return XCTFail("Expected a single-center magnifier geometry")
        }
        XCTAssertEqual(center, ScreenshotPixelPoint(x: 200, y: 200))
        XCTAssertEqual(magnifier.appearance.magnifierDiameter, ScreenshotMagnifierMetrics.defaultDiameter)
        let bounds = ScreenshotGeometry.bounds(of: magnifier)
        XCTAssertEqual(bounds.width, Int(ScreenshotMagnifierMetrics.defaultDiameter))
        XCTAssertEqual(bounds.height, bounds.width)
        XCTAssertEqual(store.activeStyle.magnifierDiameter, ScreenshotMagnifierMetrics.defaultDiameter)

        var zoomOnly = store.activeStyle
        zoomOnly.effectIntensity = 3.5
        store.updateSelectedStyle(zoomOnly, commitsImmediately: true)
        XCTAssertEqual(
            store.selectedElement?.appearance.magnifierDiameter,
            ScreenshotMagnifierMetrics.defaultDiameter,
            "Changing zoom must not restore the pre-creation diameter"
        )
    }

    func testMagnifierDragCreatesCircleAndClampsDiameterToSupportedRange() throws {
        let minimum = try makeMagnifierElement(
            from: CGPoint(x: 100, y: 100),
            to: CGPoint(x: 110, y: 110),
            sourceSize: 500
        )
        let unconstrained = try makeMagnifierElement(
            from: CGPoint(x: 100, y: 100),
            to: CGPoint(x: 260, y: 220),
            sourceSize: 500
        )
        let maximum = try makeMagnifierElement(
            from: CGPoint(x: 50, y: 50),
            to: CGPoint(x: 450, y: 450),
            sourceSize: 500
        )

        XCTAssertEqual(minimum.appearance.magnifierDiameter, ScreenshotMagnifierMetrics.minimumDiameter)
        XCTAssertEqual(unconstrained.appearance.magnifierDiameter, 160)
        XCTAssertEqual(maximum.appearance.magnifierDiameter, ScreenshotMagnifierMetrics.maximumDiameter)
        for magnifier in [minimum, unconstrained, maximum] {
            let bounds = ScreenshotGeometry.bounds(of: magnifier)
            XCTAssertEqual(bounds.width, bounds.height)
            XCTAssertEqual(Double(bounds.width), magnifier.appearance.magnifierDiameter)
            guard case .magnifier = magnifier.geometry else {
                return XCTFail("Expected a single-center magnifier geometry")
            }
        }

        let store = try makeMagnifierStore(sourceSize: 500)
        store.beginGesture(at: CGPoint(x: 100, y: 100), modifiers: [])
        store.updateGesture(to: CGPoint(x: 260, y: 220), points: [], modifiers: [])
        store.endGesture(at: CGPoint(x: 260, y: 220), modifiers: [])
        XCTAssertEqual(store.activeStyle.magnifierDiameter, 160)
        var zoomOnly = store.activeStyle
        zoomOnly.effectIntensity = 4
        store.updateSelectedStyle(zoomOnly, commitsImmediately: true)
        XCTAssertEqual(store.selectedElement?.appearance.magnifierDiameter, 160)
    }

    func testMagnifierMoveAndEveryCornerResizePreserveSingleCenterCircularLens() throws {
        let store = try ScreenshotEditorStore(
            capture: makeExpandableCapture(
                sourceWidth: 500,
                sourceHeight: 500,
                initialCropRect: ScreenshotPixelRect(x: 0, y: 0, width: 500, height: 500)
            ),
            preferencesStore: ScreenshotPreferencesStore(userDefaults: defaults),
            onComplete: { _ in },
            onRetake: {},
            onClose: {}
        )
        store.selectTool(.magnifier)
        store.beginGesture(at: CGPoint(x: 250, y: 250), modifiers: [])
        store.endGesture(at: CGPoint(x: 250, y: 250), modifiers: [])
        let id = try XCTUnwrap(store.selectedElementID)

        store.adjustAccessibilityTarget(.element(id), dx: 30, dy: -20)

        let moved = try XCTUnwrap(store.selectedElement)
        guard case let .magnifier(movedCenter) = moved.geometry else {
            return XCTFail("Expected a single-center magnifier geometry")
        }
        XCTAssertEqual(movedCenter, ScreenshotPixelPoint(x: 280, y: 230))
        XCTAssertEqual(moved.appearance.magnifierDiameter, ScreenshotMagnifierMetrics.defaultDiameter)

        for handle in [
            ScreenshotResizeHandle.northWest,
            .northEast,
            .southEast,
            .southWest,
        ] {
            let resizeStore = try makeMagnifierStore(sourceSize: 1_000)
            resizeStore.beginGesture(at: CGPoint(x: 500, y: 500), modifiers: [])
            resizeStore.endGesture(at: CGPoint(x: 500, y: 500), modifiers: [])
            let resizeID = try XCTUnwrap(resizeStore.selectedElementID)
            let initial = try XCTUnwrap(resizeStore.selectedElement)
            let initialRect = try XCTUnwrap(ScreenshotMagnifierResolvedLayout(
                element: initial,
                constrainedTo: resizeStore.sourceBounds
            )).lensRect
            let initialCorners = resizeCorners(for: handle, in: initialRect)
            let nearAnchor = ScreenshotPixelPoint(
                x: initialCorners.opposite.x + initialCorners.direction.x * 5,
                y: initialCorners.opposite.y + initialCorners.direction.y * 5
            )

            resizeStore.adjustAccessibilityTarget(
                .magnifierResizeHandle(resizeID, handle),
                dx: nearAnchor.x - initialCorners.moving.x,
                dy: nearAnchor.y - initialCorners.moving.y
            )

            let minimum = try XCTUnwrap(resizeStore.selectedElement)
            let minimumRect = try XCTUnwrap(ScreenshotMagnifierResolvedLayout(
                element: minimum,
                constrainedTo: resizeStore.sourceBounds
            )).lensRect
            XCTAssertEqual(minimum.appearance.magnifierDiameter, ScreenshotMagnifierMetrics.minimumDiameter)
            XCTAssertEqual(minimumRect.width, minimumRect.height)
            XCTAssertEqual(resizeCorners(for: handle, in: minimumRect).opposite, initialCorners.opposite)

            let minimumCorners = resizeCorners(for: handle, in: minimumRect)
            let pastMaximum = ScreenshotPixelPoint(
                x: minimumCorners.opposite.x + minimumCorners.direction.x * 800,
                y: minimumCorners.opposite.y + minimumCorners.direction.y * 800
            )
            resizeStore.adjustAccessibilityTarget(
                .magnifierResizeHandle(resizeID, handle),
                dx: pastMaximum.x - minimumCorners.moving.x,
                dy: pastMaximum.y - minimumCorners.moving.y
            )

            let maximum = try XCTUnwrap(resizeStore.selectedElement)
            let maximumRect = try XCTUnwrap(ScreenshotMagnifierResolvedLayout(
                element: maximum,
                constrainedTo: resizeStore.sourceBounds
            )).lensRect
            XCTAssertEqual(maximum.appearance.magnifierDiameter, ScreenshotMagnifierMetrics.maximumDiameter)
            XCTAssertEqual(maximumRect.width, maximumRect.height)
            XCTAssertEqual(resizeCorners(for: handle, in: maximumRect).opposite, initialCorners.opposite)
        }
    }

    func testMagnifierMovementAndAccessibilityStayInsideNonZeroCrop() throws {
        let crop = ScreenshotPixelRect(x: 100, y: 80, width: 300, height: 200)
        let store = try ScreenshotEditorStore(
