    func testSplitStepCreatesOrderedIndependentObjectsAndUndoRestoresComposite() throws {
        let (store, id) = try makeStepStoreWithNote()
        store.selectStepComponent(id, component: .note)
        let original = store.document.snapshot
        let originalAppearance = try XCTUnwrap(store.selectedElement).appearance.stepAppearance
        let originalRevision = store.document.revision

        store.splitSelectedStep()

        XCTAssertEqual(store.document.snapshot.elements.map(\.kind), [.arrow, .text, .counter])
        XCTAssertEqual(store.document.revision, originalRevision + 1)
        XCTAssertEqual(store.selectedElement?.kind, .text)
        guard case let .line(connector) = store.document.snapshot.elements[0].appearance.payload,
              case let .text(note) = store.document.snapshot.elements[1].appearance.payload,
              case let .counter(badge) = store.document.snapshot.elements[2].appearance.payload else {
            return XCTFail("Expected split connector, note, and badge appearances")
        }
        XCTAssertEqual(connector, originalAppearance.connector)
        XCTAssertEqual(note, originalAppearance.note)
        XCTAssertEqual(badge, originalAppearance.badge)
        store.undo()
        XCTAssertEqual(store.document.snapshot, original)
    }

