        XCTAssertEqual(noteResized.note.x, badgeResized.note.x)
        XCTAssertEqual(noteResized.note.y, badgeResized.note.y)
        XCTAssertGreaterThan(noteResized.note.width, badgeResized.note.width)

        store.adjustAccessibilityTarget(
            .stepResizeHandle(id, .note, .south),
            dx: 0,
            dy: 24
        )

        let noteHeightResized = try stepParts(of: XCTUnwrap(store.selectedElement))
        XCTAssertEqual(noteHeightResized.badgeCenter, noteResized.badgeCenter)
        XCTAssertEqual(noteHeightResized.badgeSize, noteResized.badgeSize)
        XCTAssertEqual(noteHeightResized.note.x, noteResized.note.x)
        XCTAssertEqual(noteHeightResized.note.y, noteResized.note.y)
        XCTAssertEqual(noteHeightResized.note.width, noteResized.note.width)
        XCTAssertGreaterThan(noteHeightResized.note.height, noteResized.note.height)
    }

    func testStepBadgeCornerResizeKeepsOppositeAnchorAtMinimumAndMaximum() throws {
        for handle in [
            ScreenshotResizeHandle.northWest,
            .northEast,
            .southEast,
            .southWest,
        ] {
            let store = try ScreenshotEditorStore(
                capture: makeExpandableCapture(
                    sourceWidth: 1_000,
                    sourceHeight: 1_000,
                    initialCropRect: .init(x: 0, y: 0, width: 1_000, height: 1_000)
                ),
                preferencesStore: ScreenshotPreferencesStore(userDefaults: defaults),
                onComplete: { _ in },
                onRetake: {},
                onClose: {}
            )
            store.selectTool(.step)
            _ = store.beginGesture(at: CGPoint(x: 500, y: 500), modifiers: [])
            store.endGesture(at: CGPoint(x: 500, y: 500), modifiers: [])
            let id = try XCTUnwrap(store.selectedElementID)
            let initialLayout = try XCTUnwrap(store.selectedElement.flatMap(ScreenshotStepResolvedLayout.init))
            let initialCorners = resizeCorners(for: handle, in: initialLayout.badgeRect)
            let nearAnchor = ScreenshotPixelPoint(
                x: initialCorners.opposite.x + initialCorners.direction.x * 2,
                y: initialCorners.opposite.y + initialCorners.direction.y * 2
            )

            store.adjustAccessibilityTarget(
                .stepResizeHandle(id, .badge, handle),
                dx: nearAnchor.x - initialCorners.moving.x,
                dy: nearAnchor.y - initialCorners.moving.y
            )

            let minimumLayout = try XCTUnwrap(store.selectedElement.flatMap(ScreenshotStepResolvedLayout.init))
            XCTAssertEqual(minimumLayout.badgeDiameter, 18)
            XCTAssertEqual(
                resizeCorners(for: handle, in: minimumLayout.badgeRect).opposite,
                initialCorners.opposite
            )

            let minimumCorners = resizeCorners(for: handle, in: minimumLayout.badgeRect)
            let pastMaximum = ScreenshotPixelPoint(
                x: minimumCorners.opposite.x + minimumCorners.direction.x * 400,
                y: minimumCorners.opposite.y + minimumCorners.direction.y * 400
            )
            store.adjustAccessibilityTarget(
                .stepResizeHandle(id, .badge, handle),
                dx: pastMaximum.x - minimumCorners.moving.x,
                dy: pastMaximum.y - minimumCorners.moving.y
            )

            let maximumLayout = try XCTUnwrap(store.selectedElement.flatMap(ScreenshotStepResolvedLayout.init))
            XCTAssertEqual(maximumLayout.badgeDiameter, 160)
            XCTAssertEqual(
                resizeCorners(for: handle, in: maximumLayout.badgeRect).opposite,
                initialCorners.opposite
            )
        }
    }

