    func testStepNoteMouseDragWithMultipleUpdatesCommitsAsOneUndoTransaction() async throws {
        let (store, id) = try makeStepStoreWithNote()
        try await waitForEditorRender(store)
        store.selectStepComponent(id, component: .note)
        try await Task.sleep(for: .milliseconds(80))
        let original = store.document.snapshot
        let originalRevision = store.document.revision
        let note = try XCTUnwrap(ScreenshotStepResolvedLayout(
            element: XCTUnwrap(store.selectedElement)
        )?.noteRect)
        let start = CGPoint(x: note.x + note.width / 2, y: note.y + note.height / 2)

        XCTAssertEqual(store.beginGesture(at: start, modifiers: []), .handled)
        store.updateGesture(
            to: CGPoint(x: start.x + 10, y: start.y + 6),
            points: [],
            modifiers: []
        )
        store.updateGesture(
            to: CGPoint(x: start.x + 24, y: start.y + 14),
            points: [],
            modifiers: []
        )
        XCTAssertNotEqual(store.document.presentedSnapshot, original)
        store.endGesture(at: CGPoint(x: start.x + 24, y: start.y + 14), modifiers: [])

        XCTAssertEqual(store.document.revision, originalRevision + 1)
        XCTAssertNotEqual(store.document.snapshot, original)
        store.undo()
        XCTAssertEqual(store.document.snapshot, original)
    }

    func testStepInlineEditingBaseLeavesTranslucentNoteChromeToOneEditorLayer() throws {
        for alpha in [0.9, 0.45] {
            let stepAppearance = ScreenshotStepAppearance(
                badgeFillColor: .accentRed,
                noteBackgroundColor: .init(red: 0.1, green: 0.1, blue: 0.1, alpha: alpha),
                noteTextColor: .white,
                noteBorderColor: .accentRed,
                noteBorderWidth: 2,
                gap: 12
            )
            let step = ScreenshotElement(
                kind: .step,
                geometry: .step(
                    badgeCenter: .init(x: 30, y: 50),
                    note: .init(x: 60, y: 30, width: 120, height: 40)
                ),
                text: "Editing",
                stepNumber: 1,
                appearance: .step(stepAppearance)
            )
            let editingBase = try XCTUnwrap(ScreenshotStepEditorLayout.editingBaseElement(from: step))
            let baseAppearance = editingBase.appearance.stepAppearance
            XCTAssertEqual(editingBase.text, "")
            XCTAssertEqual(baseAppearance.noteBackgroundColor.alpha, 0)
            XCTAssertEqual(baseAppearance.noteBorderWidth, 0)

            let source = solidImage(width: 200, height: 100, color: .white)
            let renderedBase = try ScreenshotRenderer().render(
                source: source,
                snapshot: .init(
                    cropRect: .init(x: 0, y: 0, width: 200, height: 100),
                    elements: [editingBase]
                )
            )
            let noteCenter = try XCTUnwrap(bitmapColor(renderedBase, x: 120, y: 50))
            XCTAssertGreaterThan(noteCenter.redComponent, 0.98)
            XCTAssertGreaterThan(noteCenter.greenComponent, 0.98)
            XCTAssertGreaterThan(noteCenter.blueComponent, 0.98)

            let inlineAppearance = ScreenshotStepEditorLayout.inlineTextAppearance(from: step.appearance)
            let inlineAttributes = ScreenshotInlineTextAttributes(
                appearance: inlineAppearance,
                sourceUnitsPerViewPoint: 1
            )
            XCTAssertEqual(inlineAttributes.backgroundColor.alphaComponent, alpha, accuracy: 0.001)
        }
    }

