    func testTextResizeMouseAndAccessibilityHandlesClampToNonZeroCrop() throws {
        let crop = ScreenshotPixelRect(x: 100, y: 80, width: 300, height: 200)
        func cgRect(_ rect: ScreenshotPixelRect) -> CGRect {
            CGRect(x: rect.x, y: rect.y, width: rect.width, height: rect.height)
        }
        let cropBounds = cgRect(crop)
        func point(for handle: ScreenshotResizeHandle, in bounds: CGRect) -> CGPoint {
            let x = switch handle {
            case .northWest, .west, .southWest: bounds.minX
            case .north, .south: bounds.midX
            case .northEast, .east, .southEast: bounds.maxX
            }
            let y = switch handle {
            case .northWest, .north, .northEast: bounds.minY
            case .west, .east: bounds.midY
            case .southWest, .south, .southEast: bounds.maxY
            }
            return CGPoint(x: x, y: y)
        }
        func destination(for handle: ScreenshotResizeHandle, from point: CGPoint) -> CGPoint {
            let resizesFromLeadingEdge: Bool
            let resizesFromTopEdge: Bool
            switch handle {
            case .northWest, .west, .southWest:
                resizesFromLeadingEdge = true
            case .north, .northEast, .east, .southEast, .south:
                resizesFromLeadingEdge = false
            }
            switch handle {
            case .northWest, .north, .northEast:
                resizesFromTopEdge = true
            case .west, .east, .southWest, .south, .southEast:
                resizesFromTopEdge = false
            }
            return CGPoint(
                x: resizesFromLeadingEdge ? cropBounds.minX - 1_000 : cropBounds.maxX + 1_000,
                y: resizesFromTopEdge ? cropBounds.minY - 1_000 : cropBounds.maxY + 1_000
            )
        }
        func assertInsideCrop(_ bounds: CGRect, file: StaticString = #filePath, line: UInt = #line) {
            XCTAssertGreaterThanOrEqual(bounds.minX, cropBounds.minX, file: file, line: line)
            XCTAssertGreaterThanOrEqual(bounds.minY, cropBounds.minY, file: file, line: line)
            XCTAssertLessThanOrEqual(bounds.maxX, cropBounds.maxX, file: file, line: line)
            XCTAssertLessThanOrEqual(bounds.maxY, cropBounds.maxY, file: file, line: line)
        }

        for handle in ScreenshotResizeHandle.allCases {
            let mouseStore = try ScreenshotEditorStore(
                capture: makeExpandableCapture(sourceWidth: 600, sourceHeight: 400, initialCropRect: crop),
                preferencesStore: ScreenshotPreferencesStore(userDefaults: defaults),
                onComplete: { _ in }, onRetake: {}, onClose: {}
            )
            mouseStore.selectTool(.text)
            mouseStore.applyText("text", in: CGRect(x: 160, y: 120, width: 80, height: 40), sizing: .auto)
            let mouseBounds = cgRect(ScreenshotGeometry.bounds(of: try XCTUnwrap(mouseStore.selectedElement).geometry))
            let mouseStart = point(for: handle, in: mouseBounds)
            XCTAssertEqual(mouseStore.beginGesture(at: mouseStart, modifiers: []), .handled)
            mouseStore.updateGesture(to: destination(for: handle, from: mouseStart), points: [], modifiers: [])
            mouseStore.endGesture(at: destination(for: handle, from: mouseStart), modifiers: [])
            let resizedMouse = try XCTUnwrap(mouseStore.selectedElement)
            assertInsideCrop(cgRect(ScreenshotGeometry.bounds(of: resizedMouse.geometry)))
            XCTAssertEqual(resizedMouse.textBoxSizing, .fixedBox)

            let accessibilityStore = try ScreenshotEditorStore(
                capture: makeExpandableCapture(sourceWidth: 600, sourceHeight: 400, initialCropRect: crop),
                preferencesStore: ScreenshotPreferencesStore(userDefaults: defaults),
                onComplete: { _ in }, onRetake: {}, onClose: {}
            )
            accessibilityStore.selectTool(.text)
            accessibilityStore.applyText("text", in: CGRect(x: 160, y: 120, width: 80, height: 40), sizing: .auto)
            let id = try XCTUnwrap(accessibilityStore.selectedElementID)
            let accessibilityBounds = cgRect(ScreenshotGeometry.bounds(of: try XCTUnwrap(accessibilityStore.selectedElement).geometry))
            let accessibilityStart = point(for: handle, in: accessibilityBounds)
            let target = destination(for: handle, from: accessibilityStart)
            accessibilityStore.adjustAccessibilityTarget(
                .resizeHandle(id, handle),
                dx: target.x - accessibilityStart.x,
                dy: target.y - accessibilityStart.y
            )
            let resizedAccessibility = try XCTUnwrap(accessibilityStore.selectedElement)
            assertInsideCrop(cgRect(ScreenshotGeometry.bounds(of: resizedAccessibility.geometry)))
            XCTAssertEqual(resizedAccessibility.textBoxSizing, .fixedBox)
        }
    }

