    func testRenderPipelineSuppressesAStaleCompletionThatFinishesLast() async throws {
        let firstStarted = expectation(description: "first render started")
        let secondCompleted = expectation(description: "second render completed")
        let releaseFirst = DispatchSemaphore(value: 0)
        let source = solidImage(width: 8, height: 8, color: .systemBlue)
        let bounds = ScreenshotPixelRect(x: 0, y: 0, width: 8, height: 8)
        let sourceContext = ScreenshotSourceContext(
            sourceBounds: bounds,
            tileDescriptors: [ScreenshotSourceTileDescriptor(id: "source", bounds: bounds)],
            compositeSource: source
        )
        let pipeline = ScreenshotRenderPipeline { _, request in
            if request.revision.rawValue == 1 {
                firstStarted.fulfill()
                _ = releaseFirst.wait(timeout: .now() + 2)
            }
            return source
        }
        var completedRevisions: [UInt64] = []
        let first = ScreenshotSceneRenderRequest(
            revision: .init(rawValue: 1),
            snapshot: .init(cropRect: bounds)
        )
        let second = ScreenshotSceneRenderRequest(
            revision: .init(rawValue: 2),
            snapshot: .init(cropRect: bounds)
        )

        pipeline.submit(sourceContext: sourceContext, request: first) { result in
            completedRevisions.append(result.revision.rawValue)
        }
        await fulfillment(of: [firstStarted], timeout: 1)
        pipeline.submit(sourceContext: sourceContext, request: second) { result in
            completedRevisions.append(result.revision.rawValue)
            secondCompleted.fulfill()
        }
        releaseFirst.signal()
        await fulfillment(of: [secondCompleted], timeout: 1)
        try await Task.sleep(for: .milliseconds(80))

        XCTAssertEqual(completedRevisions, [2])
    }

    func testEditorAccessibilityModelOrdersCropElementsAndSelectedHandles() {
