    func testInspectorSliderChangesCommitAsOneUndoStep() throws {
        let store = try ScreenshotEditorStore(
            capture: makeCapture(),
            preferencesStore: ScreenshotPreferencesStore(userDefaults: defaults),
            onComplete: { _ in },
            onRetake: {},
            onClose: {}
        )
        store.selectTool(.rectangle)
        store.beginGesture(at: CGPoint(x: 2, y: 2), modifiers: [])
        store.updateGesture(to: CGPoint(x: 18, y: 18), points: [], modifiers: [])
        store.endGesture(at: CGPoint(x: 18, y: 18), modifiers: [])
        let revisionAfterCreation = store.document.revision

        store.beginStyleEditing()
        var style = store.activeStyle
        style.lineWidth = 5
        store.updateSelectedStyle(style)
        style.lineWidth = 8
        store.updateSelectedStyle(style)
        store.endStyleEditing()

        XCTAssertEqual(store.document.revision, revisionAfterCreation + 1)
        XCTAssertEqual(store.selectedElement?.appearance.lineWidth, 8)
        store.undo()
        XCTAssertEqual(store.selectedElement, nil)
        XCTAssertEqual(
            store.document.snapshot.elements.first?.appearance.lineWidth,
            ScreenshotElementAppearance.defaultValue(for: .rectangle).lineWidth
        )
    }

