            pasteboardWriter: pasteboard,
            permissionRefresher: {},
            permissionSnapshotProvider: { fatalError("Action execution does not query GUI permission state") }
        )
        var willFinalizeAuthorization: Bool?
        store.configureCoordinator(
            statusRecorder: { _ in },
            retakeHandler: { _ in },
            dispatchPluginEvent: { envelope in
                if envelope.name == .screenshotWillFinalizeOutput {
                    willFinalizeAuthorization = envelope.authorization.userInitiated
                }
                return .allowed(envelope)
            }
        )
        let input = try ScreenshotCaptureActionInput(
            kind: .smart,
            interaction: .interactive,
            copy: false
        )

        let result = try await store.executeAction(input, outputFile: nil)

        XCTAssertEqual(result.pasteboard, .succeeded)
        XCTAssertEqual(pasteboard.writeCount, 1)
        XCTAssertEqual(willFinalizeAuthorization, true)
    }

