    func testLiveOverlayRoutesHostedMouseEventsIntoRegionCapture() throws {
        let controller = ScreenshotSelectionController()
        controller.prepareForInputTesting(intent: .smart, candidates: [], displays: [])
        let panel = ScreenshotSelectionPanel(
            contentRect: CGRect(x: 0, y: 0, width: 800, height: 600)
        )
        let overlay = ScreenshotSelectionOverlayView(
            frame: CGRect(x: 0, y: 0, width: 800, height: 600),
            controller: controller
        )
        panel.contentView = overlay
        overlay.layoutSubtreeIfNeeded()
        panel.orderFrontRegardless()
        defer {
            closeAppKitFixtureWindow(panel)
            drainAppKitAnimationTransactions()
        }

        panel.sendEvent(try mouseEvent(
            type: .leftMouseDown,
            location: CGPoint(x: 100, y: 100),
            windowNumber: panel.windowNumber
        ))
        panel.sendEvent(try mouseEvent(
            type: .leftMouseDragged,
            location: CGPoint(x: 240, y: 220),
            windowNumber: panel.windowNumber
        ))
        XCTAssertEqual(controller.stateForTesting, .regionDrawing(
            start: .init(x: 100, y: 100),
            current: .init(x: 240, y: 220)
        ))

        panel.sendEvent(try mouseEvent(
            type: .leftMouseUp,
            location: CGPoint(x: 240, y: 220),
            windowNumber: panel.windowNumber
        ))
        XCTAssertEqual(controller.stateForTesting, .capturing)
    }

