    func testEditingContextQuantizesSharedDisplayEdgesWithoutOverflow() throws {
        let displays = [
            ScreenshotDisplayDescriptor(
                id: 1,
                selectionFrame: ScreenshotSelectionRect(x: 0, y: 0, width: 100, height: 100),
                backingScale: 2
            ),
            ScreenshotDisplayDescriptor(
                id: 2,
                selectionFrame: ScreenshotSelectionRect(x: 100.25, y: 0, width: 100.25, height: 100),
                backingScale: 2
            )
        ]
        let plan = try ScreenshotCapturePlanner().planRegion(
            ScreenshotSelectionRect(x: 50, y: 10, width: 100.5, height: 60),
            displays: displays
        )

        let context = try ScreenshotEditingContextBuilder.make(
            plan: plan,
            displays: displays,
            displayImages: [
                1: solidImage(width: 200, height: 200, color: .systemBlue),
                2: solidImage(width: 201, height: 200, color: .systemGreen)
            ]
        )

        let sourceBounds = context.sourceContext.sourceBounds
        XCTAssertEqual(sourceBounds.width, 401)
        XCTAssertTrue(context.sourceContext.tileDescriptors.allSatisfy { descriptor in
            descriptor.bounds.x >= 0
                && descriptor.bounds.y >= 0
                && descriptor.bounds.x + descriptor.bounds.width <= sourceBounds.width
                && descriptor.bounds.y + descriptor.bounds.height <= sourceBounds.height
        })
        XCTAssertLessThanOrEqual(
            context.initialCropRect.x + context.initialCropRect.width,
            sourceBounds.width
        )
    }

    func testWindowEditingContextCompositesCleanCaptureAboveFrozenDesktop() throws {
        let displays = [ScreenshotDisplayDescriptor(
            id: 7,
            selectionFrame: ScreenshotSelectionRect(x: 0, y: 0, width: 100, height: 100),
            backingScale: 1
        )]
        let plan = try ScreenshotCapturePlanner().planRegion(
            ScreenshotSelectionRect(x: 20, y: 20, width: 40, height: 30),
            displays: displays
        )
        let cleanWindow = solidImage(width: 40, height: 30, color: .systemRed)

        let context = try ScreenshotEditingContextBuilder.make(
            plan: plan,
            displays: displays,
            displayImages: [7: solidImage(width: 100, height: 100, color: .systemBlue)],
            cleanCaptureImage: cleanWindow
        )

        XCTAssertEqual(context.initialCropRect, ScreenshotPixelRect(x: 20, y: 50, width: 40, height: 30))
        XCTAssertEqual(context.sourceContext.tileDescriptors.last?.id, "capture-overlay")
        XCTAssertEqual(context.sourceContext.tileDescriptors.last?.bounds, context.initialCropRect)
        let overlayColor = try XCTUnwrap(bitmapColor(context.sourceContext.compositeSource, x: 40, y: 65))
        let desktopColor = try XCTUnwrap(bitmapColor(context.sourceContext.compositeSource, x: 5, y: 5))
        XCTAssertGreaterThan(overlayColor.redComponent, overlayColor.blueComponent)
        XCTAssertGreaterThan(desktopColor.blueComponent, desktopColor.redComponent)
        let initialOutput = try ScreenshotRenderer().render(
            sourceContext: context.sourceContext,
            snapshot: ScreenshotSceneSnapshot(cropRect: context.initialCropRect)
        )
        XCTAssertEqual(initialOutput.width, cleanWindow.width)
        XCTAssertEqual(initialOutput.height, cleanWindow.height)
        let initialOutputColor = try XCTUnwrap(bitmapColor(initialOutput, x: 20, y: 15))
        XCTAssertGreaterThan(initialOutputColor.redComponent, initialOutputColor.blueComponent)
    }

    func testApplicationAppearanceDoesNotChangeScreenshotOutputPixels() throws {
        let previousAppearance = NSApplication.shared.appearance
        defer { NSApplication.shared.appearance = previousAppearance }

        let capture = makeCapture()
        let context = try XCTUnwrap(capture.editingContext)
        let snapshot = ScreenshotSceneSnapshot(cropRect: context.initialCropRect)
        let renderer = ScreenshotRenderer()
        let encoder = ScreenshotImageEncoder()

        NSApplication.shared.appearance = NSAppearance(named: .aqua)
        let lightOutput = try renderer.render(
            sourceContext: context.sourceContext,
            snapshot: snapshot
        )

        NSApplication.shared.appearance = NSAppearance(named: .darkAqua)
        let darkOutput = try renderer.render(
            sourceContext: context.sourceContext,
            snapshot: snapshot
        )

        XCTAssertEqual(try encoder.pngData(lightOutput), try encoder.pngData(darkOutput))
    }

