            _ = try await ScreenCaptureKitAdapter.editingContext(
                requirement: .required
            ) {
                throw ScreenshotEditingContextError.invalidSourceBounds
            }
            XCTFail("A required editing context must not silently fall back.")
        } catch {
            guard let captureError = error as? ScreenshotCaptureError,
                  case .editingContextUnavailable = captureError else {
