    func testSelectionHandoffFrameSlicesTheEditingCompositeByDisplay() throws {
        let left = solidImage(width: 100, height: 100, color: .systemRed)
        let right = solidImage(width: 100, height: 100, color: .systemBlue)
        let composite = try ScreenshotImageCompositor.compose(
            size: .init(width: 200, height: 100),
            tiles: [
                .init(
                    image: left,
                    destination: .init(x: 0, y: 0, width: 100, height: 100)
                ),
                .init(
                    image: right,
                    destination: .init(x: 100, y: 0, width: 100, height: 100)
                ),
            ]
        )
        let context = ScreenshotEditingContext(
            sourceContext: .init(
                sourceBounds: .init(x: 0, y: 0, width: 200, height: 100),
                tileDescriptors: [],
                compositeSource: composite
            ),
            sourceFrame: CGRect(x: 0, y: 0, width: 200, height: 100),
            screens: [
                .init(displayID: 1, frame: CGRect(x: 0, y: 0, width: 100, height: 100)),
                .init(displayID: 2, frame: CGRect(x: 100, y: 0, width: 100, height: 100)),
            ],
            initialCropRect: .init(x: 0, y: 0, width: 200, height: 100),
            supportsRangeExpansion: true
        )
        let frame = ScreenshotSelectionHandoffFrame(context: context)
        let leftSlice = try XCTUnwrap(frame.image(for: 1))
        let rightSlice = try XCTUnwrap(frame.image(for: 2))

        XCTAssertGreaterThan(
            try XCTUnwrap(bitmapColor(leftSlice, x: 50, y: 50)).redComponent,
            0.8
        )
        XCTAssertGreaterThan(
            try XCTUnwrap(bitmapColor(rightSlice, x: 50, y: 50)).blueComponent,
            0.8
        )
    }

    func testSelectionSurfaceHandoffCompletesOnlyOnce() {
        var completionCount = 0
        let handoff = ScreenshotSelectionSurfaceHandoff {
            completionCount += 1
        }

        XCTAssertTrue(handoff.isPending)
        handoff.complete()
        handoff.complete()

        XCTAssertFalse(handoff.isPending)
        XCTAssertEqual(completionCount, 1)
    }

    func testScreenshotEditorHandoffCancellationRejectsLateAppearanceCompletion() {
        var completionCount = 0
        let coordinator = ScreenshotEditorSelectionHandoffCoordinator()
        let transitionID = UUID()
        let handoff = ScreenshotSelectionSurfaceHandoff {
            completionCount += 1
        }

        coordinator.begin(transitionID: transitionID, handoff: handoff)
        coordinator.cancel()
        coordinator.completeIfCurrent(transitionID: transitionID)

        XCTAssertFalse(handoff.isPending)
        XCTAssertEqual(completionCount, 1)
    }

    func testScreenshotEditorImmediateCloseDuringAppearanceAnimationPressure() {
        for _ in 0..<100 {
            autoreleasepool {
                var completionCount = 0
                let transitionID = UUID()
                let coordinator = ScreenshotEditorSelectionHandoffCoordinator()
                let handoff = ScreenshotSelectionSurfaceHandoff {
                    completionCount += 1
                }
                let panel = ScreenshotEditorPresenter.makeHostPanel(
                    frame: CGRect(x: 40, y: 40, width: 240, height: 160)
                )
                panel.alphaValue = 0
                coordinator.begin(transitionID: transitionID, handoff: handoff)
                panel.orderFrontRegardless()
                BlocksAppKitMotion.animate(
                    window: panel,
                    to: panel.frame,
                    alphaValue: 1,
                    role: .confirmation
                ) {
                    coordinator.completeIfCurrent(transitionID: transitionID)
                }

                BlocksAppKitMotion.cancelAnimations(on: panel)
                coordinator.cancel()
                panel.close()
                drainAppKitAnimationTransactions()

                XCTAssertFalse(handoff.isPending)
                XCTAssertEqual(completionCount, 1)
                XCTAssertFalse(panel.isVisible)
            }
        }
    }

