    func testWindowSurfaceClassifierKeepsAppWindowsAndFloatersButRejectsTransientAndSystemSurfaces() {
        func metadata(
            layer: Int,
            ownerKind: ScreenshotWindowOwnerKind = .regular,
            isAppleOwned: Bool = false,
            isBlocksSelectionSurface: Bool = false
        ) -> ScreenshotWindowSurfaceMetadata {
            ScreenshotWindowSurfaceMetadata(
                layer: layer,
                frame: CGRect(x: 0, y: 0, width: 320, height: 180),
                alpha: 1,
                hasOwningApplication: true,
                ownerKind: ownerKind,
                isAppleOwned: isAppleOwned,
                isBlocksSelectionSurface: isBlocksSelectionSurface
            )
        }

        XCTAssertEqual(
            ScreenshotWindowSurfaceClassifier.role(for: metadata(layer: 0)),
            .appWindow
        )
        XCTAssertEqual(
            ScreenshotWindowSurfaceClassifier.role(for: metadata(layer: 3)),
            .appFloatingSurface
        )
        XCTAssertEqual(
            ScreenshotWindowSurfaceClassifier.role(for: metadata(
                layer: 21,
                ownerKind: .accessory,
                isAppleOwned: true
            )),
            .systemOverlay
        )
        XCTAssertEqual(
            ScreenshotWindowSurfaceClassifier.role(for: metadata(
                layer: 0,
                ownerKind: .accessory,
                isAppleOwned: true
            )),
            .systemOverlay
        )
        XCTAssertEqual(
            ScreenshotWindowSurfaceClassifier.role(for: metadata(
                layer: ScreenshotWindowSurfaceClassifier.transientWindowLevel
            )),
            .transientSurface
        )
        XCTAssertEqual(
            ScreenshotWindowSurfaceClassifier.role(for: metadata(
                layer: 0,
                isBlocksSelectionSurface: true
            )),
            .blocksSelectionSurface
        )
    }

