    func testToolbarPlacementStartsTopCenteredAndClampsToVisibleScreens() {
        let visibleFrame = CGRect(x: -1440, y: 24, width: 1440, height: 876)
        let size = CGSize(width: 310, height: 36)
        let initial = ScreenshotSelectionToolbarPlacement.initialFrame(
            toolbarSize: size,
            pointer: CGPoint(x: -720, y: 400),
            visibleFrames: [visibleFrame]
        )

        XCTAssertEqual(initial.midX, visibleFrame.midX, accuracy: 0.001)
        XCTAssertEqual(initial.maxY, visibleFrame.maxY - 12, accuracy: 0.001)

        let clamped = ScreenshotSelectionToolbarPlacement.clampedFrame(
            CGRect(x: -2_000, y: 1_000, width: size.width, height: size.height),
            visibleFrames: [visibleFrame]
        )
        XCTAssertGreaterThanOrEqual(clamped.minX, visibleFrame.minX)
        XCTAssertLessThanOrEqual(clamped.maxX, visibleFrame.maxX)
        XCTAssertLessThanOrEqual(clamped.maxY, visibleFrame.maxY)
    }

    func testToolbarKeyboardMoveUsesPhysicalArrowKeyCodesAndClampedPlacement() throws {
        let visibleFrame = CGRect(x: 0, y: 0, width: 400, height: 300)
