        let right = try XCTUnwrap(ScreenshotSelectionToolbarPlacement.keyboardMoveDelta(for: 124))
        let movedRight = ScreenshotSelectionToolbarPlacement.clampedFrame(
            frame.offsetBy(dx: right.width, dy: right.height),
