    func testScrollingReadyAndCapturingUseTheSameHUDControllerAndPanel() {
        let hud = ScrollingScreenshotHUDController()
        let selectionRect = CGRect(x: 100, y: 100, width: 740, height: 760)
        hud.showReady(
            selectionRect: selectionRect,
            pixelWidth: 1480,
            pixelHeight: 1520,
            isStartEnabled: true,
            onCommand: { _ in }
        )
        defer { hud.dismiss() }
        let readyWindowNumber = hud.windowNumber
        let presentation = ScrollingScreenshotHUDPresentation(state: hud.state)

        XCTAssertEqual(presentation.phaseTitle, L10n.string("screenshot.scrolling.ready"))
        XCTAssertEqual(presentation.dimensionText, "1,480 × 1,520 px")
        XCTAssertEqual(presentation.commands, [.start, .reselect, .cancel])

        hud.transitionToCapturing(selectionRect: selectionRect, onCommand: { _ in })

        XCTAssertEqual(hud.windowNumber, readyWindowNumber)
        XCTAssertEqual(hud.state.phase, .capturing)
        XCTAssertEqual(
            ScrollingScreenshotHUDPresentation(state: hud.state).commands,
            [.pause, .restart, .finish, .cancel]
        )
    }

    func testScrollingHUDDismissClosesEveryOwnedWindow() {
        let existingWindows = Set(NSApp.windows.map(ObjectIdentifier.init))
        let hud = ScrollingScreenshotHUDController()
        let visibleFrame = NSScreen.main?.visibleFrame
            ?? CGRect(x: 0, y: 0, width: 1_440, height: 900)
        let selectionRect = CGRect(
            x: visibleFrame.midX - 160,
            y: visibleFrame.midY - 120,
            width: 320,
            height: 240
        )
        hud.showReady(
            selectionRect: selectionRect,
            pixelWidth: 640,
            pixelHeight: 480,
            isStartEnabled: true,
            onCommand: { _ in }
        )
        let ownedWindows = NSApp.windows.filter {
            !existingWindows.contains(ObjectIdentifier($0))
                && ($0 is ScrollingScreenshotHUDPanel || $0 is ScreenshotSelectionPanel)
        }
        XCTAssertFalse(ownedWindows.isEmpty)
        let closeExpectations = ownedWindows.map {
            expectation(
                forNotification: NSWindow.willCloseNotification,
                object: $0
            )
        }

        hud.dismiss()
        wait(for: closeExpectations, timeout: 1)

        XCTAssertNil(hud.windowNumber)
        XCTAssertTrue(ownedWindows.allSatisfy { !$0.isVisible })
        XCTAssertTrue(ownedWindows.allSatisfy { $0.contentView == nil })
    }

