    func testFrozenSelectionCancellationDoesNotWaitForNonCooperativeSnapshot() async {
        let controller = ScreenshotSelectionController()
        controller.applyDefaults(ScreenshotCaptureDefaults(freezesFrame: true))
        let provider = SuspendedFrozenSelectionSnapshotProvider()

        let selection = Task { @MainActor in
            await controller.select(
                intent: try! ScreenshotCaptureIntent(kind: .smart),
                candidates: [],
                displays: [],
                frozenSnapshotProvider: { _ in await provider.snapshot() },
                magnifierSnapshotProvider: { [:] },
                onParametersChanged: { _ in },
                timeout: 30
            )
        }
        await provider.waitUntilStarted()
        XCTAssertTrue(controller.selectionActiveForTesting)

        controller.cancel()
        let result = await selection.value

        guard case .cancelled = result else {
            return XCTFail("Cancelling must finish while the frozen snapshot provider is still suspended")
        }
        XCTAssertFalse(controller.selectionActiveForTesting)
        XCTAssertTrue(controller.selectionSurfaceWindowIDs.isEmpty)

        await provider.resume()
        await Task.yield()
        XCTAssertFalse(controller.selectionActiveForTesting)
        XCTAssertTrue(controller.selectionSurfaceWindowIDs.isEmpty)
    }

