        )
        toolbar.appearance = try XCTUnwrap(NSAppearance(named: .aqua))
        toolbar.viewDidChangeEffectiveAppearance()
        let lightBorder = try XCTUnwrap(toolbar.layer?.borderColor)
        func descendants(of view: NSView) -> [NSView] {
            view.subviews + view.subviews.flatMap(descendants)
        }
        let lightIsland = try XCTUnwrap(
            descendants(of: toolbar)
                .compactMap { $0 as? NSStackView }
                .flatMap(\.arrangedSubviews)
                .first(where: {
                    guard let color = $0.layer?.backgroundColor else { return false }
                    return NSColor(cgColor: color)?.alphaComponent ?? 0 > 0
                })?
                .layer?.backgroundColor
        )

        toolbar.appearance = try XCTUnwrap(NSAppearance(named: .darkAqua))
        toolbar.viewDidChangeEffectiveAppearance()
        let darkBorder = try XCTUnwrap(toolbar.layer?.borderColor)
        let darkIsland = try XCTUnwrap(
            descendants(of: toolbar)
                .compactMap { $0 as? NSStackView }
                .flatMap(\.arrangedSubviews)
                .first(where: {
                    guard let color = $0.layer?.backgroundColor else { return false }
                    return NSColor(cgColor: color)?.alphaComponent ?? 0 > 0
                })?
                .layer?.backgroundColor
        )

        XCTAssertNotEqual(lightBorder, darkBorder)
        XCTAssertNotEqual(lightIsland, darkIsland)
    }

