    func testScreenshotRuntimeDisableDoesNotLetOldOutputClearNewCancellationHandler() async {
        var enabled = true
        let firstArchiveStarted = expectation(description: "first archive started")
        let secondArchiveStarted = expectation(description: "second archive started")
        let newHandlerInstalled = expectation(description: "new output handler installed")
        var archiveStarts = 0
        var handlerInstallations = 0
        let capture = makeCapture()
        let archive = SuspendingScreenshotArchiveWriter(onStart: {
            archiveStarts += 1
            if archiveStarts == 1 {
                firstArchiveStarted.fulfill()
            } else if archiveStarts == 2 {
                secondArchiveStarted.fulfill()
            }
        })
        let editor = EditorPresenterStub(
            allowsNewCapture: true,
            onFinalOutputCancellationHandlerInstalled: {
                handlerInstallations += 1
                if handlerInstallations == 2 {
                    newHandlerInstalled.fulfill()
                }
            }
        )
        let store = ScreenshotStore(
            captureService: CaptureServiceStub(capture: capture),
            editorPresenter: editor,
            preferencesStore: ScreenshotPreferencesStore(userDefaults: defaults),
            pasteboardWriter: ScreenshotPasteboardWriterSpy(),
            archiveWriter: archive,
            featureEnabled: { enabled },
            permissionRefresher: {},
            permissionSnapshotProvider: { self.grantedPermissionSnapshot() }
        )

        let firstStartResult = await store.startSmartScreenshot()
        XCTAssertEqual(firstStartResult, .completed)
        let oldCompletion = Task { @MainActor in
            await editor.finish(.completed(capture.image))
        }
        await fulfillment(of: [firstArchiveStarted], timeout: 1)

        enabled = false
        store.disableRuntime()
        enabled = true
        let secondStartResult = await store.startSmartScreenshot()
        XCTAssertEqual(secondStartResult, .completed)

        let newCompletion = Task { @MainActor in
            await editor.finish(.completed(capture.image))
        }
        await fulfillment(of: [newHandlerInstalled], timeout: 1)
        archive.resume()
        await fulfillment(of: [secondArchiveStarted], timeout: 1)

        editor.cancelFinalOutput()
        XCTAssertEqual(editor.finalOutputCancellationRequestCount, 1)
        archive.resume()
        await oldCompletion.value
        await newCompletion.value
    }

