    func testScrollingHUDNarrowWidthsReserveEveryCommandHitTarget() {
        let slotCount = ScrollingScreenshotHUDPresentation.ActionSlot.allCases.count
        let actionWidth = CGFloat(slotCount)
            * BlocksVisualTokens.Control.minimumHitTarget
            + CGFloat(slotCount - 1) * BlocksVisualTokens.Spacing.xxs
            + BlocksVisualTokens.Spacing.xxs * 2

        for visibleWidth in [CGFloat(320), 280, 220, 186] {
            let panelFrame = ScrollingScreenshotHUDPlacement.frame(
                proposedOrigin: .zero,
                visibleFrame: CGRect(
                    x: 0,
                    y: 0,
                    width: visibleWidth,
                    height: 400
                )
            )
            let metrics = ScrollingScreenshotHUDLayout.metrics(
                for: panelFrame.width
            )
            let contentWidth = panelFrame.width
                - BlocksVisualTokens.Spacing.sm * 2
            let statusSpacing = metrics.showsVisualStatus
                ? BlocksVisualTokens.Spacing.sm
                : 0

            XCTAssertLessThanOrEqual(
                metrics.statusWidth + statusSpacing + actionWidth,
                contentWidth,
                "Every command must remain inside a \(visibleWidth)pt visible frame."
            )
            XCTAssertGreaterThanOrEqual(
                actionWidth,
                CGFloat(slotCount)
                    * BlocksVisualTokens.Control.minimumHitTarget
            )
        }
    }

