    func testFinalOutputCancellationAfterEncodingStartsSkipsAllSinks() async {
        let preferences = ScreenshotPreferencesStore(userDefaults: testDefaults())
        let encodingProbe = SuspendedScreenshotPNGEncodingProbe(
            data: Data([0x89, 0x50, 0x4e, 0x47])
        )
        let pasteboard = FinalizedArtifactPasteboardWriterSpy()
        let history = FinalizedArtifactArchiveWriterSpy()
        let coordinator = ScreenshotFinalOutputCoordinator(
            preferencesStore: preferences,
            pasteboardWriter: pasteboard,
            archiveWriter: history,
            pngEncoder: { image in encodingProbe.encode(image) }
        )
        let capture = makeCapture()

        let finalization = Task { @MainActor in
            await coordinator.finalize(
                capture: capture,
                image: capture.image,
                writesPasteboard: true
            )
        }
        await encodingProbe.waitUntilStarted()
        finalization.cancel()
        let cancellationReturned = expectation(description: "cancelled finalization returned")
        let cancellationResult = Task { @MainActor in
            let result = await finalization.value
            cancellationReturned.fulfill()
            return result
        }
        await fulfillment(of: [cancellationReturned], timeout: 0.5)
        let result = await cancellationResult.value

        XCTAssertTrue(result.isCancelled)
        XCTAssertNil(pasteboard.artifact)
        XCTAssertNil(history.artifact)
        XCTAssertEqual(pasteboard.legacyImageWriteCount, 0)
        XCTAssertEqual(history.legacyImageWriteCount, 0)

        let nextCapture = makeCapture()
        let nextResult = await coordinator.finalize(
            capture: nextCapture,
            image: nextCapture.image,
            writesPasteboard: true
        )
        XCTAssertEqual(nextResult.pasteboard, .succeeded)
        XCTAssertEqual(nextResult.archive, .succeeded)

        encodingProbe.resume()
    }

    func testFinalOutputCancellationAfterWillHookPublishesCancelledTerminalAndReleasesGate() async {
        let preferences = ScreenshotPreferencesStore(userDefaults: testDefaults())
        let pasteboard = FinalizedArtifactPasteboardWriterSpy()
        let history = FinalizedArtifactArchiveWriterSpy()
        let coordinator = ScreenshotFinalOutputCoordinator(
            preferencesStore: preferences,
            pasteboardWriter: pasteboard,
            archiveWriter: history
        )
        let first = makeCapture(id: "cancel-after-will")
        let second = makeCapture(id: "after-cancel")
        let firstWillStarted = expectation(
            description: "first will-finalize hook started"
        )
        var firstWillContinuation: CheckedContinuation<Void, Never>?
        var events: [(name: BlocksPluginEventName, captureID: String, code: String?)] = []
        coordinator.configurePluginPlatform(
            dispatchPluginEvent: { envelope in
                events.append(
                    (envelope.name, envelope.sessionID ?? "", envelope.payload.string("code"))
                )
                if envelope.name == .screenshotWillFinalizeOutput,
                   envelope.sessionID == first.id {
                    firstWillStarted.fulfill()
                    await withCheckedContinuation { continuation in
                        firstWillContinuation = continuation
                    }
                }
                return .allowed(envelope)
            },
            dispatchTerminalPluginEvent: { envelope, _ in
                events.append(
                    (envelope.name, envelope.sessionID ?? "", envelope.payload.string("code"))
                )
                return .allowed(envelope)
            },
            registerResource: { _, _, _, _ in nil },
            removeResources: { _ in }
        )

        let firstTask = Task { @MainActor in
            await coordinator.finalize(
                capture: first,
                image: first.image,
                writesPasteboard: true
            )
        }
        await fulfillment(of: [firstWillStarted], timeout: 1)
        firstTask.cancel()
        firstWillContinuation?.resume()
        firstWillContinuation = nil
        let firstResult = await firstTask.value

        XCTAssertTrue(firstResult.isCancelled)
        XCTAssertNil(pasteboard.artifact)
        XCTAssertNil(history.artifact)
        XCTAssertEqual(
            events.map { $0.name },
            [.screenshotWillFinalizeOutput, .screenshotOutputFailed]
        )
        XCTAssertEqual(events.last?.captureID, first.id)
        XCTAssertEqual(events.last?.code, "cancelled")

        let secondResult = await coordinator.finalize(
            capture: second,
            image: second.image,
            writesPasteboard: true
        )
        XCTAssertFalse(secondResult.isCancelled)
        XCTAssertEqual(secondResult.pasteboard, .succeeded)
        XCTAssertEqual(secondResult.archive, .succeeded)
        XCTAssertEqual(pasteboard.artifact?.captureID, second.id)
        XCTAssertEqual(history.artifact?.captureID, second.id)
    }

    func testFinalOutputRevocationAfterDurableArchiveCommitKeepsTruthAndSuppressesTerminalEvent()
        async throws
    {
        let preferences = ScreenshotPreferencesStore(userDefaults: testDefaults())
        let pasteboard = FinalizedArtifactPasteboardWriterSpy()
        let archiveCommitted = expectation(description: "archive durable commit")
        let history = GatedFinalizedArtifactArchiveWriter(
            pauseAfterDurableCommit: true,
            onReachedPause: { archiveCommitted.fulfill() }
        )
        defer { history.resume() }
        let coordinator = ScreenshotFinalOutputCoordinator(
            preferencesStore: preferences,
            pasteboardWriter: pasteboard,
            archiveWriter: history
        )
        var eventNames: [BlocksPluginEventName] = []
        coordinator.configurePluginPlatform(
            dispatchPluginEvent: { envelope in
                eventNames.append(envelope.name)
                return .allowed(envelope)
            },
            registerResource: { _, _, _, _ in nil },
            removeResources: { _ in }
        )
        let capture = makeCapture()
        var isCurrent = true

        let finalization = Task { @MainActor in
