    func testFinalOutputArchiveCancellationAfterInvocationPublishesFailureAndReleasesGate() async {
        let preferences = ScreenshotPreferencesStore(userDefaults: testDefaults())
        let pasteboard = FinalizedArtifactPasteboardWriterSpy()
        let history = CancellingAfterFinalizedArtifactArchiveWriter()
        let coordinator = ScreenshotFinalOutputCoordinator(
            preferencesStore: preferences,
            pasteboardWriter: pasteboard,
            archiveWriter: history
        )
        var eventNames: [BlocksPluginEventName] = []
        var failedTerminalCaptureIDs: [String] = []
        var finishedTerminalCaptureIDs: [String] = []
        coordinator.configurePluginPlatform(
            dispatchPluginEvent: { envelope in
                eventNames.append(envelope.name)
                if envelope.name == .screenshotOutputFailed {
                    failedTerminalCaptureIDs.append(envelope.sessionID ?? "")
                }
                if envelope.name == .screenshotOutputFinished {
                    finishedTerminalCaptureIDs.append(envelope.sessionID ?? "")
                }
                return .allowed(envelope)
            },
            registerResource: { _, _, _, _ in nil },
            removeResources: { _ in }
        )
        let first = makeCapture(id: "archive-cancel-first")

        let firstResult = await coordinator.finalize(
            capture: first,
            image: first.image,
            writesPasteboard: true
        )

        XCTAssertFalse(firstResult.isCancelled)
        XCTAssertEqual(firstResult.pasteboard, .succeeded)
        XCTAssertEqual(firstResult.archive, .failed)
        XCTAssertEqual(pasteboard.artifact?.captureID, first.id)
        XCTAssertEqual(history.artifacts.map(\.captureID), [first.id])
        XCTAssertEqual(failedTerminalCaptureIDs, [first.id])
        XCTAssertTrue(finishedTerminalCaptureIDs.isEmpty)
        XCTAssertEqual(
            eventNames,
            [.screenshotWillFinalizeOutput, .screenshotOutputFailed]
        )

        let second = makeCapture(id: "archive-cancel-second")
        let secondResult = await coordinator.finalize(
            capture: second,
            image: second.image,
            writesPasteboard: true
        )

        XCTAssertFalse(secondResult.isCancelled)
        XCTAssertEqual(secondResult.pasteboard, .succeeded)
        XCTAssertEqual(secondResult.archive, .succeeded)
        XCTAssertEqual(pasteboard.artifact?.captureID, second.id)
        XCTAssertEqual(history.artifacts.map(\.captureID), [first.id, second.id])
        XCTAssertEqual(failedTerminalCaptureIDs, [first.id])
        XCTAssertEqual(finishedTerminalCaptureIDs, [second.id])
        XCTAssertEqual(
            eventNames,
            [
                .screenshotWillFinalizeOutput,
                .screenshotOutputFailed,
                .screenshotWillFinalizeOutput,
                .screenshotOutputFinished,
            ]
        )
    }

    func testFinalOutputSerializesBlockedWillHookBeforeNewerSinksAndTerminalEvent() async {
        let preferences = ScreenshotPreferencesStore(userDefaults: testDefaults())
        let first = makeCapture(id: "first")
        let second = makeCapture(id: "second")
        let pasteboard = FinalizedArtifactPasteboardWriterSpy()
        let history = FinalizedArtifactArchiveWriterSpy()
        let coordinator = ScreenshotFinalOutputCoordinator(
            preferencesStore: preferences,
            pasteboardWriter: pasteboard,
            archiveWriter: history
        )
        var willFinalizeCaptureIDs: [String] = []
        var terminalCaptureIDs: [String] = []
        var firstWillFinalizeStarted = false
        var firstWillFinalizeContinuation: CheckedContinuation<Void, Never>?
        coordinator.configurePluginPlatform(
            dispatchPluginEvent: { envelope in
                if envelope.name == .screenshotWillFinalizeOutput {
                    willFinalizeCaptureIDs.append(envelope.sessionID ?? "")
                }
                if envelope.name == .screenshotWillFinalizeOutput, envelope.sessionID == first.id {
                    firstWillFinalizeStarted = true
                    await withCheckedContinuation { continuation in
                        firstWillFinalizeContinuation = continuation
                    }
                }
                if envelope.name == .screenshotOutputFinished
                    || envelope.name == .screenshotOutputFailed {
                    terminalCaptureIDs.append(envelope.sessionID ?? "")
                }
                return .allowed(envelope)
            },
            registerResource: { _, _, _, _ in nil },
            removeResources: { _ in }
        )

        let firstFinalization = Task { @MainActor in
            await coordinator.finalize(
                capture: first,
                image: first.image,
                writesPasteboard: true
            )
        }
        while !firstWillFinalizeStarted { await Task.yield() }

        var secondFinalizationStarted = false
        let secondFinalization = Task { @MainActor in
            secondFinalizationStarted = true
            return await coordinator.finalize(
                capture: second,
                image: second.image,
                writesPasteboard: true
            )
        }
        while !secondFinalizationStarted { await Task.yield() }
        await Task.yield()

        XCTAssertEqual(willFinalizeCaptureIDs, [first.id])
        XCTAssertNil(pasteboard.artifact)
        XCTAssertNil(history.artifact)
        XCTAssertTrue(terminalCaptureIDs.isEmpty)

        firstWillFinalizeContinuation?.resume()
        firstWillFinalizeContinuation = nil
        let firstResult = await firstFinalization.value
        let secondResult = await secondFinalization.value

        XCTAssertEqual(firstResult.pasteboard, .succeeded)
        XCTAssertEqual(firstResult.archive, .succeeded)
        XCTAssertEqual(secondResult.pasteboard, .succeeded)
        XCTAssertEqual(secondResult.archive, .succeeded)
        XCTAssertEqual(pasteboard.artifact?.captureID, second.id)
        XCTAssertEqual(history.artifact?.captureID, second.id)
        XCTAssertEqual(willFinalizeCaptureIDs, [first.id, second.id])
        XCTAssertEqual(terminalCaptureIDs, [first.id, second.id])
    }

