    func testFinalOutputKeepsGateUntilTerminalDispatcherCompletes() async {
        let preferences = ScreenshotPreferencesStore(userDefaults: testDefaults())
        let first = makeCapture(id: "terminal-first")
        let second = makeCapture(id: "terminal-second")
        let pasteboard = FinalizedArtifactPasteboardWriterSpy()
        let history = FinalizedArtifactArchiveWriterSpy()
        let coordinator = ScreenshotFinalOutputCoordinator(
            preferencesStore: preferences,
            pasteboardWriter: pasteboard,
            archiveWriter: history
        )
        var willFinalizeCaptureIDs: [String] = []
        var terminalStartedCaptureIDs: [String] = []
        var terminalCompletedCaptureIDs: [String] = []
        var firstTerminalContinuation: CheckedContinuation<Void, Never>?
        coordinator.configurePluginPlatform(
            dispatchPluginEvent: { envelope in
                if envelope.name == .screenshotWillFinalizeOutput {
                    willFinalizeCaptureIDs.append(envelope.sessionID ?? "")
                }
                return .allowed(envelope)
            },
            dispatchTerminalPluginEvent: { envelope, _ in
                terminalStartedCaptureIDs.append(envelope.sessionID ?? "")
                if envelope.sessionID == first.id {
                    await withCheckedContinuation { continuation in
                        firstTerminalContinuation = continuation
                    }
                }
                terminalCompletedCaptureIDs.append(envelope.sessionID ?? "")
                return .allowed(envelope)
            },
            registerResource: { _, _, _, _ in nil },
            removeResources: { _ in }
        )

        let firstFinalization = Task { @MainActor in
            await coordinator.finalize(
                capture: first,
                image: first.image,
                writesPasteboard: true
            )
        }
        while terminalStartedCaptureIDs.isEmpty { await Task.yield() }

        let secondFinalization = Task { @MainActor in
            await coordinator.finalize(
                capture: second,
                image: second.image,
                writesPasteboard: true
            )
        }
        await Task.yield()

        XCTAssertEqual(willFinalizeCaptureIDs, [first.id])
        XCTAssertEqual(pasteboard.artifact?.captureID, first.id)
        XCTAssertEqual(history.artifact?.captureID, first.id)
        XCTAssertEqual(terminalStartedCaptureIDs, [first.id])
        XCTAssertTrue(terminalCompletedCaptureIDs.isEmpty)

        firstTerminalContinuation?.resume()
        firstTerminalContinuation = nil
        _ = await firstFinalization.value
        _ = await secondFinalization.value

        XCTAssertEqual(willFinalizeCaptureIDs, [first.id, second.id])
        XCTAssertEqual(pasteboard.artifact?.captureID, second.id)
        XCTAssertEqual(history.artifact?.captureID, second.id)
        XCTAssertEqual(terminalStartedCaptureIDs, [first.id, second.id])
        XCTAssertEqual(terminalCompletedCaptureIDs, [first.id, second.id])
    }

