        coordinator.configurePluginPlatform(
            dispatchPluginEvent: { envelope in
                if envelope.name == .screenshotWillFinalizeOutput, envelope.sessionID == first.id {
                    firstWillFinalizeStarted = true
                    await withCheckedContinuation { continuation in
                        firstWillFinalizeContinuation = continuation
                    }
                }
                if envelope.name == .screenshotOutputFinished
                    || envelope.name == .screenshotOutputFailed {
                    terminalCaptureIDs.append(envelope.sessionID ?? "")
                }
                return .allowed(envelope)
            },
