        let origin = ClipboardPasteboardWriteOrigin(
            operationID: UUID(),
            recordID: "history-record",
            signatureSHA256: String(repeating: "a", count: 64)
        )

        let lease = try await writer.write(
            payload: ClipboardRecorderPayload(
                recordID: origin.recordID,
                kind: .text,
                text: "fixture"
            ),
            origin: origin
        )

        let representation = try XCTUnwrap(
            pasteboard.items.first?.representations[ClipboardPasteboardWriteOrigin.pasteboardType]
        )
        guard case let .string(encodedOrigin) = representation else {
            return XCTFail("The Blocks write-origin marker must be a string representation.")
        }
        XCTAssertEqual(ClipboardPasteboardWriteOrigin.decode(encodedOrigin), origin)
        XCTAssertTrue(suppressor.consume(lease.changeCount))
    }

    func testLiveCaptureConfirmsMarkedBlocksWriteWithoutCreatingDuplicateHistory() async throws {
        let pasteboard = NSPasteboard(
            name: NSPasteboard.Name("ScreenshotAppStateTests.\(UUID().uuidString)")
        )
        let suppressor = ClipboardPasteboardChangeSuppressor()
        let writer = ClipboardPasteboardWriter(
            pasteboard: DirectClipboardPasteboard(pasteboard: pasteboard),
            changeSuppressor: suppressor
        )
        let broker = TestClipboardObservationBroker(reader: pasteboard)
        let liveCapture = ClipboardLiveCaptureService(
            pollInterval: 60,
            broker: broker
        )
        var capturedRecordIDs: [String] = []
        liveCapture.start { capturedRecordIDs.append($0.record.id) }
        defer { liveCapture.stop() }
        await waitForClipboardServiceBaseline(liveCapture)

        let lease = try await writer.write(
            payload: ClipboardRecorderPayload(
                recordID: "marked-history-record",
                kind: .text,
                text: "fixture"
            ),
            origin: ClipboardPasteboardWriteOrigin(
                operationID: UUID(),
                recordID: "marked-history-record",
                signatureSHA256: String(repeating: "b", count: 64)
            )
        )
        await broker.suppress(lease.changeCount)
        liveCapture.pollPasteboard()
        await waitForClipboardService(
            liveCapture,
            observedChangeCount: pasteboard.changeCount
        )

        XCTAssertTrue(capturedRecordIDs.isEmpty)
        XCTAssertNotNil(ClipboardPasteboardWriteOrigin.decode(
