    func testAutoPasteCopiesBeforeTargetValidationAndReportsPartialFailure() async throws {
        let pasteboard = ScriptedClipboardPasteboard(
            items: [],
            changeCount: 15,
            writeOutcomes: [true]
        )
        let coordinator = ClipboardAutoPasteCoordinator(
            pasteboard: pasteboard,
            changeSuppressor: ClipboardPasteboardChangeSuppressor()
        )
        let record = ClipboardRecorderRecord(
            id: "copy-before-target",
            createdAt: Date(timeIntervalSince1970: 1_000),
            changeCount: 15,
            kind: .text,
            formatSummary: ClipboardRecorderFormatSummary(
                itemCount: 1,
                types: ["public.utf8-plain-text"],
                byteCount: 7
            ),
            sourceApp: nil,
            signatureSHA256_12: "copy-target",
            fixtureOwned: true,
            restorable: true,
            summary: "fixture"
        )

        let copyResult = try await coordinator.copyToPasteboard(
            record: record,
            payload: ClipboardRecorderPayload(
                recordID: record.id,
                kind: .text,
                text: "fixture"
            ),
            expectedPasteboardChangeCount: 15,
            operationID: UUID()
        )

        let lease = copyResult.pasteboardLease
        XCTAssertEqual(lease.changeCount, 16)
        XCTAssertTrue(copyResult.mayContinueAutomaticPaste)
        do {
            _ = try await coordinator.dispatchPaste(
                targetContext: nil,
                pasteboardLease: lease,
                promptForAccessibility: false
            )
            XCTFail("Dispatch should fail without a target after the copy has succeeded.")
        } catch let failure as ClipboardAutoPastePartialFailure {
            XCTAssertEqual(failure.reason, .targetApplicationUnavailable)
            XCTAssertEqual(failure.pasteboardChangeCountAfterWrite, lease.changeCount)
        }
    }

    func testAutoPasteCopyReturnsPhysicalLeaseButStopsAutomaticPasteWhenOperationInvalidates() async throws {
        let pasteboard = ScriptedClipboardPasteboard(
            items: [],
            changeCount: 15,
            writeOutcomes: [true]
        )
        let coordinator = ClipboardAutoPasteCoordinator(
            pasteboard: pasteboard,
            changeSuppressor: ClipboardPasteboardChangeSuppressor()
        )
        let record = ClipboardRecorderRecord(
            id: "copy-invalidated-after-write",
            createdAt: Date(timeIntervalSince1970: 1_000),
            changeCount: 15,
            kind: .text,
            formatSummary: .init(itemCount: 1, types: ["public.utf8-plain-text"]),
            sourceApp: nil,
            signatureSHA256_12: "copy-invalid",
            fixtureOwned: true,
            restorable: true,
            summary: "fixture"
        )
        var operationCheckCount = 0

        let result = try await coordinator.copyToPasteboard(
            record: record,
            payload: ClipboardRecorderPayload(
                recordID: record.id,
                kind: .text,
                text: "replacement"
            ),
            expectedPasteboardChangeCount: 15,
            operationID: UUID(),
            operationAllowed: {
                operationCheckCount += 1
                // copyToPasteboard checks once before entering the writer and
                // the direct backend checks again immediately before the
                // synchronous AppKit mutation. Invalidate only after both
                // authorization fences have admitted the physical write.
                return operationCheckCount <= 2
            }
        )

        XCTAssertEqual(result.pasteboardLease.changeCount, 16)
        XCTAssertFalse(result.mayContinueAutomaticPaste)
        XCTAssertEqual(operationCheckCount, 3)
        XCTAssertEqual(pasteboard.items.first?.representations[.string], .string("replacement"))
    }

