    func testRealBrokerCommitBeforeFeatureDisablePersistsRecencyWithoutLateEffects()
        async throws
    {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "ClipboardRealBrokerLifecycle-\(UUID().uuidString)",
                isDirectory: true
            )
