        let broker = RealBrokerCommitReturnGate(
            client: client,
            onPhysicalCommit: { physicalCommit.fulfill() }
        )
        let repository = ClipboardRepository(database: database)
        let originalCopiedAt = Date(timeIntervalSince1970: 1_000)
        let signature = String(repeating: "c", count: 64)
        let record = ClipboardRecorderRecord(
            id: "real-broker-lifecycle-paste",
            createdAt: originalCopiedAt,
            changeCount: 0,
            kind: .text,
            formatSummary: .init(
                itemCount: 1,
                types: ["public.utf8-plain-text"],
                textLength: 11,
                byteCount: 11
            ),
            sourceApp: nil,
            signatureSHA256: signature,
            signatureSHA256_12: String(signature.prefix(12)),
            fixtureOwned: true,
            restorable: true,
            lastCopiedAt: originalCopiedAt,
            summary: "replacement"
        )
        _ = try repository.insert(
            record: record,
            payload: .init(
                recordID: record.id,
                kind: .text,
                text: "replacement"
            )
        )
        let store = ClipboardStore(repository: repository)
        store.records = [record]
        let availability = FeatureAvailabilityStore(defaults: testDefaults())
        var postedPasteShortcutCount = 0
        let target = makeEditablePasteFocusContext(
            application: .current,
            identity: "real-broker-lifecycle-target"
        )
        let coordinator = ClipboardFeatureCoordinator(
            clipboardStore: store,
            privacyStore: PrivacyStore(repository: nil),
            featureAvailabilityStore: availability,
            autoPasteCoordinator: ClipboardAutoPasteCoordinator(
                broker: broker,
                frontmostApplication: { .current },
                focusSnapshot: { _ in target },
                eventPostingAccess: { _ in true },
                pasteShortcutFactory: makePasteShortcutForTesting,
                pasteShortcutPoster: { _ in postedPasteShortcutCount += 1 }
            )
        )
        var statuses: [AppStatus] = []
        var pluginEvents: [BlocksPluginEventName] = []
        coordinator.configure(
            statusRecorder: { statuses.append($0) },
            sectionSelector: { _ in },
            closeTranslationPanel: {},
            translateRecord: { _ in },
            refreshPermissionState: {},
            dispatchPluginEvent: { envelope in
                pluginEvents.append(envelope.name)
                return .allowed(envelope)
            },
            stagePluginTextResource: { _, _, _, _ in nil },
            removePluginResources: { _ in },
            accessibilityGranted: { true },
            presentAccessibilityAssist: { _ in }
        )

        coordinator.startPaste(coordinator.makePendingPasteRequest(
            recordID: record.id,
            targetContext: target,
            promptForAccessibility: false
        ))
        await fulfillment(of: [physicalCommit], timeout: 5)

        XCTAssertEqual(pasteboard.string(forType: .string), "replacement")
        XCTAssertNotNil(pasteboard.string(
            forType: ClipboardPasteboardWriteOrigin.pasteboardType
        ))
        let committedLeaseCount = await broker.committedLeaseCount()
        XCTAssertEqual(committedLeaseCount, 1)

        let staleTask = try XCTUnwrap(coordinator.pasteTask)
        availability.setClipboardEnabled(false)
        coordinator.disableRuntime()
        let statusCountAfterDisable = statuses.count
        let notificationAfterDisable = coordinator.notificationCoordinator
            .presentationState.current
        await broker.releaseCommitReturn()
        await staleTask.value

        XCTAssertEqual(store.pasteAttempt?.state, .pasteboardWritten)
        XCTAssertNotEqual(store.records.first?.lastCopiedAt, originalCopiedAt)
        XCTAssertNotEqual(
            try repository.loadRecord(recordID: record.id)?.lastCopiedAt,
            originalCopiedAt
        )
        XCTAssertEqual(postedPasteShortcutCount, 0)
        XCTAssertEqual(statuses.count, statusCountAfterDisable)
        XCTAssertNil(notificationAfterDisable)
        XCTAssertNil(coordinator.notificationCoordinator.presentationState.current)
        XCTAssertFalse(pluginEvents.contains(.clipboardRecordUpdated))
        XCTAssertFalse(pluginEvents.contains(.clipboardDidDispatchPaste))
        XCTAssertFalse(pluginEvents.contains(.clipboardPasteFailed))
    }

