    func testClipboardCopiedFallbackUsesIndependentAutoDismissingHUD() {
        let presenter = ClipboardNotificationPanelPresenterSpy()
        let coordinator = ClipboardNotificationCoordinator(
            fallbackPanelPresenter: presenter
        )

        coordinator.setHostVisible(false)
        coordinator.copiedWithoutAutomaticPaste(
            reason: .targetApplicationUnavailable
        )

        let descriptor = presenter.presentedDescriptors.first
        XCTAssertEqual(presenter.presentedDescriptors.count, 1)
        XCTAssertEqual(descriptor?.level, .warning)
        XCTAssertEqual(
            descriptor?.title,
            L10n.string("status.clipboardPasteCopiedFallback.title")
        )
        XCTAssertEqual(
            descriptor?.detail,
            L10n.string("status.clipboardPasteCopiedFallback.detail")
        )
        XCTAssertEqual(
            descriptor?.dismissPolicy,
            .automatic(after: 4)
        )
        XCTAssertNil(
            coordinator.presentationState.current,
            "A fallback shown after panel closure must not reappear in the next clipboard invocation."
        )

        coordinator.dismissCopiedFallback()
        XCTAssertEqual(
            presenter.dismissCount,
            1,
            "Opening the next clipboard panel must dismiss the previous independent fallback immediately."
        )

        coordinator.shutdown()
        XCTAssertEqual(presenter.shutdownCount, 1)
    }

    func testAutoPasteCancelledDuringLeaseValidationDoesNotPromptOrPost() async throws {
        let broker = ControlledPlainTextCopyBroker(blockValidation: true)
        let application = NSRunningApplication.current
        let target = ClipboardPasteFocusSnapshot(target: ClipboardPasteTarget(application), windowID: 92_001)
        var permissionChecks = 0
        var posts = 0
        let coordinator = ClipboardAutoPasteCoordinator(
            broker: broker,
            frontmostApplication: { application },
            focusSnapshot: { _ in target },
            eventPostingAccess: { _ in permissionChecks += 1; return false },
            optionalTargetInspection: { _ in .unknown },
            pasteShortcutPoster: { _ in posts += 1 }
        )
        let task = Task { @MainActor in
            try? await coordinator.dispatchPaste(targetContext: target, pasteboardLease: .init(changeCount: 1))
        }
        try await broker.waitUntilValidationStarted()
        task.cancel()
        await broker.releaseValidation()
        _ = await task.value
        XCTAssertEqual(permissionChecks, 0)
        XCTAssertEqual(posts, 0)
    }

