    }

    private func assertAutoPasteFocusRejected(
        captured: ClipboardPasteFocusSnapshot,
        revalidated: ClipboardPasteFocusSnapshot,
        application: NSRunningApplication,
        helperEditability: SelectionHelperPasteTargetEditability = .unknown
    ) async throws {
        let pasteboard = ScriptedClipboardPasteboard(
            items: [],
            changeCount: 40,
            writeOutcomes: [true]
        )
        var postedShortcutCount = 0
        let coordinator = ClipboardAutoPasteCoordinator(
            pasteboard: pasteboard,
            changeSuppressor: ClipboardPasteboardChangeSuppressor(),
            frontmostApplication: { application },
            focusSnapshot: { _ in revalidated },
            eventPostingAccess: { _ in true },
            optionalTargetInspection: { _ in helperEditability },
            pasteShortcutFactory: makePasteShortcutForTesting,
            pasteShortcutPoster: { _ in postedShortcutCount += 1 }
        )

        do {
            _ = try await coordinator.dispatchPaste(
                targetContext: captured,
                pasteboardLease: ClipboardPasteboardWriteLease(changeCount: 40),
                promptForAccessibility: false
            )
            XCTFail("An unverifiable or changed editable focus must require manual paste.")
        } catch let failure as ClipboardAutoPastePartialFailure {
            XCTAssertEqual(failure.reason, .targetApplicationUnavailable)
            XCTAssertEqual(failure.pasteboardChangeCountAfterWrite, 40)
        }
        XCTAssertEqual(postedShortcutCount, 0)
        XCTAssertEqual(pasteboard.writeCallCount, 0)
    }

    private func makeEditablePasteFocusContext(
        application: NSRunningApplication,
        windowProcessIdentifier: pid_t = 92_001,
        elementProcessIdentifier: pid_t = 92_002,
        identity: String = "editable-control",
        semantics: ClipboardAXEditableSemantics? = nil
    ) -> ClipboardPasteFocusSnapshot {
        let resolvedSemantics = semantics ?? ClipboardAXEditableSemantics(
            role: "AXTextField",
            enabled: true,
            explicitlyEditable: true,
            valueSettable: true,
            selectedTextSettable: true
        )
        return ClipboardPasteFocusSnapshot(
            target: ClipboardPasteTarget(application),
            focusedWindow: AXUIElementCreateApplication(windowProcessIdentifier),
            focusedElement: AXUIElementCreateApplication(elementProcessIdentifier),
            focusedSemantics: resolvedSemantics,
            focusedIdentity: ClipboardPasteFocusIdentity(
                role: resolvedSemantics.role,
                subrole: nil,
                identifier: identity,
                domIdentifier: nil
            ),
            windowID: CGWindowID(windowProcessIdentifier)
        )
    }

    private func makePasteShortcutForTesting() throws -> (keyDown: CGEvent, keyUp: CGEvent) {
        let source = try XCTUnwrap(CGEventSource(stateID: .hidSystemState))
        return (
            keyDown: try XCTUnwrap(CGEvent(
                keyboardEventSource: source,
                virtualKey: 0x09,
                keyDown: true
            )),
            keyUp: try XCTUnwrap(CGEvent(
                keyboardEventSource: source,
                virtualKey: 0x09,
                keyDown: false
            ))
        )
    }

