    func testScreenshotPasteboardPublishesAnAppOwnedStableFileURL() async throws {
        let pasteboard = NSPasteboard(name: NSPasteboard.Name("ScreenshotAppStateTests.\(UUID().uuidString)"))
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ScreenshotPasteboardArtifacts-\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        let ioProbe = ScreenshotArtifactIOProbe()
        let fileManager = FileManager.default
        let writer = ScreenshotPasteboardWriter(
            artifactStore: ScreenshotPasteboardArtifactStore(
                rootDirectory: root,
                permissionSetter: { url, permissions in
                    ioProbe.record()
                    try fileManager.setAttributes(
                        [.posixPermissions: permissions],
                        ofItemAtPath: url.path
                    )
                }
            )
        )

        _ = try await writer.write(
            makeCapture().image,
            pasteboard: DirectClipboardPasteboard(pasteboard: pasteboard)
        )

        let fileURLString = try XCTUnwrap(pasteboard.string(forType: .fileURL))
        let fileURL = try XCTUnwrap(URL(string: fileURLString))
        XCTAssertTrue(fileURL.path.hasPrefix(root.path))
        XCTAssertTrue(FileManager.default.fileExists(atPath: fileURL.path))
        XCTAssertEqual(try Data(contentsOf: fileURL), pasteboard.data(forType: .png))
        XCTAssertEqual(try posixPermissions(at: fileURL), 0o600)
        XCTAssertFalse(ioProbe.executedOnMainThread.contains(true))
        XCTAssertGreaterThanOrEqual(ioProbe.executedOnMainThread.count, 2)
    }

