    func testScreenshotPasteboardOutOfOrderCompletionNeverDeletesPendingArtifact() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "ScreenshotPasteboardArtifacts-\(UUID().uuidString)",
                isDirectory: true
            )
        defer { try? FileManager.default.removeItem(at: root) }
        let broker = ControlledScreenshotClipboardBroker()
        let writer = ScreenshotPasteboardWriter(
            broker: broker,
            artifactStore: ScreenshotPasteboardArtifactStore(
                rootDirectory: root
            )
        )
        let capture = makeCapture()
        let firstArtifact = FinalizedScreenshotArtifact(
            capture: capture,
            image: capture.image,
            pngData: Data([0x89, 0x50, 0x4e, 0x47, 0x01]),
            pixelSize: CGSize(width: 1, height: 1)
        )
        let secondArtifact = FinalizedScreenshotArtifact(
            capture: capture,
            image: capture.image,
            pngData: Data([0x89, 0x50, 0x4e, 0x47, 0x02]),
            pixelSize: CGSize(width: 1, height: 1)
        )

        let firstTask = Task { @MainActor in
            try await writer.write(firstArtifact)
        }
        try await broker.waitForRequestCount(1)
        let secondTask = Task { @MainActor in
            try await writer.write(secondArtifact)
        }
        try await broker.waitForRequestCount(2)

        let firstURL = try brokerFileURL(
            from: await broker.request(ordinal: 0)
        )
        let secondURL = try brokerFileURL(
            from: await broker.request(ordinal: 1)
        )
        XCTAssertTrue(FileManager.default.fileExists(atPath: firstURL.path))
        XCTAssertTrue(FileManager.default.fileExists(atPath: secondURL.path))

        await broker.complete(ordinal: 1, changeCount: 102)
        _ = try await secondTask.value
        XCTAssertTrue(
            FileManager.default.fileExists(atPath: firstURL.path),
            "A still-pending artifact must be protected."
        )
        XCTAssertTrue(FileManager.default.fileExists(atPath: secondURL.path))

        await broker.complete(ordinal: 0, changeCount: 101)
        _ = try await firstTask.value
        XCTAssertFalse(FileManager.default.fileExists(atPath: firstURL.path))
        XCTAssertTrue(
            FileManager.default.fileExists(atPath: secondURL.path),
            "The newer published file URL must remain valid."
        )
    }

    func testScreenshotPasteboardRevokedAfterPrepareCancelsWithoutCommitOrArtifact() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ScreenshotPasteboardArtifacts-\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        let broker = ControlledScreenshotClipboardBroker(
            pausesPreparedReturn: true
        )
        let writer = ScreenshotPasteboardWriter(
            broker: broker,
            artifactStore: ScreenshotPasteboardArtifactStore(rootDirectory: root)
        )
        var isAllowed = true
        let capture = makeCapture()
        let artifact = FinalizedScreenshotArtifact(
            capture: capture,
            image: capture.image,
            pngData: Data([0x89, 0x50, 0x4e, 0x47]),
            pixelSize: CGSize(width: 1, height: 1)
        )

        let write = Task { @MainActor in
            do {
                _ = try await writer.write(artifact, operationAllowed: { isAllowed })
                XCTFail("Revoked prepared write must not commit.")
            } catch {}
        }
        do {
            try await broker.waitUntilPrepared()
        } catch {
            await broker.releasePreparedReturn()
            write.cancel()
            await write.value
            throw error
        }
        isAllowed = false
        await broker.releasePreparedReturn()
        await write.value

        let commitCount = await broker.commitCount()
        let cancelCount = await broker.cancelCount()
        XCTAssertEqual(commitCount, 0)
        XCTAssertEqual(cancelCount, 1)
        XCTAssertEqual(try FileManager.default.contentsOfDirectory(atPath: root.path), [])
    }

    func testScreenshotArchiveRevokedWhileWaitingForCommitGateDoesNotPersist() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ScreenshotArchiveAdmission-\(UUID().uuidString)", isDirectory: true)
        let database = try AppDatabase.open(
            environment: StorageEnvironment(rootDirectory: root)
        )
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let repository = ClipboardRepository(database: database)
        let gate = ClipboardRecordCommitGate()
        let acquiredPermit = await gate.acquire()
        let heldPermit = try XCTUnwrap(acquiredPermit)
        let reachedGate = expectation(description: "archive reached commit gate")
        let finished = expectation(description: "archive finished")
        var isCurrent = true
        var committedCount = 0
        let coordinator = ScreenshotClipboardArchiveCoordinator(
            repository: repository,
            featureAvailabilityStore: FeatureAvailabilityStore(defaults: testDefaults()),
            onCommitted: { committedCount += 1 },
            recordCommitGate: gate,
            beforeCommitGateAcquire: { reachedGate.fulfill() }
        )
        let capture = makeCapture()
        let artifact = FinalizedScreenshotArtifact(
            capture: capture,
            image: capture.image,
            pngData: Data([0x89, 0x50, 0x4e, 0x47]),
            pixelSize: CGSize(width: 1, height: 1)
        )
        var result: Result<ScreenshotClipboardArchiveResult, Error>?
        let archive = Task { @MainActor in
            defer { finished.fulfill() }
            do {
                result = .success(try await coordinator.archive(
                    artifact: artifact,
                    automaticallyRecognizesText: false,
                    isCurrent: { isCurrent }
                ))
            } catch {
                result = .failure(error)
            }
        }
        await fulfillment(of: [reachedGate], timeout: 1)
        isCurrent = false
        await gate.release(heldPermit)
        await fulfillment(of: [finished], timeout: 1)
        await archive.value

        XCTAssertEqual(try XCTUnwrap(result).get(), .ignoredFeatureDisabled)
        XCTAssertNil(try repository.loadRecord(recordID: capture.id))
        XCTAssertNil(try repository.readPayload(recordID: capture.id))
        XCTAssertEqual(committedCount, 0)
    }

