    func testActionHostCallerCancelBeforeRepositoryAdmissionLeavesNoHistoryOrOutputFile()
        async throws
    {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ScreenshotActionHostCallerCancel-\(UUID().uuidString)", isDirectory: true)
        let database = try AppDatabase.open(environment: StorageEnvironment(rootDirectory: root))
        let blobStore = BlobStore(directory: database.environment.blobDirectory, sidecarThresholdBytes: 1)
        defer {
            database.close()
            try? FileManager.default.removeItem(at: root)
        }
        let reachedAdmission = expectation(description: "action host request reaches repository admission")
        let cancellationApplied = expectation(description: "action host applies matching cancellation")
        let responseReceived = expectation(description: "action host returns cancelled response")
        let cancellationReplyReceived = expectation(description: "action host cancellation reply")
        let releaseAdmission = DispatchSemaphore(value: 0)
        let capture = makeCapture(id: "action-host-caller-cancel-before-admission")
        let repository = ClipboardRepository(database: database, blobStore: blobStore)
        let archive = ScreenshotClipboardArchiveCoordinator(
            repository: repository,
            featureAvailabilityStore: FeatureAvailabilityStore(defaults: testDefaults())
        )
        let store = ScreenshotStore(
            captureService: CaptureServiceStub(capture: capture),
            editorPresenter: EditorPresenterStub(allowsNewCapture: true),
            preferencesStore: ScreenshotPreferencesStore(userDefaults: testDefaults()),
            archiveWriter: archive,
            screenshotHistoryCommitAdmissionFactory: {
#if DEBUG
                ScreenshotHistoryCommitAdmission(beforeAdmitForTesting: {
                    reachedAdmission.fulfill()
                    _ = releaseAdmission.wait(timeout: .now() + 5)
                })
#else
                ScreenshotHistoryCommitAdmission()
#endif
            },
            permissionRefresher: {},
            permissionSnapshotProvider: { self.grantedPermissionSnapshot() }
        )
        let input = try ScreenshotCaptureActionInput(
            kind: .region,
            interaction: .noEditor,
            copy: false
        )
        let requestID = try XCTUnwrap(ActionRequestID(rawValue: "action-host-caller-cancel"))
        let request = ActionBrokerRequest(
            requestID: requestID,
            actionID: BlocksAction.screenshotCapture.actionID,
            payload: input
        )
        let requestData = try JSONEncoder().encode(request)
        let originalOutput = Data("output-must-remain-unchanged".utf8)
        let outputURL = root.appendingPathComponent("output.png")
        XCTAssertTrue(FileManager.default.createFile(atPath: outputURL.path, contents: originalOutput))
        let outputFile = try FileHandle(forWritingTo: outputURL)
        defer { try? outputFile.close() }

        let host: BlocksActionHostXPCProtocol = ScreenshotActionHostService(
            executeHandler: { data, file in
                let decoded = try! JSONDecoder().decode(
                    ActionBrokerRequest<ScreenshotCaptureActionInput>.self,
                    from: data
                )
                do {
                    let result = try await store.executeAction(decoded.payload, outputFile: file)
                    return try! JSONEncoder().encode(.completed(
                        requestID: decoded.requestID,
                        actionID: decoded.actionID,
                        result: result
                    ) as ActionBrokerTerminalResponse<ScreenshotCaptureActionResult>)
                } catch ScreenshotActionExecutionError.cancelled {
                    return try! JSONEncoder().encode(.cancelled(
                        requestID: decoded.requestID,
                        actionID: decoded.actionID,
                        code: "request_cancelled",
                        message: "The screenshot request was cancelled."
                    ) as ActionBrokerTerminalResponse<ScreenshotCaptureActionResult>)
                } catch {
                    return Data()
                }
            },
            cancelHandler: { candidate in
                guard candidate == requestID.rawValue else { return false }
                store.cancelCurrentActionRequest()
                cancellationApplied.fulfill()
                return true
            }
        )

        host.execute(requestData, outputFile: outputFile) { data in
            let response = try? JSONDecoder().decode(
                ActionBrokerTerminalResponse<ScreenshotCaptureActionResult>.self,
                from: data
            )
            XCTAssertEqual(response?.status, .cancelled)
            XCTAssertEqual(response?.requestID, requestID)
            XCTAssertNil(response?.result)
            responseReceived.fulfill()
        }
        await fulfillment(of: [reachedAdmission], timeout: 1)
        host.cancel(requestID.rawValue) { cancelled in
            XCTAssertTrue(cancelled)
            cancellationReplyReceived.fulfill()
        }
        await fulfillment(of: [cancellationApplied], timeout: 1)
        releaseAdmission.signal()
        await fulfillment(of: [responseReceived, cancellationReplyReceived], timeout: 1)

        XCTAssertNil(try repository.loadRecord(recordID: capture.id))
        XCTAssertNil(try repository.readPayload(recordID: capture.id))
        XCTAssertTrue(try FileManager.default.contentsOfDirectory(at: blobStore.directory, includingPropertiesForKeys: nil).isEmpty)
        XCTAssertEqual(try repository.pendingSidecarCleanupCount(), 0)
        XCTAssertEqual(try Data(contentsOf: outputURL), originalOutput)
    }

    func testScreenshotArchiveCallerCancellationBeforeRepositoryAdmissionDoesNotPersist() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "ScreenshotArchiveCallerCancellationBeforeAdmission-\(UUID().uuidString)",
                isDirectory: true
            )
        let database = try AppDatabase.open(
