            try? FileManager.default.removeItem(at: root)
        }
        let reachedAdmission = expectation(description: "repository archive admission reached")
        let finished = expectation(description: "archive task finished")
        let releaseAdmission = DispatchSemaphore(value: 0)
        let capture = makeCapture(id: "caller-cancel-before-repository-admission")
        let repository = ClipboardRepository(database: database, blobStore: blobStore)
        var committedCount = 0
        let archive = ScreenshotClipboardArchiveCoordinator(
            repository: repository,
            featureAvailabilityStore: FeatureAvailabilityStore(defaults: testDefaults()),
            onCommitted: { committedCount += 1 }
        )
#if DEBUG
        let admission = ScreenshotHistoryCommitAdmission(beforeAdmitForTesting: {
            reachedAdmission.fulfill()
            _ = releaseAdmission.wait(timeout: .now() + 5)
        })
#else
        let admission = ScreenshotHistoryCommitAdmission()
#endif
        let captureCGImage = try XCTUnwrap(
            capture.image.cgImage(
                forProposedRect: nil,
                context: nil,
                hints: nil
            )
        )
        let artifact = FinalizedScreenshotArtifact(
            capture: capture,
            image: capture.image,
            pngData: try ScreenshotImageEncoder().pngData(captureCGImage),
            pixelSize: capture.pixelSize
        )
        let task = Task { @MainActor () -> Result<ScreenshotClipboardArchiveResult, Error> in
            defer { finished.fulfill() }
            do {
                return .success(try await archive.archive(
                    artifact: artifact,
                    automaticallyRecognizesText: false,
                    isCurrent: { true },
                    admission: admission
                ))
            } catch {
                return .failure(error)
            }
        }
        defer {
            task.cancel()
            releaseAdmission.signal()
        }

        await fulfillment(of: [reachedAdmission], timeout: 1)
        task.cancel()
        releaseAdmission.signal()
        await fulfillment(of: [finished], timeout: 1)
        let result = await task.value

        XCTAssertThrowsError(try result.get()) {
            XCTAssertTrue($0 is CancellationError)
        }
        XCTAssertNil(try repository.loadRecord(recordID: capture.id))
        XCTAssertNil(try repository.readPayload(recordID: capture.id))
        let blobURLs = try FileManager.default.contentsOfDirectory(
            at: blobStore.directory,
            includingPropertiesForKeys: nil
        )
        XCTAssertTrue(blobURLs.filter { $0.lastPathComponent.contains(".staged.") }.isEmpty)
        XCTAssertTrue(blobURLs.filter { !$0.lastPathComponent.contains(".staged.") }.isEmpty)
        XCTAssertEqual(committedCount, 0)
    }

