    func testScreenshotPasteboardFailureDoesNotRollbackAndSuppressesMutationCount() async throws {
        let original = ClipboardPasteboardWriteItem(
            representations: [.string: .string("keep me")]
        )
        let pasteboard = ScriptedClipboardPasteboard(
            items: [original],
            changeCount: 40,
            writeOutcomes: [false]
        )
        let suppressor = ClipboardPasteboardChangeSuppressor()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ScreenshotPasteboardArtifacts-\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        let writer = ScreenshotPasteboardWriter(
            changeSuppressor: suppressor,
            artifactStore: ScreenshotPasteboardArtifactStore(rootDirectory: root)
        )

        do {
            _ = try await writer.write(makeCapture().image, pasteboard: pasteboard)
            XCTFail("The scripted pasteboard write should fail.")
        } catch {}

        XCTAssertTrue(pasteboard.items.isEmpty)
        XCTAssertEqual(pasteboard.writeCallCount, 1)
        XCTAssertTrue(suppressor.consume(41), "The failed mutation must not be ingested as external content.")
        XCTAssertFalse(suppressor.consume(41), "Each suppression is single-use.")
        XCTAssertFalse(suppressor.consume(42), "A failed write must not attempt a rollback mutation.")
        XCTAssertEqual(try FileManager.default.contentsOfDirectory(atPath: root.path), [])
    }

    func testScreenshotPasteboardPermissionFailurePreventsPublicationAndRemovesArtifact() async throws {
        let pasteboard = ScriptedClipboardPasteboard(items: [], changeCount: 10, writeOutcomes: [true])
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ScreenshotPasteboardArtifacts-\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        let fileManager = FileManager.default
        let store = ScreenshotPasteboardArtifactStore(
            rootDirectory: root,
            permissionSetter: { url, permissions in
                if url.pathExtension == "png" { throw TestFailure.expected }
                try fileManager.setAttributes([.posixPermissions: permissions], ofItemAtPath: url.path)
            }
        )
        let writer = ScreenshotPasteboardWriter(artifactStore: store)

        do {
            _ = try await writer.write(makeCapture().image, pasteboard: pasteboard)
            XCTFail("Invalid artifact permissions must fail before publication.")
        } catch {}

        XCTAssertEqual(pasteboard.writeCallCount, 0)
        XCTAssertEqual(try fileManager.contentsOfDirectory(atPath: root.path), [])
    }

