    func testScreenshotPasteboardCleanupDiagnosticDoesNotExposeArtifactPath() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("private-screenshot-path-\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        let abandonedURL = root.appendingPathComponent("blocks-screenshot-sensitive-name.png")
        try Data([0x01]).write(to: abandonedURL)
        try FileManager.default.setAttributes(
            [.modificationDate: Date().addingTimeInterval(-120)],
            ofItemAtPath: abandonedURL.path
        )
        let currentURL = root.appendingPathComponent("blocks-screenshot-current.png")
        try Data([0x02]).write(to: currentURL)
        var diagnostics: [ScreenshotPasteboardArtifactDiagnostic] = []

        let store = ScreenshotPasteboardArtifactStore(
            rootDirectory: root,
            retentionInterval: 60,
            removeItem: { url in
                throw NSError(
                    domain: "ScreenshotCleanupFixture",
                    code: 77,
                    userInfo: [NSFilePathErrorKey: url.path]
                )
            },
            diagnosticHandler: { diagnostics.append($0) }
        )
        await store.prepare()

        let diagnostic = try XCTUnwrap(diagnostics.first)
        XCTAssertEqual(diagnostic.phase, .startupCleanup)
        XCTAssertEqual(diagnostic.errorDomain, "ScreenshotCleanupFixture")
        XCTAssertEqual(diagnostic.errorCode, 77)
        XCTAssertFalse(diagnostic.description.contains(root.path))
        XCTAssertFalse(diagnostic.description.contains(abandonedURL.lastPathComponent))
    }

    func testScreenshotPasteboardArtifactCleanupRetriesARecoverableRemoveFailure() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ScreenshotArtifactCleanupRetry-\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        let retryFinished = expectation(description: "cleanup retry succeeded")
        let fileManager = FileManager.default
        var removeAttempts = 0
        var diagnostics: [ScreenshotPasteboardArtifactDiagnostic] = []
        let store = ScreenshotPasteboardArtifactStore(
            rootDirectory: root,
            removeItem: { url in
                removeAttempts += 1
                if removeAttempts == 1 {
                    throw NSError(domain: "ScreenshotCleanupFixture", code: 88)
                }
                try fileManager.removeItem(at: url)
                retryFinished.fulfill()
            },
            diagnosticHandler: { diagnostics.append($0) },
            cleanupRetryDelay: .milliseconds(1),
            cleanupRetryLimit: 2
        )
        let artifactURL = try await store.persist(Data([0x89, 0x50, 0x4e, 0x47]))
        await store.remove(artifactURL)

        let pendingAfterFailure = await store.pendingCleanupCount()
        XCTAssertEqual(pendingAfterFailure, 1)
        XCTAssertEqual(diagnostics.first?.phase, .rollbackCleanup)
        await fulfillment(of: [retryFinished], timeout: 1)
        let pendingAfterRetry = await store.pendingCleanupCount()
        XCTAssertEqual(pendingAfterRetry, 0)
        XCTAssertFalse(fileManager.fileExists(atPath: artifactURL.path))
    }

    private func brokerFileURL(
        from request: ClipboardBrokerWriteRequest?
    ) throws -> URL {
        let entry = try XCTUnwrap(
            request?.items.first?.representations.first {
                $0.pasteboardType
                    == NSPasteboard.PasteboardType.fileURL.rawValue
            }
        )
        guard case let .string(value) = entry.value else {
            throw TestFailure.expected
        }
        return try XCTUnwrap(URL(string: value))
    }

    func testEditorSecureFileWriterCreatesPrivateFileAndPreservesExistingPermissions() throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("ScreenshotSecureFileWriter-\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        let writer = ScreenshotSecureFileWriter()
        let newURL = root.appendingPathComponent("new.png")

        try writer.write(Data("new".utf8), to: newURL)
        XCTAssertEqual(try posixPermissions(at: newURL), 0o600)

        let existingURL = root.appendingPathComponent("existing.png")
        try Data("old".utf8).write(to: existingURL)
        try FileManager.default.setAttributes([.posixPermissions: 0o400], ofItemAtPath: existingURL.path)

        try writer.write(Data("replacement".utf8), to: existingURL)

        XCTAssertEqual(try posixPermissions(at: existingURL), 0o400)
        XCTAssertEqual(try Data(contentsOf: existingURL), Data("replacement".utf8))
        XCTAssertTrue(
            try FileManager.default.contentsOfDirectory(atPath: root.path)
                .allSatisfy { !$0.hasPrefix(".blocks-screenshot-") }
        )
    }

