    func testStoreRetriesImmediatelyAfterSingleFrameTimeoutWithoutBusyOrLateStatePollution()
        async throws
    {
        let firstOperation = SingleFrameRequestOperationHarness()
        let secondOperation = SingleFrameRequestOperationHarness()
        let firstImage = solidImage(width: 3, height: 3, color: .systemBlue)
        let secondImage = solidImage(width: 5, height: 5, color: .systemGreen)
        let succeedingCapture = makeCapture()
        let captureService = TimedOutThenSuccessfulSingleFrameCaptureService(
            firstOperation: firstOperation,
            secondOperation: secondOperation,
            succeedingCapture: succeedingCapture
        )
        let store = ScreenshotStore(
            captureService: captureService,
            editorPresenter: EditorPresenterStub(allowsNewCapture: true),
            preferencesStore: ScreenshotPreferencesStore(userDefaults: testDefaults()),
            permissionRefresher: {},
            permissionSnapshotProvider: { self.grantedPermissionSnapshot() }
        )
        let firstStart = Task { @MainActor in
            await store.startSmartScreenshot()
        }
        var secondStart: Task<ScreenshotStartResult, Never>?

        do {
            try await firstOperation.waitUntilStarted()
            let firstResult = await firstStart.value
            XCTAssertEqual(firstResult, .failed)
            XCTAssertTrue(captureService.firstRequestTimedOut)

            secondStart = Task { @MainActor in
                await store.startSmartScreenshot()
            }
            try await secondOperation.waitUntilStarted()

            // The first ScreenCaptureKit request completes after its deadline
            // while the replacement is still pending. It must remain stale.
            await firstOperation.resume(with: firstImage)
            try await firstOperation.waitUntilCompleted()
            XCTAssertNil(captureService.successfulImage)

            await secondOperation.resume(with: secondImage)
            let secondResult = await secondStart!.value
            XCTAssertNotEqual(secondResult, .busy)
            XCTAssertEqual(secondResult, .completed)
            XCTAssertEqual(captureService.captureCount, 2)
            XCTAssertEqual(captureService.successfulImage?.width, secondImage.width)
            XCTAssertEqual(captureService.successfulImage?.height, secondImage.height)
            XCTAssertEqual(
                store.lastCaptureSummary,
                L10n.format(
                    "capture.summary",
                    Int(succeedingCapture.pixelSize.width),
                    Int(succeedingCapture.pixelSize.height),
                    succeedingCapture.kind.localizedTitle
                )
            )
        } catch {
            await firstOperation.resume(with: firstImage)
            await secondOperation.resume(with: secondImage)
            _ = await firstStart.value
            if let secondStart {
                _ = await secondStart.value
            }
            throw error
        }
    }

