    func testManualOCRTimeoutUnlocksWithoutWaitingForUncooperativeRecognizerAndDropsLateResult() async throws {
        let harness = NonCooperativeManualOCRHarness()
        let coordinator = ScreenshotManualOCRCoordinator(timeout: .milliseconds(20)) { _ in
            await harness.recognize()
        }
        let image = solidImage(width: 20, height: 20, color: .white)
        let firstRegion = ScreenshotPixelRect(x: 0, y: 0, width: 8, height: 8)
        let secondRegion = ScreenshotPixelRect(x: 4, y: 4, width: 8, height: 8)

        _ = coordinator.recognize(image: image, region: firstRegion, revision: 10)
        try await harness.waitForRequestCount(1)
        try await Task.sleep(for: .milliseconds(50))
        guard case let .failed(_, region, revision, reason) = coordinator.state else {
            return XCTFail("Expected first request to time out")
        }
        XCTAssertEqual(region, firstRegion)
        XCTAssertEqual(revision, 10)
        XCTAssertEqual(reason, .timedOut)
        XCTAssertFalse(coordinator.state.isLocked)

        _ = coordinator.recognize(image: image, region: secondRegion, revision: 11)
        try await harness.waitForRequestCount(2)
        await harness.resume(request: 1, text: "current")
        try await waitForManualOCRToFinish(coordinator)
        guard case let .result(_, region, revision, text) = coordinator.state else {
            return XCTFail("Expected second request result")
        }
        XCTAssertEqual(region, secondRegion)
        XCTAssertEqual(revision, 11)
        XCTAssertEqual(text, "current")

        await harness.resume(request: 0, text: "late")
        try await Task.sleep(for: .milliseconds(30))
        guard case let .result(_, finalRegion, finalRevision, finalText) = coordinator.state else {
            return XCTFail("Late result must not replace the current terminal state")
        }
        XCTAssertEqual(finalRegion, secondRegion)
        XCTAssertEqual(finalRevision, 11)
        XCTAssertEqual(finalText, "current")
    }

