    func testPinnedScreenshotOCRCopyGatePersistsAcrossRetryUntilPriorWriteCompletes() async throws {
        let copyHarness = SuspendedPinnedOCRCopyHarness()
        var attempts = 0
        let controller = makePinnedScreenshotController(
            recognizeOCRText: { _, _ in
                attempts += 1
                return attempts == 1 ? "first result" : "replacement result"
            },
            writePlainText: { text in await copyHarness.write(text) }
        )
        defer { controller.closeForTesting() }

        controller.startTestingOCR()
        await controller.waitForTestingOCRTask()
        controller.copyTestingOCRText()
        let firstCopy = try XCTUnwrap(controller.testingOCRCopyTask)
        try await copyHarness.waitForWriteCount(1)

        controller.retryTestingOCR()
        await controller.waitForTestingOCRTask()
        controller.copyTestingOCRText()
        try await Task.sleep(for: .milliseconds(20))
        let copiedBeforeFirstWriteCompletes = await copyHarness.copiedTexts
        XCTAssertEqual(copiedBeforeFirstWriteCompletes, ["first result"])

        await copyHarness.resume()
        await firstCopy.value
        controller.copyTestingOCRText()
        let secondCopy = try XCTUnwrap(controller.testingOCRCopyTask)
        try await copyHarness.waitForWriteCount(2)
        let copiedAfterFirstWriteCompletes = await copyHarness.copiedTexts
        XCTAssertEqual(copiedAfterFirstWriteCompletes, ["first result", "replacement result"])
        await copyHarness.resume()
        await secondCopy.value
    }

    func testPinnedScreenshotClosingParentLetsCommittedOCRCopyFinishWithoutLateUIFeedback() async throws {
        let copyHarness = SuspendedPinnedOCRCopyHarness()
        let preResumedCopyHarness = SuspendedPinnedOCRCopyHarness()
        await preResumedCopyHarness.resume()
        await preResumedCopyHarness.resume()
        await preResumedCopyHarness.write("resume-before-write")
        let preResumedTexts = await preResumedCopyHarness.copiedTexts
        XCTAssertEqual(preResumedTexts, ["resume-before-write"])

        let controller = makePinnedScreenshotController(
            recognizeOCRText: { _, _ in "recognized text" },
            writePlainText: { text in
                await copyHarness.write(text)
            }
        )
        var suspendedCopyTask: Task<Void, Never>?

        do {
            controller.startTestingOCR()
            let recognitionObserverTask = controller.testingOCRTask
            await recognitionObserverTask?.value
            let childPanel = try XCTUnwrap(controller.testingOCRPanel)

            controller.copyTestingOCRText()
            suspendedCopyTask = controller.testingOCRCopyTask
            let copyTask = try XCTUnwrap(suspendedCopyTask)
            try await copyHarness.waitForWriteCount(1)
            controller.closeForTesting()
            drainAppKitAnimationTransactions()

            XCTAssertFalse(childPanel.isVisible)
            XCTAssertNil(controller.testingOCRPanel)
            XCTAssertNil(controller.testingOCRCopyFeedback)

            await copyHarness.resume()
            await copyTask.value

            let copiedTexts = await copyHarness.copiedTexts
            XCTAssertEqual(copiedTexts, ["recognized text"])
            XCTAssertNil(controller.testingOCRPanel)
            XCTAssertNil(controller.testingOCRCopyFeedback)
        } catch {
            controller.closeForTesting()
            await copyHarness.resume()
            await suspendedCopyTask?.value
            throw error
        }
    }

