    func testPinnedScreenshotClosingParentClosesChildAndCancelsOCRTask() async throws {
        var capturedRequestToken: LocalVisionOCRRequestToken?
        let controller = makePinnedScreenshotController(
            recognizeOCRText: { _, requestToken in
                capturedRequestToken = requestToken
                return "recognized text"
            },
            writePlainText: { _ in }
        )

        var pendingController: PinnedScreenshotController?
        var pendingOCRTask: Task<Void, Never>?
        do {
            controller.startTestingOCR()
            await controller.waitForTestingOCRTask()
            let childPanel = try XCTUnwrap(controller.testingOCRPanel)
            controller.closeForTesting()
            drainAppKitAnimationTransactions()

            XCTAssertFalse(childPanel.isVisible)
            XCTAssertNil(controller.testingOCRPanel)

            let started = expectation(description: "pending OCR request started")
            pendingController = makePinnedScreenshotController(
                recognizeOCRText: { _, requestToken in
                    capturedRequestToken = requestToken
                    started.fulfill()
                    return try await withTaskCancellationHandler {
                        try await withCheckedThrowingContinuation { continuation in
                            requestToken.addCancellationHandler {
                                continuation.resume(throwing: CancellationError())
                            }
                        }
                    } onCancel: {
                        requestToken.cancel()
                    }
                },
                writePlainText: { _ in }
            )
            pendingController?.startTestingOCR()
            pendingOCRTask = pendingController?.testingOCRTask
            await fulfillment(of: [started], timeout: 1)
            pendingController?.closeForTesting()
            drainAppKitAnimationTransactions()
            await pendingOCRTask?.value

            XCTAssertTrue(capturedRequestToken?.isCancelled == true)
            XCTAssertFalse(pendingController?.testingHasActiveOCRTask == true)
        } catch {
            controller.closeForTesting()
            pendingController?.closeForTesting()
            await pendingOCRTask?.value
            throw error
        }
    }

