    func testEditorManualOCRCopyFailureDoesNotRollbackAndReportsFailure() async throws {
        let adapter = ManualOCRAdapterSpy()
        let store = try ScreenshotEditorStore(
            capture: makeCapture(),
            preferencesStore: ScreenshotPreferencesStore(userDefaults: testDefaults()),
            onComplete: { _ in },
            onRetake: {},
            onClose: {},
