        )
        try await waitForEditorRender(store)
        store.selectToolbarItem(.ocr)
        store.beginGesture(at: CGPoint(x: 2, y: 3), modifiers: [])
        store.updateGesture(to: CGPoint(x: 14, y: 13), points: [], modifiers: [])
        store.endGesture(at: CGPoint(x: 14, y: 13), modifiers: [])
        try await waitForManualOCRToFinish(store)
        let original = ClipboardPasteboardWriteItem(
            representations: [.string: .string("original clipboard text")]
        )
        let pasteboard = ScriptedClipboardPasteboard(
            items: [original],
            changeCount: 90,
            writeOutcomes: [false]
        )
        let suppressor = ClipboardPasteboardChangeSuppressor()

        await store.copyManualOCRText(
            pasteboard: pasteboard,
            changeSuppressor: suppressor
        )

        XCTAssertTrue(pasteboard.items.isEmpty)
        XCTAssertEqual(pasteboard.writeCallCount, 1)
        XCTAssertEqual(
            store.notificationState.current?.descriptor.title,
            L10n.string("screenshot.result.copyFailed")
        )
        XCTAssertEqual(store.notificationState.current?.descriptor.level, .error)
        XCTAssertTrue(suppressor.consume(91))
        XCTAssertFalse(suppressor.consume(92))
    }

