    func testPinnedScreenshotKeyboardFocusCyclesThroughEnabledToolbarControls() throws {
        let controller = makePinnedScreenshotController(
            logicalSize: CGSize(width: 640, height: 480),
            recognizeOCRText: { _, _ in "recognized text" },
            writePlainText: { _ in }
        )
        defer { controller.closeForTesting() }

        let tab = try keyEvent(keyCode: 48)
        let shiftTab = try keyEvent(keyCode: 48, modifiers: .shift)
        let expectedForward = [
            L10n.string("screenshot.pin.zoomOut"),
            L10n.string("screenshot.editor.zoom"),
            L10n.string("screenshot.pin.zoomIn"),
            L10n.string("screenshot.pin.opacity"),
