            L10n.string("common.close"),
            L10n.string("screenshot.pin.zoomOut"),
        ]
        var forward = [controller.sendTestingCanvasKeyDown(tab)]
        for _ in 0..<(expectedForward.count - 1) {
            forward.append(controller.sendTestingFocusedToolbarKeyDown(tab))
        }
        XCTAssertEqual(forward, expectedForward.map(Optional.some))

        let expectedBackward = [
            L10n.string("common.close"),
            L10n.string("screenshot.pin.save"),
            L10n.string("screenshot.pin.copy"),
            L10n.string("screenshot.pin.ocr"),
