        ]
        var backward = [controller.sendTestingCanvasKeyDown(shiftTab)]
        for _ in 0..<(expectedBackward.count - 1) {
            backward.append(controller.sendTestingFocusedToolbarKeyDown(shiftTab))
        }
        XCTAssertEqual(backward, expectedBackward.map(Optional.some))

        controller.setTestingOCRInProgress(true)
        XCTAssertEqual(
            controller.sendTestingCanvasKeyDown(tab),
            L10n.string("screenshot.pin.zoomOut")
        )
        for _ in 0..<3 {
            _ = controller.sendTestingFocusedToolbarKeyDown(tab)
        }
        XCTAssertEqual(
            controller.sendTestingFocusedToolbarKeyDown(tab),
            L10n.string("screenshot.pin.copy")
        )
    }

    func testPinnedScreenshotOCRCopyFailureProvidesReadableRetryFeedback() async throws {
        let controller = makePinnedScreenshotController(
            recognizeOCRText: { _, _ in "recognized text" },
            writePlainText: { _ in throw PinnedScreenshotOCRTestError.failed }
        )
        defer { controller.closeForTesting() }

        controller.startTestingOCR()
        await controller.waitForTestingOCRTask()
        controller.copyTestingOCRText()
        let copyTask = try XCTUnwrap(controller.testingOCRCopyTask)
        await copyTask.value

        let feedback = try XCTUnwrap(controller.testingOCRCopyFeedback)
        XCTAssertTrue(feedback.contains(L10n.string("screenshot.result.copyFailed")))
        XCTAssertTrue(feedback.contains(L10n.string("screenshot.ocr.retry")))
    }

    func testPinnedScreenshotImageCopyFailureProvidesVisibleRetryFeedback() async throws {
