    func testPinnedScreenshotSaveFailureUsesSaveFeedbackAndRetryClearsIt() async throws {
        let destination = FileManager.default.temporaryDirectory
            .appendingPathComponent("PinnedScreenshotSave.\(UUID().uuidString).png")
        defer { try? FileManager.default.removeItem(at: destination) }
        let probe = PinnedScreenshotSaveWriterProbe()
        let controller = makePinnedScreenshotController(
            logicalSize: CGSize(width: 320, height: 240),
            recognizeOCRText: { _, _ in "recognized text" },
            writePlainText: { _ in },
            savePanelPresenter: { _, _ in .ok(destination) },
            saveWriter: { image, url in
                try probe.write(image, to: url)
            }
        )
        defer { controller.closeForTesting() }
        let originalCopyAccessibilityValue =
            controller.testingImageCopyButtonAccessibilityValue

        controller.saveImage()
        await probe.waitForAttemptCount(1)
        for _ in 0..<100 where controller.testingSaveFailureFeedback == nil {
            try await Task.sleep(for: .milliseconds(5))
        }

        let feedback = try XCTUnwrap(controller.testingSaveFailureFeedback)
        XCTAssertTrue(feedback.contains(L10n.string("screenshot.result.saveFailed")))
        XCTAssertTrue(feedback.contains(L10n.string("screenshot.result.saveFailedDetail")))
        XCTAssertTrue(feedback.contains(L10n.string("screenshot.result.saveAs")))
        XCTAssertEqual(controller.testingSaveButtonAccessibilityValue, feedback)
        XCTAssertEqual(
            controller.testingImageCopyButtonAccessibilityValue,
            originalCopyAccessibilityValue
        )

        controller.saveImage()
        await probe.waitForAttemptCount(2)
        for _ in 0..<100 where controller.testingSaveFailureFeedback != nil {
            try await Task.sleep(for: .milliseconds(5))
        }

        XCTAssertNil(controller.testingSaveFailureFeedback)
        XCTAssertEqual(controller.testingSaveButtonAccessibilityValue, "")
        XCTAssertEqual(
            controller.testingImageCopyButtonAccessibilityValue,
            originalCopyAccessibilityValue
        )
    }

    func testPinnedScreenshotSavePanelUsesItsOwnWindowAndCloseRejectsLateOK()
        async throws
    {
        let destination = FileManager.default.temporaryDirectory
            .appendingPathComponent(
                "PinnedScreenshotLateSave.\(UUID().uuidString).png"
            )
        defer { try? FileManager.default.removeItem(at: destination) }
        let presenter = PinnedScreenshotSavePanelPresentationProbe()
        let writer = PinnedScreenshotSaveWriterProbe()
        let first = makePinnedScreenshotController(
            recognizeOCRText: { _, _ in "first" },
            writePlainText: { _ in },
            savePanelPresenter: { panel, owner in
                await presenter.present(panel: panel, owner: owner)
            },
            saveWriter: { image, url in try writer.write(image, to: url) }
        )
        let second = makePinnedScreenshotController(
            recognizeOCRText: { _, _ in "second" },
            writePlainText: { _ in },
            savePanelPresenter: { _, _ in .cancel }
        )
        defer {
            first.closeForTesting()
            second.closeForTesting()
        }

        first.saveImage()
        let owner = await presenter.waitUntilPresented()

        XCTAssertTrue(owner === first.testingPanel)
        XCTAssertFalse(owner === second.testingPanel)
        XCTAssertTrue(first.testingHasActiveSavePanel)

        first.closeForTesting()
        await presenter.finish(.ok(destination))
        for _ in 0..<20 where first.testingHasActiveSavePanel {
            await Task.yield()
        }

        XCTAssertFalse(first.testingHasActiveSavePanel)
        XCTAssertEqual(writer.currentAttemptCount, 0)
        XCTAssertFalse(FileManager.default.fileExists(atPath: destination.path))
    }

