    private func makePinnedScreenshotController(
        logicalSize: CGSize = NSSize(width: 4, height: 4),
        recognizeOCRText: @escaping (CGImage, LocalVisionOCRRequestToken) async throws -> String,
        writePlainText: @escaping (String) async throws -> Void,
        writeImage: @escaping (NSImage) async throws -> Void = { image in
            try await ScreenshotPasteboardWriter().write(image)
        },
        savePanelPresenter: @escaping PinnedScreenshotSavePanelPresenter = { _, _ in
            .cancel
        },
        saveWriter: @escaping PinnedScreenshotSaveWriter = { _, _ in }
    ) -> PinnedScreenshotController {
        let image = NSImage(
            cgImage: solidImage(width: 4, height: 4, color: .white),
            size: NSSize(width: 4, height: 4)
        )
        let presentation = PinnedScreenshotPresentation(
            image: image,
            logicalSize: logicalSize,
            outputPixelScale: 1,
            preferredScreenFrame: CGRect(origin: CGPoint(x: 20, y: 20), size: logicalSize),
            targetVisibleFrame: CGRect(x: 0, y: 0, width: 640, height: 480)
        )
        return PinnedScreenshotController(
            id: UUID(),
            presentation: presentation,
            recognizeOCRText: recognizeOCRText,
            writePlainText: writePlainText,
            writeImage: writeImage,
            savePanelPresenter: savePanelPresenter,
            saveWriter: saveWriter,
            onClose: { _ in }
        )
    }

