    private func insertClipboardCleanupFixture(
        _ repository: ClipboardRepository,
        id: String,
        timestamp: TimeInterval
    ) throws {
        let text = "cleanup fixture \(id)"
        let signature = String(format: "%064llx", Int64(timestamp))
        _ = try repository.insert(
            record: ClipboardRecorderRecord(
                id: id,
                createdAt: Date(timeIntervalSince1970: timestamp),
                changeCount: Int(timestamp),
                kind: .text,
                formatSummary: .init(
                    itemCount: 1,
                    types: ["public.utf8-plain-text"],
                    textLength: text.count,
                    byteCount: text.utf8.count
                ),
                sourceApp: nil,
                signatureSHA256: signature,
                signatureSHA256_12: String(signature.prefix(12)),
                fixtureOwned: true,
                restorable: true,
                summary: text
            ),
            payload: .init(recordID: id, kind: .text, text: text)
        )
    }

    private func waitForClipboardSearch(
        _ store: ClipboardStore,
        query: String
    ) async throws {
        for _ in 0..<200 {
            if store.currentSearchResult.query == query,
               store.currentSearchResult.state != .failed {
                return
            }
            try await Task.sleep(for: .milliseconds(10))
        }
        XCTFail("Timed out waiting for clipboard search query \(query)")
    }

    private func waitForClipboardRecords(
        _ store: ClipboardStore,
        expectedCount: Int? = nil,
        containing recordID: String? = nil
    ) async throws {
        for _ in 0..<200 {
            let countMatches = expectedCount.map { store.records.count == $0 } ?? true
            let recordMatches = recordID.map { id in
                store.records.contains(where: { $0.id == id })
            } ?? true
            if countMatches, recordMatches {
                return
            }
            try await Task.sleep(for: .milliseconds(10))
        }
        XCTFail("Timed out waiting for clipboard repository records")
    }

    private func waitForClipboardDetail(
        _ store: ClipboardDetailStore,
        condition: (ClipboardDetailStore) -> Bool
    ) async throws {
        for _ in 0..<300 {
            if condition(store) {
                return
            }
            try await Task.sleep(for: .milliseconds(5))
        }
        XCTFail(
            "Timed out waiting for clipboard detail state: status=\(store.status.rawValue), busy=\(store.isBusy)"
        )
    }

