    private func makeCaptureWithoutEditingContext() -> ScreenshotCapture {
        let image = NSImage(size: NSSize(width: 24, height: 24))
        image.lockFocus()
        NSColor.white.setFill()
        NSRect(x: 0, y: 0, width: 24, height: 24).fill()
        image.unlockFocus()
        return ScreenshotCapture(
            id: "fixture",
            image: image,
            pixelSize: CGSize(width: 24, height: 24),
            sourceRect: CGRect(x: 0, y: 0, width: 24, height: 24),
            kind: .region,
            displayScope: nil,
            sourceSummary: "fixture"
        )
    }

    private func makeCapture(id: String = "fixture") -> ScreenshotCapture {
        let capture = makeCaptureWithoutEditingContext()
        let cgImage = capture.image.cgImage(forProposedRect: nil, context: nil, hints: nil)!
        let bounds = ScreenshotPixelRect(x: 0, y: 0, width: 24, height: 24)
        return ScreenshotCapture(
            id: id,
            image: capture.image,
            pixelSize: capture.pixelSize,
            sourceRect: capture.sourceRect,
            kind: capture.kind,
            displayScope: capture.displayScope,
            sourceSummary: capture.sourceSummary,
            editingContext: ScreenshotEditingContext(
                sourceContext: ScreenshotSourceContext(
                    sourceBounds: bounds,
                    tileDescriptors: [ScreenshotSourceTileDescriptor(id: "display-1", bounds: bounds)],
                    compositeSource: cgImage
                ),
                sourceFrame: CGRect(x: 0, y: 0, width: 24, height: 24),
                screens: [ScreenshotEditingScreen(displayID: 1, frame: CGRect(x: 0, y: 0, width: 24, height: 24))],
                initialCropRect: bounds,
                supportsRangeExpansion: true
            )
        )
    }

    private func makeScrollingCapture() -> ScreenshotCapture {
        let capture = makeCapture()
        return ScreenshotCapture(
            id: "scrolling-fixture",
            image: capture.image,
            pixelSize: capture.pixelSize,
            sourceRect: capture.sourceRect,
            kind: capture.kind,
            displayScope: capture.displayScope,
            sourceSummary: "scrolling fixture",
            editingContext: capture.editingContext,
            defersOutputUntilEditorCompletion: true,
            scrollingSessionID: "scrolling-session"
        )
    }

    private func makeExpandableCapture(
        sourceWidth: Int = 64,
        sourceHeight: Int = 64,
        initialCropRect: ScreenshotPixelRect = ScreenshotPixelRect(x: 8, y: 8, width: 40, height: 40),
        initialRegionConstraint: ScreenshotRegionConstraint = .free,
        kind: ScreenshotResolvedCaptureKind = .region,
        defersOutputUntilEditorCompletion: Bool = false
    ) -> ScreenshotCapture {
        let image = NSImage(size: NSSize(width: sourceWidth, height: sourceHeight))
        image.lockFocus()
        NSColor.white.setFill()
        NSRect(x: 0, y: 0, width: sourceWidth, height: sourceHeight).fill()
        image.unlockFocus()
        let cgImage = image.cgImage(forProposedRect: nil, context: nil, hints: nil)!
        let bounds = ScreenshotPixelRect(x: 0, y: 0, width: sourceWidth, height: sourceHeight)
        return ScreenshotCapture(
            id: "expandable-fixture",
            image: image,
            pixelSize: CGSize(width: initialCropRect.width, height: initialCropRect.height),
            sourceRect: CGRect(
                x: initialCropRect.x,
                y: initialCropRect.y,
                width: initialCropRect.width,
                height: initialCropRect.height
            ),
            kind: kind,
            displayScope: nil,
            sourceSummary: "expandable fixture",
            editingContext: ScreenshotEditingContext(
                sourceContext: ScreenshotSourceContext(
                    sourceBounds: bounds,
                    tileDescriptors: [ScreenshotSourceTileDescriptor(id: "display-1", bounds: bounds)],
                    compositeSource: cgImage
                ),
                sourceFrame: CGRect(x: 0, y: 0, width: sourceWidth, height: sourceHeight),
                screens: [ScreenshotEditingScreen(
                    displayID: 1,
                    frame: CGRect(x: 0, y: 0, width: sourceWidth, height: sourceHeight)
                )],
                initialCropRect: initialCropRect,
                supportsRangeExpansion: true,
                initialRegionConstraint: initialRegionConstraint
            ),
            defersOutputUntilEditorCompletion: defersOutputUntilEditorCompletion
        )
    }

    func testApplyingWatermarkReplacesTheSingleExistingInstance() throws {
        let store = try makeWatermarkStore()
        let first = ScreenshotWatermarkPreset(
            name: "First",
            style: .init(text: "FIRST", density: 0.3, angleDegrees: -20, opacity: 0.25)
        )
        let second = ScreenshotWatermarkPreset(
            name: "Second",
            style: .init(text: "SECOND", density: 0.8, angleDegrees: 25, opacity: 0.55)
        )

        let firstID = try XCTUnwrap(store.applyWatermark(first))
        let secondID = try XCTUnwrap(store.applyWatermark(second))

        XCTAssertNotEqual(firstID, secondID)
        XCTAssertEqual(store.appliedWatermarkElements.map(\.id), [secondID])
        XCTAssertEqual(store.selectedWatermark?.style, second.style)
    }

    func testUpdatingWatermarkKeepsInstanceAndUsesInlineStyleFields() throws {
        let store = try makeWatermarkStore()
        let preset = ScreenshotWatermarkPreset(name: "Original", style: .init(text: "ORIGINAL"))
        let elementID = try XCTUnwrap(store.applyWatermark(preset))
        let geometry = try XCTUnwrap(store.selectedElement).geometry
        let updated = ScreenshotWatermarkPreset(
            id: preset.id,
            name: "Updated",
            style: .init(
                text: "UPDATED",
                color: .accentRed,
                fontSizeFraction: 0.09,
                density: 0.75,
                angleDegrees: 33,
                opacity: 0.42
            )
        )

        XCTAssertEqual(store.applyWatermark(updated, replacing: elementID), elementID)
        XCTAssertEqual(store.appliedWatermarkElements.count, 1)
        XCTAssertEqual(store.selectedElement?.geometry, geometry)
        XCTAssertEqual(store.selectedWatermark?.style, updated.style)
    }

    func testWatermarkEditingCommitsLiveValuesAsOneUndoableTransaction() throws {
        let store = try makeWatermarkStore()
        let preset = ScreenshotWatermarkPreset(
            name: "Original",
            style: .init(text: "ORIGINAL", density: 0.2, angleDegrees: -15, opacity: 0.3)
        )
        let elementID = try XCTUnwrap(store.applyWatermark(preset))

        store.beginWatermarkEditing()
        store.updateSelectedWatermark { $0.text = "UPDATED" }
        store.updateSelectedWatermark { $0.density = 0.8 }
        store.updateSelectedWatermark { $0.angleDegrees = 35 }
        store.updateSelectedWatermark { $0.opacity = 0.7 }
        store.endWatermarkEditing()

        XCTAssertEqual(store.selectedElementID, elementID)
        XCTAssertEqual(store.selectedWatermark?.style.text, "UPDATED")
        XCTAssertEqual(store.selectedWatermark?.style.density, 0.8)
        XCTAssertEqual(store.selectedWatermark?.style.angleDegrees, 35)
        XCTAssertEqual(store.selectedWatermark?.style.opacity, 0.7)

        store.undo()
        let restored = store.document.snapshot.elements.first(where: { $0.id == elementID })?.watermark
        XCTAssertEqual(restored?.style, preset.style)
    }

