    func testClipboardPointerSurfaceUsesNativePrimaryButtonRecognizers() {
        let view = ClipboardRecordPointerSurfaceView()

        XCTAssertEqual(view.pressRecognizer.buttonMask, 0x1)
        XCTAssertEqual(view.pressRecognizer.minimumPressDuration, 0)
        XCTAssertEqual(view.singleClickRecognizer.buttonMask, 0x1)
        XCTAssertEqual(view.singleClickRecognizer.numberOfClicksRequired, 1)
        XCTAssertEqual(view.doubleClickRecognizer.buttonMask, 0x1)
        XCTAssertEqual(view.doubleClickRecognizer.numberOfClicksRequired, 2)
        XCTAssertTrue(view.acceptsFirstMouse(for: nil))
        XCTAssertTrue(
            view.gestureRecognizer(
                view.singleClickRecognizer,
                shouldRequireFailureOf: view.doubleClickRecognizer
            )
        )
        XCTAssertFalse(
            view.gestureRecognizer(
                view.doubleClickRecognizer,
                shouldRequireFailureOf: view.singleClickRecognizer
            )
        )
        XCTAssertTrue(
            view.gestureRecognizer(
                view.pressRecognizer,
                shouldRecognizeSimultaneouslyWith: view.doubleClickRecognizer
            )
        )
        XCTAssertFalse(
            view.gestureRecognizer(
                view.singleClickRecognizer,
                shouldRecognizeSimultaneouslyWith: view.doubleClickRecognizer
            )
        )
    }

    func testClipboardPointerSurfaceRejectsNonPrimaryPointerEvents() throws {
        let view = ClipboardRecordPointerSurfaceView()
        let leftMouseDown = try XCTUnwrap(
            NSEvent.mouseEvent(
                with: .leftMouseDown,
                location: .zero,
                modifierFlags: [],
                timestamp: 0,
                windowNumber: 0,
                context: nil,
                eventNumber: 1,
                clickCount: 1,
                pressure: 1
            )
        )
        let rightMouseDown = try XCTUnwrap(
            NSEvent.mouseEvent(
                with: .rightMouseDown,
                location: .zero,
                modifierFlags: [],
                timestamp: 0,
                windowNumber: 0,
                context: nil,
                eventNumber: 2,
                clickCount: 1,
                pressure: 1
            )
        )
        let keyboardEvent = try XCTUnwrap(
            NSEvent.keyEvent(
                with: .keyDown,
                location: .zero,
                modifierFlags: [],
                timestamp: 0,
                windowNumber: 0,
                context: nil,
                characters: "a",
                charactersIgnoringModifiers: "a",
                isARepeat: false,
                keyCode: 0
            )
        )

        XCTAssertTrue(
            view.gestureRecognizer(view.singleClickRecognizer, shouldAttemptToRecognizeWith: leftMouseDown)
        )
        XCTAssertFalse(
            view.gestureRecognizer(view.singleClickRecognizer, shouldAttemptToRecognizeWith: rightMouseDown)
        )
        XCTAssertFalse(
            view.gestureRecognizer(view.singleClickRecognizer, shouldAttemptToRecognizeWith: keyboardEvent)
        )
    }

    func testClipboardPointerSurfaceNativeSingleClickWaitsForDoubleClickFailure() {
        let panel = NSPanel(
            contentRect: CGRect(x: 40, y: 40, width: 180, height: 90),
            styleMask: [.borderless],
            backing: .buffered,
            defer: false
        )
        panel.animationBehavior = .none
        let view = ClipboardRecordPointerSurfaceView(frame: panel.contentView?.bounds ?? .zero)
        var presses = 0
        var singleClicks = 0
        var doubleClicks = 0
        view.configure(
            panelSessionID: UUID(),
            recordID: "native-single",
            source: .bottomCard,
            onPointerPress: { presses += 1 },
            onSingleClick: { singleClicks += 1 },
            onDoubleClick: { doubleClicks += 1 }
        )
        panel.contentView = view
        panel.orderFront(nil)
        defer {
            closeAppKitFixtureWindow(panel)
            drainAppKitAnimationTransactions()
        }

        let location = CGPoint(x: 40, y: 40)
        for type in [NSEvent.EventType.leftMouseDown, .leftMouseUp] {
            guard let event = NSEvent.mouseEvent(
                with: type,
                location: location,
                modifierFlags: [],
                timestamp: 0,
                windowNumber: panel.windowNumber,
                context: nil,
                eventNumber: type == .leftMouseDown ? 1 : 2,
                clickCount: 1,
                pressure: type == .leftMouseDown ? 1 : 0
            ) else {
                XCTFail("Unable to create native primary-button event")
                return
            }
            panel.sendEvent(event)
        }

        RunLoop.current.run(until: Date().addingTimeInterval(NSEvent.doubleClickInterval + 0.1))

        XCTAssertEqual(presses, 1)
        XCTAssertEqual(singleClicks, 1)
        XCTAssertEqual(doubleClicks, 0)
    }

