        let view = ClipboardRecordPointerSurfaceView(frame: panel.contentView?.bounds ?? .zero)
        var presses = 0
        var singleClicks = 0
        var doubleClicks = 0
        view.configure(
            panelSessionID: UUID(),
            recordID: "native-double",
            source: .sideRow,
            onPointerPress: { presses += 1 },
            onSingleClick: { singleClicks += 1 },
            onDoubleClick: { doubleClicks += 1 }
        )
        panel.contentView = view
        panel.orderFront(nil)
        drainAppKitAnimationTransactions()
        defer {
            closeAppKitFixtureWindow(panel)
            drainAppKitAnimationTransactions()
        }

        let location = CGPoint(x: 40, y: 40)
        var eventNumber = 1
        for clickCount in [1, 2] {
            for type in [NSEvent.EventType.leftMouseDown, .leftMouseUp] {
                guard let event = NSEvent.mouseEvent(
                    with: type,
                    location: location,
                    modifierFlags: [],
                    timestamp: TimeInterval(clickCount) * 0.05,
                    windowNumber: panel.windowNumber,
                    context: nil,
                    eventNumber: eventNumber,
                    clickCount: clickCount,
                    pressure: type == .leftMouseDown ? 1 : 0
                ) else {
                    XCTFail("Unable to create native primary-button event")
                    return
                }
                eventNumber += 1
                panel.sendEvent(event)
            }
        }

        RunLoop.current.run(until: Date().addingTimeInterval(0.1))

        XCTAssertEqual(presses, 2)
        XCTAssertEqual(singleClicks, 0)
        XCTAssertEqual(doubleClicks, 1)
    }

