    func testStatusBarDeletionSelectsTheNearestRemainingObject() {
        let first = ScreenshotElement(
            kind: .text,
            geometry: .rect(ScreenshotPixelRect(x: 0, y: 0, width: 20, height: 20))
        )
        let middle = ScreenshotElement(
            kind: .callout,
            geometry: .rect(ScreenshotPixelRect(x: 24, y: 0, width: 20, height: 20))
        )
        let last = ScreenshotElement(
            kind: .rectangle,
            geometry: .rect(ScreenshotPixelRect(x: 48, y: 0, width: 20, height: 20))
        )
        let elements = [first, middle, last]

        XCTAssertEqual(
            ScreenshotEditorStatusBarModel.nextElementID(afterDeleting: middle.id, from: elements),
            last.id
        )
        XCTAssertEqual(
            ScreenshotEditorStatusBarModel.nextElementID(afterDeleting: last.id, from: elements),
            middle.id
        )
        XCTAssertNil(
            ScreenshotEditorStatusBarModel.nextElementID(afterDeleting: first.id, from: [first])
        )
    }

    func testStatusBarDeletionAtomicallySelectsTheRequestedNeighbor() throws {
        let store = try ScreenshotEditorStore(
            capture: makeExpandableCapture(),
            preferencesStore: ScreenshotPreferencesStore(userDefaults: defaults),
            onComplete: { _ in },
            onRetake: {},
            onClose: {}
        )
        store.selectTool(.rectangle)
        store.beginGesture(at: CGPoint(x: 4, y: 4), modifiers: [])
        store.updateGesture(to: CGPoint(x: 24, y: 24), points: [], modifiers: [])
        store.endGesture(at: CGPoint(x: 24, y: 24), modifiers: [])
        let firstID = try XCTUnwrap(store.selectedElementID)
        store.beginGesture(at: CGPoint(x: 40, y: 40), modifiers: [.option])
        store.updateGesture(to: CGPoint(x: 64, y: 64), points: [], modifiers: [.option])
        store.endGesture(at: CGPoint(x: 64, y: 64), modifiers: [.option])
        let secondID = try XCTUnwrap(store.selectedElementID)

        store.deleteElement(firstID, selecting: secondID)

