    // MARK: - ScreenCaptureKit single-frame request lifecycle

    func testSingleFrameRequestDeadlineWinsOverLateSuccessWithoutClearingReplacement() async throws {
        let adapter = ScreenCaptureKitAdapter()
        let firstOperation = SingleFrameRequestOperationHarness()
        let replacementOperation = SingleFrameRequestOperationHarness()
        let firstImage = solidImage(width: 3, height: 3, color: .systemBlue)
        let replacementImage = solidImage(width: 5, height: 5, color: .systemGreen)
        let firstFinished = expectation(description: "first request times out")
        var firstError: ScreenshotCaptureError?

        Task { @MainActor [adapter] in
            do {
                _ = try await adapter.captureSingleFrameImage(
                    deadline: .milliseconds(50),
                    operation: { await firstOperation.run() }
                )
            } catch {
                firstError = error as? ScreenshotCaptureError
            }
            firstFinished.fulfill()
        }

        try await firstOperation.waitUntilStarted()
        await fulfillment(of: [firstFinished], timeout: 1)
        guard case .timedOut? = firstError else {
            return XCTFail("Expected the deadline to win, got \(String(describing: firstError))")
        }

        let replacementFinished = expectation(description: "replacement request succeeds")
        var replacementResult: CGImage?
        Task { @MainActor [adapter] in
            replacementResult = try? await adapter.captureSingleFrameImage(
                deadline: .seconds(1),
                operation: { await replacementOperation.run() }
            )
            replacementFinished.fulfill()
        }

        try await replacementOperation.waitUntilStarted()
        await firstOperation.resume(with: firstImage)
        await replacementOperation.resume(with: replacementImage)
        await fulfillment(of: [replacementFinished], timeout: 1)
        XCTAssertEqual(replacementResult?.width, replacementImage.width)
        XCTAssertEqual(replacementResult?.height, replacementImage.height)
    }

    func testSingleFrameDeadlineReleasesOwnerWhileNonCooperativeOperationOutlivesRequest()
        async throws
    {
        let adapter = ScreenCaptureKitAdapter()
        let firstOperation = SingleFrameRequestOperationHarness()
        let replacementOperation = SingleFrameRequestOperationHarness()
        let releaseProbe = SingleFrameRequestOwnerReleaseProbe()
        let replacementImage = solidImage(
            width: 5, height: 5, color: .systemGreen
        )
        let firstFinished = expectation(description: "deadline request finishes")
        var firstError: ScreenshotCaptureError?

        let firstRequest = Task { @MainActor [adapter, releaseProbe] in
            do {
                _ = try await adapter.captureSingleFrameImage(
                    deadline: .milliseconds(50),
                    onOwnerRelease: { releaseProbe.recordRelease() },
                    operation: { await firstOperation.run() }
                )
            } catch {
                firstError = error as? ScreenshotCaptureError
            }
            firstFinished.fulfill()
        }

        try await firstOperation.waitUntilStarted()
        await fulfillment(of: [firstFinished], timeout: 1)
        _ = await firstRequest.value
        guard case .timedOut? = firstError else {
            return XCTFail(
                "Expected deadline failure, got \(String(describing: firstError))"
            )
        }
        let ownerReleased = await releaseProbe.waitUntilReleased()
        XCTAssertTrue(ownerReleased)

        let replacementFinished = expectation(
            description: "replacement request succeeds"
        )
        var replacementResult: CGImage?
        Task { @MainActor [adapter] in
            replacementResult = try? await adapter.captureSingleFrameImage(
                deadline: .seconds(1),
                operation: { await replacementOperation.run() }
            )
            replacementFinished.fulfill()
        }
        try await replacementOperation.waitUntilStarted()
        await replacementOperation.resume(with: replacementImage)
        await fulfillment(of: [replacementFinished], timeout: 1)
        XCTAssertEqual(replacementResult?.width, replacementImage.width)
        XCTAssertEqual(replacementResult?.height, replacementImage.height)

        await firstOperation.resume(
            with: solidImage(width: 3, height: 3, color: .systemBlue)
        )
        try await firstOperation.waitUntilCompleted()
        XCTAssertEqual(releaseProbe.releaseCount, 1)
        XCTAssertEqual(replacementResult?.width, replacementImage.width)
        XCTAssertEqual(replacementResult?.height, replacementImage.height)
    }

    func testCancelCurrentCaptureCancelsPendingSingleFrameRequestAndProtectsReplacement() async throws {
        let adapter = ScreenCaptureKitAdapter()
        let firstOperation = SingleFrameRequestOperationHarness()
        let replacementOperation = SingleFrameRequestOperationHarness()
        let firstImage = solidImage(width: 3, height: 3, color: .systemBlue)
        let replacementImage = solidImage(width: 5, height: 5, color: .systemGreen)
        let firstFinished = expectation(description: "cancelled request completes")
        var firstError: ScreenshotCaptureError?

        Task { @MainActor [adapter] in
            do {
                _ = try await adapter.captureSingleFrameImage(
                    deadline: .seconds(1),
                    operation: { await firstOperation.run() }
                )
            } catch {
                firstError = error as? ScreenshotCaptureError
            }
            firstFinished.fulfill()
        }

        try await firstOperation.waitUntilStarted()
        adapter.cancelCurrentCapture()
        await fulfillment(of: [firstFinished], timeout: 1)
        guard case .cancelled? = firstError else {
            return XCTFail("Expected cancellation, got \(String(describing: firstError))")
        }

        let replacementFinished = expectation(description: "replacement after cancellation succeeds")
        var replacementResult: CGImage?
        Task { @MainActor [adapter] in
            replacementResult = try? await adapter.captureSingleFrameImage(
                deadline: .seconds(1),
                operation: { await replacementOperation.run() }
            )
            replacementFinished.fulfill()
        }

        try await replacementOperation.waitUntilStarted()
        await firstOperation.resume(with: firstImage)
        await replacementOperation.resume(with: replacementImage)
        await fulfillment(of: [replacementFinished], timeout: 1)
        XCTAssertEqual(replacementResult?.width, replacementImage.width)
        XCTAssertEqual(replacementResult?.height, replacementImage.height)
    }

    func testSingleFrameCancellationBeforeContinuationInstallStartsNoOperation() async throws {
        let adapter = ScreenCaptureKitAdapter()
        let installGate = SingleFrameRequestInstallGate()
        let operation = SingleFrameRequestOperationHarness()
        let finished = expectation(description: "pre-install cancellation completes")
        var result: ScreenshotCaptureError?

        let request = Task { @MainActor [adapter] in
            do {
                _ = try await adapter.captureSingleFrameImage(
                    deadline: .seconds(1),
                    beforeInstall: { await installGate.waitBeforeInstall() },
                    operation: { await operation.run() }
                )
            } catch {
                result = error as? ScreenshotCaptureError
            }
            finished.fulfill()
        }

        try await installGate.waitUntilEntered()
        request.cancel()
        await installGate.release()
        await fulfillment(of: [finished], timeout: 1)
        guard case .cancelled? = result else {
            return XCTFail("Expected cancellation, got \(String(describing: result))")
        }
        let operationCount = await operation.invocationCount()
        XCTAssertEqual(operationCount, 0)
    }

    private func makeWatermarkStore() throws -> ScreenshotEditorStore {
        let preferences = ScreenshotPreferencesStore(
            userDefaults: defaults,
            watermarkAssetStore: ScreenshotWatermarkAssetStore(
                directory: makeTemporaryWatermarkDirectory()
            )
        )
        return try ScreenshotEditorStore(
            capture: makeExpandableCapture(
                sourceWidth: 600,
                sourceHeight: 400,
                initialCropRect: ScreenshotPixelRect(x: 0, y: 0, width: 600, height: 400)
            ),
            preferencesStore: preferences,
            onComplete: { _ in },
            onRetake: {},
            onClose: {}
        )
    }

    private func makeTemporaryWatermarkDirectory() -> URL {
        FileManager.default.temporaryDirectory
            .appendingPathComponent("ScreenshotWatermarkTests.\(UUID().uuidString)", isDirectory: true)
    }


    private func makeMagnifierElement(
        from start: CGPoint,
        to end: CGPoint,
        sourceSize: Int
    ) throws -> ScreenshotElement {
        let store = try makeMagnifierStore(sourceSize: sourceSize)
        store.beginGesture(at: start, modifiers: [])
        store.updateGesture(to: end, points: [start, end], modifiers: [])
        store.endGesture(at: end, modifiers: [])
        return try XCTUnwrap(store.document.snapshot.elements.last)
    }

