    private func makeStepStoreWithNote() throws -> (ScreenshotEditorStore, UUID) {
        let store = try ScreenshotEditorStore(
            capture: makeExpandableCapture(
                sourceWidth: 500,
                sourceHeight: 500,
                initialCropRect: ScreenshotPixelRect(x: 0, y: 0, width: 500, height: 500)
