    private func stepParts(
        of element: ScreenshotElement
    ) throws -> (badgeCenter: ScreenshotPixelPoint, note: ScreenshotPixelRect, badgeSize: Double) {
        let parts: (ScreenshotPixelPoint, ScreenshotPixelRect?, Double)? = switch element.geometry {
        case let .step(badgeCenter, rawNote): (
            badgeCenter,
            rawNote,
            element.appearance.stepAppearance.badgeSize
        )
        default: nil
        }
        let unwrapped = try XCTUnwrap(parts, "Expected step geometry")
        return (unwrapped.0, try XCTUnwrap(unwrapped.1), unwrapped.2)
    }

    private func resizeCorners(
        for handle: ScreenshotResizeHandle,
        in rect: ScreenshotPixelRect
    ) -> (moving: ScreenshotPixelPoint, opposite: ScreenshotPixelPoint, direction: ScreenshotPixelPoint) {
        let left = Double(rect.x)
        let top = Double(rect.y)
        let right = Double(rect.x + rect.width)
        let bottom = Double(rect.y + rect.height)
        return switch handle {
        case .northWest: (
            .init(x: left, y: top),
            .init(x: right, y: bottom),
            .init(x: -1, y: -1)
        )
        case .northEast: (
            .init(x: right, y: top),
            .init(x: left, y: bottom),
            .init(x: 1, y: -1)
        )
        case .southEast: (
            .init(x: right, y: bottom),
            .init(x: left, y: top),
            .init(x: 1, y: 1)
        )
        case .southWest: (
            .init(x: left, y: bottom),
            .init(x: right, y: top),
            .init(x: -1, y: 1)
        )
        default:
            fatalError("Only corner handles define square resize anchors")
        }
    }

    private func mouseEvent(
        type: NSEvent.EventType,
        location: CGPoint,
        windowNumber: Int
    ) throws -> NSEvent {
        try XCTUnwrap(NSEvent.mouseEvent(
            with: type,
            location: location,
            modifierFlags: [],
            timestamp: 0,
            windowNumber: windowNumber,
            context: nil,
            eventNumber: 1,
            clickCount: 1,
            pressure: 1
        ))
    }

    private func keyEvent(
        keyCode: UInt16,
        modifiers: NSEvent.ModifierFlags = [],
        characters: String = "\t"
    ) throws -> NSEvent {
        try XCTUnwrap(NSEvent.keyEvent(
            with: .keyDown,
            location: .zero,
            modifierFlags: modifiers,
            timestamp: 0,
            windowNumber: 0,
            context: nil,
            characters: characters,
            charactersIgnoringModifiers: characters,
            isARepeat: false,
            keyCode: keyCode
        ))
    }

    private func solidImage(width: Int, height: Int, color: NSColor) -> CGImage {
        let colorSpace = CGColorSpace(name: CGColorSpace.sRGB)!
        let context = CGContext(
            data: nil,
            width: width,
            height: height,
            bitsPerComponent: 8,
            bytesPerRow: 0,
            space: colorSpace,
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        )!
        context.setFillColor(color.usingColorSpace(.sRGB)!.cgColor)
        context.fill(CGRect(x: 0, y: 0, width: width, height: height))
        return context.makeImage()!
    }

    private func transparentImage(width: Int, height: Int, insetColor: NSColor) -> CGImage {
        let colorSpace = CGColorSpace(name: CGColorSpace.sRGB)!
        let context = CGContext(
            data: nil,
            width: width,
            height: height,
            bitsPerComponent: 8,
            bytesPerRow: 0,
            space: colorSpace,
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        )!
        context.clear(CGRect(x: 0, y: 0, width: width, height: height))
        context.setFillColor(insetColor.usingColorSpace(.sRGB)!.cgColor)
        context.fill(CGRect(x: 4, y: 4, width: width - 8, height: height - 8))
        return context.makeImage()!
    }

    private func bitmapColor(_ image: CGImage, x: Int, y: Int) -> NSColor? {
        NSBitmapImageRep(cgImage: image)
            .colorAt(x: x, y: y)?
            .usingColorSpace(.sRGB)
    }

    private func nonWhitePixelCount(_ image: CGImage) -> Int {
        let bitmap = NSBitmapImageRep(cgImage: image)
        var count = 0
        for y in 0..<bitmap.pixelsHigh {
            for x in 0..<bitmap.pixelsWide {
                guard let color = bitmap.colorAt(x: x, y: y)?.usingColorSpace(.sRGB) else { continue }
                if color.redComponent < 0.98 || color.greenComponent < 0.98 || color.blueComponent < 0.98 {
                    count += 1
                }
            }
        }
        return count
    }

    private func grantedPermissionSnapshot() -> PermissionStateSnapshot {
        let diagnostic = PermissionDiagnosticSnapshot(
            kind: .screenRecording,
            granted: true,
            bundleID: "app.blocks.test",
            appPath: "/Applications/Blocks.app",
