@MainActor
private final class ActionBrokerRetrySchedulerTestDouble {
    private final class Pending {
        var isCancelled = false
        let action: @MainActor () -> Void

        init(action: @escaping @MainActor () -> Void) {
            self.action = action
        }
    }

    private var pending: [Pending] = []

    var pendingCount: Int {
        pending.filter { !$0.isCancelled }.count
    }

    func schedule(
        after _: Duration,
        action: @escaping @MainActor () -> Void
    ) -> AnyCancellable {
        let item = Pending(action: action)
        pending.append(item)
        return AnyCancellable { item.isCancelled = true }
    }

    func fireNext() {
        guard let index = pending.firstIndex(where: { !$0.isCancelled }) else { return }
        let item = pending.remove(at: index)
        guard !item.isCancelled else { return }
        item.action()
    }
}

