private final class ScreenshotInlineTextFocusWindow: NSWindow {
    private let acceptedAfterAttempt: Int
    private(set) var textResponderAttemptCount = 0

    init(
        acceptedAfterAttempt: Int,
        contentRect: NSRect,
        styleMask style: NSWindow.StyleMask,
        backing backingStoreType: NSWindow.BackingStoreType,
        defer flag: Bool
    ) {
        self.acceptedAfterAttempt = acceptedAfterAttempt
        super.init(contentRect: contentRect, styleMask: style, backing: backingStoreType, defer: flag)
    }

    override func makeFirstResponder(_ responder: NSResponder?) -> Bool {
        guard responder is NSTextView else {
            return super.makeFirstResponder(responder)
        }
        textResponderAttemptCount += 1
        guard textResponderAttemptCount >= acceptedAfterAttempt else { return false }
        return super.makeFirstResponder(responder)
    }
}

private final class ClipboardAnchorRetryPanel: NSPanel {
    var observesAnchorRequests = false
    var rejectsNextAnchorRequest = false
    var onNextAnchorRequest: (() -> Void)?
    private(set) var anchorRequestCount = 0

    init() {
        super.init(contentRect: CGRect(x: 0, y: 0, width: 120, height: 120), styleMask: [.borderless, .nonactivatingPanel], backing: .buffered, defer: false)
        isReleasedWhenClosed = false
    }

    override var canBecomeKey: Bool { true }
    override var isKeyWindow: Bool { true }

    override func makeFirstResponder(_ responder: NSResponder?) -> Bool {
        guard observesAnchorRequests, responder is ClipboardPanelRecordFocusAnchorView else {
            return super.makeFirstResponder(responder)
        }
        anchorRequestCount += 1
        let callback = onNextAnchorRequest
        onNextAnchorRequest = nil
        callback?()
        if rejectsNextAnchorRequest {
            rejectsNextAnchorRequest = false
            return false
        }
        return super.makeFirstResponder(responder)
    }
}

private final class ClipboardTestKeyPanel: NSPanel {
    var usesDeterministicKeyWindowState = false
    private var deterministicKeyWindowState = false
    private(set) var makeKeyInvocationCount = 0

    override var canBecomeKey: Bool {
        true
    }

    override var isKeyWindow: Bool {
        usesDeterministicKeyWindowState ? deterministicKeyWindowState : super.isKeyWindow
    }

    override func makeKey() {
        makeKeyInvocationCount += 1
        if usesDeterministicKeyWindowState {
            deterministicKeyWindowState = true
        }
        super.makeKey()
    }

    override func resignKey() {
        if usesDeterministicKeyWindowState {
            deterministicKeyWindowState = false
        }
        super.resignKey()
    }
}

