private protocol TestClipboardPasteboardReading: AnyObject {
    var changeCount: Int { get }
    var types: [NSPasteboard.PasteboardType]? { get }
    func data(forType dataType: NSPasteboard.PasteboardType) -> Data?
    func string(forType dataType: NSPasteboard.PasteboardType) -> String?
}

extension NSPasteboard: TestClipboardPasteboardReading {}

private actor TestClipboardObservationBroker: ClipboardBrokerServing {
    private let reader: any TestClipboardPasteboardReading
    private var suppressedChangeCounts: Set<Int> = []

    init(reader: any TestClipboardPasteboardReading) {
        self.reader = reader
    }

    func suppress(_ changeCount: Int) {
        suppressedChangeCounts.insert(changeCount)
    }

    func baseline() async throws -> Int {
        reader.changeCount
    }

    func observe(
        _ request: ClipboardBrokerObserveRequest
    ) async throws -> ClipboardBrokerObservationResult {
        let before = reader.changeCount
        if request.baselineChangeCount == nil
            || request.baselineChangeCount == before {
            return result(status: .noChange, changeCount: before, request: request)
        }
        if suppressedChangeCounts.remove(before) != nil
            || request.suppressedChangeCounts.contains(before) {
            return result(
                status: .skipped,
                changeCount: before,
                request: request,
                skipReason: .selfWrite
            )
        }
        if request.prefilterDisposition != .allow {
            return result(status: .redacted, changeCount: before, request: request)
        }

        let types = reader.types ?? []
        let names = types.map(\.rawValue).sorted()
        let representation: ClipboardBrokerCapturedRepresentation?
        if types.contains(.fileURL), let value = reader.string(forType: .fileURL) {
            representation = ClipboardBrokerCapturedRepresentation(
                family: .fileURL,
                pasteboardType: NSPasteboard.PasteboardType.fileURL.rawValue,
                advertisedTypes: names,
                value: value
            )
        } else if types.contains(.png), let data = reader.data(forType: .png) {
            representation = ClipboardBrokerCapturedRepresentation(
                family: .imagePNG,
                pasteboardType: NSPasteboard.PasteboardType.png.rawValue,
                advertisedTypes: names,
                data: .inline(data)
            )
        } else if types.contains(.tiff), let data = reader.data(forType: .tiff) {
            representation = ClipboardBrokerCapturedRepresentation(
                family: .imageTIFF,
                pasteboardType: NSPasteboard.PasteboardType.tiff.rawValue,
                advertisedTypes: names,
                data: .inline(data)
            )
        } else if types.contains(.URL), let value = reader.string(forType: .URL) {
            representation = ClipboardBrokerCapturedRepresentation(
                family: .url,
                pasteboardType: NSPasteboard.PasteboardType.URL.rawValue,
                advertisedTypes: names,
                value: value
            )
        } else if types.contains(.rtf), let data = reader.data(forType: .rtf) {
            let plainText = (try? NSAttributedString(
                data: data,
                options: [.documentType: NSAttributedString.DocumentType.rtf],
                documentAttributes: nil
            ))?.string
            representation = ClipboardBrokerCapturedRepresentation(
                family: .richText,
                pasteboardType: NSPasteboard.PasteboardType.rtf.rawValue,
                advertisedTypes: names,
                plainText: plainText,
                data: .inline(data)
            )
        } else if types.contains(.string), let value = reader.string(forType: .string) {
            representation = ClipboardBrokerCapturedRepresentation(
                family: .text,
                pasteboardType: NSPasteboard.PasteboardType.string.rawValue,
                advertisedTypes: names,
                value: value
            )
        } else {
            representation = nil
        }

        let after = reader.changeCount
        guard after == before, let representation else {
            return ClipboardBrokerObservationResult(
                status: .skipped,
                changeCount: before,
                observedAfterChangeCount: after,
                skipReason: representation == nil ? .unsupported : .stale,
                prefilterDisposition: request.prefilterDisposition
            )
        }
        return ClipboardBrokerObservationResult(
            status: .captured,
            changeCount: before,
            observedAfterChangeCount: after,
            representation: representation,
            prefilterDisposition: request.prefilterDisposition
        )
    }

    func write(
        _ request: ClipboardBrokerWriteRequest
    ) async throws -> ClipboardPasteboardWriteLease {
        throw ClipboardBrokerClientError.writeFailed
    }

    func validate(_ lease: ClipboardPasteboardWriteLease) async -> Bool {
        lease.changeCount == reader.changeCount
    }

    func currentPlainText(
        limit: Int
    ) async throws -> ClipboardBrokerPlainTextResult {
        let text = reader.string(forType: .string)
        return ClipboardBrokerPlainTextResult(
            text: text.map { String($0.prefix(limit)) },
            originalCharacterCount: text?.count ?? 0,
            truncated: (text?.count ?? 0) > limit,
            changeCount: reader.changeCount
        )
    }

    func shutdown() async {}

    private func result(
        status: ClipboardBrokerObservationStatus,
        changeCount: Int,
        request: ClipboardBrokerObserveRequest,
        skipReason: ClipboardBrokerSkipReason? = nil
    ) -> ClipboardBrokerObservationResult {
        ClipboardBrokerObservationResult(
            status: status,
            changeCount: changeCount,
            observedAfterChangeCount: changeCount,
            skipReason: skipReason,
            prefilterDisposition: request.prefilterDisposition
        )
    }
}

private final class ClipboardCleanupInvocationCounter: @unchecked Sendable {
    private let lock = NSLock()
    private var value = 0

    func increment() -> Int {
        lock.withLock {
            value += 1
            return value
        }
    }

    var currentValue: Int {
        lock.withLock { value }
    }
}

private final class OneShotDispatchSemaphoreGate: @unchecked Sendable {
    private let semaphore = DispatchSemaphore(value: 0)
    private let lock = NSLock()
    private var isReleased = false

    func wait() {
        semaphore.wait()
    }

    func release() {
        lock.withLock {
            guard !isReleased else { return }
            isReleased = true
            semaphore.signal()
        }
    }
}

private final class ClipboardMutationExecutionProbe: @unchecked Sendable {
    private let lock = NSLock()
    private var storedTagCompleted = false
    private var storedRecordExecutions: [(
        kind: ClipboardRecordMutationKind,
        onMainThread: Bool
    )] = []

    var tagCompleted: Bool {
        lock.withLock { storedTagCompleted }
    }

    var recordExecutions: [(kind: ClipboardRecordMutationKind, onMainThread: Bool)] {
        lock.withLock { storedRecordExecutions }
    }

    func markTagCompleted() {
        lock.withLock { storedTagCompleted = true }
    }

    func record(kind: ClipboardRecordMutationKind, onMainThread: Bool) {
        lock.withLock {
            storedRecordExecutions.append((kind: kind, onMainThread: onMainThread))
        }
    }
}

private final class CLIRefreshDigestProbe: @unchecked Sendable {
    private let blockedURL: URL
    private let condition = NSCondition()
    private var didBlock = false
    private var isBlocked = false
    private var isResumed = false
    private var calledOnMainThread = false
    private var blockedWaiters: [CheckedContinuation<Void, Never>] = []

    init(blockedURL: URL) {
        self.blockedURL = blockedURL
    }

    var digest: (URL) -> String? {
        { [weak self] url in
            guard let self else { return nil }
            self.condition.lock()
            self.calledOnMainThread = self.calledOnMainThread || Thread.isMainThread
            let shouldBlock = url == self.blockedURL && !self.didBlock
            if shouldBlock {
                self.didBlock = true
                self.isBlocked = true
                let waiters = self.blockedWaiters
                self.blockedWaiters.removeAll()
                self.condition.unlock()
                waiters.forEach { $0.resume() }
                self.condition.lock()
                while !self.isResumed {
                    self.condition.wait()
                }
            }
            self.condition.unlock()
            return BlocksCLIFileDigest.sha256(of: url)
        }
    }

    var wasCalledOnMainThread: Bool {
        condition.lock()
        defer { condition.unlock() }
        return calledOnMainThread
    }

    func waitUntilBlocked() async {
        await withCheckedContinuation { continuation in
            condition.lock()
            if isBlocked {
                condition.unlock()
                continuation.resume()
                return
            }
            blockedWaiters.append(continuation)
            condition.unlock()
        }
    }

    func resume() {
        condition.lock()
        isResumed = true
        condition.broadcast()
        condition.unlock()
    }
}

private final class CLIJournalStoreProbe: @unchecked Sendable {
    private let lock = NSLock()
    private var storedSaveCount = 0
    private var storedClearCount = 0

    var saveCount: Int { lock.withLock { storedSaveCount } }
    var clearCount: Int { lock.withLock { storedClearCount } }

    func save(_: Data) -> Bool {
        lock.withLock { storedSaveCount += 1 }
        return true
    }

    func clear() -> Bool {
        lock.withLock { storedClearCount += 1 }
        return true
    }
}

private final class CLISourceMutationDigestProbe: @unchecked Sendable {
    private let lock = NSLock()
    private let sourceURL: URL
    private var didMutateSource = false

    init(sourceURL: URL) {
        self.sourceURL = sourceURL.standardizedFileURL
    }

    func digest(_ url: URL) -> String? {
        let value = BlocksCLIFileDigest.sha256(of: url)
        lock.lock()
        let shouldMutate = !didMutateSource
            && url.standardizedFileURL == sourceURL
        if shouldMutate {
            didMutateSource = true
        }
        lock.unlock()
        if shouldMutate {
            try? Data("v2".utf8).write(to: sourceURL)
        }
        return value
    }
}

private final class CLIIdentityFollowingBookmarkAccess: @unchecked Sendable {
    private enum Entry {
        case path(URL)
        case directory(identity: Data, parent: URL)
        case file(identity: Data, directory: URL)
    }

    private let lock = NSLock()
    private var entries: [Data: Entry] = [:]

    var access: BlocksCLIInstallationBookmarkAccess {
        BlocksCLIInstallationBookmarkAccess(
            make: { [weak self] url in
                guard let self else { throw CocoaError(.fileNoSuchFile) }
                return self.makeBookmark(for: url)
            },
            resolve: { [weak self] data in
                self?.resolveBookmark(data)
            },
            start: { _ in true },
            stop: { _ in }
        )
    }

    private func makeBookmark(for url: URL) -> Data {
        let token = Data(UUID().uuidString.utf8)
        var isDirectory = ObjCBool(false)
        let exists = FileManager.default.fileExists(
            atPath: url.path,
            isDirectory: &isDirectory
        )
        let entry: Entry
        if exists,
           isDirectory.boolValue,
           let identity = directoryIdentity(of: url) {
            entry = .directory(
                identity: identity,
                parent: url.deletingLastPathComponent()
            )
        } else if exists,
                  let identity = BlocksCLIFileIdentity.resourceIdentifier(of: url) {
            entry = .file(
                identity: identity,
                directory: url.deletingLastPathComponent()
            )
        } else {
            entry = .path(url)
        }
        lock.lock()
        entries[token] = entry
        lock.unlock()
        return token
    }

    private func resolveBookmark(_ data: Data) -> URL? {
        lock.lock()
        let entry = entries[data]
        lock.unlock()
        guard let entry else { return nil }
        switch entry {
        case let .path(url):
            return url
        case let .directory(identity, parent):
            guard let children = try? FileManager.default.contentsOfDirectory(
                at: parent,
                includingPropertiesForKeys: nil
            ) else {
                return nil
            }
            return children.first {
                directoryIdentity(of: $0) == identity
            }
        case let .file(identity, directory):
            guard let children = try? FileManager.default.contentsOfDirectory(
                at: directory,
                includingPropertiesForKeys: nil
            ) else {
                return nil
            }
            return children.first {
                BlocksCLIFileIdentity.resourceIdentifier(of: $0) == identity
            }
        }
    }

    private func directoryIdentity(of url: URL) -> Data? {
        var metadata = stat()
        let result = url.path.withCString { path in
            lstat(path, &metadata)
        }
        guard result == 0, metadata.st_mode & S_IFMT == S_IFDIR else {
            return nil
        }
        var device = UInt64(metadata.st_dev).littleEndian
        var inode = UInt64(metadata.st_ino).littleEndian
        var generation = UInt64(metadata.st_gen).littleEndian
        var identity = Data()
        withUnsafeBytes(of: &device) { identity.append(contentsOf: $0) }
        withUnsafeBytes(of: &inode) { identity.append(contentsOf: $0) }
        withUnsafeBytes(of: &generation) { identity.append(contentsOf: $0) }
        return identity
    }
}

private final class CLIInstallCommitGate: @unchecked Sendable {
    private let condition = NSCondition()
    private var isBlocked = false
    private var isResumed = false
    private var waiters: [CheckedContinuation<Void, Never>] = []

    func waitBeforeCommit() {
        condition.lock()
        isBlocked = true
        let currentWaiters = waiters
        waiters.removeAll()
        condition.unlock()
        currentWaiters.forEach { $0.resume() }

        condition.lock()
        while !isResumed {
            condition.wait()
        }
        condition.unlock()
    }

    func waitUntilBlocked() async {
        await withCheckedContinuation { continuation in
            condition.lock()
            if isBlocked {
                condition.unlock()
                continuation.resume()
                return
            }
            waiters.append(continuation)
            condition.unlock()
        }
    }

    func resume() {
        condition.lock()
        isResumed = true
        condition.broadcast()
        condition.unlock()
    }
}

private actor CLIUninstallCommitGate {
    private var isBlocked = false
    private var continuation: CheckedContinuation<Void, Never>?

    func waitBeforeCommit() async {
        isBlocked = true
        await withCheckedContinuation { continuation in
            self.continuation = continuation
        }
    }

    func waitUntilBlocked() async {
        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: .seconds(1))
        while !isBlocked, clock.now < deadline {
            try? await Task.sleep(for: .milliseconds(5))
        }
        if !isBlocked {
            XCTFail("Timed out waiting for CLI uninstall to reach its commit point.")
        }
    }

    func resume() {
        continuation?.resume()
        continuation = nil
    }
}

private actor CLIJournalRecoveryGate {
    private var isBlocked = false
    private var hasBlocked = false
    private var continuation: CheckedContinuation<Void, Never>?

    func waitBeforeRecovery() async {
        guard !hasBlocked else { return }
        hasBlocked = true
        isBlocked = true
        await withCheckedContinuation { continuation in
            self.continuation = continuation
        }
    }

    func waitUntilBlocked() async {
        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: .seconds(1))
        while !isBlocked, clock.now < deadline {
            try? await Task.sleep(for: .milliseconds(5))
        }
        if !isBlocked {
            XCTFail("Timed out waiting for CLI journal recovery to block.")
        }
    }

    func resume() {
        continuation?.resume()
        continuation = nil
    }
}

private final class CLILeaseThreadProbe: @unchecked Sendable {
    private let lock = NSLock()
    private var acquireThreads: [Bool] = []
    private var releaseThreads: [Bool] = []

    var acquireCount: Int {
        lock.withLock { acquireThreads.count }
    }

    var releaseCount: Int {
        lock.withLock { releaseThreads.count }
    }

    var acquireWasCalledOnMainThread: Bool {
        lock.withLock { acquireThreads.contains(true) }
    }

    var releaseWasCalledOnMainThread: Bool {
        lock.withLock { releaseThreads.contains(true) }
    }

    func recordAcquire() {
        lock.withLock { acquireThreads.append(Thread.isMainThread) }
    }

    func recordRelease() {
        lock.withLock { releaseThreads.append(Thread.isMainThread) }
    }
}

private actor ClipboardLiveCaptureStageGate {
    private var started: Set<String> = []
    private var continuations: [String: CheckedContinuation<Void, Never>] = [:]

    func recordStart(_ label: String) {
        started.insert(label)
    }

    func hasStarted(_ label: String) -> Bool {
        started.contains(label)
    }

    func waitForRelease(of label: String) async {
        started.insert(label)
        await withCheckedContinuation { continuation in
            continuations[label] = continuation
        }
    }

    func release(_ label: String) {
        continuations.removeValue(forKey: label)?.resume()
    }
}

