private final class ScriptedClipboardPasteboardReader: TestClipboardPasteboardReading, @unchecked Sendable {
    private let lock = NSLock()
    private var storedChangeCount: Int
    private let storedTypes: [NSPasteboard.PasteboardType]
    private let strings: [NSPasteboard.PasteboardType: String]
    private let dataValues: [NSPasteboard.PasteboardType: Data]
    private var dataRequests: [NSPasteboard.PasteboardType] = []
    private var stringRequests: [NSPasteboard.PasteboardType] = []
    private var readThreads: [Bool] = []
    var failIfImageRepresentationIsRequested = false

    init(
        changeCount: Int,
        types: [NSPasteboard.PasteboardType],
        strings: [NSPasteboard.PasteboardType: String] = [:],
        data: [NSPasteboard.PasteboardType: Data] = [:]
    ) {
        storedChangeCount = changeCount
        storedTypes = types
        self.strings = strings
        dataValues = data
    }

    var changeCount: Int {
        lock.withLock { storedChangeCount }
    }

    var types: [NSPasteboard.PasteboardType]? {
        storedTypes
    }

    var requestedDataTypes: [NSPasteboard.PasteboardType] {
        lock.withLock { dataRequests }
    }

    var requestedStringTypes: [NSPasteboard.PasteboardType] {
        lock.withLock { stringRequests }
    }

    var representationReadOnMainThread: [Bool] {
        lock.withLock { readThreads }
    }

    func advanceChangeCount() {
        lock.withLock { storedChangeCount += 1 }
    }

    func data(forType dataType: NSPasteboard.PasteboardType) -> Data? {
        lock.withLock {
            dataRequests.append(dataType)
            readThreads.append(Thread.isMainThread)
        }
        if failIfImageRepresentationIsRequested,
           (dataType == .png || dataType == .tiff) {
            XCTFail("Text-only capture must not request an image representation.")
        }
        return dataValues[dataType]
    }

    func string(forType dataType: NSPasteboard.PasteboardType) -> String? {
        lock.withLock {
            stringRequests.append(dataType)
            readThreads.append(Thread.isMainThread)
        }
        return strings[dataType]
    }
}

@MainActor
private final class ScriptedClipboardPasteboard: ClipboardPasteboardWriting {
    private(set) var items: [ClipboardPasteboardWriteItem]
    private(set) var changeCount: Int
    private(set) var writeCallCount = 0
    private var writeOutcomes: [Bool]
    private let changeCountStep: Int

    init(
        items: [ClipboardPasteboardWriteItem],
        changeCount: Int,
        writeOutcomes: [Bool],
        changeCountStep: Int = 1
    ) {
        self.items = items
        self.changeCount = changeCount
        self.writeOutcomes = writeOutcomes
        self.changeCountStep = max(1, changeCountStep)
    }

    func writeItems(_ replacement: [ClipboardPasteboardWriteItem]) -> Bool {
        writeCallCount += 1
        changeCount += changeCountStep
        let succeeds = writeOutcomes.isEmpty ? true : writeOutcomes.removeFirst()
        items = succeeds ? replacement : []
        return succeeds
    }
}

