private final class SuspendedScreenshotOutputImageProcessorProbe: @unchecked Sendable {
    private let condition = NSCondition()
    private let suspends: Bool
    private var started = false
    private var resumed = false
    private var mainThreadExecutions: [Bool] = []

    init(suspends: Bool) {
        self.suspends = suspends
    }

    var executedOnMainThread: [Bool] {
        condition.lock()
        defer { condition.unlock() }
        return mainThreadExecutions
    }

    func process(_ image: CGImage) -> CGImage {
        condition.lock()
        mainThreadExecutions.append(Thread.isMainThread)
        started = true
        condition.broadcast()
        while suspends, !resumed {
            condition.wait()
        }
        condition.unlock()
        return image
    }

    func waitUntilStarted() async {
        while !isStarted {
            await Task.yield()
        }
    }

    private var isStarted: Bool {
        condition.lock()
        defer { condition.unlock() }
        return started
    }

    func resume() {
        condition.lock()
        resumed = true
        condition.broadcast()
        condition.unlock()
    }
}

private final class PinnedScreenshotSaveWriterProbe: @unchecked Sendable {
    private let lock = NSLock()
    private var attemptCount = 0

    func write(_ image: CGImage, to url: URL) throws {
        _ = image.width
        _ = url.path
        let attempt = lock.withLock { () -> Int in
            attemptCount += 1
            return attemptCount
        }
        if attempt == 1 {
            throw PinnedScreenshotSaveWriterProbeError.fixtureFailure
        }
    }

    func waitForAttemptCount(_ expected: Int) async {
        while currentAttemptCount < expected {
            await Task.yield()
        }
    }

    var currentAttemptCount: Int {
        lock.withLock { attemptCount }
    }
}

private actor PinnedScreenshotSavePanelPresentationProbe {
    private var presentationContinuation: CheckedContinuation<NSWindow, Never>?
    private var resultContinuation:
        CheckedContinuation<PinnedScreenshotSavePanelResult, Never>?
    private var presentedOwner: NSWindow?
    private var pendingResult: PinnedScreenshotSavePanelResult?

    func present(
        panel _: NSSavePanel,
        owner: NSWindow
    ) async -> PinnedScreenshotSavePanelResult {
        presentedOwner = owner
        presentationContinuation?.resume(returning: owner)
        presentationContinuation = nil
        if let pendingResult {
            self.pendingResult = nil
            return pendingResult
        }
        return await withCheckedContinuation { continuation in
            resultContinuation = continuation
        }
    }

    func waitUntilPresented() async -> NSWindow {
        if let presentedOwner { return presentedOwner }
        return await withCheckedContinuation { continuation in
            presentationContinuation = continuation
        }
    }

    func finish(_ result: PinnedScreenshotSavePanelResult) {
        if let resultContinuation {
            self.resultContinuation = nil
            resultContinuation.resume(returning: result)
        } else {
            pendingResult = result
        }
    }
}

private enum PinnedScreenshotSaveWriterProbeError: Error {
    case fixtureFailure
}

private final class SuspendedScreenshotPNGEncodingProbe: @unchecked Sendable {
    let data: Data
    private let condition = NSCondition()
    private var started = false
    private var resumed = false
    private var invocationCount = 0

    init(data: Data) {
        self.data = data
    }

    func encode(_ image: CGImage) -> Data {
        _ = image.width
        condition.lock()
        invocationCount += 1
        let suspends = invocationCount == 1
        started = true
        condition.broadcast()
        while suspends, !resumed {
            condition.wait()
        }
        condition.unlock()
        return data
    }

    func waitUntilStarted() async {
        while !isStarted {
            await Task.yield()
        }
    }

    private var isStarted: Bool {
        condition.lock()
        defer { condition.unlock() }
        return started
    }

    func resume() {
        condition.lock()
        resumed = true
        condition.broadcast()
        condition.unlock()
    }
}

