private func screenshotAppStateBrokerClient(
    pasteboardName: String
) throws -> ClipboardBrokerClient {
    let candidates = [
        Bundle.main.bundleURL
            .appendingPathComponent("Contents", isDirectory: true)
            .appendingPathComponent("MacOS", isDirectory: true)
            .appendingPathComponent("BlocksClipboardBroker", isDirectory: false),
        Bundle.main.bundleURL
            .deletingLastPathComponent()
            .appendingPathComponent("BlocksClipboardBroker", isDirectory: false),
        Bundle(for: ScreenshotAppStateTests.self).bundleURL
            .deletingLastPathComponent()
            .appendingPathComponent("BlocksClipboardBroker", isDirectory: false),
    ]
    guard let brokerURL = candidates.first(where: {
        FileManager.default.isExecutableFile(atPath: $0.path)
    }) else {
        throw XCTSkip("Missing test product BlocksClipboardBroker.")
    }
    return ClipboardBrokerClient(
        executableURLProvider: { brokerURL },
        environmentOverrides: [
            "BLOCKS_CLIPBOARD_BROKER_TEST_PASTEBOARD_NAME": pasteboardName,
        ]
    )
}

private actor RealBrokerCommitReturnGate: ClipboardBrokerServing {
    private let client: ClipboardBrokerClient
    private let onPhysicalCommit: @Sendable () -> Void
    private var commitReturnContinuation: CheckedContinuation<Void, Never>?
    private var committedLeases: [ClipboardPasteboardWriteLease] = []

    init(
        client: ClipboardBrokerClient,
        onPhysicalCommit: @escaping @Sendable () -> Void
    ) {
        self.client = client
        self.onPhysicalCommit = onPhysicalCommit
    }

    func baseline() async throws -> Int { try await client.baseline() }

    func observe(
        _ request: ClipboardBrokerObserveRequest
    ) async throws -> ClipboardBrokerObservationResult {
        try await client.observe(request)
    }

    func write(
        _ request: ClipboardBrokerWriteRequest
    ) async throws -> ClipboardPasteboardWriteLease {
        try await client.write(request)
    }

    func supportsPreparedWrites() async -> Bool {
        await client.supportsPreparedWrites()
    }

    func prepare(
        _ request: ClipboardBrokerWriteRequest
    ) async throws -> ClipboardPreparedPasteboardWriteLease {
        try await client.prepare(request)
    }

    func commit(
        _ lease: ClipboardPreparedPasteboardWriteLease
    ) async throws -> ClipboardPasteboardWriteLease {
        let committedLease = try await client.commit(lease)
        committedLeases.append(committedLease)
        onPhysicalCommit()
        await withCheckedContinuation { continuation in
            commitReturnContinuation = continuation
        }
        return committedLease
    }

    func cancel(
        _ lease: ClipboardPreparedPasteboardWriteLease
    ) async throws {
        try await client.cancel(lease)
    }

    func validate(_ lease: ClipboardPasteboardWriteLease) async -> Bool {
        await client.validate(lease)
    }

    func generationIsCurrent(_ brokerGeneration: UInt64) async -> Bool {
        await client.generationIsCurrent(brokerGeneration)
    }

    func currentPlainText(
        limit: Int
    ) async throws -> ClipboardBrokerPlainTextResult {
        try await client.currentPlainText(limit: limit)
    }

    func shutdown() async { await client.shutdown() }

    func committedLeaseCount() -> Int { committedLeases.count }

    func releaseCommitReturn() {
        commitReturnContinuation?.resume()
        commitReturnContinuation = nil
    }
}

private actor ControlledScreenshotClipboardBroker: ClipboardBrokerServing {
    private struct PendingWrite {
        let request: ClipboardBrokerWriteRequest
        let continuation:
            CheckedContinuation<ClipboardPasteboardWriteLease, Error>
    }

    private var nextOrdinal = 0
    private var pendingWrites: [Int: PendingWrite] = [:]
    private var recordedRequests: [Int: ClipboardBrokerWriteRequest] = [:]
    private var preparedRequest: ClipboardBrokerWriteRequest?
    private var preparedWriteID: UUID?
    private var prepareStarted = false
    private var preparedReturnWasReleased = false
    private var preparedReturnContinuation: CheckedContinuation<Void, Never>?
    private let pausesPreparedReturn: Bool
    private let onPrepared: @Sendable () -> Void
    private var committedCount = 0
    private var cancelledCount = 0

    init(
        pausesPreparedReturn: Bool = false,
        onPrepared: @escaping @Sendable () -> Void = {}
    ) {
        self.pausesPreparedReturn = pausesPreparedReturn
        self.onPrepared = onPrepared
    }

    func baseline() async throws -> Int { 0 }

    func observe(
        _ request: ClipboardBrokerObserveRequest
    ) async throws -> ClipboardBrokerObservationResult {
        ClipboardBrokerObservationResult(
            status: .noChange,
            changeCount: request.baselineChangeCount ?? 0,
            observedAfterChangeCount: request.baselineChangeCount ?? 0
        )
    }

    func write(
        _ request: ClipboardBrokerWriteRequest
    ) async throws -> ClipboardPasteboardWriteLease {
        let ordinal = nextOrdinal
        nextOrdinal += 1
        recordedRequests[ordinal] = request
        return try await withCheckedThrowingContinuation { continuation in
            pendingWrites[ordinal] = PendingWrite(
                request: request,
                continuation: continuation
            )
        }
    }

    func supportsPreparedWrites() async -> Bool { true }

    func prepare(
        _ request: ClipboardBrokerWriteRequest
    ) async throws -> ClipboardPreparedPasteboardWriteLease {
        let preparedWriteID = UUID()
        preparedRequest = request
        self.preparedWriteID = preparedWriteID
        prepareStarted = true
        onPrepared()
        if pausesPreparedReturn, !preparedReturnWasReleased {
            await withCheckedContinuation { continuation in
                preparedReturnContinuation = continuation
            }
        }
        return ClipboardPreparedPasteboardWriteLease(
            preparedWriteID: preparedWriteID,
            brokerGeneration: 1
        )
    }

    func commit(
        _ lease: ClipboardPreparedPasteboardWriteLease
    ) async throws -> ClipboardPasteboardWriteLease {
        guard preparedWriteID == lease.preparedWriteID,
              let request = preparedRequest else {
            throw ClipboardBrokerClientError.requestSuperseded
        }
        preparedRequest = nil
        preparedWriteID = nil
        committedCount += 1
        return try await write(request)
    }

    func cancel(
        _ lease: ClipboardPreparedPasteboardWriteLease
    ) async throws {
        guard preparedWriteID == lease.preparedWriteID else {
            throw ClipboardBrokerClientError.requestSuperseded
        }
        preparedRequest = nil
        preparedWriteID = nil
        cancelledCount += 1
    }

    func validate(_ lease: ClipboardPasteboardWriteLease) async -> Bool {
        true
    }

    func currentPlainText(
        limit: Int
    ) async throws -> ClipboardBrokerPlainTextResult {
        ClipboardBrokerPlainTextResult(
            text: nil,
            originalCharacterCount: 0,
            truncated: false,
            changeCount: 0
        )
    }

    func shutdown() async {}

    func commitCount() -> Int { committedCount }

    func cancelCount() -> Int { cancelledCount }

    func waitUntilPrepared() async throws {
        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: .seconds(1))
        while !prepareStarted, clock.now < deadline {
            try await Task.sleep(for: .milliseconds(5))
        }
        guard prepareStarted else {
            throw ClipboardBrokerClientError.requestTimedOut
        }
    }

    func releasePreparedReturn() {
        preparedReturnWasReleased = true
        preparedReturnContinuation?.resume()
        preparedReturnContinuation = nil
    }

    func waitForRequestCount(_ expected: Int) async throws {
        let deadline = ContinuousClock.now.advanced(by: .seconds(1))
        while nextOrdinal < expected, ContinuousClock.now < deadline {
            try await Task.sleep(for: .milliseconds(5))
        }
        guard nextOrdinal >= expected else {
            throw ClipboardBrokerClientError.requestTimedOut
        }
    }

    func request(ordinal: Int) -> ClipboardBrokerWriteRequest? {
        recordedRequests[ordinal]
    }

    func complete(ordinal: Int, changeCount: Int) {
        pendingWrites.removeValue(forKey: ordinal)?.continuation.resume(
            returning: ClipboardPasteboardWriteLease(
                changeCount: changeCount,
                brokerGeneration: 1
            )
        )
    }
}

private actor InvalidLeaseClipboardBroker: ClipboardBrokerServing {
    func baseline() async throws -> Int { 0 }

    func observe(
