private actor ControlledPlainTextCopyBroker: ClipboardBrokerServing {
    private let blockPrepare: Bool
    private let blockAfterPhysicalWrite: Bool
    private let blockValidation: Bool
    private var validationStarted = false
    private var validationContinuation: CheckedContinuation<Void, Never>?
    private var preparedWriteID: UUID?
    private var preparedRequest: ClipboardBrokerWriteRequest?
    private var prepareStarted = false
    private var prepareContinuation: CheckedContinuation<Void, Never>?
    private var commitContinuation: CheckedContinuation<Void, Never>?
    private var physicalWriteCount = 0
    private var commitCount = 0
    private var cancelCount = 0
    private var commitReturnCount = 0

    init(
        blockPrepare: Bool = false,
        blockAfterPhysicalWrite: Bool = false,
        blockValidation: Bool = false
    ) {
        self.blockPrepare = blockPrepare
        self.blockAfterPhysicalWrite = blockAfterPhysicalWrite
        self.blockValidation = blockValidation
    }

    func baseline() async throws -> Int { 0 }

    func observe(
        _ request: ClipboardBrokerObserveRequest
    ) async throws -> ClipboardBrokerObservationResult {
        ClipboardBrokerObservationResult(
            status: .noChange,
            changeCount: request.baselineChangeCount ?? 0,
            observedAfterChangeCount: request.baselineChangeCount ?? 0
        )
    }

    func write(
        _ request: ClipboardBrokerWriteRequest
    ) async throws -> ClipboardPasteboardWriteLease {
        _ = request
        physicalWriteCount += 1
        return ClipboardPasteboardWriteLease(
            changeCount: physicalWriteCount,
            brokerGeneration: 1
        )
    }

    func supportsPreparedWrites() async -> Bool { true }

    func prepare(
        _ request: ClipboardBrokerWriteRequest
    ) async throws -> ClipboardPreparedPasteboardWriteLease {
        let preparedWriteID = UUID()
        self.preparedWriteID = preparedWriteID
        preparedRequest = request
        prepareStarted = true
        if blockPrepare {
            await withCheckedContinuation { continuation in
                prepareContinuation = continuation
            }
        }
        return ClipboardPreparedPasteboardWriteLease(
            preparedWriteID: preparedWriteID,
            brokerGeneration: 1
        )
    }

    func commit(
        _ lease: ClipboardPreparedPasteboardWriteLease
    ) async throws -> ClipboardPasteboardWriteLease {
        guard preparedWriteID == lease.preparedWriteID,
              preparedRequest != nil else {
            throw ClipboardBrokerClientError.requestSuperseded
        }
        preparedWriteID = nil
        preparedRequest = nil
        commitCount += 1
        physicalWriteCount += 1
        let writeLease = ClipboardPasteboardWriteLease(
            changeCount: physicalWriteCount,
            brokerGeneration: 1
        )
        if blockAfterPhysicalWrite {
            await withCheckedContinuation { continuation in
                commitContinuation = continuation
            }
        }
        commitReturnCount += 1
        return writeLease
    }

    func cancel(
        _ lease: ClipboardPreparedPasteboardWriteLease
    ) async throws {
        guard preparedWriteID == lease.preparedWriteID else {
            throw ClipboardBrokerClientError.requestSuperseded
        }
        preparedWriteID = nil
        preparedRequest = nil
        cancelCount += 1
    }

    func validate(_ lease: ClipboardPasteboardWriteLease) async -> Bool {
        _ = lease
        validationStarted = true
        if blockValidation {
            await withCheckedContinuation { validationContinuation = $0 }
        }
        return true
    }

    func waitUntilValidationStarted() async throws {
        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: .seconds(1))
        while !validationStarted, clock.now < deadline {
            try await Task.sleep(for: .milliseconds(5))
        }
        guard validationStarted else { throw ClipboardBrokerClientError.requestTimedOut }
    }

    func releaseValidation() {
        validationContinuation?.resume()
        validationContinuation = nil
    }

    func currentPlainText(
        limit: Int
    ) async throws -> ClipboardBrokerPlainTextResult {
        _ = limit
        return ClipboardBrokerPlainTextResult(
            text: nil,
            originalCharacterCount: 0,
            truncated: false,
            changeCount: 0
        )
    }

    func shutdown() async {}

    func waitUntilPrepareStarted() async throws {
        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: .seconds(1))
        while !prepareStarted, clock.now < deadline {
            try await Task.sleep(for: .milliseconds(5))
        }
        guard prepareStarted else {
            throw ClipboardBrokerClientError.requestTimedOut
        }
    }

    func waitUntilPhysicalWrite() async throws {
        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: .seconds(1))
        while physicalWriteCount < 1, clock.now < deadline {
            try await Task.sleep(for: .milliseconds(5))
        }
        guard physicalWriteCount >= 1 else {
            throw ClipboardBrokerClientError.requestTimedOut
        }
    }

    func waitUntilCancelled() async throws {
        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: .seconds(1))
        while cancelCount < 1, clock.now < deadline {
            try await Task.sleep(for: .milliseconds(5))
        }
        guard cancelCount >= 1 else {
            throw ClipboardBrokerClientError.requestTimedOut
        }
    }

    func waitUntilCommitReturned() async throws {
        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: .seconds(1))
        while commitReturnCount < 1, clock.now < deadline {
            try await Task.sleep(for: .milliseconds(5))
        }
        guard commitReturnCount >= 1 else {
            throw ClipboardBrokerClientError.requestTimedOut
        }
    }

    func releasePrepare() {
        prepareContinuation?.resume()
        prepareContinuation = nil
    }

    func releaseCommit() {
        commitContinuation?.resume()
        commitContinuation = nil
    }

    func metrics() -> (physicalWrites: Int, commits: Int) {
        (physicalWriteCount, commitCount)
    }
}

