@MainActor
private final class GatedFinalizedArtifactArchiveWriter: ScreenshotClipboardArchiving {
    private let pauseAfterDurableCommit: Bool
    private let onReachedPause: () -> Void
    private var continuation: CheckedContinuation<Void, Never>?
    private var hasResumePermit = false
    private(set) var archiveCount = 0

    init(
        pauseAfterDurableCommit: Bool,
        onReachedPause: @escaping () -> Void
    ) {
        self.pauseAfterDurableCommit = pauseAfterDurableCommit
        self.onReachedPause = onReachedPause
    }

    func archive(
        capture: ScreenshotCapture,
        image: NSImage,
        automaticallyRecognizesText: Bool
    ) async throws -> ScreenshotClipboardArchiveResult {
        _ = capture
        _ = image
        _ = automaticallyRecognizesText
        return .stored
    }

    func archive(
        artifact: FinalizedScreenshotArtifact,
        automaticallyRecognizesText: Bool,
        isCurrent: @escaping @MainActor () -> Bool
    ) async throws -> ScreenshotClipboardArchiveResult {
        _ = artifact
        _ = automaticallyRecognizesText
        guard isCurrent() else { return .ignoredFeatureDisabled }
        archiveCount += 1
        onReachedPause()
        if hasResumePermit {
            hasResumePermit = false
        } else {
            await withCheckedContinuation { continuation in
                self.continuation = continuation
            }
        }
        guard pauseAfterDurableCommit || isCurrent() else {
            return .ignoredFeatureDisabled
        }
        return .stored
    }

    func resume() {
        if let continuation {
            self.continuation = nil
            continuation.resume()
        } else {
            hasResumePermit = true
        }
    }
}

