private actor NonCooperativeManualOCRHarness {
    private var continuations: [Int: CheckedContinuation<String, Never>] = [:]
    private var nextRequest = 0

    func recognize() async -> String {
        let request = nextRequest
        nextRequest += 1
        return await withCheckedContinuation { continuation in
            continuations[request] = continuation
        }
    }

    func resume(request: Int, text: String) {
        continuations.removeValue(forKey: request)?.resume(returning: text)
    }

    func waitForRequestCount(_ expected: Int) async throws {
        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: .seconds(1))
        while nextRequest < expected, clock.now < deadline {
            try await Task.sleep(for: .milliseconds(5))
        }
        if nextRequest < expected {
            throw NonCooperativeManualOCRHarnessError.requestDidNotStart
        }
    }
}

private actor SuspendedPinnedOCRCopyHarness {
    private var continuation: CheckedContinuation<Void, Never>?
    private var hasResumePermit = false
    private var hasWriteInFlight = false
    private(set) var copiedTexts: [String] = []

    func write(_ text: String) async {
        copiedTexts.append(text)
        hasWriteInFlight = true
        if hasResumePermit {
            hasResumePermit = false
            hasWriteInFlight = false
            return
        }
        await withCheckedContinuation { continuation in
            self.continuation = continuation
        }
        hasWriteInFlight = false
    }

    func waitForWriteCount(_ expected: Int) async throws {
        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: .seconds(1))
        while copiedTexts.count < expected, clock.now < deadline {
            try await Task.sleep(for: .milliseconds(5))
        }
        if copiedTexts.count < expected {
            throw NonCooperativeManualOCRHarnessError.requestDidNotStart
        }
    }

    func resume() {
        if let continuation {
            self.continuation = nil
            continuation.resume()
        } else if !hasWriteInFlight {
            hasResumePermit = true
        }
    }
}

private actor SuspendedPinnedImageWriterHarness {
