private actor SuspendedClipboardDetailSaveHarness {
    private var continuation: CheckedContinuation<Void, Never>?
    private var isSuspended = false
    private var hasSuspendedOnce = false

    func suspendFirstSave() async {
        guard !hasSuspendedOnce else { return }
        hasSuspendedOnce = true
        isSuspended = true
        await withCheckedContinuation { continuation in
            self.continuation = continuation
        }
        isSuspended = false
    }

    func waitUntilSuspended() async throws {
        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: .seconds(1))
        while !isSuspended, clock.now < deadline {
            try await Task.sleep(for: .milliseconds(5))
        }
        if !isSuspended {
            throw NonCooperativeManualOCRHarnessError.requestDidNotStart
        }
    }

    func resume() {
        continuation?.resume()
        continuation = nil
    }
}

