    private(set) var captureCount = 0
    private(set) var firstRequestTimedOut = false
    private(set) var successfulImage: CGImage?

    init(
        firstOperation: SingleFrameRequestOperationHarness,
        secondOperation: SingleFrameRequestOperationHarness,
        succeedingCapture: ScreenshotCapture
    ) {
        self.firstOperation = firstOperation
        self.secondOperation = secondOperation
        self.succeedingCapture = succeedingCapture
    }

    func capture(
        intent: ScreenshotCaptureIntent,
        requiresEditingContext: Bool
    ) async throws -> ScreenshotCapture {
        captureCount += 1

        switch captureCount {
        case 1:
            let operation = firstOperation
            do {
                _ = try await adapter.captureSingleFrameImage(
                    deadline: .milliseconds(50),
                    operation: { await operation.run() }
                )
                throw ScreenshotCaptureError.captureFailed(
                    "The timed-out fixture request unexpectedly succeeded."
                )
            } catch let error as ScreenshotCaptureError {
                if case .timedOut = error {
                    firstRequestTimedOut = true
                }
                throw error
            }
        case 2:
            let operation = secondOperation
            let image = try await adapter.captureSingleFrameImage(
                deadline: .seconds(1),
                operation: { await operation.run() }
            )
            successfulImage = image
            return succeedingCapture
        default:
            throw ScreenshotCaptureError.captureFailed(
                "Unexpected fixture capture invocation."
            )
        }
    }

    func cancelCurrentCapture() {
        adapter.cancelCurrentCapture()
    }
}

