@MainActor
private final class SuspendingScrollingCaptureService: ScreenshotCapturing, ScreenshotScrollingSessionControlling {
    let capture: ScreenshotCapture
    private var finishStarted = false
    private var finishContinuation: CheckedContinuation<ScrollingScreenshotControlResult, Never>?

    init(capture: ScreenshotCapture) {
        self.capture = capture
    }

    func capture(
        intent: ScreenshotCaptureIntent,
        requiresEditingContext: Bool
    ) async throws -> ScreenshotCapture {
        capture
    }

    func cancelCurrentCapture() {}

    func scrollingSessionStatus() async -> ScrollingScreenshotRuntimeSnapshot {
        ScrollingScreenshotRuntimeSnapshot(
            sessionID: capture.scrollingSessionID,
            state: .editing,
            outputSize: ScreenshotPixelSize(
                width: Int(capture.pixelSize.width),
                height: Int(capture.pixelSize.height)
            ),
            warning: nil
        )
    }

    func finishScrollingSession(sessionID: String) -> Bool { true }

    func cancelScrollingSession(
        sessionID: String,
        confirm: Bool
    ) async -> ScrollingScreenshotControlResult {
        if finishStarted {
            return .rejected(.alreadyTerminal, state: .editing, wasEditing: true)
        }
        return .accepted(state: .idle, wasEditing: true)
    }

    func finishScrollingEditingSession(
        sessionID: String,
        terminal: ScrollingScreenshotSessionTerminal
    ) async -> ScrollingScreenshotControlResult {
        finishStarted = true
        return await withCheckedContinuation { continuation in
            finishContinuation = continuation
        }
    }

    func waitUntilFinishStarted() async throws {
        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: .seconds(1))
        while !finishStarted, clock.now < deadline {
            try await Task.sleep(for: .milliseconds(5))
        }
        guard finishStarted else {
            throw ClipboardBrokerClientError.requestTimedOut
        }
    }

    func resumeFinish() {
        finishContinuation?.resume(returning: .accepted(state: .idle, wasEditing: true))
        finishContinuation = nil
    }
}

