@MainActor
private final class EditorPresenterStub: ScreenshotEditorPresenting {
    let allowsNewCapture: Bool
    private var editOutcomes: [ScreenshotEditorOutcome]
    private let onFinalOutputCancellationHandlerInstalled: () -> Void
    private(set) var presentCount = 0
    private(set) var cancelCount = 0
    private(set) var editCount = 0
    private(set) var finalOutputCancellationRequestCount = 0
    private var completion: ((ScreenshotEditorOutcome) async -> Void)?
    private var retake: (() -> Void)?
    private var finalOutputCancellationHandler: (@MainActor () -> Void)?

    init(
        allowsNewCapture: Bool,
        editOutcome: ScreenshotEditorOutcome? = nil,
        editOutcomes: [ScreenshotEditorOutcome] = [],
        onFinalOutputCancellationHandlerInstalled: @escaping () -> Void = {}
    ) {
        self.allowsNewCapture = allowsNewCapture
        self.editOutcomes = editOutcomes
        self.onFinalOutputCancellationHandlerInstalled =
            onFinalOutputCancellationHandlerInstalled
        if let editOutcome {
            self.editOutcomes.append(editOutcome)
        }
    }

    func prepareForNewCapture() async -> Bool { allowsNewCapture }

    func present(
        capture: ScreenshotCapture,
        retake: @escaping () -> Void,
        completion: @escaping (ScreenshotEditorOutcome) async -> Void
    ) {
        presentCount += 1
        self.retake = retake
        self.completion = completion
    }

    func edit(capture: ScreenshotCapture) async -> ScreenshotEditorOutcome {
        editCount += 1
        guard !editOutcomes.isEmpty else { return .completed(capture.image) }
        return editOutcomes.removeFirst()
    }

    func cancelCurrentSession() { cancelCount += 1 }

    func setFinalOutputCancellationHandler(
        _ handler: (@MainActor () -> Void)?
    ) {
        finalOutputCancellationHandler = handler
        if handler != nil {
            onFinalOutputCancellationHandlerInstalled()
        }
    }

    func cancelFinalOutput() {
        guard let finalOutputCancellationHandler else { return }
        finalOutputCancellationRequestCount += 1
        finalOutputCancellationHandler()
    }

    func requestRetake() {
        retake?()
    }

    func finish(_ outcome: ScreenshotEditorOutcome) async {
        let completion = self.completion
        self.completion = nil
        await completion?(outcome)
    }
}

private enum PermissionRefreshTestHarnessError: Error {
    case missingContinuation(Int)
    case timedOut(Int)
}

@MainActor
private final class ControlledPermissionSnapshotProvider: PermissionSnapshotProviding {
    private let initial: PermissionStateSnapshot
    private var nextOrdinal = 0
    private var startedOrdinals: Set<Int> = []
    private var returnedOrdinals: Set<Int> = []
    private var continuations: [Int: CheckedContinuation<PermissionStateSnapshot, Never>] = [:]
    private var releaseSnapshot: PermissionStateSnapshot?

    init(initialSnapshot: PermissionStateSnapshot) {
        self.initial = initialSnapshot
    }

    func initialSnapshot() -> PermissionStateSnapshot {
        initial
    }

    func snapshot() async -> PermissionStateSnapshot {
        let ordinal = nextOrdinal
        nextOrdinal += 1
        startedOrdinals.insert(ordinal)

        let snapshot: PermissionStateSnapshot
        if let releaseSnapshot {
            snapshot = releaseSnapshot
        } else {
            snapshot = await withCheckedContinuation { continuation in
                continuations[ordinal] = continuation
            }
        }
        returnedOrdinals.insert(ordinal)
        return snapshot
    }

    func waitUntilStarted(ordinal: Int) async throws {
        try await waitUntil(ordinal: ordinal) {
            self.startedOrdinals.contains(ordinal)
        }
    }

    func waitUntilReturned(ordinal: Int) async throws {
        try await waitUntil(ordinal: ordinal) {
            self.returnedOrdinals.contains(ordinal)
        }
    }

    func finish(ordinal: Int, with snapshot: PermissionStateSnapshot) throws {
        guard let continuation = continuations.removeValue(forKey: ordinal) else {
            throw PermissionRefreshTestHarnessError.missingContinuation(ordinal)
        }
        continuation.resume(returning: snapshot)
    }

    func releaseAll(with snapshot: PermissionStateSnapshot) {
        releaseSnapshot = snapshot
        let pending = continuations.values
        continuations.removeAll()
        pending.forEach { $0.resume(returning: snapshot) }
    }

    private func waitUntil(
        ordinal: Int,
        condition: () -> Bool
    ) async throws {
        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: .seconds(1))
        while !condition(), clock.now < deadline {
            try await Task.sleep(for: .milliseconds(5))
        }
        guard condition() else {
            throw PermissionRefreshTestHarnessError.timedOut(ordinal)
        }
    }
}

