private func permissionRefreshTestSnapshot(
    granted: Bool,
    capturedAt: Date
) -> PermissionStateSnapshot {
    let recommendedAction: PermissionRecommendedAction = granted
        ? .granted
        : .requestInSystemSettings
    let screenRecording = PermissionDiagnosticSnapshot(
        kind: .screenRecording,
        granted: granted,
        bundleID: "app.blocks.permission-refresh-tests",
        appPath: "/Applications/Blocks.app",
        signatureKind: "developer-id",
        teamID: "TEAMID",
        hasUsageDescription: true,
        lastCheckedAt: capturedAt,
        recommendedAction: recommendedAction,
        matchingRunningAppPaths: [],
        identityIssue: .none
    )
    return PermissionStateSnapshot(
        screenRecording: screenRecording,
        accessibility: PermissionDiagnosticSnapshot(
            kind: .accessibility,
            granted: granted,
            bundleID: screenRecording.bundleID,
            appPath: screenRecording.appPath,
            signatureKind: screenRecording.signatureKind,
            teamID: screenRecording.teamID,
            hasUsageDescription: true,
            lastCheckedAt: capturedAt,
            recommendedAction: recommendedAction,
            matchingRunningAppPaths: [],
            identityIssue: .none
        ),
        inputMonitoring: PermissionDiagnosticSnapshot(
            kind: .inputMonitoring,
            granted: granted,
            bundleID: screenRecording.bundleID,
            appPath: screenRecording.appPath,
            signatureKind: screenRecording.signatureKind,
            teamID: screenRecording.teamID,
            hasUsageDescription: true,
            lastCheckedAt: capturedAt,
            recommendedAction: recommendedAction,
            matchingRunningAppPaths: [],
            identityIssue: .none
        ),
        capturedAt: capturedAt
    )
}
